    status         text,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    payment_method text,
    paid_at        timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
    perform assert_approved_courier();
    return query
    select o.id, g.name, g.address, g.lat, g.lng,
           o.customer_name, o.phone, o.address, o.status,
           o.total, o.currency, o.created_at,
           o.payment_method, o.paid_at
      from orders o
      join orgs g on g.id = o.org_id
     where o.courier_id = auth.uid()
     order by (o.status in ('ready', 'in_transit')) desc, o.created_at desc;
end;
$$;

-- ------------------------------------------------------------
-- Grants
-- ------------------------------------------------------------
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function storefront(text) to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function storefront(text)                to authenticated;
        grant execute on function place_order(text, jsonb, text, text, text, text, text) to authenticated;
        grant execute on function set_order_paid(uuid, boolean)   to authenticated;
        grant execute on function my_orders()                     to authenticated;
        grant execute on function shop_orders(uuid)               to authenticated;
        grant execute on function available_deliveries()          to authenticated;
        grant execute on function courier_deliveries()            to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 058_delivery_pin.sql
-- ============================================================
-- ============================================================
-- 058_delivery_pin.sql — the customer's door, as a pin.
--
-- "Dassasgho, en face de la pharmacie" gets a courier to the quartier;
-- the pin gets them to the door. A customer ordering a livraison can now
-- attach their position — the phone's fix, or the coordinates out of a
-- Google Maps link — and the courier's card turns it into an itinerary,
-- the same way the shop's own pin already does (054).
--
-- The rules are the shop-pin's rules: both numbers or neither (half a
-- position is no position), on the world, and only a delivery carries
-- one — a pickup's destination is the shop. Who sees it is who already
-- sees the address: the shop, the courier who took the job, the board a
-- vetted courier reads, and the customer themself. Nothing new leaks.
-- ============================================================

alter table orders add column if not exists drop_lat double precision;
alter table orders add column if not exists drop_lng double precision;
alter table orders drop constraint if exists orders_drop_lat_range;
alter table orders add  constraint orders_drop_lat_range
    check (drop_lat is null or drop_lat between -90 and 90);
alter table orders drop constraint if exists orders_drop_lng_range;
alter table orders add  constraint orders_drop_lng_range
    check (drop_lng is null or drop_lng between -180 and 180);
alter table orders drop constraint if exists orders_drop_pin_pair;
alter table orders add  constraint orders_drop_pin_pair
    check ((drop_lat is null) = (drop_lng is null));

-- ------------------------------------------------------------
-- Ordering carries the pin. The 057 signature goes first: overloads whose
-- extra arguments all have defaults make every short call ambiguous.
-- ------------------------------------------------------------
drop function if exists place_order(text, jsonb, text, text, text, text, text);
create or replace function place_order(
    p_slug       text,
    p_lines      jsonb,
    p_fulfilment text default 'pickup',
    p_note       text default null,
    p_address    text default null,
    p_phone      text default null,
    p_payment    text default 'cash',
    p_drop_lat   double precision default null,
    p_drop_lng   double precision default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org      uuid;
    v_id       uuid;
    v_line     jsonb;
    v_product  products%rowtype;
    v_qty      numeric;
    v_total    numeric := 0;
    v_name     text;
    v_phone    text;
    v_currency text;
    v_wave     text;
    v_address  text := nullif(btrim(coalesce(p_address, '')), '');
begin
    if auth.uid() is null then
        raise exception 'Sign in to order';
    end if;
    v_org := storefront_open(p_slug);
    if v_org is null then
        raise exception 'This shop is not taking orders';
    end if;
    if p_fulfilment not in ('pickup', 'delivery') then
        raise exception 'Unknown fulfilment: %', p_fulfilment;
    end if;
    if p_fulfilment = 'delivery' and v_address is null then
        raise exception 'A delivery needs an address';
    end if;
    if (p_drop_lat is null) <> (p_drop_lng is null) then
        raise exception 'A delivery pin needs both a latitude and a longitude';
    end if;
    if p_payment not in ('cash', 'wave') then
        raise exception 'Unknown payment method: %', p_payment;
    end if;
    select wave_merchant, default_currency into v_wave, v_currency
      from orgs where id = v_org;
    if p_payment = 'wave' and v_wave is null then
        raise exception 'This shop does not take Wave';
    end if;
    if p_lines is null or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'An order needs at least one article';
    end if;

    select coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''),
                    nullif(btrim(coalesce(full_name, '')), ''),
                    'Client'),
           phone
      into v_name, v_phone
      from profiles where id = auth.uid();

    insert into orders (org_id, customer_id, customer_name, phone,
                        fulfilment, note, address, currency, payment_method,
                        drop_lat, drop_lng)
    values (v_org, auth.uid(), v_name,
            coalesce(nullif(btrim(coalesce(p_phone, '')), ''), v_phone),
            p_fulfilment,
            nullif(btrim(coalesce(p_note, '')), ''),
            v_address,
            coalesce(v_currency, 'XOF'),
            p_payment,
            -- A pickup's destination is the shop; a pin on it is noise.
            case when p_fulfilment = 'delivery' then p_drop_lat end,
            case when p_fulfilment = 'delivery' then p_drop_lng end)
    returning id into v_id;

    for v_line in select * from jsonb_array_elements(p_lines) loop
        v_qty := (v_line->>'quantity')::numeric;
        if v_qty is null or v_qty <= 0 then
            raise exception 'A quantity must be positive';
        end if;
        select * into v_product
          from products
         where id = (v_line->>'product_id')::uuid
           and org_id = v_org
           and is_active
           and is_published;
        if not found then
            raise exception 'An article is not in this shop''s window';
        end if;
        insert into order_lines (order_id, product_id, name, unit_price, quantity)
        values (v_id, v_product.id, v_product.name,
                coalesce(v_product.sale_price, 0), v_qty);
        v_total := v_total + coalesce(v_product.sale_price, 0) * v_qty;
    end loop;

    update orders set total = v_total where id = v_id;

    begin
        perform notify_org_admins(
            v_org, 'new_order',
            'Nouvelle commande de ' || v_name || ' : '
            || to_char(v_total, 'FM999G999G999D00') || ' '
            || coalesce(v_currency, 'XOF')
            || case when p_payment = 'wave' then ' (Wave)' else '' end);
    exception when others then
        null;
    end;

    return v_id;
end;
$$;

-- ------------------------------------------------------------
-- Whoever sees the address sees the pin. Return types change: dropped,
-- recreated, re-granted — and drop-before-create keeps the bundle safe
-- to re-run over a database that is already ahead (the 052 lesson).
-- ------------------------------------------------------------
drop function if exists available_deliveries();
create function available_deliveries()
returns table (
    order_id       uuid,
    shop_name      text,
    shop_address   text,
    shop_lat       double precision,
    shop_lng       double precision,
    drop_address   text,
    drop_lat       double precision,
    drop_lng       double precision,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    payment_method text,
    paid_at        timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
    perform assert_approved_courier();
    return query
    select o.id, g.name, g.address, g.lat, g.lng,
           o.address, o.drop_lat, o.drop_lng, o.total, o.currency,
           o.created_at, o.payment_method, o.paid_at
      from orders o
      join orgs g on g.id = o.org_id
     where o.status = 'ready'
       and o.fulfilment = 'delivery'
       and o.courier_id is null
       and g.archived_at  is null
       and g.suspended_at is null
     order by o.created_at;
end;
$$;

drop function if exists courier_deliveries();
create function courier_deliveries()
returns table (
    order_id       uuid,
    shop_name      text,
    shop_address   text,
    shop_lat       double precision,
    shop_lng       double precision,
    customer_name  text,
    phone          text,
    drop_address   text,
    drop_lat       double precision,
    drop_lng       double precision,
    status         text,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    payment_method text,
    paid_at        timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
    perform assert_approved_courier();
    return query
    select o.id, g.name, g.address, g.lat, g.lng,
           o.customer_name, o.phone, o.address, o.drop_lat, o.drop_lng,
           o.status, o.total, o.currency, o.created_at,
           o.payment_method, o.paid_at
      from orders o
      join orgs g on g.id = o.org_id
     where o.courier_id = auth.uid()
     order by (o.status in ('ready', 'in_transit')) desc, o.created_at desc;
end;
$$;

drop function if exists shop_orders(uuid);
create function shop_orders(p_org_id uuid)
returns table (
    id             uuid,
    customer_name  text,
    phone          text,
    status         text,
    fulfilment     text,
    note           text,
    address        text,
    drop_lat       double precision,
    drop_lng       double precision,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    courier_name   text,
    payment_method text,
    paid_at        timestamptz,
    lines          jsonb
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
    if not is_org_member(p_org_id) then
        raise exception 'Only the shop sees its orders';
    end if;
    return query
    select o.id, o.customer_name, o.phone, o.status, o.fulfilment,
           o.note, o.address, o.drop_lat, o.drop_lng,
           o.total, o.currency, o.created_at,
           (select coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                            nullif(btrim(coalesce(p.full_name, '')), ''))
              from profiles p where p.id = o.courier_id),
           o.payment_method, o.paid_at,
           (select coalesce(jsonb_agg(jsonb_build_object(
                       'name', l.name, 'unit_price', l.unit_price,
                       'quantity', l.quantity) order by l.name), '[]'::jsonb)
              from order_lines l where l.order_id = o.id)
      from orders o
     where o.org_id = p_org_id
     order by (o.status in ('pending', 'accepted', 'ready', 'in_transit')) desc,
              o.created_at desc;
end;
$$;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function place_order(text, jsonb, text, text, text, text, text, double precision, double precision) to authenticated;
        grant execute on function available_deliveries() to authenticated;
        grant execute on function courier_deliveries()   to authenticated;
        grant execute on function shop_orders(uuid)      to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 059_product_search.sql
-- ============================================================
-- ============================================================
-- 059_product_search.sql — one search across every shop window.
--
-- A shopper knows what they want ("savon", "riz 25kg") before they know
-- which shop has it. So the street gets one question that looks through
-- every open vitrine at once and answers with articles, each naming its
-- shop — the opposite of the directory (053), which lists shops and lets
-- the shopper walk in.
--
-- Same posture as every street read (052): a SECURITY DEFINER function that
-- names its columns and is granted to anon, returning only what a window
-- shows — name, price, in stock or not, a photo, the shop and where it is.
-- Never a cost, a count, an unpublished article, or a shop that is closed,
-- suspended or archived.
--
-- Matching is accent-blind on purpose: names are typed by shopkeepers in
-- French, with and without accents ("Café" and "cafe" are the same word to
-- a shopper). Folding is done here with translate() rather than the
-- unaccent extension so the function carries no dependency the database
-- might not have.
-- ============================================================

-- Lower-case and strip the accents French product names actually carry.
-- Immutable, so it could back an index later if catalogues grow.
create or replace function fold_search_text(p_text text)
returns text
language sql
immutable
set search_path = public
as $$
    select translate(lower(coalesce(p_text, '')),
                     'àâäáãéèêëíîïóôöõúùûüçñ',
                     'aaaaaeeeeiiiooooouuuucn');
$$;

-- The search. Two letters at least — one letter is browsing, and browsing
-- is the directory's job. Fifty rows at most: a longer answer is a
-- catalogue, and the query can always be narrowed. Matches that start the
-- name come before matches buried in it; in stock comes before out; then
-- nearest, when the shopper said where they are; then the name itself.
create or replace function search_products(
    p_query text,
    p_lat   double precision default null,
    p_lng   double precision default null
)
returns table (
    id          uuid,
    name        text,
    sale_price  numeric,
    in_stock    boolean,
    photo_key   text,
    shop_name   text,
    shop_slug   text,
    currency    text,
    shop_lat    double precision,
    shop_lng    double precision,
    distance_km double precision
)
language sql
stable
security definer
set search_path = public
as $$
    with q as (
        -- Escape the pattern characters so a shopper typing "%" or "_"
        -- searches for those characters instead of everything.
        select fold_search_text(btrim(coalesce(p_query, ''))) as folded
    ),
    hits as (
        select p.id, p.name, p.sale_price, (p.quantity > 0) as in_stock,
               (select d.r2_key from documents d
                 where d.product_id = p.id
                 order by coalesce(d.captured_at, d.created_at) desc
                 limit 1) as photo_key,
               o.name as shop_name, o.slug as shop_slug,
               o.default_currency as currency,
               o.lat as shop_lat, o.lng as shop_lng,
               case
                   when p_lat is null or p_lng is null
                     or o.lat is null or o.lng is null then null
                   else 6371.0 * 2 * asin(sqrt(
                            power(sin(radians(o.lat - p_lat) / 2), 2)
                          + cos(radians(p_lat)) * cos(radians(o.lat))
                          * power(sin(radians(o.lng - p_lng) / 2), 2)))
               end as distance_km,
               position((select folded from q) in fold_search_text(p.name))
                   as hit_at
        from products p
        join orgs o on o.id = p.org_id
        where length((select folded from q)) >= 2
          and fold_search_text(p.name) like
              '%' || replace(replace(replace((select folded from q),
                    '\', '\\'), '%', '\%'), '_', '\_') || '%'
          and p.is_active
          and p.is_published
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    )
    select h.id, h.name, h.sale_price, h.in_stock, h.photo_key,
           h.shop_name, h.shop_slug, h.currency,
           h.shop_lat, h.shop_lng, h.distance_km
    from hits h
    order by (h.hit_at = 1) desc, h.in_stock desc,
             (h.distance_km is null), h.distance_km, h.name, h.shop_name
    limit 50;
$$;

-- ------------------------------------------------------------
-- Who may call what: the street asks, nobody writes
-- ------------------------------------------------------------
revoke execute on function fold_search_text(text) from public;
revoke execute on function search_products(text, double precision, double precision) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function search_products(text, double precision, double precision) to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function search_products(text, double precision, double precision) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 060_push_subscriptions.sql
-- ============================================================
-- ============================================================
-- 060_push_subscriptions.sql — where the bell can reach, when the app is closed.
--
-- The bell (030) writes one notifications row per recipient at the moments
-- worth interrupting somebody for — an order in, a delivery taken, a job on
-- the board. It rings only inside the app. A shopkeeper serving the counter
-- and a courier on a moto in traffic do not have the app open, so the ring
-- has to travel: Web Push, carried by the browser, delivered by a Worker
-- (workers/push) that a database webhook wakes on each notifications insert.
--
-- This migration is the address book that Worker reads: which browsers a
-- person has said "yes" in. One row per browser endpoint, owned by the
-- person, written only through save_push_subscription() as themselves.
--
-- Who reads it is the point. A push endpoint plus its keys lets anyone send
-- that browser notifications, so the rows are visible to their owner alone
-- under RLS, and the one function that hands them out (push_targets) is
-- executable by the service role only — the Worker's key, never the app's.
-- ============================================================

create table if not exists push_subscriptions (
    endpoint    text primary key,
    user_id     uuid not null references profiles(id) on delete cascade,
    p256dh      text not null,
    auth        text not null,
    user_agent  text,
    created_at  timestamptz not null default now(),
    last_seen   timestamptz not null default now()
);

create index if not exists push_subscriptions_by_user
    on push_subscriptions (user_id);

comment on table push_subscriptions is
    'Browsers that agreed to carry the bell. One row per endpoint, owned by '
    'the person; read out only by the push Worker through push_targets().';

alter table push_subscriptions enable row level security;

drop policy if exists push_subscriptions_own_select on push_subscriptions;
create policy push_subscriptions_own_select on push_subscriptions
    for select using (user_id = auth.uid());

drop policy if exists push_subscriptions_own_delete on push_subscriptions;
create policy push_subscriptions_own_delete on push_subscriptions
    for delete using (user_id = auth.uid());

-- ------------------------------------------------------------
-- The person says yes in this browser
-- ------------------------------------------------------------
-- An endpoint is unique to a browser profile and an origin; if one ever
-- reappears under another account (a shared phone, a sign-out and in) it
-- moves to the new owner rather than ringing the old one.
create or replace function save_push_subscription(
    p_endpoint   text,
    p_p256dh     text,
    p_auth       text,
    p_user_agent text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
    if auth.uid() is null then
        raise exception 'save_push_subscription() needs a signed-in caller';
    end if;
    if coalesce(p_endpoint, '') = '' or coalesce(p_p256dh, '') = ''
       or coalesce(p_auth, '') = '' then
        raise exception 'A push subscription needs an endpoint and both keys';
    end if;
    insert into push_subscriptions (endpoint, user_id, p256dh, auth, user_agent)
    values (p_endpoint, auth.uid(), p_p256dh, p_auth, left(p_user_agent, 200))
    on conflict (endpoint) do update
        set user_id = excluded.user_id,
            p256dh = excluded.p256dh,
            auth = excluded.auth,
            user_agent = excluded.user_agent,
            last_seen = now();
end;
$$;

-- The person says no again, in this browser.
create or replace function remove_push_subscription(p_endpoint text)
returns void
language sql
security definer
set search_path = public
as $$
    delete from push_subscriptions
     where endpoint = p_endpoint and user_id = auth.uid();
$$;

-- ------------------------------------------------------------
-- What the Worker reads, and what it cleans up
-- ------------------------------------------------------------
-- Service role only (see grants): the Worker asks "where can I reach this
-- person?" and gets endpoints and keys, nothing else about them.
create or replace function push_targets(p_recipient uuid)
returns table (endpoint text, p256dh text, auth text)
language sql
stable
security definer
set search_path = public
as $$
    select s.endpoint, s.p256dh, s.auth
      from push_subscriptions s
     where s.user_id = p_recipient;
$$;

-- A browser that answered 404 or 410 has unsubscribed behind our back;
-- the Worker drops it so the next ring does not knock on a closed door.
create or replace function remove_push_target(p_endpoint text)
returns void
language sql
security definer
set search_path = public
as $$
    delete from push_subscriptions where endpoint = p_endpoint;
$$;

-- ------------------------------------------------------------
-- Who may call what
-- ------------------------------------------------------------
revoke execute on function save_push_subscription(text, text, text, text) from public;
revoke execute on function remove_push_subscription(text)                  from public;
revoke execute on function push_targets(uuid)                              from public;
revoke execute on function remove_push_target(text)                        from public;

do $$
begin
    -- Supabase's default privileges grant every new function to anon and
    -- authenticated directly, not through public — so "revoke from public"
    -- alone would leave the address book readable by any signed-in person.
    -- Named, explicitly, for the two functions that must never reach them.
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function push_targets(uuid)       from anon;
        revoke execute on function remove_push_target(text) from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        revoke execute on function push_targets(uuid)       from authenticated;
        revoke execute on function remove_push_target(text) from authenticated;
        grant execute on function save_push_subscription(text, text, text, text) to authenticated;
        grant execute on function remove_push_subscription(text)                  to authenticated;
    end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then
        grant execute on function push_targets(uuid)       to service_role;
        grant execute on function remove_push_target(text) to service_role;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 061_delivery_fee.sql
-- ============================================================
-- ============================================================
-- 061_delivery_fee.sql — what a delivery costs, said before anyone commits.
--
-- A customer chose "livraison" without knowing the price; a courier took a
-- run without knowing what it paid. Ambiguity at the moment of commitment
-- is where orders die, so the fee is now a number, computed the way every
-- delivery market here settles on: a base for mounting the moto at all,
-- plus a rate per kilometre from the shop's pin to the customer's pin —
-- rounded to 25 F so cash changes hands cleanly.
--
--   * The platform sets the defaults (platform_settings); a shop may
--     override both numbers for itself (set_delivery_rates).
--   * delivery_fee() answers null, not a guess, when there is no pin on
--     either side or no rate for the shop's currency — the app then says
--     "à discuter" instead of inventing a price.
--   * The fee is fixed on the order at order time (orders.delivery_fee),
--     shown to the buyer inside the total before they send it, and to the
--     courier before they take it. It is paid to the courier in cash on
--     delivery, whatever the goods were paid with.
-- ============================================================

-- ------------------------------------------------------------
-- Platform defaults
-- ------------------------------------------------------------
create table if not exists platform_settings (
    key        text primary key,
    value      jsonb not null,
    updated_at timestamptz not null default now()
);
alter table platform_settings enable row level security;
-- No policies on purpose: read and written only through the functions
-- below, which run as their definer.

insert into platform_settings (key, value) values
    ('delivery_base',     '500'),
    ('delivery_per_km',   '150'),
    ('delivery_currency', '"XOF"')
on conflict (key) do nothing;

create or replace function set_platform_setting(p_key text, p_value jsonb)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
    if not exists (select 1 from profiles
                    where id = auth.uid() and is_platform_admin) then
        raise exception 'Only the platform can change its settings';
    end if;
    insert into platform_settings (key, value) values (p_key, p_value)
    on conflict (key) do update set value = excluded.value, updated_at = now();
end;
$$;

-- ------------------------------------------------------------
-- A shop's own rates, when it has them
-- ------------------------------------------------------------
alter table orgs add column if not exists delivery_base   numeric(12, 2);
alter table orgs add column if not exists delivery_per_km numeric(12, 2);
alter table orgs drop constraint if exists orgs_delivery_rates_positive;
alter table orgs add constraint orgs_delivery_rates_positive
    check ((delivery_base is null or delivery_base >= 0)
       and (delivery_per_km is null or delivery_per_km >= 0));
alter table orgs drop constraint if exists orgs_delivery_rates_pair;
alter table orgs add constraint orgs_delivery_rates_pair
    check ((delivery_base is null) = (delivery_per_km is null));

-- Both numbers or neither: null-null returns the shop to the platform's
-- defaults, which is what "I never thought about it" should mean.
create or replace function set_delivery_rates(
    p_org_id uuid,
    p_base   numeric,
    p_per_km numeric
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null then
        raise exception 'set_delivery_rates() needs a signed-in caller';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Only an administrator sets the delivery rates';
    end if;
    if (p_base is null) <> (p_per_km is null) then
        raise exception 'Delivery rates need both a base and a per-km amount';
    end if;
    if p_base < 0 or p_per_km < 0 then
        raise exception 'A delivery rate cannot be negative';
    end if;
    update orgs set delivery_base = p_base, delivery_per_km = p_per_km
     where id = p_org_id;
end;
$$;

-- ------------------------------------------------------------
-- The fee
-- ------------------------------------------------------------
-- Great-circle distance in km. The same haversine the directory uses,
-- named once so the fee and the courier's board agree to the metre.
create or replace function distance_km(
    lat1 double precision, lng1 double precision,
    lat2 double precision, lng2 double precision
)
returns double precision
language sql
immutable
as $$
    select 6371.0 * 2 * asin(sqrt(
               power(sin(radians(lat2 - lat1) / 2), 2)
             + cos(radians(lat1)) * cos(radians(lat2))
             * power(sin(radians(lng2 - lng1) / 2), 2)));
$$;

create or replace function delivery_fee(
    p_org_id uuid,
    p_lat    double precision,
    p_lng    double precision
)
returns numeric
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_org      orgs%rowtype;
    v_base     numeric;
    v_per_km   numeric;
    v_currency text;
    v_fee      numeric;
begin
    if p_lat is null or p_lng is null then
        return null;
    end if;
    select * into v_org from orgs where id = p_org_id;
    if not found or v_org.lat is null or v_org.lng is null then
        return null;
    end if;
    if v_org.delivery_base is not null then
        v_base   := v_org.delivery_base;
        v_per_km := v_org.delivery_per_km;
    else
        select (value #>> '{}')::text into v_currency
          from platform_settings where key = 'delivery_currency';
        if coalesce(v_org.default_currency, 'XOF') <> coalesce(v_currency, 'XOF') then
            return null; -- the platform's numbers are in another money
        end if;
        select (value #>> '{}')::numeric into v_base
          from platform_settings where key = 'delivery_base';
        select (value #>> '{}')::numeric into v_per_km
          from platform_settings where key = 'delivery_per_km';
        if v_base is null or v_per_km is null then
            return null;
        end if;
    end if;
    v_fee := v_base + v_per_km * distance_km(v_org.lat, v_org.lng, p_lat, p_lng);
    return round(v_fee / 25) * 25;
end;
$$;

-- The street's question, before ordering: "what would it cost to bring
-- this here?" Anyone may ask; the answer is a number or nothing.
create or replace function delivery_quote(
    p_slug text,
    p_lat  double precision,
    p_lng  double precision
)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
    select delivery_fee(storefront_open(p_slug), p_lat, p_lng);
$$;

-- ------------------------------------------------------------
-- The fee on the order, fixed when it is placed
-- ------------------------------------------------------------
alter table orders add column if not exists delivery_fee numeric(12, 2);

-- Same signature as 058 (the return type does not change), so create or
-- replace is right here; the body gains the fee.
create or replace function place_order(
    p_slug       text,
    p_lines      jsonb,
    p_fulfilment text default 'pickup',
    p_note       text default null,
    p_address    text default null,
    p_phone      text default null,
    p_payment    text default 'cash',
    p_drop_lat   double precision default null,
    p_drop_lng   double precision default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org      uuid;
    v_id       uuid;
    v_line     jsonb;
    v_product  products%rowtype;
    v_qty      numeric;
    v_total    numeric := 0;
    v_name     text;
    v_phone    text;
    v_currency text;
    v_wave     text;
    v_fee      numeric;
    v_address  text := nullif(btrim(coalesce(p_address, '')), '');
begin
    if auth.uid() is null then
        raise exception 'Sign in to order';
    end if;
    v_org := storefront_open(p_slug);
    if v_org is null then
        raise exception 'This shop is not taking orders';
    end if;
    if p_fulfilment not in ('pickup', 'delivery') then
        raise exception 'Unknown fulfilment: %', p_fulfilment;
    end if;
    if p_fulfilment = 'delivery' and v_address is null then
        raise exception 'A delivery needs an address';
    end if;
    if (p_drop_lat is null) <> (p_drop_lng is null) then
        raise exception 'A delivery pin needs both a latitude and a longitude';
    end if;
    if p_payment not in ('cash', 'wave') then
        raise exception 'Unknown payment method: %', p_payment;
    end if;
    select wave_merchant, default_currency into v_wave, v_currency
      from orgs where id = v_org;
    if p_payment = 'wave' and v_wave is null then
        raise exception 'This shop does not take Wave';
    end if;
    if p_lines is null or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'An order needs at least one article';
    end if;

    select coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''),
                    nullif(btrim(coalesce(full_name, '')), ''),
                    'Client'),
           phone
      into v_name, v_phone
      from profiles where id = auth.uid();

    -- The fee is fixed now, from the pin the customer gave: a rate
    -- changed tomorrow does not change what was agreed today.
    if p_fulfilment = 'delivery' then
        v_fee := delivery_fee(v_org, p_drop_lat, p_drop_lng);
    end if;

    insert into orders (org_id, customer_id, customer_name, phone,
                        fulfilment, note, address, currency, payment_method,
                        drop_lat, drop_lng, delivery_fee)
    values (v_org, auth.uid(), v_name,
            coalesce(nullif(btrim(coalesce(p_phone, '')), ''), v_phone),
            p_fulfilment,
            nullif(btrim(coalesce(p_note, '')), ''),
            v_address,
            coalesce(v_currency, 'XOF'),
            p_payment,
            case when p_fulfilment = 'delivery' then p_drop_lat end,
            case when p_fulfilment = 'delivery' then p_drop_lng end,
            v_fee)
    returning id into v_id;

    for v_line in select * from jsonb_array_elements(p_lines) loop
        v_qty := (v_line->>'quantity')::numeric;
        if v_qty is null or v_qty <= 0 then
            raise exception 'A quantity must be positive';
        end if;
        select * into v_product
          from products
         where id = (v_line->>'product_id')::uuid
           and org_id = v_org
           and is_active
           and is_published;
        if not found then
            raise exception 'An article is not in this shop''s window';
        end if;
        insert into order_lines (order_id, product_id, name, unit_price, quantity)
        values (v_id, v_product.id, v_product.name,
                coalesce(v_product.sale_price, 0), v_qty);
        v_total := v_total + coalesce(v_product.sale_price, 0) * v_qty;
    end loop;

    update orders set total = v_total where id = v_id;

    begin
        perform notify_org_admins(
            v_org, 'new_order',
            'Nouvelle commande de ' || v_name || ' : '
            || to_char(v_total, 'FM999G999G999D00') || ' '
            || coalesce(v_currency, 'XOF')
            || case when p_payment = 'wave' then ' (Wave)' else '' end
            || case when v_fee is not null
                    then ' + livraison ' || to_char(v_fee, 'FM999G999G999') else '' end);
    exception when others then
        null;
    end;

    return v_id;
end;
$$;

-- ------------------------------------------------------------
-- Everyone who sees an order sees its fee. Return types grow: dropped,
-- recreated, re-granted (the 052 lesson).
-- ------------------------------------------------------------
drop function if exists my_orders();
create function my_orders()
returns table (
    id             uuid,
    org_id         uuid,
    shop_name      text,
    shop_slug      text,
    status         text,
    fulfilment     text,
    note           text,
    address        text,
    phone          text,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    courier_name   text,
    payment_method text,
    paid_at        timestamptz,
    shop_wave      text,
    delivery_fee   numeric,
    lines          jsonb
)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.org_id, g.name, g.slug, o.status, o.fulfilment,
           o.note, o.address, o.phone, o.total, o.currency, o.created_at,
           (select coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                            nullif(btrim(coalesce(p.full_name, '')), ''))
              from profiles p where p.id = o.courier_id),
           o.payment_method, o.paid_at, g.wave_merchant, o.delivery_fee,
           (select coalesce(jsonb_agg(jsonb_build_object(
                       'name', l.name, 'unit_price', l.unit_price,
                       'quantity', l.quantity) order by l.name), '[]'::jsonb)
              from order_lines l where l.order_id = o.id)
      from orders o
      join orgs g on g.id = o.org_id
     where o.customer_id = auth.uid()
     order by (o.status in ('pending', 'accepted', 'ready', 'in_transit')) desc,
              o.created_at desc;
$$;

drop function if exists shop_orders(uuid);
create function shop_orders(p_org_id uuid)
returns table (
    id             uuid,
    customer_name  text,
    phone          text,
    status         text,
    fulfilment     text,
    note           text,
    address        text,
    drop_lat       double precision,
    drop_lng       double precision,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    courier_name   text,
    payment_method text,
    paid_at        timestamptz,
    delivery_fee   numeric,
    lines          jsonb
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
    if not is_org_member(p_org_id) then
        raise exception 'Only the shop sees its orders';
    end if;
    return query
    select o.id, o.customer_name, o.phone, o.status, o.fulfilment,
           o.note, o.address, o.drop_lat, o.drop_lng,
           o.total, o.currency, o.created_at,
           (select coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                            nullif(btrim(coalesce(p.full_name, '')), ''))
              from profiles p where p.id = o.courier_id),
           o.payment_method, o.paid_at, o.delivery_fee,
           (select coalesce(jsonb_agg(jsonb_build_object(
                       'name', l.name, 'unit_price', l.unit_price,
                       'quantity', l.quantity) order by l.name), '[]'::jsonb)
              from order_lines l where l.order_id = o.id)
      from orders o
     where o.org_id = p_org_id
     order by (o.status in ('pending', 'accepted', 'ready', 'in_transit')) desc,
              o.created_at desc;
end;
$$;

drop function if exists available_deliveries();
create function available_deliveries()
returns table (
    order_id       uuid,
    shop_name      text,
    shop_address   text,
    shop_lat       double precision,
    shop_lng       double precision,
    drop_address   text,
    drop_lat       double precision,
    drop_lng       double precision,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    payment_method text,
    paid_at        timestamptz,
    delivery_fee   numeric,
    distance_km    double precision
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
    perform assert_approved_courier();
    return query
    select o.id, g.name, g.address, g.lat, g.lng,
           o.address, o.drop_lat, o.drop_lng, o.total, o.currency,
           o.created_at, o.payment_method, o.paid_at, o.delivery_fee,
           case when g.lat is null or o.drop_lat is null then null
                else distance_km(g.lat, g.lng, o.drop_lat, o.drop_lng) end
      from orders o
      join orgs g on g.id = o.org_id
     where o.status = 'ready'
       and o.fulfilment = 'delivery'
       and o.courier_id is null
       and g.archived_at  is null
       and g.suspended_at is null
     order by o.created_at;
end;
$$;

drop function if exists courier_deliveries();
create function courier_deliveries()
returns table (
    order_id       uuid,
    shop_name      text,
    shop_address   text,
    shop_lat       double precision,
    shop_lng       double precision,
    customer_name  text,
    phone          text,
    drop_address   text,
    drop_lat       double precision,
    drop_lng       double precision,
    status         text,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    payment_method text,
    paid_at        timestamptz,
    delivery_fee   numeric,
    distance_km    double precision
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
    perform assert_approved_courier();
    return query
    select o.id, g.name, g.address, g.lat, g.lng,
           o.customer_name, o.phone, o.address, o.drop_lat, o.drop_lng,
           o.status, o.total, o.currency, o.created_at,
           o.payment_method, o.paid_at, o.delivery_fee,
           case when g.lat is null or o.drop_lat is null then null
                else distance_km(g.lat, g.lng, o.drop_lat, o.drop_lng) end
      from orders o
      join orgs g on g.id = o.org_id
     where o.courier_id = auth.uid()
     order by (o.status in ('ready', 'in_transit')) desc, o.created_at desc;
end;
$$;

-- ------------------------------------------------------------
-- Who may call what
-- ------------------------------------------------------------
revoke execute on function set_platform_setting(text, jsonb)                 from public;
revoke execute on function set_delivery_rates(uuid, numeric, numeric)        from public;
revoke execute on function delivery_fee(uuid, double precision, double precision)   from public;
revoke execute on function delivery_quote(text, double precision, double precision) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function delivery_quote(text, double precision, double precision) to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_platform_setting(text, jsonb)                 to authenticated;
        grant execute on function set_delivery_rates(uuid, numeric, numeric)        to authenticated;
        grant execute on function delivery_quote(text, double precision, double precision) to authenticated;
        grant execute on function place_order(text, jsonb, text, text, text, text, text, double precision, double precision) to authenticated;
        grant execute on function my_orders()            to authenticated;
        grant execute on function shop_orders(uuid)      to authenticated;
        grant execute on function available_deliveries() to authenticated;
        grant execute on function courier_deliveries()   to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 062_courier_earnings.sql
-- ============================================================
-- ============================================================
-- 062_courier_earnings.sql — what the courier has earned, at a glance.
--
-- The single most motivating screen in every courier app is the one that
-- says what today paid. Three rows — today, this week, this month — each
-- with the courses delivered, the fees they carried (061) and the
-- kilometres ridden (shop pin to door pin, the distance the fee was
-- priced on). Read by the courier about themselves alone: the function
-- runs as its definer but filters on auth.uid(), and refuses anyone who
-- is not an approved courier, like every other courier read (056).
--
-- "Delivered" is the status the courier set, and updated_at is when they
-- set it (056 stamps it on every status move), so a course counts on the
-- day it was finished, not the day it was ordered. Days are Ouagadougou
-- days, not UTC ones: a course at 23:30 belongs to the evening it was
-- ridden.
-- ============================================================

-- Dropped first, not replaced: 067 widens this row with the platform's
-- share, and a `create or replace` cannot narrow a return table back
-- (42P13) — which is what re-running the bundle on a database already at
-- 067 would do here.
drop function if exists courier_earnings();
create function courier_earnings()
returns table (
    period   text,
    courses  int,
    fees     numeric,
    km       double precision
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_now   timestamptz := now();
    v_today date := (v_now at time zone 'Africa/Ouagadougou')::date;
begin
    perform assert_approved_courier();
    return query
    with done as (
        select o.delivery_fee,
               case when g.lat is null or o.drop_lat is null then null
                    else distance_km(g.lat, g.lng, o.drop_lat, o.drop_lng) end as km,
               (o.updated_at at time zone 'Africa/Ouagadougou')::date as day
          from orders o
          join orgs g on g.id = o.org_id
         where o.courier_id = auth.uid()
           and o.status = 'delivered'
    ),
    spans as (
        select 'today' as period, v_today as since
        union all select 'week',  v_today - ((extract(isodow from v_today)::int) - 1)
        union all select 'month', date_trunc('month', v_today)::date
    )
    select s.period,
           count(d.day)::int,
           coalesce(sum(d.delivery_fee), 0)::numeric,
           coalesce(sum(d.km), 0)::double precision
      from spans s
      left join done d on d.day >= s.since and d.day <= v_today
     group by s.period, s.since
     order by s.since desc;
end;
$$;

revoke execute on function courier_earnings() from public;
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function courier_earnings() to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 063_least_privilege.sql
-- ============================================================
-- ============================================================
-- 063_least_privilege.sql — the street may look, nobody else may knock.
--
-- Supabase grants EXECUTE on every new function to anon, authenticated and
-- service_role by default (pg_default_acl for postgres in public), and
-- Postgres itself grants it to PUBLIC. So every SECURITY DEFINER function
-- this project ever wrote — shop_orders, courier_mark, delete_org, all 150
-- of them — has been callable with the public key and no session. Each
-- one checks auth.uid() and refuses a stranger, so nothing leaked; but a
-- refusal inside the function is one line of plpgsql away from a leak,
-- and the linter (0028) is right to flag it. Defence in depth: the
-- database should refuse at the door, before the function runs.
--
-- Two moves, both dynamic so they cover what exists and re-run clean:
--
--   1. Every SECURITY DEFINER function in public loses EXECUTE for PUBLIC
--      and anon, and keeps it explicitly for authenticated and
--      service_role — except the street: the storefront readers, the
--      search, the delivery quote, the photo check the uploads Worker
--      makes with the public key, and the invitation preview a person
--      reads before they have an account. Those are the whole public
--      surface, listed by name below; place_order is not among them
--      because it already requires a session (055).
--
--   2. Default privileges change so the next function is born without
--      anon or PUBLIC execute. A future migration grants what it means to
--      grant, as this project's already do.
--
-- One family is deliberately left open besides the street: the handful of
-- helpers RLS policies call (is_org_member, is_org_admin, can_write_org,
-- has_full_visibility, feature_access, my_org_ids). A policy runs its
-- expression as the caller, so those must be executable by anon for a
-- stranger's select to come back empty instead of erroring. They are
-- found from pg_policy at run time, not listed by hand.
--
-- And the search_path linter (0011): the 28 SECURITY INVOKER helpers
-- written without `set search_path` get `public`, the same setting every
-- definer function here already carries. A function whose search path
-- follows the caller's can be pointed at a shadowing schema; pinning it
-- costs nothing. Extension-owned functions are left alone.
--
-- Roles are guarded because the test cluster creates anon and
-- authenticated lazily, per suite; on Supabase all three exist.
-- ============================================================

do $$
declare
    -- The public surface: what a stranger with the publishable key may run.
    v_street constant text[] := array[
        'storefront',
        'storefront_products',
        'storefront_featured',
        'storefront_directory',
        'storefront_open',
        'storefront_photo_allowed',
        'search_products',
        'delivery_quote',
        'delivery_check',      -- 069: the basket's "how far, how far may it go"
        'storefront_previews', -- 070: three articles per card in the directory
        'record_visit',          -- 071: the street counts what it sees
        'record_seen',           -- 071: the strip, counted in one call
        'storefront_spotlights', -- 071: the shops paying for the top of the list
        'invitation_preview'
    ];
    -- The functions RLS itself calls. A policy expression runs as the
    -- caller, so is_org_member() and its kin must stay executable by every
    -- role a policy can apply to — anon included: a stranger reading orgs
    -- gets an empty answer through the policy, and a revoked helper would
    -- turn that into "permission denied for function is_org_admin" on a
    -- plain select. Found from the policies rather than listed, so a
    -- helper added later is covered the day a policy uses it.
    v_policy_fns text[] := (
        with refs as (
            select pg_get_expr(polqual, polrelid) as e from pg_policy
            union all
            select pg_get_expr(polwithcheck, polrelid) from pg_policy
            union all
            select pg_get_viewdef(c.oid)
              from pg_class c join pg_namespace n on n.oid = c.relnamespace
             where n.nspname = 'public' and c.relkind = 'v'
        )
        select coalesce(array_agg(distinct m[1]), '{}')
          from refs, regexp_matches(e, '([a-z_]+)\(', 'g') m
    );
    v_has_anon    boolean := exists (select 1 from pg_roles where rolname = 'anon');
    v_has_auth    boolean := exists (select 1 from pg_roles where rolname = 'authenticated');
    v_has_service boolean := exists (select 1 from pg_roles where rolname = 'service_role');
    r record;
    v_sig text;
begin
    for r in
        select p.oid, p.proname
          from pg_proc p
          join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public'
           and p.prokind = 'f'
           and p.prosecdef
           and not exists (select 1 from pg_depend d
                            where d.objid = p.oid and d.deptype = 'e')
    loop
        v_sig := r.oid::regprocedure::text;
        if r.proname = any (v_street) or r.proname = any (v_policy_fns) then
            -- The street and the policy helpers stay open, and are said so
            -- here rather than left to the grants of 052–061: on a cluster
            -- where anon was created after those ran (the test cluster),
            -- this is what opens them.
            if v_has_anon then
                execute format('grant execute on function %s to anon', v_sig);
            end if;
            if v_has_auth then
                execute format('grant execute on function %s to authenticated', v_sig);
            end if;
            continue;
        end if;
        execute format('revoke execute on function %s from public', v_sig);
        if v_has_anon then
            execute format('revoke execute on function %s from anon', v_sig);
        end if;
        if v_has_auth then
            execute format('grant execute on function %s to authenticated', v_sig);
        end if;
        if v_has_service then
            execute format('grant execute on function %s to service_role', v_sig);
        end if;
    end loop;

    -- push_targets and remove_push_target (060) are service-role only and
    -- must stay that way: the loop above re-granted authenticated to every
    -- definer function, so take it back from these two.
    if v_has_auth then
        revoke execute on function push_targets(uuid) from authenticated;
        revoke execute on function remove_push_target(text) from authenticated;
    end if;

    -- The next function is born closed to the street. PUBLIC's execute
    -- comes from Postgres's built-in defaults, and a schema-scoped entry
    -- can only add to those, never take from them — so that one revoke is
    -- global (for this role, every schema); the rest stay in public.
    alter default privileges revoke execute on functions from public;
    if v_has_anon then
        alter default privileges in schema public revoke execute on functions from anon;
    end if;
    if v_has_auth then
        alter default privileges in schema public grant execute on functions to authenticated;
    end if;
    if v_has_service then
        alter default privileges in schema public grant execute on functions to service_role;
    end if;

    -- A pinned search path for every project function that lacked one.
    for r in
        select p.oid
          from pg_proc p
          join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'public'
           and p.prokind = 'f'
           and not exists (select 1 from pg_depend d
                            where d.objid = p.oid and d.deptype = 'e')
           and not coalesce((select true from unnest(p.proconfig) c
                              where c like 'search_path=%'), false)
    loop
        execute format('alter function %s set search_path = public',
                       r.oid::regprocedure::text);
    end loop;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 064_product_description.sql
-- ============================================================
-- ============================================================
-- 064_product_description.sql — a few words under the article, for the street.
--
-- The owner, looking at the vitrine: "there is no description of the
-- product." A name and a price sell sugar; they do not sell a cake, a
-- pagne or a phone — the shopper needs the two lines a shopkeeper would
-- say across the counter: what size, what taste, where from. One optional
-- text on the article, written by the shop, shown on the vitrine under the
-- name. Short by constraint: 300 characters is two honest sentences, and
-- a tile that scrolls is a tile nobody reads.
--
-- storefront_products() grows a column, so it is dropped and recreated
-- (a `create or replace` cannot change a function's return table — the
-- 42P13 every reader here has met once). Since 063 a new function is born
-- closed to the street, so the grant to anon is said again, explicitly.
-- ============================================================

alter table products add column if not exists description text;

alter table products drop constraint if exists products_description_length;
alter table products add constraint products_description_length
    check (description is null or char_length(description) <= 300);

drop function if exists storefront_products(text);
create function storefront_products(p_slug text)
returns table (
    id          uuid,
    name        text,
    sale_price  numeric,
    in_stock    boolean,
    photo_key   text,
    description text
)
language sql
stable
security definer
set search_path = public
as $$
    select p.id, p.name, p.sale_price, (p.quantity > 0),
           (select d.r2_key from documents d
             where d.product_id = p.id
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1),
           nullif(btrim(p.description), '')
    from products p
    where p.org_id = storefront_open(p_slug)
      and p.is_active
      and p.is_published
    order by p.name;
$$;

revoke execute on function storefront_products(text) from public;
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function storefront_products(text) to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function storefront_products(text) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 065_org_plan.sql
-- ============================================================
-- ============================================================
-- 065_org_plan.sql — which plan a business is on, and until when.
--
-- M10 block 1. Two plans, not three: 'free' (Kaj, forever) and 'pro' (Kaj
-- Pro, paid). This migration is only the flag and who may set it — no tool
-- is gated yet (that is 066), no money moves (that is by hand, then M9).
-- Shipping the flag alone first means the console can already record who
-- paid before anyone is asked to.
--
-- The rules, all of them here:
--   * plan_until is the paid-until date. Null means no end (a gift, a
--     partner, a test business). A Pro business past its date reads as
--     'free' — org_plan() is the one place that decides — and nothing else
--     happens to it: no cliff, no read-only, nothing deleted. Lapsing Pro
--     is Free, exactly as it was before it paid.
--   * Only the platform sets a plan. SECURITY DEFINER like set_org_suspended
--     (049), and for the same reason: it writes a column RLS would rightly
--     refuse to a non-member, and the platform admin is a member of nothing.
--   * The change is in the activity log for free: orgs carries the 008
--     audit trigger, so the row's diff (plan, plan_until, plan_note) lands
--     in audit_log with the platform admin as actor. Nothing to add.
--   * my_orgs() carries the effective plan so the app knows it offline,
--     from the cached org list, the way it knows a suspension.
--   * platform_overview() counts the Pro businesses, and search_orgs()
--     lists them behind a tile — the console's first revenue number.
--
-- Since 063 a new function is born closed to anon; both of these are for
-- signed-in callers only, so the grant to authenticated is all they need.
-- ============================================================

alter table orgs add column if not exists plan text not null default 'free';
alter table orgs add column if not exists plan_until date;
alter table orgs add column if not exists plan_note text;

alter table orgs drop constraint if exists orgs_plan_known;
alter table orgs add constraint orgs_plan_known check (plan in ('free', 'pro'));

comment on column orgs.plan is
    'The plan the platform set: free or pro. Read through org_plan(), which '
    'also applies plan_until; never read raw for a gate.';
comment on column orgs.plan_until is
    'Paid until, inclusive. Null = no end. Past this date a pro business '
    'reads as free — nothing else changes.';
comment on column orgs.plan_note is
    'Why, for the platform: "Wave 25 000 F le 12/09", "partenaire", "test".';

-- The one place the effective plan is decided. Unknown business: free.
create or replace function org_plan(p_org_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select case
        when o.plan = 'pro'
         and (o.plan_until is null
              or o.plan_until >= (now() at time zone 'Africa/Ouagadougou')::date)
        then 'pro'
        else 'free'
    end
    from orgs o
    where o.id = p_org_id
    union all
    select 'free'
    where not exists (select 1 from orgs where id = p_org_id)
    limit 1;
$$;

-- Set or change a plan. Platform admin only. Re-runnable: setting the same
-- plan again with the same date is a no-op the audit trigger also ignores.
create or replace function set_org_plan(
    p_org_id uuid,
    p_plan   text,
    p_until  date default null,
    p_note   text default null
)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles
                   where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can set a business''s plan';
    end if;
    if not exists (select 1 from orgs where id = p_org_id) then
        raise exception 'No such business';
    end if;
    if p_plan not in ('free', 'pro') then
        raise exception 'Unknown plan: %', p_plan;
    end if;

    update orgs
       set plan       = p_plan,
           -- A date on a free plan means nothing; do not keep one.
           plan_until = case when p_plan = 'pro' then p_until else null end,
           plan_note  = nullif(btrim(coalesce(p_note, '')), '')
     where id = p_org_id;
end;
$$;

-- my_orgs() carries the effective plan. 049 verbatim plus the column; the
-- return type changes, so it is dropped and recreated.
drop function if exists my_orgs();

create function my_orgs()
returns table (
    org_id           uuid,
    name             text,
    slug             text,
    profile          text,
    default_currency text,
    roles            text[],
    visibility       text,
    theme            text,
    suspended        boolean,
    plan             text
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array['platform_admin'::text],
        'full'::text,
        o.theme,
        (o.suspended_at is not null),
        org_plan(o.id)
    from orgs o
    where exists(select 1 from profiles where id = auth.uid() and is_platform_admin)

    union all

    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array_agg(distinct m.role::text order by m.role::text),
        case when bool_or(m.visibility = 'full') then 'full' else 'summary' end,
        o.theme,
        (o.suspended_at is not null),
        org_plan(o.id)
    from memberships m
    join orgs o on o.id = m.org_id
    where m.user_id = auth.uid()
      and o.archived_at is null
      and not exists(select 1 from profiles where id = auth.uid() and is_platform_admin)
    group by o.id, o.name, o.slug, o.profile, o.default_currency, o.theme,
             o.suspended_at

    order by name;
$$;

-- platform_overview() gains the Pro count. 021 verbatim plus the column;
-- the return type changes, so it is dropped and recreated.
drop function if exists platform_overview();

create function platform_overview()
returns table (
    total          int,
    active         int,
    archived       int,
    farms          int,
    shops          int,
    churches       int,
    other_profiles int,
    new_this_week  int,
    active_7d      int,
    silent_30d     int,
    never_active   int,
    pro            int
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not exists (
        select 1 from profiles where id = auth.uid() and is_platform_admin
    ) then
        raise exception 'Only a platform admin can read the platform overview';
    end if;

    return query
    select
        count(*)::int,
        count(*) filter (where o.archived_at is null)::int,
        count(*) filter (where o.archived_at is not null)::int,
        count(*) filter (where o.profile = 'farm')::int,
        count(*) filter (where o.profile = 'retail')::int,
        count(*) filter (where o.profile = 'church')::int,
        count(*) filter (where o.profile not in ('farm','retail','church'))::int,
        count(*) filter (where o.created_at > now() - interval '7 days')::int,
        count(*) filter (where o.last_activity_at > now() - interval '7 days')::int,
        -- The churn signal: alive once, silent for a month.
        count(*) filter (
            where o.archived_at is null
              and o.last_activity_at is not null
              and o.last_activity_at < now() - interval '30 days')::int,
        -- Onboarded and never used. A different failure, and a different fix:
        -- this one belongs to whoever signed them up.
        count(*) filter (
            where o.archived_at is null and o.last_activity_at is null)::int,
        -- Paying today: the effective plan, so a lapsed Pro is not counted.
        count(*) filter (
            where o.archived_at is null and org_plan(o.id) = 'pro')::int
    from orgs o;
end;
$$;

-- search_orgs() learns one more activity filter, 'pro', so the console's
-- Pro tile opens onto the businesses behind the number. 021 verbatim plus
-- that one branch; same return type, so replaced in place.
create or replace function search_orgs(
    p_query    text    default null,
    p_profile  text    default null,   -- 'farm' | 'retail' | 'church' | null
    p_status   text    default 'active', -- 'active' | 'archived' | 'all'
    p_activity text    default null,   -- 'active7' | 'silent30' | 'never' | 'pro'
    p_sort     text    default 'activity', -- 'activity' | 'name' | 'newest'
    p_limit    int     default 50,
    p_offset   int     default 0
)
returns table (
    org_id           uuid,
    name             text,
    slug             text,
    profile          text,
    currency         text,
    archived_at      timestamptz,
    created_at       timestamptz,
    last_activity_at timestamptz,
    member_count     int,
    total_count      int
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_limit  int := least(greatest(coalesce(p_limit, 50), 1), 200);
    v_offset int := greatest(coalesce(p_offset, 0), 0);
    v_query  text := nullif(btrim(coalesce(p_query, '')), '');
begin
    if not exists (
        select 1 from profiles where id = auth.uid() and is_platform_admin
    ) then
        raise exception 'Only a platform admin can search every business';
    end if;

    return query
    with filtered as (
        select o.id, o.name, o.slug, o.profile, o.default_currency,
               o.archived_at, o.created_at, o.last_activity_at,
               count(*) over () as total
        from orgs o
        where
            -- Status
            (   coalesce(p_status, 'active') = 'all'
             or (p_status = 'archived' and o.archived_at is not null)
             or (coalesce(p_status, 'active') = 'active' and o.archived_at is null))
            -- Profile
        and (p_profile is null or o.profile = p_profile)
            -- Activity
        and (   p_activity is null
             or (p_activity = 'active7'
                 and o.last_activity_at > now() - interval '7 days')
             or (p_activity = 'silent30'
                 and o.last_activity_at is not null
                 and o.last_activity_at < now() - interval '30 days')
             or (p_activity = 'never' and o.last_activity_at is null)
             or (p_activity = 'pro' and org_plan(o.id) = 'pro'))
            -- Text: name or slug. Both lowered, so case never matters.
        and (   v_query is null
             or lower(o.name) like '%' || lower(v_query) || '%'
             or lower(o.slug) like '%' || lower(v_query) || '%')
        order by
            case when p_sort = 'name'   then lower(o.name) end asc,
            case when p_sort = 'newest' then o.created_at  end desc,
            -- Default: the businesses that have done something most recently,
            -- with the never-active ones last rather than first — a null is
            -- not "the most recent".
            case when coalesce(p_sort, 'activity') = 'activity'
                 then o.last_activity_at end desc nulls last,
            lower(o.name) asc
        limit v_limit offset v_offset
    )
    -- Only the page pays for this. That is the whole point of the CTE.
    select f.id, f.name, f.slug, f.profile, f.default_currency,
           f.archived_at, f.created_at, f.last_activity_at,
           (select count(*)::int from memberships m where m.org_id = f.id),
           f.total::int
    from filtered f;
end;
$$;

revoke execute on function org_plan(uuid)                          from public;
revoke execute on function set_org_plan(uuid, text, date, text)    from public;
revoke execute on function my_orgs()                               from public;
revoke execute on function platform_overview()                     from public;
revoke execute on function search_orgs(text, text, text, text, text, int, int) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function org_plan(uuid)                       to authenticated;
        grant execute on function set_org_plan(uuid, text, date, text) to authenticated;
        grant execute on function my_orgs()                            to authenticated;
        grant execute on function platform_overview()                  to authenticated;
        grant execute on function search_orgs(text, text, text, text, text, int, int)
            to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 066_pro_gates.sql
-- ============================================================
-- ============================================================
-- 066_pro_gates.sql — where the line between Kaj and Kaj Pro is drawn, and held.
--
-- M10 block 2. 065 said which plan a business is on; this says what that
-- changes. The line itself lives in platform_settings, not in code, so it
-- moves without a migration: which tools are Pro, how many staff, invoices
-- a month and photos a Free business gets, and what Pro costs.
--
-- The rules:
--   * A Pro tool on a Free business answers 'view', never 'hidden'. The
--     owner keeps seeing the tool, greyed, with what it would give them.
--     The layer sits AFTER the owner's dial (031) and only ever lowers
--     'edit' to 'view' — a dial that says 'hidden' still wins below it.
--   * The platform admin is never gated: they run the platform.
--   * Enforced where it is cheap and matters: writes. Payroll (shifts,
--     staff_payments) and tontines get the 031 guard trigger with a Pro
--     message; the owner's dial (org_feature_rules) and the currency rates
--     demand 'edit' in their write policies; the three caps are BEFORE
--     INSERT triggers on memberships, invoices and documents, catching
--     every path that writes those rows without redefining any function.
--   * Read-only Pro tools (analytics, the accounting hub) are gated in the
--     app in this block. A signed-in owner who calls those functions by
--     hand reads their own figures; nobody reads anyone else's. Block 5
--     revisits this once money moves through the platform.
--   * Every refusal for the plan's reason starts with "Kaj Pro :" — the
--     app reads that prefix and opens the door to pay instead of an error.
--   * "J'ai payé" is a row in plan_requests the console lists; the platform
--     checks its Wave app and sets the plan (065). No money moves here.
--
-- Since 063 a new function is born closed to anon; the grants below say
-- exactly who may call what. feature_access() is a policy helper and keeps
-- the grants it has — `create or replace` preserves them.
-- ============================================================

-- ------------------------------------------------------------
-- 1. THE LINE, AS SETTINGS
-- ------------------------------------------------------------
insert into platform_settings (key, value) values
    ('pro_features',            '["payroll","team_access","analytics","accounting","currencies","tontines"]'),
    ('free_max_staff',          '3'),
    ('free_max_invoices_month', '20'),
    ('free_max_photos',         '50'),
    ('free_history_months',     '12'),
    ('pro_price_month',         '2500'),
    ('pro_price_year',          '25000'),
    ('pro_currency',            '"XOF"'),
    -- The number the owner pays to. Empty until the platform sets it from
    -- the console: a paywall with no number says "contact us" instead.
    ('platform_wave',           '""'),
    ('platform_wave_name',      '""')
on conflict (key) do nothing;

create or replace function plan_setting(p_key text)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select value from platform_settings where key = p_key;
$$;

create or replace function plan_limit(p_key text, p_default int)
returns int
language sql
stable
security definer
set search_path = public
as $$
    select coalesce(
        nullif(plan_setting(p_key) #>> '{}', '')::int,
        p_default);
$$;

-- Everything the paywall and the badges need, in one round trip. The prices
-- and the Wave number are public by nature — they are what the owner is
-- asked to pay and where — so any signed-in caller may read them.
create or replace function plan_terms()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'pro_features',            coalesce(plan_setting('pro_features'), '[]'::jsonb),
        'free_max_staff',          plan_limit('free_max_staff', 3),
        'free_max_invoices_month', plan_limit('free_max_invoices_month', 20),
        'free_max_photos',         plan_limit('free_max_photos', 50),
        'free_history_months',     plan_limit('free_history_months', 12),
        'pro_price_month',         plan_limit('pro_price_month', 2500),
        'pro_price_year',          plan_limit('pro_price_year', 25000),
        'pro_currency',            coalesce(plan_setting('pro_currency') #>> '{}', 'XOF'),
        'platform_wave',           coalesce(plan_setting('platform_wave') #>> '{}', ''),
        'platform_wave_name',      coalesce(plan_setting('platform_wave_name') #>> '{}', '')
    );
$$;

-- Is this tool behind the plan for this business right now? True only when
-- the business is Free and the tool is on the Pro list. The platform admin
-- and a caller with no session (a suite as postgres, a server job) are
-- never gated, exactly as feature_access() treats them.
create or replace function pro_locked(p_org_id uuid, p_feature text)
returns boolean
language sql
stable
security definer
set search_path = public, auth
as $$
    select auth.uid() is not null
       and not exists (select 1 from profiles
                        where id = auth.uid() and is_platform_admin)
       and org_plan(p_org_id) = 'free'
       and coalesce(plan_setting('pro_features'), '[]'::jsonb) ? p_feature;
$$;

-- ------------------------------------------------------------
-- 2. THE QUESTION EVERY GUARD ASKS, WITH ONE MORE LAYER
-- ------------------------------------------------------------
-- 041 verbatim, with the admin branch falling through to the plan layer
-- instead of returning at once, and the plan layer at the end: on a Free
-- business a Pro tool is 'view'. 'hidden' stays 'hidden' — the dial wins
-- below the plan.
create or replace function feature_access(p_org_id uuid, p_feature text)
returns text
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_roles  text[];
    v_tier   text;
    v_access text;
begin
    -- No session: fail closed, as 032 made it. A permission function's answer
    -- for "nobody signed in" must never be its most-open one.
    if auth.uid() is null then
        return 'hidden';
    end if;

    -- The platform runs the platform: every tool, on every plan.
    if exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        return 'edit';
    end if;

    select array_agg(distinct role) into v_roles
      from memberships
     where org_id = p_org_id and user_id = auth.uid();

    if v_roles is null then
        return 'hidden';
    end if;
    if v_roles && array['owner', 'super_admin', 'admin'] then
        v_access := 'edit';
    else
        v_tier := case
            when v_roles && array['manager', 'supervisor'] then 'supervisor'
            else 'employee'
        end;

        select access into v_access
          from org_feature_rules
         where org_id = p_org_id and tier = v_tier and feature = p_feature;

        -- No rule set: full access by default, so a business that never
        -- touched the dial works exactly as before 031 — except reports,
        -- which 032 defaults to 'view'. Keep both.
        v_access := coalesce(v_access,
            case when p_feature = 'reports' then 'view' else 'edit' end);
    end if;

    -- The plan layer (066): a Pro tool on a Free business is 'view', never
    -- 'hidden'. Only ever lowers 'edit'; whatever the dial hid stays hidden.
    if v_access = 'edit'
       and org_plan(p_org_id) = 'free'
       and coalesce(plan_setting('pro_features'), '[]'::jsonb) ? p_feature then
        return 'view';
    end if;

    return v_access;
end;
$$;

-- ------------------------------------------------------------
-- 3. THE GUARDS
-- ------------------------------------------------------------
-- 031's guard, saying why. When the plan is the reason the message opens
-- the door to pay; otherwise it is the dial's own sentence, as before.
create or replace function trg_guard_feature_edit()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if feature_access(new.org_id, tg_argv[0]) <> 'edit' then
        if pro_locked(new.org_id, tg_argv[0]) then
            raise exception 'Kaj Pro : cet outil fait partie de Kaj Pro. Ouvrez Compte › Kaj Pro pour passer à la formule payante.';
        end if;
        raise exception '%', tg_argv[1];
    end if;
    return new;
end;
$$;

-- Payroll: a day worked and a wage paid. The 032 functions still make their
-- own membership checks; this adds the plan on top, on every path.
drop trigger if exists guard_payroll_shifts on shifts;
create trigger guard_payroll_shifts
before insert on shifts
for each row execute function trg_guard_feature_edit(
    'payroll', 'Les pointages vous sont fermés. Voyez le propriétaire.');

drop trigger if exists guard_payroll_payments on staff_payments;
create trigger guard_payroll_payments
before insert on staff_payments
for each row execute function trg_guard_feature_edit(
    'payroll', 'La paie vous est fermée. Voyez le propriétaire.');

-- Tontines: opening a new one. Rounds and contributions of an existing
-- tontine go on — a lapsed Pro loses nothing it started.
drop trigger if exists guard_tontines on tontines;
create trigger guard_tontines
before insert on tontines
for each row execute function trg_guard_feature_edit(
    'tontines', 'Les tontines vous sont fermées. Voyez le propriétaire.');

-- The owner's dial and the currency rates: their write policies demand
-- 'edit' on the Pro tool. Reading stays as it was, so a lapsed Pro's rules
-- and rates keep applying; they just cannot be changed until it pays.
drop policy if exists "feature rules written by admins" on org_feature_rules;
create policy "feature rules written by admins"
on org_feature_rules for all
using (is_org_admin(org_id) and feature_access(org_id, 'team_access') = 'edit')
with check (is_org_admin(org_id) and feature_access(org_id, 'team_access') = 'edit');

drop policy if exists "currency rates written by admins" on org_currency_rates;
create policy "currency rates written by admins"
on org_currency_rates for all
using (is_org_admin(org_id) and feature_access(org_id, 'currencies') = 'edit')
with check (is_org_admin(org_id) and feature_access(org_id, 'currencies') = 'edit');

-- ------------------------------------------------------------
-- 4. THE CAPS
-- ------------------------------------------------------------
-- One trigger function, three tables. Counts only when the business is
-- Free and the caller is neither the platform nor the furniture.
create or replace function trg_cap_free_plan()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_cap   int;
    v_count int;
begin
    if auth.uid() is null
       or exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
       or org_plan(new.org_id) <> 'free' then
        return new;
    end if;

    if tg_table_name = 'memberships' then
        -- The owner is not staff. Everyone else with an account is.
        if new.role = 'owner' then return new; end if;
        v_cap := plan_limit('free_max_staff', 3);
        select count(*) into v_count from memberships
         where org_id = new.org_id and role <> 'owner';
        if v_count >= v_cap then
            raise exception 'Kaj Pro : la formule gratuite compte % comptes en plus du propriétaire. Ouvrez Compte › Kaj Pro pour en ajouter.', v_cap;
        end if;

    elsif tg_table_name = 'invoices' then
        v_cap := plan_limit('free_max_invoices_month', 20);
        select count(*) into v_count from invoices
         where org_id = new.org_id
           and issued_on >= date_trunc('month', coalesce(new.issued_on, current_date))::date
           and issued_on <  (date_trunc('month', coalesce(new.issued_on, current_date)) + interval '1 month')::date;
        if v_count >= v_cap then
            raise exception 'Kaj Pro : la formule gratuite permet % factures par mois. Ouvrez Compte › Kaj Pro pour continuer ce mois-ci.', v_cap;
        end if;

    elsif tg_table_name = 'documents' then
        v_cap := plan_limit('free_max_photos', 50);
        select count(*) into v_count from documents where org_id = new.org_id;
        if v_count >= v_cap then
            raise exception 'Kaj Pro : la formule gratuite garde % photos. Ouvrez Compte › Kaj Pro pour en ajouter.', v_cap;
        end if;
    end if;

    return new;
end;
$$;

drop trigger if exists cap_free_staff on memberships;
create trigger cap_free_staff
before insert on memberships
for each row execute function trg_cap_free_plan();

drop trigger if exists cap_free_invoices on invoices;
create trigger cap_free_invoices
before insert on invoices
for each row execute function trg_cap_free_plan();

drop trigger if exists cap_free_photos on documents;
create trigger cap_free_photos
before insert on documents
for each row execute function trg_cap_free_plan();

-- ------------------------------------------------------------
-- 5. "J'AI PAYÉ"
-- ------------------------------------------------------------
create table if not exists plan_requests (
    id          uuid primary key default gen_random_uuid(),
    org_id      uuid not null references orgs(id) on delete cascade,
    user_id     uuid not null references profiles(id),
    -- What the owner says they paid, in the platform's currency. Null when
    -- they did not say.
    amount      numeric(14, 2) check (amount is null or amount > 0),
    note        text,
    created_at  timestamptz not null default now(),
    handled_at  timestamptz,
    handled_by  uuid references profiles(id)
);

create index if not exists plan_requests_open
    on plan_requests (created_at desc) where handled_at is null;

comment on table plan_requests is
    'An owner tapped "J''ai payé". The platform checks its Wave app and sets '
    'the plan (set_org_plan), then marks the request handled. No money moves here.';

alter table plan_requests enable row level security;

-- The business's admins see their own requests; the platform sees all.
drop policy if exists "plan requests readable by org admins" on plan_requests;
create policy "plan requests readable by org admins"
on plan_requests for select using (is_org_admin(org_id));
-- No insert/update/delete policy: written only through the functions below.

-- An admin of the business says they paid. One open request per business:
-- tapping twice does not queue two.
create or replace function request_pro(
    p_org_id uuid,
    p_amount numeric default null,
    p_note   text    default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_id uuid;
begin
    if auth.uid() is null then
        raise exception 'request_pro() needs a signed-in caller';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur de l''entreprise peut demander Kaj Pro';
    end if;
    if p_amount is not null and p_amount <= 0 then
        raise exception 'Le montant doit être supérieur à zéro';
    end if;

    select id into v_id from plan_requests
     where org_id = p_org_id and handled_at is null
     order by created_at desc limit 1;
    if v_id is not null then
        update plan_requests
           set amount = coalesce(p_amount, amount),
               note   = coalesce(nullif(btrim(coalesce(p_note, '')), ''), note),
               user_id = auth.uid()
         where id = v_id;
        return v_id;
    end if;

    insert into plan_requests (org_id, user_id, amount, note)
    values (p_org_id, auth.uid(), p_amount,
            nullif(btrim(coalesce(p_note, '')), ''))
    returning id into v_id;
    return v_id;
end;
$$;

-- What the platform has to look at. Open requests, oldest first, with the
-- business and the person, legible without opening either.
create or replace function plan_requests_open()
returns table (
    id           uuid,
    org_id       uuid,
    org_name     text,
    org_plan     text,
    requested_by text,
    amount       numeric,
    note         text,
    created_at   timestamptz
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select r.id, r.org_id, o.name, org_plan(o.id),
           coalesce(p.full_name, p.phone, 'Inconnu'),
           r.amount, r.note, r.created_at
    from plan_requests r
    join orgs o on o.id = r.org_id
    left join profiles p on p.id = r.user_id
    where exists (select 1 from profiles
                  where id = auth.uid() and is_platform_admin)
      and r.handled_at is null
    order by r.created_at asc;
$$;

create or replace function handle_plan_request(p_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles
                   where id = auth.uid() and is_platform_admin) then
        raise exception 'Only a platform admin can handle a plan request';
    end if;
    update plan_requests
       set handled_at = now(), handled_by = auth.uid()
     where id = p_id and handled_at is null;
end;
$$;

-- ------------------------------------------------------------
-- 6. GRANTS
-- ------------------------------------------------------------
revoke execute on function plan_setting(text)                    from public;
revoke execute on function plan_limit(text, int)                 from public;
revoke execute on function plan_terms()                          from public;
revoke execute on function pro_locked(uuid, text)                from public;
revoke execute on function request_pro(uuid, numeric, text)      from public;
revoke execute on function plan_requests_open()                  from public;
revoke execute on function handle_plan_request(uuid)             from public;
revoke execute on function trg_cap_free_plan()                   from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant select on plan_requests to authenticated;
        grant execute on function plan_terms()                     to authenticated;
        grant execute on function pro_locked(uuid, text)           to authenticated;
        grant execute on function request_pro(uuid, numeric, text) to authenticated;
        grant execute on function plan_requests_open()             to authenticated;
        grant execute on function handle_plan_request(uuid)        to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 067_delivery_share.sql
-- ============================================================
-- ============================================================
-- 067_delivery_share.sql — the platform's part of a delivery fee.
--
-- M10 block 4. The second revenue stream, and the one that fits the market
-- better than any subscription: pay when you earned. Every delivery carries
-- a fee fixed at order time (061); from now on a share of that fee is the
-- platform's, also fixed at order time, stored beside it. Nothing moves
-- here — the customer still pays the courier at the door — so the share is
-- a debt the courier settles monthly, by Wave, from a report the console
-- prints. Once money moves through the platform (M9), the same column is
-- what gets kept before the rest is paid out.
--
-- The rules:
--   * The share is a percentage in platform_settings (delivery_share_pct,
--     10 to start). Changing it changes the next order, never an order
--     already placed: what was agreed is what is owed.
--   * Computed by a trigger on orders, so every path that sets a fee —
--     place_order today, whatever comes later — carries the share without
--     being rewritten. A pickup has no fee and no share.
--   * Orders placed before this migration keep a share of zero. The
--     couriers were paid in full for them; a cut invented after the fact
--     would be a cut nobody agreed to.
--   * The courier's tally (062) shows the share and the net beside the
--     fees, so what they keep is never a surprise on settlement day.
--   * The settlement is one platform-only read, per courier, per month.
-- ============================================================

insert into platform_settings (key, value) values
    ('delivery_share_pct', '10')
on conflict (key) do nothing;

alter table orders add column if not exists platform_fee numeric(12, 2) not null default 0;
alter table orders drop constraint if exists orders_platform_fee_nonneg;
alter table orders add constraint orders_platform_fee_nonneg check (platform_fee >= 0);

comment on column orders.platform_fee is
    'The platform''s share of delivery_fee, fixed when the fee was (067). '
    'Zero for a pickup and for orders placed before 067. Settled monthly by '
    'the courier until money moves through the platform.';

-- Fixed with the fee, whole francs. Only when the fee itself is set or
-- changed: a status move, a courier taking the job, a payment landing —
-- none of those touch the share.
create or replace function trg_order_platform_fee()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    new.platform_fee := case
        when new.delivery_fee is null or new.delivery_fee <= 0 then 0
        else round(new.delivery_fee * plan_limit('delivery_share_pct', 10) / 100.0)
    end;
    return new;
end;
$$;

drop trigger if exists order_platform_fee on orders;
create trigger order_platform_fee
before insert or update of delivery_fee on orders
for each row execute function trg_order_platform_fee();

-- The courier's tally grows two columns: the platform's share of those
-- fees, and what is left. 062 verbatim otherwise; the return type changes,
-- so it is dropped and recreated.
drop function if exists courier_earnings();

create function courier_earnings()
returns table (
    period   text,
    courses  int,
    fees     numeric,
    km       double precision,
    share    numeric,
    net      numeric
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_now   timestamptz := now();
    v_today date := (v_now at time zone 'Africa/Ouagadougou')::date;
begin
    perform assert_approved_courier();
    return query
    with done as (
        select o.delivery_fee, o.platform_fee,
               case when g.lat is null or o.drop_lat is null then null
                    else distance_km(g.lat, g.lng, o.drop_lat, o.drop_lng) end as km,
               (o.updated_at at time zone 'Africa/Ouagadougou')::date as day
          from orders o
          join orgs g on g.id = o.org_id
         where o.courier_id = auth.uid()
           and o.status = 'delivered'
    ),
    spans as (
        select 'today' as period, v_today as since
        union all select 'week',  v_today - ((extract(isodow from v_today)::int) - 1)
        union all select 'month', date_trunc('month', v_today)::date
    )
    select s.period,
           count(d.day)::int,
           coalesce(sum(d.delivery_fee), 0)::numeric,
           coalesce(sum(d.km), 0)::double precision,
           coalesce(sum(d.platform_fee), 0)::numeric,
           (coalesce(sum(d.delivery_fee), 0) - coalesce(sum(d.platform_fee), 0))::numeric
      from spans s
      left join done d on d.day >= s.since and d.day <= v_today
     group by s.period, s.since
     order by s.since desc;
end;
$$;

-- What each courier owes for one month: the courses they delivered in it
-- (on the day they finished them, Ouagadougou days), the fees those
-- carried, the platform's share of them, and what they kept. Platform
-- only. Null month = the current one.
create or replace function platform_delivery_settlement(p_month date default null)
returns table (
    courier_id uuid,
    name       text,
    phone      text,
    courses    int,
    fees       numeric,
    share      numeric,
    net        numeric
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_from date := date_trunc('month',
        coalesce(p_month, (now() at time zone 'Africa/Ouagadougou')::date))::date;
    v_to   date := (v_from + interval '1 month')::date;
begin
    if not exists (select 1 from profiles
                    where profiles.id = auth.uid() and profiles.is_platform_admin) then
        raise exception 'Only the platform reads the settlement';
    end if;
    return query
    select c.user_id,
           coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                    nullif(btrim(coalesce(p.full_name, '')), ''),
                    'Sans nom'),
           c.phone,
           count(o.id)::int,
           coalesce(sum(o.delivery_fee), 0)::numeric,
           coalesce(sum(o.platform_fee), 0)::numeric,
           (coalesce(sum(o.delivery_fee), 0) - coalesce(sum(o.platform_fee), 0))::numeric
      from couriers c
      join profiles p on p.id = c.user_id
      join orders o on o.courier_id = c.user_id
                   and o.status = 'delivered'
                   and (o.updated_at at time zone 'Africa/Ouagadougou')::date >= v_from
                   and (o.updated_at at time zone 'Africa/Ouagadougou')::date <  v_to
     group by c.user_id, p.first_name, p.last_name, p.full_name, c.phone
    having coalesce(sum(o.delivery_fee), 0) > 0
     order by 6 desc, 2;
end;
$$;

-- plan_terms() says the share too, so the console field and the courier
-- screen read the same number. 066 verbatim plus one key; same return
-- type, so replaced in place.
create or replace function plan_terms()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'pro_features',            coalesce(plan_setting('pro_features'), '[]'::jsonb),
        'free_max_staff',          plan_limit('free_max_staff', 3),
        'free_max_invoices_month', plan_limit('free_max_invoices_month', 20),
        'free_max_photos',         plan_limit('free_max_photos', 50),
        'free_history_months',     plan_limit('free_history_months', 12),
        'pro_price_month',         plan_limit('pro_price_month', 2500),
        'pro_price_year',          plan_limit('pro_price_year', 25000),
        'pro_currency',            coalesce(plan_setting('pro_currency') #>> '{}', 'XOF'),
        'platform_wave',           coalesce(plan_setting('platform_wave') #>> '{}', ''),
        'platform_wave_name',      coalesce(plan_setting('platform_wave_name') #>> '{}', ''),
        'delivery_share_pct',      plan_limit('delivery_share_pct', 10)
    );
$$;

revoke execute on function courier_earnings()                    from public;
revoke execute on function platform_delivery_settlement(date)    from public;
revoke execute on function trg_order_platform_fee()              from public;
revoke execute on function plan_terms()                          from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function courier_earnings()                 to authenticated;
        grant execute on function platform_delivery_settlement(date) to authenticated;
        grant execute on function plan_terms()                       to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 068_vitrine_plus.sql
-- ============================================================
-- ============================================================
-- 068_vitrine_plus.sql — a Kaj Pro business dresses its window.
--
-- The vitrine (052) is one design for every shop on purpose: a name, a few
-- words, the goods on their squares. That is what keeps the street legible.
-- What a paying business gets on top is the shopkeeper's touch, within
-- that design: a cover photograph over the band, a tagline under the
-- name, opening hours, the colour of its buttons, up to six articles held
-- at the top of the shelf, and the choice to hide what is out of stock.
--
-- The rules:
--   * One column, orgs.storefront_style, a small JSON with known keys and
--     nothing else. set_storefront_style() validates every key and drops
--     the ones it does not know, so a build ahead of the database cannot
--     write something the street would then render.
--   * Behind the plan (066): the tool is 'vitrine_plus' on the Pro list.
--     A Free business is refused with the "Kaj Pro :" sentence that opens
--     the door to pay. The platform admin is never gated.
--   * The street sees the style only while the business is Pro. A lapsed
--     Pro keeps what it wrote — nothing is deleted — and the window goes
--     back to the common design until it pays again. Lapsing is not a
--     cliff; it is also not free.
--   * The cover is one of the business's own photographs (a documents row
--     of that org). The uploads Worker asks storefront_photo_allowed()
--     before serving a photo to the street; that gate learns the cover.
--   * Pinned articles must be the business's own; the app orders the shelf
--     by them. Nothing here changes what storefront_products() returns.
-- ============================================================

alter table orgs add column if not exists storefront_style jsonb not null default '{}'::jsonb;

comment on column orgs.storefront_style is
    'The Pro dressing of the vitrine (068): tagline, hours, accent, '
    'cover_key, pinned, hide_out_of_stock. Written only by '
    'set_storefront_style(); shown by storefront() only while the business '
    'is Pro.';

-- The tool joins the Pro list on every database, including ones where 066
-- already seeded the list without it.
update platform_settings
   set value = value || '["vitrine_plus"]'::jsonb
 where key = 'pro_features'
   and jsonb_typeof(value) = 'array'
   and not value ? 'vitrine_plus';

-- The shopkeeper's touch, validated key by key. Null clears everything.
create or replace function set_storefront_style(p_org_id uuid, p_style jsonb)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_in       jsonb := coalesce(p_style, '{}'::jsonb);
    v_out      jsonb := '{}'::jsonb;
    v_text     text;
    v_pinned   jsonb;
    v_id       text;
    v_count    int;
begin
    if auth.uid() is null then
        raise exception 'set_storefront_style() needs a signed-in caller';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur peut habiller la vitrine';
    end if;
    if feature_access(p_org_id, 'vitrine_plus') <> 'edit' then
        if pro_locked(p_org_id, 'vitrine_plus') then
            raise exception 'Kaj Pro : la vitrine personnalisée fait partie de Kaj Pro. Ouvrez Compte › Kaj Pro pour passer à la formule payante.';
        end if;
        raise exception 'La vitrine personnalisée vous est fermée. Voyez le propriétaire.';
    end if;
    if jsonb_typeof(v_in) <> 'object' then
        raise exception 'Le style de la vitrine doit être un objet';
    end if;

    v_text := nullif(btrim(coalesce(v_in ->> 'tagline', '')), '');
    if v_text is not null then
        if char_length(v_text) > 80 then
            raise exception 'La phrase d''accroche fait 80 caractères au plus';
        end if;
        v_out := v_out || jsonb_build_object('tagline', v_text);
    end if;

    v_text := nullif(btrim(coalesce(v_in ->> 'hours', '')), '');
    if v_text is not null then
        if char_length(v_text) > 120 then
            raise exception 'Les horaires font 120 caractères au plus';
        end if;
        v_out := v_out || jsonb_build_object('hours', v_text);
    end if;

    v_text := nullif(btrim(coalesce(v_in ->> 'accent', '')), '');
    if v_text is not null then
        if v_text !~ '^#[0-9A-Fa-f]{6}$' then
            raise exception 'La couleur doit s''écrire #RRGGBB';
        end if;
        v_out := v_out || jsonb_build_object('accent', upper(v_text));
    end if;

    v_text := nullif(btrim(coalesce(v_in ->> 'cover_key', '')), '');
    if v_text is not null then
        if not exists (select 1 from documents d
                        where d.org_id = p_org_id and d.r2_key = v_text) then
            raise exception 'La photo de couverture doit être une photo de cette entreprise';
        end if;
        v_out := v_out || jsonb_build_object('cover_key', v_text);
    end if;

    v_pinned := v_in -> 'pinned';
    if v_pinned is not null and jsonb_typeof(v_pinned) = 'array'
       and jsonb_array_length(v_pinned) > 0 then
        if jsonb_array_length(v_pinned) > 6 then
            raise exception 'Six articles épinglés au plus';
        end if;
        for v_id in select jsonb_array_elements_text(v_pinned) loop
            if v_id !~ '^[0-9a-fA-F-]{36}$' or not exists (
                select 1 from products p
                 where p.id = v_id::uuid and p.org_id = p_org_id) then
                raise exception 'Un article épinglé doit être un article de cette entreprise';
            end if;
        end loop;
        select count(distinct e) into v_count
          from jsonb_array_elements_text(v_pinned) e;
        if v_count <> jsonb_array_length(v_pinned) then
            raise exception 'Un article ne s''épingle qu''une fois';
        end if;
        v_out := v_out || jsonb_build_object('pinned', v_pinned);
    end if;

    if (v_in -> 'hide_out_of_stock') = 'true'::jsonb then
        v_out := v_out || '{"hide_out_of_stock": true}'::jsonb;
    end if;

    update orgs set storefront_style = v_out where id = p_org_id;
end;
$$;

-- The window carries the style — while the business is Pro. 057 verbatim
-- plus the column; the return type changes, so dropped and recreated.
drop function if exists storefront(text);
create function storefront(p_slug text)
returns table (
    org_id        uuid,
    name          text,
    slug          text,
    profile       text,
    blurb         text,
    phone         text,
    address       text,
    theme         text,
    currency      text,
    lat           double precision,
    lng           double precision,
    wave_merchant text,
    style         jsonb
)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.name, o.slug, o.profile::text, o.storefront_blurb,
           o.phone, o.address, o.theme, o.default_currency, o.lat, o.lng,
           o.wave_merchant,
           case when org_plan(o.id) = 'pro' then o.storefront_style
                else '{}'::jsonb end
    from orgs o
    where o.id = storefront_open(p_slug);
$$;

-- The photos the Worker may serve to the street: the published articles'
-- (052) and now a Pro business's cover, while it is Pro and open.
create or replace function storefront_photo_allowed(p_key text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists (
        select 1
        from documents d
        join products p on p.id = d.product_id
        join orgs     o on o.id = p.org_id
        where d.r2_key = p_key
          and p.is_active
          and p.is_published
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    ) or exists (
        select 1
        from orgs o
        where o.storefront_style ->> 'cover_key' = p_key
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
          and org_plan(o.id) = 'pro'
    );
$$;

revoke execute on function set_storefront_style(uuid, jsonb) from public;
revoke execute on function storefront(text)                  from public;
revoke execute on function storefront_photo_allowed(text)    from public;

do $$
begin
    -- The window is for the street: anonymous callers may look (063 rule:
    -- a recreated street function says its grant again, by name).
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function storefront(text)               to anon;
        grant execute on function storefront_photo_allowed(text) to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_storefront_style(uuid, jsonb) to authenticated;
        grant execute on function storefront(text)                  to authenticated;
        grant execute on function storefront_photo_allowed(text)    to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 069_reach_and_locks.sql
-- ============================================================
-- ============================================================
-- 069_reach_and_locks.sql — a delivery has a reach, and three tools that
-- were only hidden are now locked.
--
-- Two findings of the October audit, both live:
--
--   1. A delivery had no maximum distance. delivery_fee() multiplied the
--      per-km rate by whatever lay between the shop's pin and the
--      customer's, so a shop pinned in New Jersey quoted a customer in
--      Ouagadougou 1 149 450 FCFA for 7 660 km. A moto delivers across a
--      town, not an ocean. From here a delivery has a reach: the platform's
--      default (delivery_max_km, 15 to start) unless the shop set its own.
--      Beyond it there is no fee (delivery_fee() answers null, as it does
--      for "no pin"), delivery_check() says so in numbers for the basket,
--      and an order for delivery beyond it is refused at the door — whatever
--      the app in front of it is old enough to believe.
--
--   2. The owner's dial (031) is enforced by the database for articles,
--      credits, production, tontines and payroll — and only by hiding
--      buttons for Factures, Photos and Rapports. A hidden button is not a
--      lock: an employee the owner shut out of invoices could still create
--      one through the API. Now:
--        * invoices: writing one (create, revise, cancel, a payment) needs
--          'edit' on 'invoices', by triggers on the tables, so every writer
--          present and future is caught — the 031 pattern.
--        * photos: a document needs 'edit' on 'photos' to be taken or
--          filed; one attached to an article needs 'edit' on 'products'
--          instead, the dial the owner set for articles. The gallery's two
--          lists need 'photos' not hidden.
--        * reports: the eight report functions refuse a caller whose dial
--          says 'hidden' for 'reports'.
--
-- How the report and gallery functions are guarded without rewriting
-- them: each is renamed <name>_core and closed to everyone, and a thin
-- function under the original name checks the dial and calls it. Their
-- bodies — the part that took care to get right — are not touched, and
-- the bundle stays re-runnable (an earlier migration re-creating the
-- original only replaces the guard, which this one then puts back).
-- ============================================================

-- ------------------------------------------------------------
-- 1. The reach of a delivery
-- ------------------------------------------------------------
insert into platform_settings (key, value) values ('delivery_max_km', '15')
on conflict (key) do nothing;

alter table orgs add column if not exists delivery_max_km numeric(8, 2);
alter table orgs drop constraint if exists orgs_delivery_max_km_positive;
alter table orgs add constraint orgs_delivery_max_km_positive
    check (delivery_max_km is null or (delivery_max_km > 0 and delivery_max_km <= 200));

comment on column orgs.delivery_max_km is
    'How far this shop delivers, in km (069). Null = the platform default '
    '(platform_settings.delivery_max_km). Beyond it no fee is quoted and a '
    'delivery order is refused.';

-- The reach that applies to a shop: its own, else the platform's.
create or replace function delivery_reach_km(p_org_id uuid)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
    select coalesce(
        (select delivery_max_km from orgs where id = p_org_id),
        (select (value #>> '{}')::numeric from platform_settings
          where key = 'delivery_max_km'),
        15);
$$;

-- An administrator of the shop sets its reach; null returns it to the
-- platform's default.
create or replace function set_delivery_reach(p_org_id uuid, p_km numeric)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null then
        raise exception 'set_delivery_reach() needs a signed-in caller';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur règle la distance de livraison';
    end if;
    if p_km is not null and (p_km <= 0 or p_km > 200) then
        raise exception 'La distance de livraison va de 1 à 200 km';
    end if;
    update orgs set delivery_max_km = p_km where id = p_org_id;
end;
$$;

-- 061 verbatim, with the reach: beyond it, no fee.
create or replace function delivery_fee(
    p_org_id uuid,
    p_lat    double precision,
    p_lng    double precision
)
returns numeric
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_org      orgs%rowtype;
    v_base     numeric;
    v_per_km   numeric;
    v_currency text;
    v_fee      numeric;
    v_km       double precision;
begin
    if p_lat is null or p_lng is null then
        return null;
    end if;
    select * into v_org from orgs where id = p_org_id;
    if not found or v_org.lat is null or v_org.lng is null then
        return null;
    end if;
    v_km := distance_km(v_org.lat, v_org.lng, p_lat, p_lng);
    if v_km > delivery_reach_km(p_org_id) then
        return null; -- out of reach: there is no price for an impossible run
    end if;
    if v_org.delivery_base is not null then
        v_base   := v_org.delivery_base;
        v_per_km := v_org.delivery_per_km;
    else
        select (value #>> '{}')::text into v_currency
          from platform_settings where key = 'delivery_currency';
        if coalesce(v_org.default_currency, 'XOF') <> coalesce(v_currency, 'XOF') then
            return null; -- the platform's numbers are in another money
        end if;
        select (value #>> '{}')::numeric into v_base
          from platform_settings where key = 'delivery_base';
        select (value #>> '{}')::numeric into v_per_km
          from platform_settings where key = 'delivery_per_km';
        if v_base is null or v_per_km is null then
            return null;
        end if;
    end if;
    v_fee := v_base + v_per_km * v_km;
    return round(v_fee / 25) * 25;
end;
$$;

-- The basket's question, answered in numbers: the fee (or none), how far
-- the door is, how far this shop goes, and whether it is too far. One row
-- when the shop is open and has a pin; none otherwise. A new function
-- rather than a new shape for delivery_quote(), so an app built before
-- 069 keeps asking its old question and gets its old kind of answer.
create or replace function delivery_check(
    p_slug text,
    p_lat  double precision,
    p_lng  double precision
)
returns table (
    fee         numeric,
    distance_km numeric,
    max_km      numeric,
    too_far     boolean
)
language sql
stable
security definer
set search_path = public
as $$
    select delivery_fee(o.id, p_lat, p_lng),
           round(distance_km(o.lat, o.lng, p_lat, p_lng)::numeric, 1),
           delivery_reach_km(o.id),
           distance_km(o.lat, o.lng, p_lat, p_lng) > delivery_reach_km(o.id)
    from orgs o
    where o.id = storefront_open(p_slug)
      and o.lat is not null and o.lng is not null
      and p_lat is not null and p_lng is not null;
$$;

-- The door: a delivery pinned beyond the shop's reach is refused, by
-- whichever path the order arrives.
create or replace function trg_order_within_reach()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org orgs%rowtype;
    v_km  double precision;
    v_max numeric;
begin
    if new.fulfilment <> 'delivery'
       or new.drop_lat is null or new.drop_lng is null then
        return new;
    end if;
    select * into v_org from orgs where id = new.org_id;
    if v_org.lat is null or v_org.lng is null then
        return new; -- no shop pin: no distance to hold it to
    end if;
    v_km  := distance_km(v_org.lat, v_org.lng, new.drop_lat, new.drop_lng);
    v_max := delivery_reach_km(new.org_id);
    if v_km > v_max then
        raise exception 'Trop loin pour une livraison : % km, la boutique livre jusqu''à % km. Choisissez le retrait en boutique.',
            round(v_km::numeric, 1), v_max;
    end if;
    return new;
end;
$$;

drop trigger if exists order_within_reach on orders;
create trigger order_within_reach
before insert on orders
for each row execute function trg_order_within_reach();

-- ------------------------------------------------------------
-- 2. Factures: locked by the dial
-- ------------------------------------------------------------
-- Its own guard rather than 031's shared one: that one fails closed when
-- nobody is signed in, which would also lock the platform itself out of
-- an invoice (the SQL editor, a service key).
create or replace function trg_guard_invoice()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null then
        return new; -- the platform itself; see trg_guard_document()
    end if;
    if feature_access(new.org_id, 'invoices') <> 'edit' then
        raise exception 'Les factures vous sont fermées. Voyez le propriétaire.';
    end if;
    return new;
end;
$$;

drop trigger if exists guard_invoices on invoices;
create trigger guard_invoices
before insert or update on invoices
for each row execute function trg_guard_invoice();

-- invoice_payments carries no org_id; its invoice knows it.
create or replace function trg_guard_invoice_payment()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid;
begin
    if auth.uid() is null then
        return new; -- the platform itself; see trg_guard_document()
    end if;
    select org_id into v_org from invoices where id = new.invoice_id;
    if v_org is not null and feature_access(v_org, 'invoices') <> 'edit' then
        raise exception 'Les factures vous sont fermées. Voyez le propriétaire.';
    end if;
    return new;
end;
$$;

drop trigger if exists guard_invoice_payments on invoice_payments;
create trigger guard_invoice_payments
before insert on invoice_payments
for each row execute function trg_guard_invoice_payment();

-- ------------------------------------------------------------
-- 3. Photos: locked by the dial
-- ------------------------------------------------------------
-- Taking or filing a document is 'photos'; an article's own photograph is
-- the articles dial's business, since that is where the owner said who may
-- change an article.
create or replace function trg_guard_document()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    -- No signed-in person: the platform itself (the SQL editor, a service
    -- key). A stranger never gets here — anon holds no grant on documents
    -- and every function that writes one demands a member (can_write_org).
    if auth.uid() is null then
        return new;
    end if;
    if new.product_id is not null then
        if feature_access(new.org_id, 'products') <> 'edit' then
            raise exception 'Les articles vous sont fermés. Voyez le propriétaire.';
        end if;
    elsif feature_access(new.org_id, 'photos') <> 'edit' then
        raise exception 'Les photos vous sont fermées. Voyez le propriétaire.';
    end if;
    return new;
end;
$$;

drop trigger if exists guard_documents on documents;
create trigger guard_documents
before insert or update on documents
for each row execute function trg_guard_document();

-- ------------------------------------------------------------
-- 4. The guard in front of a function
-- ------------------------------------------------------------
-- Raises when the caller's dial is below what the tool needs. 'view' means
-- "not hidden"; 'edit' means edit.
create or replace function require_feature(
    p_org_id  uuid,
    p_feature text,
    p_need    text default 'view'
)
returns void
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v text;
begin
    -- No signed-in person: step aside and let the function behind decide,
    -- as it did before 069 (each answers a non-member with nothing).
    -- feature_access() fails closed for "nobody" (032), which is right for
    -- a permission answer and wrong for a guard in front of one.
    if auth.uid() is null then
        return;
    end if;
    -- A stranger to the business is not refused here either: the function
    -- behind answers them with nothing, the promise the report suites hold
    -- it to. Only a member the owner shut out is told no.
    if not exists (select 1 from memberships
                    where org_id = p_org_id and user_id = auth.uid()) then
        return;
    end if;
    v := feature_access(p_org_id, p_feature);
    if v = 'hidden' or (p_need = 'edit' and v <> 'edit') then
        raise exception '%', case p_feature
            when 'reports'  then 'Les rapports vous sont fermés. Voyez le propriétaire.'
            when 'photos'   then 'Les photos vous sont fermées. Voyez le propriétaire.'
            when 'invoices' then 'Les factures vous sont fermées. Voyez le propriétaire.'
            else 'Cet outil vous est fermé. Voyez le propriétaire.' end;
    end if;
end;
$$;

-- Renames f(args) to f_core(args) once, and closes the core to everyone:
-- only the guard in front of it calls it.
do $$
declare
    v_sig text;
    v_core text;
begin
    foreach v_sig in array array[
        'income_statement(uuid, date, date)',
        'balance_sheet(uuid, date)',
        'trial_balance(uuid, date, date)',
        'account_ledger(uuid, uuid, date, date, integer)',
        'journal_page(uuid, date, date, integer, integer)',
        'church_weekly_summary(uuid, date)',
        'church_balances(uuid)',
        'member_giving_statement(uuid, integer)',
        'org_documents(uuid, text, integer, integer)',
        'unfiled_documents(uuid, integer)'
    ] loop
        v_core := split_part(v_sig, '(', 1) || '_core(' || split_part(v_sig, '(', 2);
        -- Once only. On a re-run of the bundle the core already exists, and
        -- the original that an earlier migration re-created over the guard
        -- is simply replaced by the guard below.
        if to_regprocedure(v_core) is null then
            execute format('alter function %s rename to %s',
                           v_sig, split_part(v_sig, '(', 1) || '_core');
        end if;
        execute format('revoke execute on function %s from public', v_core);
        if exists (select 1 from pg_roles where rolname = 'anon') then
            execute format('revoke execute on function %s from anon', v_core);
        end if;
        if exists (select 1 from pg_roles where rolname = 'authenticated') then
            execute format('revoke execute on function %s from authenticated', v_core);
        end if;
    end loop;
end $$;

create or replace function income_statement(
    p_org_id uuid, p_from date default null, p_to date default null)
returns table (section text, code text, name text, amount numeric)
language plpgsql stable security definer set search_path = public, auth
as $$
begin
    perform require_feature(p_org_id, 'reports');
    return query select * from income_statement_core(p_org_id, p_from, p_to);
end;
$$;

create or replace function balance_sheet(
    p_org_id uuid, p_as_of date default null)
returns table (section text, code text, name text, amount numeric)
language plpgsql stable security definer set search_path = public, auth
as $$
begin
    perform require_feature(p_org_id, 'reports');
    return query select * from balance_sheet_core(p_org_id, p_as_of);
end;
$$;

create or replace function trial_balance(
    p_org_id uuid, p_from date default null, p_to date default null)
returns table (code text, name text, type text,
               total_debit numeric, total_credit numeric, balance numeric)
language plpgsql stable security definer set search_path = public, auth
as $$
begin
    perform require_feature(p_org_id, 'reports');
    return query select * from trial_balance_core(p_org_id, p_from, p_to);
end;
$$;

create or replace function account_ledger(
    p_org_id uuid, p_account_id uuid,
    p_from date default null, p_to date default null, p_limit int default 200)
returns table (entry_id uuid, occurred_at timestamptz, label text, memo text,
               debit numeric, credit numeric, balance numeric,
               reversed boolean, recorded_by text)
language plpgsql stable security definer set search_path = public, auth
as $$
begin
    perform require_feature(p_org_id, 'reports');
    return query select * from account_ledger_core(
        p_org_id, p_account_id, p_from, p_to, p_limit);
end;
$$;

create or replace function journal_page(
    p_org_id uuid, p_from date default null, p_to date default null,
    p_limit int default 100, p_offset int default 0)
returns table (entry_id uuid, occurred_at timestamptz, label text, memo text,
               details jsonb, amount numeric, debit_names text,
               credit_names text, direction text, reversed boolean,
               is_reversal boolean, recorded_by text)
language plpgsql stable security definer set search_path = public, auth
as $$
begin
    perform require_feature(p_org_id, 'reports');
    return query select * from journal_page_core(
        p_org_id, p_from, p_to, p_limit, p_offset);
end;
$$;

create or replace function church_weekly_summary(
    p_org_id uuid, p_week_ending date default current_date)
returns table (category text, label text, amount numeric)
language plpgsql stable security definer set search_path = public, auth
as $$
begin
    perform require_feature(p_org_id, 'reports');
    return query select * from church_weekly_summary_core(p_org_id, p_week_ending);
end;
$$;

create or replace function church_balances(p_org_id uuid)
returns table (account_name text, balance numeric)
language plpgsql stable security definer set search_path = public, auth
as $$
begin
    perform require_feature(p_org_id, 'reports');
    return query select * from church_balances_core(p_org_id);
end;
$$;

-- Keyed by member, not by business: the member's business holds the dial.
create or replace function member_giving_statement(
    p_member_id uuid,
    p_year int default extract(year from current_date)::int)
returns table (contribution_date date, kind text, amount numeric)
language plpgsql stable security definer set search_path = public, auth
as $$
declare
    v_org uuid;
begin
    select org_id into v_org from church_members where id = p_member_id;
    if v_org is not null then
        perform require_feature(v_org, 'reports');
    end if;
    return query select * from member_giving_statement_core(p_member_id, p_year);
end;
$$;

-- The gallery's lists run as the caller (013), and stay so.
create or replace function org_documents(
    p_org_id uuid, p_kind text default null,
    p_limit int default 60, p_offset int default 0)
returns table (id uuid, r2_key text, kind text, caption text,
               content_type text, byte_size bigint, captured_at timestamptz,
               ocr_status text, ocr_text text, barcode text, product_id uuid,
               product_name text, entry_id uuid, entry_label text,
               uploaded_by uuid, uploaded_name text)
language plpgsql stable security invoker set search_path = public
as $$
begin
    perform require_feature(p_org_id, 'photos');
    return query select * from org_documents_core(p_org_id, p_kind, p_limit, p_offset);
end;
$$;

create or replace function unfiled_documents(p_org_id uuid, p_limit int default 60)
returns table (id uuid, r2_key text, kind text, content_type text,
               captured_at timestamptz, ocr_status text, ocr_text text,
               barcode text)
language plpgsql stable security invoker set search_path = public
as $$
begin
    perform require_feature(p_org_id, 'photos');
    return query select * from unfiled_documents_core(p_org_id, p_limit);
end;
$$;

-- The invoker gallery calls a core it may not execute directly: the cores
-- of the two invoker lists stay callable by authenticated (they were
-- invoker before and still are — RLS still decides every row), and only
-- the definer report cores are closed.
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function org_documents_core(uuid, text, integer, integer) to authenticated;
        grant execute on function unfiled_documents_core(uuid, integer)            to authenticated;
    end if;
end $$;

-- ------------------------------------------------------------
-- 5. Grants
-- ------------------------------------------------------------
revoke execute on function delivery_reach_km(uuid)                 from public;
revoke execute on function set_delivery_reach(uuid, numeric)       from public;
revoke execute on function delivery_check(text, double precision, double precision) from public;
revoke execute on function require_feature(uuid, text, text)       from public;
revoke execute on function income_statement(uuid, date, date)      from public;
revoke execute on function balance_sheet(uuid, date)               from public;
revoke execute on function trial_balance(uuid, date, date)         from public;
revoke execute on function account_ledger(uuid, uuid, date, date, integer) from public;
revoke execute on function journal_page(uuid, date, date, integer, integer) from public;
revoke execute on function church_weekly_summary(uuid, date)       from public;
revoke execute on function church_balances(uuid)                   from public;
revoke execute on function member_giving_statement(uuid, integer)  from public;
revoke execute on function org_documents(uuid, text, integer, integer) from public;
revoke execute on function unfiled_documents(uuid, integer)        from public;

do $$
begin
    -- The street asks the reach before an order (063 rule: say it by name).
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function delivery_check(text, double precision, double precision) to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function delivery_check(text, double precision, double precision) to authenticated;
        grant execute on function set_delivery_reach(uuid, numeric)       to authenticated;
        -- Called as the caller by the two invoker gallery lists.
        grant execute on function require_feature(uuid, text, text)       to authenticated;
        grant execute on function income_statement(uuid, date, date)      to authenticated;
        grant execute on function balance_sheet(uuid, date)               to authenticated;
        grant execute on function trial_balance(uuid, date, date)         to authenticated;
        grant execute on function account_ledger(uuid, uuid, date, date, integer) to authenticated;
        grant execute on function journal_page(uuid, date, date, integer, integer) to authenticated;
        grant execute on function church_weekly_summary(uuid, date)       to authenticated;
        grant execute on function church_balances(uuid)                   to authenticated;
        grant execute on function member_giving_statement(uuid, integer)  to authenticated;
        grant execute on function org_documents(uuid, text, integer, integer) to authenticated;
        grant execute on function unfiled_documents(uuid, integer)        to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 070_vitrine_sells.sql
-- ============================================================
-- ============================================================
-- 070_vitrine_sells.sql — a vitrine that is never empty, and says so.
--
-- The October audit, from the live data: ELIM SHOP opened its vitrine with
-- 57 articles and published none, so a shopper who followed the directory
-- found "Aucun article affiché". Publishing was one switch per article,
-- off by default, and nobody flips 57 switches. Across the platform one
-- article in seventy had a photo, no shop had a description, an address or
-- a phone, and nothing told an owner what their window was missing.
--
--   1. An article is published unless the owner hides it: the column's
--      default turns to true for new articles. Ingredients (028) are the
--      exception — the production flour is not for sale on the street.
--      Existing articles are not touched: what an owner decided stays.
--   2. publish_all_products(): the one tap for the 57 — every active,
--      priced, non-ingredient article, by somebody the articles dial lets
--      edit them.
--   3. The directory lists an open vitrine only once it has something to
--      show: an open window with an empty shelf is a dead end, not a shop.
--      The link itself keeps working; only the listing waits.
--   4. storefront_previews(): three articles per shop for the directory's
--      cards, photographed ones first — the card shows what is sold
--      instead of the shop's initial on a beige square.
--   5. vitrine_checklist(): what this window has and lacks, for its own
--      members — the meter on the vitrine settings.
-- ============================================================

-- ------------------------------------------------------------
-- 1. Published unless hidden
-- ------------------------------------------------------------
alter table products alter column is_published set default true;

create or replace function trg_ingredient_unpublished()
returns trigger
language plpgsql
as $$
begin
    if new.is_ingredient then
        new.is_published := false;
    end if;
    return new;
end;
$$;

create or replace trigger ingredient_unpublished
before insert on products
for each row execute function trg_ingredient_unpublished();

-- ------------------------------------------------------------
-- 2. Tout publier
-- ------------------------------------------------------------
create or replace function publish_all_products(p_org_id uuid)
returns integer
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_count integer;
begin
    if auth.uid() is null then
        raise exception 'publish_all_products() needs a signed-in caller';
    end if;
    if not can_write_org(p_org_id) then
        raise exception 'Vous ne pouvez pas modifier les articles de cette entreprise';
    end if;
    if feature_access(p_org_id, 'products') <> 'edit' then
        raise exception 'Les articles vous sont fermés. Voyez le propriétaire.';
    end if;
    update products
       set is_published = true
     where org_id = p_org_id
       and is_active
       and not is_ingredient
       and not is_published
       and coalesce(sale_price, 0) > 0;
    get diagnostics v_count = row_count;
    return v_count;
end;
$$;

-- ------------------------------------------------------------
-- 3. The directory lists a window with something in it
-- ------------------------------------------------------------
-- 053 verbatim, plus the shelf test. Same signature, so create or replace.
create or replace function storefront_directory(
    p_lat double precision default null,
    p_lng double precision default null
)
returns table (
    org_id      uuid,
    name        text,
    slug        text,
    profile     text,
    blurb       text,
    address     text,
    lat         double precision,
    lng         double precision,
    distance_km double precision
)
language sql
stable
security definer
set search_path = public
as $$
    select d.org_id, d.name, d.slug, d.profile, d.blurb, d.address,
           d.lat, d.lng, d.distance_km
    from (
        select o.id as org_id, o.name, o.slug, o.profile::text,
               o.storefront_blurb as blurb, o.address, o.lat, o.lng,
               case
                   when p_lat is null or p_lng is null
                     or o.lat is null or o.lng is null then null
                   else 6371.0 * 2 * asin(sqrt(
                            power(sin(radians(o.lat - p_lat) / 2), 2)
                          + cos(radians(p_lat)) * cos(radians(o.lat))
                          * power(sin(radians(o.lng - p_lng) / 2), 2)))
               end as distance_km
        from orgs o
        where o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
          and exists (select 1 from products p
                       where p.org_id = o.id
                         and p.is_active
                         and p.is_published)
    ) d
    order by (d.distance_km is null), d.distance_km, d.name;
$$;

-- ------------------------------------------------------------
-- 4. What each card shows
-- ------------------------------------------------------------
create or replace function storefront_previews(p_slugs text[])
returns table (
    slug       text,
    product_id uuid,
    name       text,
    sale_price numeric,
    photo_key  text
)
language sql
stable
security definer
set search_path = public
as $$
    select x.slug, x.id, x.name, x.sale_price, x.photo_key
    from (
        select o.slug, p.id, p.name, p.sale_price, ph.r2_key as photo_key,
               row_number() over (
                   partition by o.id
                   order by (ph.r2_key is null), (p.quantity <= 0), p.name
               ) as n
        from orgs o
        join products p on p.org_id = o.id
        left join lateral (
            select d.r2_key from documents d
             where d.product_id = p.id
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1
        ) ph on true
        where o.slug = any (coalesce(p_slugs, '{}'))
          and o.id = storefront_open(o.slug)
          and p.is_active
          and p.is_published
    ) x
    where x.n <= 3
    order by x.slug, x.n;
$$;

-- ------------------------------------------------------------
-- 5. The checklist behind the meter
-- ------------------------------------------------------------
create or replace function vitrine_checklist(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select case when not is_org_member(p_org_id) then null else
    jsonb_build_object(
        'open',        o.storefront_enabled,
        'active',      (select count(*) from products p
                         where p.org_id = o.id and p.is_active and not p.is_ingredient),
        'published',   (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published),
        'unpublished', (select count(*) from products p
                         where p.org_id = o.id and p.is_active and not p.is_published
                           and not p.is_ingredient and coalesce(p.sale_price, 0) > 0),
        'with_photo',  (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published
                           and exists (select 1 from documents d where d.product_id = p.id)),
        'blurb',       nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null,
        'address',     nullif(btrim(coalesce(o.address, '')), '') is not null,
        'phone',       nullif(btrim(coalesce(o.phone, '')), '') is not null,
        'pin',         o.lat is not null and o.lng is not null
    ) end
    from orgs o where o.id = p_org_id;
$$;

-- ------------------------------------------------------------
-- 6. Grants
-- ------------------------------------------------------------
revoke execute on function publish_all_products(uuid)      from public;
revoke execute on function storefront_previews(text[])     from public;
revoke execute on function vitrine_checklist(uuid)         from public;
revoke execute on function storefront_directory(double precision, double precision) from public;

do $$
begin
    -- The street reads the cards (063 rule: say it by name).
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function storefront_previews(text[]) to anon;
        grant execute on function storefront_directory(double precision, double precision) to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function storefront_previews(text[])  to authenticated;
        grant execute on function storefront_directory(double precision, double precision) to authenticated;
        grant execute on function publish_all_products(uuid)   to authenticated;
        grant execute on function vitrine_checklist(uuid)      to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 071_spots.sql
-- ============================================================
-- ============================================================
-- 071_spots.sql — "Mettre en avant": a shop buys a place on the street.
--
-- The October audit: 054 built an "À la une" strip and a featured_until
-- date per article, but only the platform could set it, by hand, from the
-- console. An owner could not ask for a spot, there was no price, no way
-- to pay, and nothing counted what a spot earned — nothing counted visits
-- at all, so there was no figure to sell a spot with. This is the market
-- for those spots, and the counter under it.
--
--   1. storefront_visits: per day, per shop, per article (or the shop as a
--      whole), how often it was seen, opened, added to a basket, ordered.
--      record_visit() is the street's one write; orders count themselves.
--   2. promotions: a spot asked for — an article for À la une and the top
--      of search, or the whole shop for the top of the directory — for 7
--      or 30 days at the price the platform set. Paid by Wave to the
--      platform's number like Kaj Pro (066), "J'ai payé" from the owner,
--      approved by the platform; later the payment confirmation (M9).
--   3. A fixed number of article spots run at once (spots_max_live, 8), so
--      a spot is scarce and seen. An approved spot that finds the strip
--      full starts when the earliest running one ends.
--   4. Kaj Pro includes one free 7-day article spot a month; it skips the
--      payment and the approval — it is already paid for.
--   5. The rules a spot must meet: an article needs a photo, a price and
--      stock and must be on the vitrine; the shop's window must be open.
--   6. promotion_report(): what the spot earned, over its own days.
-- ============================================================

insert into platform_settings (key, value) values
    ('spot_price_article_7',  '1000'),
    ('spot_price_article_30', '3000'),
    ('spot_price_shop_7',     '2500'),
    ('spot_price_shop_30',    '8000'),
    ('spots_max_live',        '8'),
    ('pro_free_spots_month',  '1')
on conflict (key) do nothing;

-- ------------------------------------------------------------
-- 1. The counter
-- ------------------------------------------------------------
create table if not exists storefront_visits (
    day        date not null default current_date,
    org_id     uuid not null references orgs(id) on delete cascade,
    -- Null: the shop as a whole (its window opened).
    product_id uuid references products(id) on delete cascade,
    seen       integer not null default 0,
    opened     integer not null default 0,
    added      integer not null default 0,
    ordered    integer not null default 0
);
create unique index if not exists storefront_visits_key
    on storefront_visits (day, org_id,
        coalesce(product_id, '00000000-0000-0000-0000-000000000000'::uuid));
alter table storefront_visits enable row level security;
-- No policies: written by record_visit() and the order trigger, read by
-- promotion_report() and the owner's analytics, all as their definer.

-- The street's one write. p_kind: 'seen' (in a list), 'opened' (the shop's
-- window, or an article's sheet), 'added' (to a basket). Anyone may count;
-- the numbers are indicative, never money.
create or replace function record_visit(
    p_slug       text,
    p_kind       text,
    p_product_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org uuid := storefront_open(p_slug);
begin
    if v_org is null or p_kind not in ('seen', 'opened', 'added') then
        return;
    end if;
    if p_product_id is not null and not exists (
        select 1 from products where id = p_product_id and org_id = v_org) then
        return;
    end if;
    insert into storefront_visits (day, org_id, product_id, seen, opened, added)
    values (current_date, v_org, p_product_id,
            (p_kind = 'seen')::int, (p_kind = 'opened')::int, (p_kind = 'added')::int)
    on conflict (day, org_id,
        (coalesce(product_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    do update set
        seen   = storefront_visits.seen   + excluded.seen,
        opened = storefront_visits.opened + excluded.opened,
        added  = storefront_visits.added  + excluded.added;
end;
$$;

-- The welcome page's strip, counted in one call: each article shown, once.
-- Only articles of open windows count; the rest is ignored.
create or replace function record_seen(p_product_ids uuid[])
returns void
language sql
security definer
set search_path = public
as $$
    insert into storefront_visits (day, org_id, product_id, seen)
    select current_date, p.org_id, p.id, 1
      from products p
      join orgs o on o.id = p.org_id
     where p.id = any (p_product_ids[1:24])
       and o.id = storefront_open(o.slug)
    on conflict (day, org_id,
        (coalesce(product_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    do update set seen = storefront_visits.seen + 1;
$$;

-- An order counts itself, per article.
create or replace function trg_count_ordered()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org uuid;
begin
    if new.product_id is null then
        return new;
    end if;
    select org_id into v_org from orders where id = new.order_id;
    if v_org is null then
        return new;
    end if;
    insert into storefront_visits (day, org_id, product_id, ordered)
    values (current_date, v_org, new.product_id, 1)
    on conflict (day, org_id,
        (coalesce(product_id, '00000000-0000-0000-0000-000000000000'::uuid)))
    do update set ordered = storefront_visits.ordered + 1;
    return new;
end;
$$;

create or replace trigger count_ordered
after insert on order_lines
for each row execute function trg_count_ordered();

-- ------------------------------------------------------------
-- 2. The spots
-- ------------------------------------------------------------
create table if not exists promotions (
    id           uuid primary key default gen_random_uuid(),
    org_id       uuid not null references orgs(id) on delete cascade,
    -- Null for a whole-shop spot.
    product_id   uuid references products(id) on delete cascade,
    kind         text not null check (kind in ('article', 'shop')),
    days         integer not null check (days in (7, 30)),
    price        numeric(14, 2) not null default 0,
    currency     text not null default 'XOF',
    free         boolean not null default false,
    status       text not null default 'requested'
                 check (status in ('requested', 'paid_claimed', 'approved', 'refused', 'cancelled')),
    starts_at    timestamptz,
    ends_at      timestamptz,
    requested_by uuid references profiles(id),
    decided_by   uuid references profiles(id),
    decided_at   timestamptz,
    note         text,
    created_at   timestamptz not null default now(),
    check ((kind = 'article') = (product_id is not null))
);
create index if not exists promotions_running
    on promotions (starts_at, ends_at) where status = 'approved';
create index if not exists promotions_open
    on promotions (created_at desc) where status in ('requested', 'paid_claimed');
alter table promotions enable row level security;
drop policy if exists "promotions readable by members" on promotions;
create policy "promotions readable by members"
on promotions for select using (is_org_member(org_id));

create or replace function spot_setting(p_key text, p_default numeric)
returns numeric
language sql
stable
security definer
set search_path = public
as $$
    select coalesce((select (value #>> '{}')::numeric
                       from platform_settings where key = p_key), p_default);
$$;

-- When an approved article spot can start: now if the strip has room,
-- else when the earliest running (or queued) spot ends.
create or replace function next_spot_start(p_kind text)
returns timestamptz
language sql
stable
security definer
set search_path = public
as $$
    with booked as (
        select ends_at from promotions
         where status = 'approved' and kind = p_kind and ends_at > now()
    )
    select case
        when p_kind = 'shop' then now()
        when (select count(*) from booked) < spot_setting('spots_max_live', 8)
            then now()
        else (select ends_at from booked order by ends_at
               offset greatest(0, (select count(*) from booked)
                                   - spot_setting('spots_max_live', 8)::int)
               limit 1)
    end;
$$;

-- The platform's bell (030 rings it for applications; this is the same
-- fan-out, for spots).
create or replace function notify_platform_spot(p_kind text, p_message text)
returns void
language sql
security definer
set search_path = public
as $$
    insert into notifications (recipient_id, org_id, kind, message)
    select id, null, p_kind, p_message from profiles where is_platform_admin;
$$;

create or replace function request_promotion(
    p_org_id     uuid,
    p_product_id uuid,
    p_days       integer
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_kind    text := case when p_product_id is null then 'shop' else 'article' end;
    v_org     orgs%rowtype;
    v_price   numeric;
    v_free    boolean := false;
    v_id      uuid;
    v_start   timestamptz;
begin
    if auth.uid() is null then
        raise exception 'request_promotion() needs a signed-in caller';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur met la boutique en avant';
    end if;
    if p_days not in (7, 30) then
        raise exception 'Une mise en avant dure 7 ou 30 jours';
    end if;
    select * into v_org from orgs where id = p_org_id;
    if not v_org.storefront_enabled then
        raise exception 'Ouvrez d''abord la vitrine';
    end if;
    if v_kind = 'article' and not exists (
        select 1 from products p
         where p.id = p_product_id and p.org_id = p_org_id
           and p.is_active and p.is_published
           and coalesce(p.sale_price, 0) > 0 and p.quantity > 0
           and exists (select 1 from documents d where d.product_id = p.id)) then
        raise exception 'Un article mis en avant doit être sur la vitrine, avec une photo, un prix et du stock';
    end if;
    if exists (select 1 from promotions
                where org_id = p_org_id
                  and coalesce(product_id, '00000000-0000-0000-0000-000000000000'::uuid)
                    = coalesce(p_product_id, '00000000-0000-0000-0000-000000000000'::uuid)
                  and (status in ('requested', 'paid_claimed')
                       or (status = 'approved' and ends_at > now()))) then
        raise exception 'Cet emplacement est déjà demandé ou en cours';
    end if;

    v_price := spot_setting('spot_price_' || v_kind || '_' || p_days, 0);

    -- Kaj Pro's included spot: one 7-day article spot per calendar month.
    if v_kind = 'article' and p_days = 7 and org_plan(p_org_id) = 'pro'
       and (select count(*) from promotions
             where org_id = p_org_id and free
               and created_at >= date_trunc('month', now()))
           < spot_setting('pro_free_spots_month', 1) then
        v_free := true;
    end if;

    if v_free then
        v_start := next_spot_start(v_kind);
        insert into promotions (org_id, product_id, kind, days, price, currency,
                                free, status, starts_at, ends_at, requested_by,
                                decided_at)
        values (p_org_id, p_product_id, v_kind, p_days, 0,
                coalesce(v_org.default_currency, 'XOF'), true, 'approved',
                v_start, v_start + make_interval(days => p_days), auth.uid(), now())
        returning id into v_id;
    else
        insert into promotions (org_id, product_id, kind, days, price, currency,
                                requested_by)
        values (p_org_id, p_product_id, v_kind, p_days, v_price,
                coalesce(v_org.default_currency, 'XOF'), auth.uid())
        returning id into v_id;
        perform notify_platform_spot('spot_requested',
            v_org.name || ' demande une mise en avant (' || p_days || ' jours).');
    end if;
    return v_id;
end;
$$;

-- "J'ai payé": the owner says the Wave transfer went.
create or replace function claim_promotion_paid(p_promotion_id uuid, p_note text default null)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v promotions%rowtype;
begin
    select * into v from promotions where id = p_promotion_id;
    if not found or not is_org_admin(v.org_id) then
        raise exception 'Mise en avant introuvable';
    end if;
    if v.status <> 'requested' then
        raise exception 'Cette mise en avant n''attend pas de paiement';
    end if;
    update promotions set status = 'paid_claimed',
           note = nullif(btrim(coalesce(p_note, '')), '')
     where id = p_promotion_id;
    perform notify_platform_spot('spot_paid',
        (select name from orgs where id = v.org_id)
        || ' dit avoir payé sa mise en avant.');
end;
$$;

-- The platform's yes or no.
create or replace function decide_promotion(p_promotion_id uuid, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v promotions%rowtype;
    v_start timestamptz;
begin
    if not exists (select 1 from profiles
                    where id = auth.uid() and is_platform_admin) then
        raise exception 'Seule la plateforme valide une mise en avant';
    end if;
    select * into v from promotions where id = p_promotion_id;
    if not found or v.status not in ('requested', 'paid_claimed') then
        raise exception 'Cette demande n''est plus en attente';
    end if;
    if p_approve then
        v_start := next_spot_start(v.kind);
        update promotions
           set status = 'approved', starts_at = v_start,
               ends_at = v_start + make_interval(days => v.days),
               decided_by = auth.uid(), decided_at = now()
         where id = p_promotion_id;
    else
        update promotions
           set status = 'refused', decided_by = auth.uid(), decided_at = now()
         where id = p_promotion_id;
    end if;
    begin
        perform notify_org_admins(v.org_id, 'spot_' || case when p_approve then 'approved' else 'refused' end,
            case when p_approve
                 then 'Votre mise en avant est validée : elle commence le '
                      || to_char(v_start at time zone 'Africa/Ouagadougou', 'DD/MM à HH24:MI') || '.'
                 else 'Votre demande de mise en avant n''a pas été retenue.' end);
    exception when others then null;
    end;
end;
$$;

-- An owner's spots, newest first, with what each earned so far.
create or replace function my_promotions(p_org_id uuid)
returns table (
    id uuid, kind text, product_id uuid, product_name text, days integer,
    price numeric, currency text, free boolean, status text,
    starts_at timestamptz, ends_at timestamptz, created_at timestamptz,
    seen bigint, opened bigint, added bigint, ordered bigint
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select p.id, p.kind, p.product_id, pr.name, p.days, p.price, p.currency,
           p.free, p.status, p.starts_at, p.ends_at, p.created_at,
           coalesce(r.seen, 0), coalesce(r.opened, 0),
           coalesce(r.added, 0), coalesce(r.ordered, 0)
    from promotions p
    left join products pr on pr.id = p.product_id
    left join lateral (
        select sum(v.seen) seen, sum(v.opened) opened,
               sum(v.added) added, sum(v.ordered) ordered
          from storefront_visits v
         where v.org_id = p.org_id
           and (p.product_id is null or v.product_id = p.product_id)
           and p.starts_at is not null
           and v.day >= (p.starts_at at time zone 'Africa/Ouagadougou')::date
           and v.day <= (least(p.ends_at, now()) at time zone 'Africa/Ouagadougou')::date
    ) r on true
    where p.org_id = p_org_id and is_org_member(p_org_id)
    order by p.created_at desc;
$$;

-- The console's queue: what waits on the platform, and what runs.
create or replace function platform_promotions()
returns table (
    id uuid, org_id uuid, org_name text, kind text, product_name text,
    days integer, price numeric, currency text, free boolean, status text,
    starts_at timestamptz, ends_at timestamptz, created_at timestamptz,
    note text
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select p.id, p.org_id, o.name, p.kind, pr.name, p.days, p.price,
           p.currency, p.free, p.status, p.starts_at, p.ends_at,
           p.created_at, p.note
    from promotions p
    join orgs o on o.id = p.org_id
    left join products pr on pr.id = p.product_id
    where exists (select 1 from profiles
                   where id = auth.uid() and is_platform_admin)
      and (p.status in ('requested', 'paid_claimed')
           or (p.status = 'approved' and p.ends_at > now()))
    order by (p.status = 'paid_claimed') desc, (p.status = 'requested') desc,
             p.created_at desc;
$$;

-- What a spot costs, for the sheet that sells it.
create or replace function spot_terms()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'article_7',  spot_setting('spot_price_article_7', 1000),
        'article_30', spot_setting('spot_price_article_30', 3000),
        'shop_7',     spot_setting('spot_price_shop_7', 2500),
        'shop_30',    spot_setting('spot_price_shop_30', 8000),
        'max_live',   spot_setting('spots_max_live', 8),
        'wave',       (select value #>> '{}' from platform_settings where key = 'platform_wave'),
        'wave_name',  (select value #>> '{}' from platform_settings where key = 'platform_wave_name'),
        'currency',   coalesce((select value #>> '{}' from platform_settings where key = 'pro_currency'), 'XOF')
    );
$$;

-- ------------------------------------------------------------
-- 3. Where the spots show
-- ------------------------------------------------------------
-- À la une: the running article spots, then 054's hand-set ones. Same
-- return type as 054, so create or replace.
create or replace function storefront_featured()
returns table (
    id         uuid,
    name       text,
    sale_price numeric,
    in_stock   boolean,
    photo_key  text,
    shop_name  text,
    shop_slug  text,
    currency   text
)
language sql
stable
security definer
set search_path = public
as $$
    select p.id, p.name, p.sale_price, (p.quantity > 0),
           (select d.r2_key from documents d
             where d.product_id = p.id
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1),
           o.name, o.slug, o.default_currency
    from products p
    join orgs o on o.id = p.org_id
    left join lateral (
        select min(pm.starts_at) as since from promotions pm
         where pm.product_id = p.id and pm.status = 'approved'
           and pm.starts_at <= now() and pm.ends_at > now()
    ) spot on true
    where (spot.since is not null or p.featured_until > now())
      and p.is_active
      and p.is_published
      and o.storefront_enabled
      and o.archived_at  is null
      and o.suspended_at is null
    order by (spot.since is null), spot.since, p.featured_until desc nulls last, p.name
    limit 12;
$$;

-- The shops paying for the top of the directory, right now.
create or replace function storefront_spotlights()
returns table (slug text)
language sql
stable
security definer
set search_path = public
as $$
    select distinct o.slug
    from promotions pm
    join orgs o on o.id = pm.org_id
    where pm.kind = 'shop' and pm.status = 'approved'
      and pm.starts_at <= now() and pm.ends_at > now()
      and o.id = storefront_open(o.slug);
$$;

-- ------------------------------------------------------------
-- 4. Grants
-- ------------------------------------------------------------
revoke execute on function record_visit(text, text, uuid)           from public;
revoke execute on function record_seen(uuid[])                      from public;
revoke execute on function request_promotion(uuid, uuid, integer)   from public;
revoke execute on function claim_promotion_paid(uuid, text)         from public;
revoke execute on function decide_promotion(uuid, boolean)          from public;
revoke execute on function my_promotions(uuid)                      from public;
revoke execute on function platform_promotions()                    from public;
revoke execute on function spot_terms()                             from public;
revoke execute on function storefront_spotlights()                  from public;
revoke execute on function storefront_featured()                    from public;
revoke execute on function spot_setting(text, numeric)              from public;
revoke execute on function next_spot_start(text)                    from public;
revoke execute on function notify_platform_spot(text, text)         from public;

do $$
begin
    -- The street counts and reads (063 rule: say it by name).
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function record_visit(text, text, uuid) to anon;
        grant execute on function record_seen(uuid[])            to anon;
        grant execute on function storefront_spotlights()        to anon;
        grant execute on function storefront_featured()          to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function record_visit(text, text, uuid)         to authenticated;
        grant execute on function record_seen(uuid[])                    to authenticated;
        grant execute on function storefront_spotlights()                to authenticated;
        grant execute on function storefront_featured()                  to authenticated;
        grant execute on function request_promotion(uuid, uuid, integer) to authenticated;
        grant execute on function claim_promotion_paid(uuid, text)       to authenticated;
        grant execute on function decide_promotion(uuid, boolean)        to authenticated;
        grant execute on function my_promotions(uuid)                    to authenticated;
        grant execute on function platform_promotions()                  to authenticated;
        grant execute on function spot_terms()                           to authenticated;
        grant select on promotions to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 072_console_today.sql
-- ============================================================
-- ============================================================
-- 072_console_today.sql — the console opens on today.
--
-- The October audit: the platform console opened on a table of businesses
-- under nine unlabelled icons. What waited on the platform — a business
-- application, a "J'ai payé" for Kaj Pro or a spot, a courier asking to
-- carry, an order nobody had touched — was each behind its own icon, and
-- nothing said what the platform earned or whether it was growing.
--
--   1. platform_today(): one call, four blocks —
--        todo:   what waits on the platform, each a count the console
--                links to its screen; orders stuck (pending over 2 h,
--                on the road over 3 h) are counted here too.
--        money:  this month — Pro claimed and handled, spots sold, the
--                delivery cut (067), and what the shops sold through
--                their windows.
--        growth: businesses, windows open and windows with something on
--                them, orders this week against last, shoppers new this
--                month, from the street's counter (071) the windows
--                opened this week.
--        health: businesses gone silent 30 days, open windows with an
--                empty shelf, franc CFA shops pinned outside the zone,
--                published articles without a photo.
--      Platform admins only; anyone else gets null.
--   2. send_platform_message(): the platform writes to the people who
--      answer for a business — one, or every business — through the bell
--      (030). The console's "Écrire aux boutiques".
-- ============================================================

create or replace function platform_today()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_month timestamptz := date_trunc('month', now() at time zone 'Africa/Ouagadougou')
                           at time zone 'Africa/Ouagadougou';
    v_week  timestamptz := now() - interval '7 days';
begin
    if not exists (select 1 from profiles
                    where id = auth.uid() and is_platform_admin) then
        return null;
    end if;

    return jsonb_build_object(
        'todo', jsonb_build_object(
            'applications', (select count(*) from org_applications where status = 'pending'),
            'pro_requests', (select count(*) from plan_requests where handled_at is null),
            'spots',        (select count(*) from promotions
                              where status in ('requested', 'paid_claimed')),
            'spots_paid',   (select count(*) from promotions where status = 'paid_claimed'),
            'couriers',     (select count(*) from couriers where status = 'pending'),
            'orders_stuck', (select count(*) from orders
                              where (status = 'pending' and created_at < now() - interval '2 hours')
                                 or (status in ('in_transit', 'picked_up')
                                     and updated_at < now() - interval '3 hours'))
        ),
        'money', jsonb_build_object(
            'currency', 'XOF',
            'pro',      (select coalesce(sum(amount), 0) from plan_requests
                          where handled_at >= v_month),
            'spots',    (select coalesce(sum(price), 0) from promotions
                          where status = 'approved' and not free
                            and decided_at >= v_month),
            'delivery_cut', (select coalesce(sum(platform_fee), 0) from orders
                              where status = 'delivered' and updated_at >= v_month),
            'shops_sold',   (select coalesce(sum(total), 0) from orders
                              where status = 'delivered' and updated_at >= v_month
                                and currency = 'XOF')
        ),
        'growth', jsonb_build_object(
            'businesses',     (select count(*) from orgs where archived_at is null),
            'new_month',      (select count(*) from orgs
                                where archived_at is null and created_at >= v_month),
            'windows_open',   (select count(*) from orgs
                                where storefront_enabled and archived_at is null
                                  and suspended_at is null),
            'windows_stocked', (select count(*) from orgs o
                                 where o.storefront_enabled and o.archived_at is null
                                   and o.suspended_at is null
                                   and exists (select 1 from products p
                                                where p.org_id = o.id and p.is_active
                                                  and p.is_published)),
            'orders_week',    (select count(*) from orders where created_at >= v_week),
            'orders_last_week', (select count(*) from orders
                                  where created_at >= v_week - interval '7 days'
                                    and created_at <  v_week),
            'shoppers_new',   (select count(distinct customer_id) from orders o
                                where o.created_at >= v_month
                                  and not exists (select 1 from orders e
                                                   where e.customer_id = o.customer_id
                                                     and e.created_at < v_month)),
            'windows_opened_week', (select coalesce(sum(opened), 0) from storefront_visits
                                     where product_id is null
                                       and day >= current_date - 6)
        ),
        'health', jsonb_build_object(
            'silent_30',   (select count(*) from orgs
                             where archived_at is null and suspended_at is null
                               and coalesce(last_activity_at, created_at)
                                   < now() - interval '30 days'),
            'empty_windows', (select count(*) from orgs o
                               where o.storefront_enabled and o.archived_at is null
                                 and not exists (select 1 from products p
                                                  where p.org_id = o.id and p.is_active
                                                    and p.is_published)),
            'pins_far',    (select count(*) from orgs
                             where archived_at is null and lat is not null
                               and ((default_currency = 'XOF'
                                     and not (lat between 2 and 26 and lng between -19 and 17))
                                 or (default_currency = 'XAF'
                                     and not (lat between -6 and 24 and lng between 7 and 30)))),
            'published',   (select count(*) from products p
                             join orgs o on o.id = p.org_id
                            where o.storefront_enabled and p.is_active and p.is_published),
            'no_photo',    (select count(*) from products p
                             join orgs o on o.id = p.org_id
                            where o.storefront_enabled and p.is_active and p.is_published
                              and not exists (select 1 from documents d
                                               where d.product_id = p.id))
        )
    );
end;
$$;

-- The platform writes to the businesses. Null org: every live business.
-- Returns how many people it reached.
create or replace function send_platform_message(p_org_id uuid, p_message text)
returns integer
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_text  text := nullif(btrim(coalesce(p_message, '')), '');
    v_count integer;
begin
    if not exists (select 1 from profiles
                    where id = auth.uid() and is_platform_admin) then
        raise exception 'Seule la plateforme écrit aux boutiques';
    end if;
    if v_text is null then
        raise exception 'Le message est vide';
    end if;
    if length(v_text) > 500 then
        raise exception 'Un message tient en 500 caractères';
    end if;
    insert into notifications (recipient_id, org_id, kind, message)
    select distinct m.user_id, m.org_id, 'platform_message', 'Kaj : ' || v_text
      from memberships m
      join orgs o on o.id = m.org_id
     where m.role in ('owner', 'super_admin', 'admin')
       and o.archived_at is null
       and (p_org_id is null or m.org_id = p_org_id);
    get diagnostics v_count = row_count;
    return v_count;
end;
$$;

revoke execute on function platform_today()                  from public;
revoke execute on function send_platform_message(uuid, text) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function platform_today()                  to authenticated;
        grant execute on function send_platform_message(uuid, text) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 073_delivery_runs.sql
-- ============================================================
-- ============================================================
-- 073_delivery_runs.sql — a delivery that runs itself, and says where it is.
--
-- The October audit, "the delivery side is trash": a shopper who ordered
-- saw a status word and nothing else — no time, no courier, no way to know
-- it was stuck; a ready order nobody took sat there with nothing telling
-- the shop, and nothing the shop could do but wait; the courier marked an
-- order delivered with one tap, at any door; a door that did not open had
-- no outcome but "delivered"; the cash a courier collected was nobody's
-- ledger; a shop with its own boy on a moto could not hand him its orders;
-- and the board listed deliveries oldest first, wherever they were.
--
--   1. order_events: every status an order passes through, with its time.
--      Written by trigger, so every path — shop, courier, cancel — records.
--      The state clocks, the shopper's timeline and "stuck" read it.
--   2. A handover code: four digits drawn at a delivery order's birth,
--      shown to the shopper only. courier_deliver(order, code) is the way
--      a courier closes a delivery; courier_mark(…, 'delivered') now asks
--      for it. The shop can still mark it delivered (its word, its order).
--   3. courier_fail(order, reason): the door did not open — absent,
--      refused, unreachable, other. The order is cancelled with the reason
--      (orders.outcome), the goods go back to the shop, everyone is told.
--   4. shop_deliver_self(order): a ready delivery nobody has taken — the
--      shop carries it itself. No courier, no platform share.
--   5. The cash: a cash order a courier delivered is owed to the shop until
--      the shop says it was handed over (confirm_cash_received). The
--      courier sees what they hold; the shop sees what it is owed.
--   6. org_couriers: a shop names its own couriers. Its ready orders are
--      theirs alone for the first ten minutes, then the street's.
--   7. delivery_board(lat, lng): the board, nearest shop first, the shop's
--      own orders flagged and first; take_delivery honours the ten minutes.
--   8. order_tracking(order): the shopper's page — the timeline, the
--      courier's name and phone once on the road, the shop's phone, the
--      code; for the shop, the same without the code.
-- ============================================================

insert into platform_settings (key, value) values
    ('own_courier_minutes', '10'),
    ('stuck_ready_minutes', '20')
on conflict (key) do nothing;

-- ------------------------------------------------------------
-- 1. The timeline
-- ------------------------------------------------------------
create table if not exists order_events (
    id       bigserial primary key,
    order_id uuid not null references orders(id) on delete cascade,
    status   text not null,
    at       timestamptz not null default now(),
    by_user  uuid
);
create index if not exists order_events_by_order on order_events (order_id, at);
alter table order_events enable row level security;
-- No policies: read through order_tracking() as its definer.

create or replace function trg_order_event()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if tg_op = 'INSERT' or new.status is distinct from old.status then
        insert into order_events (order_id, status, by_user)
        values (new.id, new.status, auth.uid());
    end if;
    return new;
end;
$$;

create or replace trigger order_event
after insert or update of status on orders
for each row execute function trg_order_event();

-- Orders placed before 073 get their birth and their present state, so a
-- clock can still be read on them.
insert into order_events (order_id, status, at)
select o.id, 'pending', o.created_at from orders o
 where not exists (select 1 from order_events e where e.order_id = o.id);
insert into order_events (order_id, status, at)
select o.id, o.status, o.updated_at from orders o
 where o.status <> 'pending'
   and not exists (select 1 from order_events e
                    where e.order_id = o.id and e.status = o.status);

-- When an order entered the state it is in.
create or replace function order_status_since(p_order_id uuid)
returns timestamptz
language sql
stable
security definer
set search_path = public
as $$
    select coalesce(
        (select max(e.at) from order_events e
          join orders o on o.id = e.order_id
         where e.order_id = p_order_id and e.status = o.status),
        (select updated_at from orders where id = p_order_id));
$$;

-- ------------------------------------------------------------
-- 2. The handover code
-- ------------------------------------------------------------
alter table orders add column if not exists handover_code text;
alter table orders add column if not exists outcome text;
alter table orders add column if not exists self_delivered boolean not null default false;
alter table orders add column if not exists cash_received_at timestamptz;

create or replace function trg_order_handover_code()
returns trigger
language plpgsql
as $$
begin
    if new.fulfilment = 'delivery' and new.handover_code is null then
        new.handover_code := lpad((floor(random() * 10000))::int::text, 4, '0');
    end if;
    return new;
end;
$$;

create or replace trigger order_handover_code
before insert on orders
for each row execute function trg_order_handover_code();

update orders set handover_code = lpad((floor(random() * 10000))::int::text, 4, '0')
 where fulfilment = 'delivery' and handover_code is null
   and status in ('pending', 'accepted', 'ready', 'in_transit');

-- The courier closes a delivery at the door, with the shopper's code.
create or replace function courier_deliver(p_order_id uuid, p_code text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v orders%rowtype; v_shop text;
begin
    select * into v from orders where id = p_order_id;
    if not found or v.courier_id is distinct from auth.uid() then
        raise exception 'Cette livraison n''est pas la vôtre';
    end if;
    if v.status <> 'in_transit' then
        raise exception 'Cette livraison n''est pas en route';
    end if;
    if v.handover_code is not null
       and btrim(coalesce(p_code, '')) <> v.handover_code then
        raise exception 'Code incorrect : demandez au client les 4 chiffres de sa commande';
    end if;
    update orders set status = 'delivered', updated_at = now() where id = p_order_id;
    select name into v_shop from orgs where id = v.org_id;
    begin
        insert into notifications (recipient_id, org_id, kind, message)
        values (v.customer_id, v.org_id, 'order_delivered',
                'Votre commande chez ' || v_shop || ' est livrée');
        perform notify_org_admins(v.org_id, 'order_delivered',
            'La commande de ' || v.customer_name || ' est livrée');
    exception when others then null;
    end;
end;
$$;

-- 056's courier_mark, same signature: the road is still one tap, the door
-- now needs the code (courier_deliver).
create or replace function courier_mark(p_order_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare v_order orders%rowtype; v_shop text;
begin
    select * into v_order from orders where id = p_order_id;
    if not found or v_order.courier_id is distinct from auth.uid() then
        raise exception 'This delivery is not yours';
    end if;
    if p_status = 'delivered' then
        if v_order.status <> 'in_transit' then
            raise exception 'A delivery cannot go from % to %', v_order.status, p_status;
        end if;
        if v_order.handover_code is not null then
            raise exception 'Demandez au client le code de sa commande pour la clore';
        end if;
        perform courier_deliver(p_order_id, null);
        return;
    end if;
    if not (v_order.status = 'ready' and p_status = 'in_transit') then
        raise exception 'A delivery cannot go from % to %', v_order.status, p_status;
    end if;
    update orders set status = p_status, updated_at = now() where id = p_order_id;
    select name into v_shop from orgs where id = v_order.org_id;
    begin
        insert into notifications (recipient_id, org_id, kind, message)
        values (v_order.customer_id, v_order.org_id, 'order_in_transit',
                'Votre commande chez ' || v_shop || ' est en route');
    exception when others then null;
    end;
end;
$$;

-- ------------------------------------------------------------
-- 3. When the door does not open
-- ------------------------------------------------------------
create or replace function courier_fail(p_order_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v orders%rowtype; v_shop text; v_words text;
begin
    select * into v from orders where id = p_order_id;
    if not found or v.courier_id is distinct from auth.uid() then
        raise exception 'Cette livraison n''est pas la vôtre';
    end if;
    if v.status <> 'in_transit' then
        raise exception 'Seule une livraison en route peut échouer';
    end if;
    if p_reason not in ('absent', 'refused', 'unreachable', 'other') then
        raise exception 'Raison inconnue : %', p_reason;
    end if;
    v_words := case p_reason
        when 'absent'      then 'client absent'
        when 'refused'     then 'refusée par le client'
        when 'unreachable' then 'client injoignable'
        else 'autre raison' end;
    update orders set status = 'cancelled', outcome = p_reason, updated_at = now()
     where id = p_order_id;
    select name into v_shop from orgs where id = v.org_id;
    begin
        perform notify_org_admins(v.org_id, 'delivery_failed',
            'Livraison de ' || v.customer_name || ' échouée (' || v_words
            || ') : le livreur rapporte la commande.');
        insert into notifications (recipient_id, org_id, kind, message)
        values (v.customer_id, v.org_id, 'delivery_failed',
                'La livraison de votre commande chez ' || v_shop
                || ' n''a pas pu se faire (' || v_words || ').');
    exception when others then null;
    end;
end;
$$;

-- ------------------------------------------------------------
-- 4. "Je livre moi-même"
-- ------------------------------------------------------------
create or replace function shop_deliver_self(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v orders%rowtype; v_shop text;
begin
    select * into v from orders where id = p_order_id;
    if not found or not can_write_org(v.org_id) then
        raise exception 'Seule la boutique livre ses commandes';
    end if;
    if v.fulfilment <> 'delivery' or v.status not in ('accepted', 'ready')
       or v.courier_id is not null then
        raise exception 'Cette commande a déjà un livreur, ou n''est pas à livrer';
    end if;
    update orders
       set status = 'in_transit', self_delivered = true, platform_fee = 0,
           updated_at = now()
     where id = p_order_id;
    select name into v_shop from orgs where id = v.org_id;
    begin
        insert into notifications (recipient_id, org_id, kind, message)
        values (v.customer_id, v.org_id, 'order_in_transit',
                v_shop || ' vous livre lui-même : votre commande est en route');
    exception when others then null;
    end;
end;
$$;

-- decide_order (056) lets the shop take in_transit → delivered already.

-- ------------------------------------------------------------
-- 5. The cash
-- ------------------------------------------------------------
-- What a courier holds: cash orders they delivered that the shop has not
-- said it received, newest first.
create or replace function courier_cash()
returns table (
    order_id      uuid,
    shop_name     text,
    shop_phone    text,
    customer_name text,
    total         numeric,
    delivery_fee  numeric,
    currency      text,
    delivered_at  timestamptz
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    perform assert_approved_courier();
    return query
    select o.id, g.name, g.phone, o.customer_name, o.total, o.delivery_fee,
           o.currency, o.updated_at
      from orders o join orgs g on g.id = o.org_id
     where o.courier_id = auth.uid()
       and o.status = 'delivered' and o.payment_method = 'cash'
       and o.paid_at is null and o.cash_received_at is null
     order by o.updated_at desc;
end;
$$;

-- What the shop is owed, courier by courier.
create or replace function shop_cash_owed(p_org_id uuid)
returns table (
    order_id      uuid,
    courier_name  text,
    courier_phone text,
    customer_name text,
    total         numeric,
    currency      text,
    delivered_at  timestamptz
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not is_org_member(p_org_id) then
        raise exception 'Only the shop sees its orders';
    end if;
    return query
    select o.id,
           coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                    nullif(btrim(coalesce(p.full_name, '')), ''), 'Livreur'),
           c.phone, o.customer_name, o.total, o.currency, o.updated_at
      from orders o
      join profiles p on p.id = o.courier_id
      left join couriers c on c.user_id = o.courier_id
     where o.org_id = p_org_id
       and o.status = 'delivered' and o.payment_method = 'cash'
       and o.paid_at is null and o.cash_received_at is null
     order by o.updated_at;
end;
$$;

create or replace function confirm_cash_received(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v orders%rowtype;
begin
    select * into v from orders where id = p_order_id;
    if not found or not can_write_org(v.org_id) then
        raise exception 'Seule la boutique confirme l''argent reçu';
    end if;
    if v.status <> 'delivered' or v.payment_method <> 'cash' then
        raise exception 'Cette commande n''attend pas d''argent du livreur';
    end if;
    update orders set cash_received_at = now(), paid_at = coalesce(paid_at, now())
     where id = p_order_id;
end;
$$;

-- ------------------------------------------------------------
-- 6. A shop's own couriers
-- ------------------------------------------------------------
create table if not exists org_couriers (
    org_id     uuid not null references orgs(id) on delete cascade,
    user_id    uuid not null references profiles(id) on delete cascade,
    created_at timestamptz not null default now(),
    primary key (org_id, user_id)
);
alter table org_couriers enable row level security;
do $$ begin
    if not exists (select 1 from pg_policies where tablename = 'org_couriers'
                    and policyname = 'org couriers readable by members') then
        create policy "org couriers readable by members"
        on org_couriers for select using (is_org_member(org_id));
    end if;
end $$;

-- Adds an approved courier to the shop by phone; returns their name.
create or replace function add_org_courier(p_org_id uuid, p_phone text)
returns text
language plpgsql
security definer
set search_path = public, auth
as $$
declare v_user uuid; v_name text;
    v_digits text := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g');
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur choisit les livreurs de la boutique';
    end if;
    select c.user_id into v_user from couriers c
      left join profiles p on p.id = c.user_id
     where c.status = 'approved'
       and length(v_digits) >= 8
       and (right(regexp_replace(coalesce(c.phone, ''), '\D', '', 'g'), 8) = right(v_digits, 8)
            or right(regexp_replace(coalesce(p.phone, ''), '\D', '', 'g'), 8) = right(v_digits, 8))
     limit 1;
    if v_user is null then
        raise exception 'Aucun livreur validé avec ce numéro. Il doit d''abord s''inscrire comme livreur dans Kaj.';
    end if;
    insert into org_couriers (org_id, user_id) values (p_org_id, v_user)
    on conflict do nothing;
    select coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''),
                    nullif(btrim(coalesce(full_name, '')), ''), 'Livreur')
      into v_name from profiles where id = v_user;
    return v_name;
end;
$$;

create or replace function remove_org_courier(p_org_id uuid, p_user_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur choisit les livreurs de la boutique';
    end if;
    delete from org_couriers where org_id = p_org_id and user_id = p_user_id;
end;
$$;

create or replace function org_courier_list(p_org_id uuid)
returns table (user_id uuid, name text, phone text)
language sql
stable
security definer
set search_path = public, auth
as $$
    select oc.user_id,
           coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                    nullif(btrim(coalesce(p.full_name, '')), ''), 'Livreur'),
           coalesce(c.phone, p.phone)
      from org_couriers oc
      join profiles p on p.id = oc.user_id
      left join couriers c on c.user_id = oc.user_id
     where oc.org_id = p_org_id and is_org_member(p_org_id)
     order by oc.created_at;
$$;

-- Whether this courier may take this ready order now: the shop's own
-- couriers at once, everyone else after own_courier_minutes.
create or replace function courier_may_take(p_order_id uuid, p_user uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select not exists (select 1 from org_couriers oc
                        join orders o on o.org_id = oc.org_id
                       where o.id = p_order_id)
        or exists (select 1 from org_couriers oc
                    join orders o on o.org_id = oc.org_id
                   where o.id = p_order_id and oc.user_id = p_user)
        or order_status_since(p_order_id)
           < now() - make_interval(mins => plan_limit('own_courier_minutes', 10)::int);
$$;

-- 056's take_delivery, same signature, with the shop's ten minutes.
create or replace function take_delivery(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare v_order orders%rowtype; v_shop text;
begin
    perform assert_approved_courier();
    if not courier_may_take(p_order_id, auth.uid()) then
        raise exception 'Cette boutique a ses livreurs : la course s''ouvre à tous dans quelques minutes';
    end if;
    update orders
       set courier_id = auth.uid(), updated_at = now()
     where id = p_order_id
       and status = 'ready'
       and fulfilment = 'delivery'
       and courier_id is null
    returning * into v_order;
    if not found then
        raise exception 'This delivery is no longer available';
    end if;
    select name into v_shop from orgs where id = v_order.org_id;
    begin
        perform notify_org_admins(v_order.org_id, 'delivery_taken',
            'Un livreur prend la commande de ' || v_order.customer_name);
        insert into notifications (recipient_id, org_id, kind, message)
        values (v_order.customer_id, v_order.org_id, 'order_courier',
                'Un livreur s''occupe de votre commande chez ' || v_shop);
    exception when others then
        null;
    end;
end;
$$;

-- ------------------------------------------------------------
-- 7. The board, nearest first
-- ------------------------------------------------------------
create or replace function delivery_board(
    p_lat double precision default null,
    p_lng double precision default null
)
returns table (
    order_id       uuid,
    shop_name      text,
    shop_address   text,
    shop_lat       double precision,
    shop_lng       double precision,
    drop_address   text,
    drop_lat       double precision,
    drop_lng       double precision,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    payment_method text,
    paid_at        timestamptz,
    delivery_fee   numeric,
    distance_km    double precision,
    to_shop_km     double precision,
    own_shop       boolean,
    ready_since    timestamptz
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    perform assert_approved_courier();
    return query
    select x.* from (
        select o.id, g.name, g.address, g.lat, g.lng,
               o.address, o.drop_lat, o.drop_lng, o.total, o.currency,
               o.created_at, o.payment_method, o.paid_at, o.delivery_fee,
               case when g.lat is null or o.drop_lat is null then null
                    else distance_km(g.lat, g.lng, o.drop_lat, o.drop_lng) end,
               case when p_lat is null or p_lng is null or g.lat is null then null
                    else distance_km(p_lat, p_lng, g.lat, g.lng) end,
               exists (select 1 from org_couriers oc
                        where oc.org_id = o.org_id and oc.user_id = auth.uid()),
               order_status_since(o.id)
          from orders o
          join orgs g on g.id = o.org_id
         where o.status = 'ready'
           and o.fulfilment = 'delivery'
           and o.courier_id is null
           and g.archived_at  is null
           and g.suspended_at is null
           and courier_may_take(o.id, auth.uid())
    ) x (order_id, shop_name, shop_address, shop_lat, shop_lng, drop_address,
         drop_lat, drop_lng, total, currency, created_at, payment_method,
         paid_at, delivery_fee, distance_km, to_shop_km, own_shop, ready_since)
    order by x.own_shop desc, (x.to_shop_km is null), x.to_shop_km, x.created_at;
end;
$$;

-- ------------------------------------------------------------
-- 8. Where is my order
-- ------------------------------------------------------------
create or replace function order_tracking(p_order_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare v orders%rowtype; g orgs%rowtype; v_customer boolean; v_courier jsonb;
begin
    select * into v from orders where id = p_order_id;
    if not found then
        return null;
    end if;
    v_customer := v.customer_id = auth.uid();
    if not v_customer and not is_org_member(v.org_id)
       and v.courier_id is distinct from auth.uid() then
        return null;
    end if;
    select * into g from orgs where id = v.org_id;
    if v.courier_id is not null then
        select jsonb_build_object(
                   'name', coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                                    nullif(btrim(coalesce(p.full_name, '')), ''), 'Livreur'),
                   -- A phone to call once the courier is on the road.
                   'phone', case when v.status = 'in_transit' or not v_customer
                                 then coalesce(c.phone, p.phone) end)
          into v_courier
          from profiles p left join couriers c on c.user_id = p.id
         where p.id = v.courier_id;
    end if;
    return jsonb_build_object(
        'status',     v.status,
        'fulfilment', v.fulfilment,
        'outcome',    v.outcome,
        'self',       v.self_delivered,
        'since',      order_status_since(v.id),
        'shop',       jsonb_build_object('name', g.name, 'phone', g.phone,
                                         'address', g.address),
        'courier',    v_courier,
        'code',       case when v_customer and v.status in ('ready', 'in_transit', 'accepted', 'pending')
                           then v.handover_code end,
        'events',     (select coalesce(jsonb_agg(jsonb_build_object(
                                 'status', e.status, 'at', e.at) order by e.at), '[]'::jsonb)
                         from order_events e where e.order_id = v.id)
    );
end;
$$;

-- The shop's open orders and how long each has sat in its state; the
-- shop's orders screen reads it beside shop_orders.
create or replace function shop_order_clocks(p_org_id uuid)
returns table (order_id uuid, status text, since timestamptz, stuck boolean,
               self_delivered boolean, outcome text)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not is_org_member(p_org_id) then
        raise exception 'Only the shop sees its orders';
    end if;
    return query
    select o.id, o.status, order_status_since(o.id),
           (o.status = 'pending' and order_status_since(o.id) < now() - interval '30 minutes')
        or (o.status = 'ready' and o.fulfilment = 'delivery' and o.courier_id is null
            and order_status_since(o.id)
                < now() - make_interval(mins => plan_limit('stuck_ready_minutes', 20)::int))
        or (o.status = 'in_transit' and order_status_since(o.id) < now() - interval '2 hours'),
           o.self_delivered, o.outcome
      from orders o
     where o.org_id = p_org_id
       and (o.status in ('pending', 'accepted', 'ready', 'in_transit')
            or (o.outcome is not null and o.updated_at > now() - interval '2 days'));
end;
$$;

-- ------------------------------------------------------------
-- Grants
-- ------------------------------------------------------------
revoke execute on function courier_deliver(uuid, text)                    from public;
revoke execute on function courier_fail(uuid, text)                       from public;
revoke execute on function shop_deliver_self(uuid)                        from public;
revoke execute on function courier_cash()                                 from public;
revoke execute on function shop_cash_owed(uuid)                           from public;
revoke execute on function confirm_cash_received(uuid)                    from public;
revoke execute on function add_org_courier(uuid, text)                    from public;
revoke execute on function remove_org_courier(uuid, uuid)                 from public;
revoke execute on function org_courier_list(uuid)                         from public;
revoke execute on function courier_may_take(uuid, uuid)                   from public;
revoke execute on function delivery_board(double precision, double precision) from public;
revoke execute on function order_tracking(uuid)                           from public;
revoke execute on function shop_order_clocks(uuid)                        from public;
revoke execute on function order_status_since(uuid)                       from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function courier_deliver(uuid, text)         to authenticated;
        grant execute on function courier_fail(uuid, text)            to authenticated;
        grant execute on function shop_deliver_self(uuid)             to authenticated;
        grant execute on function courier_cash()                      to authenticated;
        grant execute on function shop_cash_owed(uuid)                to authenticated;
        grant execute on function confirm_cash_received(uuid)         to authenticated;
        grant execute on function add_org_courier(uuid, text)         to authenticated;
        grant execute on function remove_org_courier(uuid, uuid)      to authenticated;
        grant execute on function org_courier_list(uuid)              to authenticated;
        grant execute on function delivery_board(double precision, double precision) to authenticated;
        grant execute on function order_tracking(uuid)                to authenticated;
        grant execute on function shop_order_clocks(uuid)             to authenticated;
        grant select on org_couriers to authenticated;
    end if;
end $$;

