-- ============================================================
-- 074_live_orders.sql
-- ============================================================
-- ============================================================
-- 074_live_orders.sql — an order reaches the screen when it happens.
--
-- The audit: phones learned of a new order, a courier taking one or a
-- delivery closing only when somebody pulled to refresh (073 added quiet
-- re-reads every minute). Supabase Realtime sends a row's change to every
-- screen subscribed to it, filtered by the same row-level security as a
-- read: the shop's members see their shop's orders, the shopper theirs,
-- the courier those they carry (056's policy). Nothing else changes —
-- the screens re-read through their usual functions when told.
--
-- The publication exists only on Supabase; elsewhere (CI, a local
-- Postgres) this does nothing.
-- ============================================================

do $$
begin
    if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
       and not exists (select 1 from pg_publication_tables
                        where pubname = 'supabase_realtime'
                          and schemaname = 'public' and tablename = 'orders') then
        execute 'alter publication supabase_realtime add table public.orders';
    end if;
end $$;


-- ============================================================
-- 075_security.sql
-- ============================================================
-- ============================================================
-- 075_security.sql — what the Sécurité page reads and does.
--
-- Before this, a person could change their password, and that was all:
-- no list of where the account was signed in, no way to close a phone that
-- was lost, no word when the account appeared on a new device, and nothing
-- an owner could require of the phones holding the shop's books.
--
--   1. user_devices: each phone or browser this account opened Kaj on,
--      named by the app (a local id, never a hardware one). register_device()
--      is called once per launch; a device seen for the first time, on an
--      account that already had one, rings that account's bell everywhere:
--      « Nouvelle connexion … ce n'était pas vous ? ».
--   2. my_sessions() / close_my_session() / close_my_other_sessions(): the
--      account's sign-in sessions (auth.sessions), its own and nobody
--      else's. Closing one ends its refresh; an access token already issued
--      lives out its hour, and the page says so.
--   3. security_events: the account's own security history — new devices,
--      password and code changes, sessions closed, an admin's sign-out —
--      read by my_security_events().
--   4. orgs.lock_max_minutes: an owner's rule for the team's phones — the
--      app locks with the code after at most this many minutes away.
--      my_lock_policy() gives the strictest rule across the person's
--      businesses; set_lock_policy() is the owner's.
--   5. sign_out_member(): a lost phone. An admin closes every session of a
--      member of their business (never an owner's, never their own).
-- ============================================================

-- ------------------------------------------------------------
-- 1. Devices
-- ------------------------------------------------------------
create table if not exists user_devices (
    user_id    uuid not null references profiles(id) on delete cascade,
    device_id  text not null check (length(device_id) between 8 and 64),
    label      text not null default 'Appareil',
    first_seen timestamptz not null default now(),
    last_seen  timestamptz not null default now(),
    primary key (user_id, device_id)
);
alter table user_devices enable row level security;
-- No policies: read and written through the functions below.

create table if not exists security_events (
    id      bigint generated always as identity primary key,
    user_id uuid not null references profiles(id) on delete cascade,
    kind    text not null,
    detail  text,
    at      timestamptz not null default now()
);
create index if not exists security_events_by_user on security_events (user_id, at desc);
alter table security_events enable row level security;

create or replace function security_log(p_user uuid, p_kind text, p_detail text)
returns void
language sql
security definer
set search_path = public
as $$
    insert into security_events (user_id, kind, detail) values (p_user, p_kind, p_detail);
$$;

-- Called once per launch. Returns true when this device is new to the
-- account.
create or replace function register_device(p_device_id text, p_label text)
returns boolean
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_me    uuid := auth.uid();
    v_label text := left(coalesce(nullif(btrim(p_label), ''), 'Appareil'), 80);
    v_new   boolean;
    v_had   boolean;
begin
    if v_me is null then
        raise exception 'register_device() needs a signed-in caller';
    end if;
    select exists (select 1 from user_devices where user_id = v_me) into v_had;
    insert into user_devices (user_id, device_id, label)
    values (v_me, p_device_id, v_label)
    on conflict (user_id, device_id)
    do update set last_seen = now(), label = excluded.label
    returning (xmax = 0) into v_new;
    if v_new then
        perform security_log(v_me, 'new_device', v_label);
        if v_had then
            begin
                insert into notifications (recipient_id, org_id, kind, message)
                values (v_me, null, 'new_device',
                        'Nouvelle connexion à votre compte sur ' || v_label
                        || '. Ce n''était pas vous ? Ouvrez Compte › Sécurité '
                        || 'et fermez les autres appareils.');
            exception when others then null;
            end;
        end if;
    end if;
    return v_new;
end;
$$;

-- ------------------------------------------------------------
-- 2. Sessions
-- ------------------------------------------------------------
create or replace function my_sessions()
returns table (
    id         uuid,
    created_at timestamptz,
    last_used  timestamptz,
    user_agent text,
    ip         text,
    current    boolean
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select s.id, s.created_at,
           coalesce(s.refreshed_at at time zone 'UTC', s.updated_at),
           s.user_agent, host(s.ip),
           s.id::text = (auth.jwt() ->> 'session_id')
    from auth.sessions s
    where s.user_id = auth.uid()
    order by (s.id::text = (auth.jwt() ->> 'session_id')) desc,
             coalesce(s.refreshed_at at time zone 'UTC', s.updated_at) desc;
$$;

create or replace function close_my_session(p_session_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v_rows int;
begin
    if auth.uid() is null then
        raise exception 'close_my_session() needs a signed-in caller';
    end if;
    if p_session_id::text = (auth.jwt() ->> 'session_id') then
        raise exception 'C''est cet appareil : utilisez « Se déconnecter »';
    end if;
    delete from auth.sessions where id = p_session_id and user_id = auth.uid();
    get diagnostics v_rows = row_count;
    if v_rows = 0 then
        raise exception 'Session introuvable';
    end if;
    perform security_log(auth.uid(), 'session_closed', null);
end;
$$;

create or replace function close_my_other_sessions()
returns integer
language plpgsql
security definer
set search_path = public, auth
as $$
declare v_rows int;
begin
    if auth.uid() is null then
        raise exception 'close_my_other_sessions() needs a signed-in caller';
    end if;
    delete from auth.sessions
     where user_id = auth.uid()
       and id::text is distinct from (auth.jwt() ->> 'session_id');
    get diagnostics v_rows = row_count;
    perform security_log(auth.uid(), 'signed_out_others', v_rows::text);
    return v_rows;
end;
$$;

-- ------------------------------------------------------------
-- 3. The account's history
-- ------------------------------------------------------------
-- What the app itself reports: a password or a code changed.
create or replace function log_security_event(p_kind text, p_detail text default null)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null then
        raise exception 'log_security_event() needs a signed-in caller';
    end if;
    if p_kind not in ('password_changed', 'pin_changed', 'lock_changed') then
        raise exception 'Événement inconnu : %', p_kind;
    end if;
    perform security_log(auth.uid(), p_kind, left(p_detail, 120));
end;
$$;

create or replace function my_security_events(p_limit integer default 20)
returns table (kind text, detail text, at timestamptz)
language sql
stable
security definer
set search_path = public, auth
as $$
    select e.kind, e.detail, e.at
    from security_events e
    where e.user_id = auth.uid()
    order by e.at desc
    limit least(greatest(coalesce(p_limit, 20), 1), 100);
$$;

create or replace function my_devices()
returns table (device_id text, label text, first_seen timestamptz, last_seen timestamptz)
language sql
stable
security definer
set search_path = public, auth
as $$
    select d.device_id, d.label, d.first_seen, d.last_seen
    from user_devices d
    where d.user_id = auth.uid()
    order by d.last_seen desc;
$$;

-- ------------------------------------------------------------
-- 4. The team's lock rule
-- ------------------------------------------------------------
alter table orgs add column if not exists lock_max_minutes integer;
do $$ begin
    if not exists (select 1 from pg_constraint where conname = 'orgs_lock_max_minutes_range') then
        alter table orgs add constraint orgs_lock_max_minutes_range
            check (lock_max_minutes is null or lock_max_minutes between 1 and 60);
    end if;
end $$;

create or replace function set_lock_policy(p_org_id uuid, p_minutes integer)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur fixe la règle de verrouillage';
    end if;
    if p_minutes is not null and (p_minutes < 1 or p_minutes > 60) then
        raise exception 'Entre 1 et 60 minutes';
    end if;
    update orgs set lock_max_minutes = p_minutes where id = p_org_id;
end;
$$;

-- The strictest rule among the person's businesses; null when none has one.
create or replace function my_lock_policy()
returns integer
language sql
stable
security definer
set search_path = public, auth
as $$
    select min(o.lock_max_minutes)
    from memberships m
    join orgs o on o.id = m.org_id
    where m.user_id = auth.uid() and o.archived_at is null;
$$;

create or replace function org_lock_policy(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public, auth
as $$
    select lock_max_minutes from orgs
     where id = p_org_id and is_org_member(p_org_id);
$$;

-- ------------------------------------------------------------
-- 5. A lost phone
-- ------------------------------------------------------------
create or replace function sign_out_member(p_org_id uuid, p_user_id uuid)
returns integer
language plpgsql
security definer
set search_path = public, auth
as $$
declare v_rows int;
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur peut déconnecter un membre';
    end if;
    if p_user_id = auth.uid() then
        raise exception 'Pour vous-même : Compte › Sécurité';
    end if;
    if not exists (select 1 from memberships
                    where org_id = p_org_id and user_id = p_user_id) then
        raise exception 'Cette personne n''est pas membre de l''entreprise';
    end if;
    if exists (select 1 from memberships
                where user_id = p_user_id and org_id = p_org_id
                  and role in ('owner', 'super_admin')) then
        raise exception 'Le propriétaire ne peut pas être déconnecté par un autre';
    end if;
    delete from auth.sessions where user_id = p_user_id;
    get diagnostics v_rows = row_count;
    perform security_log(p_user_id, 'signed_out_by_admin',
        (select name from orgs where id = p_org_id));
    return v_rows;
end;
$$;

-- ------------------------------------------------------------
-- Grants
-- ------------------------------------------------------------
revoke execute on function security_log(uuid, text, text)        from public;
revoke execute on function register_device(text, text)           from public;
revoke execute on function my_sessions()                         from public;
revoke execute on function close_my_session(uuid)                from public;
revoke execute on function close_my_other_sessions()             from public;
revoke execute on function log_security_event(text, text)        from public;
revoke execute on function my_security_events(integer)           from public;
revoke execute on function my_devices()                          from public;
revoke execute on function set_lock_policy(uuid, integer)        from public;
revoke execute on function my_lock_policy()                      from public;
revoke execute on function org_lock_policy(uuid)                 from public;
revoke execute on function sign_out_member(uuid, uuid)           from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function register_device(text, text)       to authenticated;
        grant execute on function my_sessions()                     to authenticated;
        grant execute on function close_my_session(uuid)            to authenticated;
        grant execute on function close_my_other_sessions()         to authenticated;
        grant execute on function log_security_event(text, text)    to authenticated;
        grant execute on function my_security_events(integer)       to authenticated;
        grant execute on function my_devices()                      to authenticated;
        grant execute on function set_lock_policy(uuid, integer)    to authenticated;
        grant execute on function my_lock_policy()                  to authenticated;
        grant execute on function org_lock_policy(uuid)             to authenticated;
        grant execute on function sign_out_member(uuid, uuid)       to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 076_wave_checkout.sql
-- ============================================================
-- ============================================================
-- 076_wave_checkout.sql — paying by Wave (or card, on Wave's page), and the
-- shop paid on its own Wave number a moment later.
--
-- Until now every payment closed by hand: "J'ai payé" for Kaj Pro and spots,
-- « Paiement reçu » from the shop for a vitrine order paid on its own Wave
-- link. This is the automatic path, and it is Kaj's to run (the owner's
-- choice, "option 2"): Kaj holds one Wave Business account, registered with
-- Wave as an aggregator, and
--
--   * a shopper pays an order through a Wave checkout session tagged with
--     the shop (its aggregated-merchant id);
--   * Wave tells the kaj-pay Worker it is paid (a signed webhook);
--   * the order is marked paid, the shop and shopper are told, and the
--     Worker sends the goods' price, less the platform's share, to the
--     shop's own Wave number through Wave's Payout API — no Wave Business,
--     no RCCM, no key on the shop's side;
--   * Kaj Pro and spots paid the same way activate themselves.
--
-- "Card": Wave's checkout page is where a card is taken, when Wave offers it
-- for the account. The session is the same; the app opens it in a browser
-- rather than the Wave app. Nothing here touches a card number.
--
-- Dormant by design: nothing is offered until the platform turns
-- `wave_checkout` on (after the Worker has its WAVE_API_KEY), and an order is
-- payable this way only once its shop has given a payout number.
--
--   1. orgs.wave_payout_number (the shop's), orgs.wave_merchant_ref (the
--      aggregated-merchant id Wave gives each shop, set by the platform).
--   2. wave_payments: every session, its status, and the payout behind it.
--   3. wave_begin(): the caller's side — checks the thing exists, is theirs
--      to pay and is not paid, and fixes the amount from the database, never
--      from the phone.
--   4. wave_attach / wave_settle / wave_payout_done / wave_payout_queue:
--      the Worker's side, for the service role alone.
--   5. The reads: wave_terms(), my_wave_payment(), platform_wave_payments().
-- ============================================================

insert into platform_settings (key, value) values
    ('wave_checkout',       'false'),
    -- Whether Wave's page takes cards for this account: Wave's to offer,
    -- the platform's to say once it has seen it work.
    ('wave_card',           'false'),
    ('wave_commission_pct', '0')
on conflict (key) do nothing;

-- ------------------------------------------------------------
-- 1. The shop's side
-- ------------------------------------------------------------
alter table orgs add column if not exists wave_payout_number text;
alter table orgs add column if not exists wave_merchant_ref text;

create or replace function set_wave_payout_number(p_org_id uuid, p_number text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v text := nullif(regexp_replace(coalesce(p_number, ''), '[^0-9+]', '', 'g'), '');
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur choisit le numéro qui reçoit l''argent';
    end if;
    if v is not null and length(regexp_replace(v, '\D', '', 'g')) < 8 then
        raise exception 'Numéro Wave trop court';
    end if;
    if v is not null and left(v, 1) <> '+' then
        v := '+226' || right(v, 8);
    end if;
    update orgs set wave_payout_number = v where id = p_org_id;
end;
$$;

create or replace function set_wave_merchant_ref(p_org_id uuid, p_ref text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Seule la plateforme enregistre une boutique chez Wave';
    end if;
    update orgs set wave_merchant_ref = nullif(btrim(coalesce(p_ref, '')), '')
     where id = p_org_id;
end;
$$;

-- ------------------------------------------------------------
-- 2. The payments
-- ------------------------------------------------------------
create table if not exists wave_payments (
    id              uuid primary key default gen_random_uuid(),
    kind            text not null check (kind in ('order', 'pro', 'spot')),
    org_id          uuid not null references orgs(id) on delete cascade,
    order_id        uuid references orders(id) on delete set null,
    promotion_id    uuid references promotions(id) on delete set null,
    period          text check (period in ('month', 'year')),
    payer_id        uuid references profiles(id) on delete set null,
    method          text not null default 'wave' check (method in ('wave', 'card')),
    amount          numeric(14, 2) not null check (amount > 0),
    currency        text not null default 'XOF',
    commission      numeric(14, 2) not null default 0,
    session_id      text unique,
    launch_url      text,
    status          text not null default 'created'
                    check (status in ('created', 'open', 'succeeded', 'failed', 'expired')),
    transaction_id  text,
    payout_status   text not null default 'none'
                    check (payout_status in ('none', 'pending', 'sent', 'failed')),
    payout_to       text,
    payout_amount   numeric(14, 2),
    payout_id       text,
    payout_error    text,
    payout_attempts integer not null default 0,
    created_at      timestamptz not null default now(),
    paid_at         timestamptz,
    paid_out_at     timestamptz
);
create index if not exists wave_payments_payouts on wave_payments (created_at)
    where payout_status in ('pending', 'failed');
create index if not exists wave_payments_by_order on wave_payments (order_id);
alter table wave_payments enable row level security;
-- No policies: read through the functions below.

-- ------------------------------------------------------------
-- 3. The caller's side
-- ------------------------------------------------------------
create or replace function wave_on()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select coalesce((select (value #>> '{}')::boolean
                       from platform_settings where key = 'wave_checkout'), false);
$$;

-- Starts a payment: kind 'order' (p_ref an order of the caller's), 'pro'
-- (p_ref an org the caller administers; p_period month or year) or 'spot'
-- (p_ref a promotion awaiting payment). Returns what the Worker needs to ask
-- Wave for a session. The amount is the database's.
create or replace function wave_begin(
    p_kind   text,
    p_ref    uuid,
    p_method text default 'wave',
    p_period text default 'month'
)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_me     uuid := auth.uid();
    v_org    orgs%rowtype;
    v_amount numeric;
    v_cur    text := 'XOF';
    v_order  orders%rowtype;
    v_spot   promotions%rowtype;
    v_id     uuid;
    v_pct    numeric := coalesce((select (value #>> '{}')::numeric
                                    from platform_settings where key = 'wave_commission_pct'), 0);
begin
    if v_me is null then
        raise exception 'wave_begin() needs a signed-in caller';
    end if;
    if not wave_on() then
        raise exception 'Le paiement Wave n''est pas encore ouvert';
    end if;
    if p_method not in ('wave', 'card') then
        raise exception 'Moyen de paiement inconnu : %', p_method;
    end if;

    if p_kind = 'order' then
        select * into v_order from orders where id = p_ref;
        if not found or v_order.customer_id <> v_me then
            raise exception 'Commande introuvable';
        end if;
        if v_order.status in ('refused', 'cancelled') then
            raise exception 'Cette commande est annulée';
        end if;
        if v_order.paid_at is not null then
            raise exception 'Cette commande est déjà payée';
        end if;
        select * into v_org from orgs where id = v_order.org_id;
        if v_org.wave_payout_number is null then
            raise exception 'Cette boutique ne reçoit pas encore les paiements Wave';
        end if;
        v_amount := v_order.total;
        v_cur := v_order.currency;
    elsif p_kind = 'pro' then
        if not is_org_admin(p_ref) then
            raise exception 'Seul un administrateur paie Kaj Pro';
        end if;
        select * into v_org from orgs where id = p_ref;
        if p_period not in ('month', 'year') then
            raise exception 'Période inconnue : %', p_period;
        end if;
        v_amount := plan_limit(case when p_period = 'year' then 'pro_price_year'
                                    else 'pro_price_month' end,
                               case when p_period = 'year' then 25000 else 2500 end);
    elsif p_kind = 'spot' then
        select * into v_spot from promotions where id = p_ref;
        if not found or not is_org_admin(v_spot.org_id) then
            raise exception 'Mise en avant introuvable';
        end if;
        if v_spot.status not in ('requested', 'paid_claimed') then
            raise exception 'Cette mise en avant n''attend pas de paiement';
        end if;
        select * into v_org from orgs where id = v_spot.org_id;
        v_amount := v_spot.price;
        v_cur := v_spot.currency;
    else
        raise exception 'Paiement inconnu : %', p_kind;
    end if;

    if v_cur <> 'XOF' then
        raise exception 'Wave encaisse en francs CFA (XOF) seulement';
    end if;
    if coalesce(v_amount, 0) <= 0 then
        raise exception 'Rien à payer';
    end if;

    insert into wave_payments (kind, org_id, order_id, promotion_id, period,
                               payer_id, method, amount, currency, commission)
    values (p_kind, v_org.id,
            case when p_kind = 'order' then p_ref end,
            case when p_kind = 'spot' then p_ref end,
            case when p_kind = 'pro' then p_period end,
            v_me, p_method, v_amount, v_cur,
            case when p_kind = 'order' then round(v_amount * v_pct / 100.0) else 0 end)
    returning id into v_id;

    return jsonb_build_object(
        'payment_id',      v_id,
        'client_reference', v_id,
        'amount',          v_amount,
        'currency',        v_cur,
        'kind',            p_kind,
        -- Only an order is the shop's money; Kaj Pro and spots are Kaj's own.
        'aggregated_merchant_id', case when p_kind = 'order' then v_org.wave_merchant_ref end
    );
end;
$$;

-- What the app reads after coming back from Wave: did it go through?
create or replace function my_wave_payment(p_payment_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select jsonb_build_object('status', p.status, 'kind', p.kind,
                              'amount', p.amount, 'paid_at', p.paid_at)
    from wave_payments p
    where p.id = p_payment_id
      and (p.payer_id = auth.uid() or is_org_member(p.org_id));
$$;

-- Whether to draw « Payer avec Wave » at all: the platform's switch, and for
-- an order, the shop's payout number.
create or replace function wave_terms(p_org_id uuid default null)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'on', wave_on(),
        'shop_ready', p_org_id is not null and exists (
            select 1 from orgs where id = p_org_id and wave_payout_number is not null),
        'card', coalesce((select (value #>> '{}')::boolean
                            from platform_settings where key = 'wave_card'), false),
        'commission_pct', coalesce((select (value #>> '{}')::numeric
                                      from platform_settings where key = 'wave_commission_pct'), 0)
    );
$$;

-- ------------------------------------------------------------
-- 4. The Worker's side (service role only)
-- ------------------------------------------------------------
create or replace function wave_attach(p_payment_id uuid, p_session_id text, p_launch_url text)
returns void
language sql
security definer
set search_path = public
as $$
    update wave_payments
       set session_id = p_session_id, launch_url = p_launch_url, status = 'open'
     where id = p_payment_id and status = 'created';
$$;

-- Wave says a session ended. Idempotent: a second delivery of the same
-- webhook changes nothing and asks for no second payout. Returns the payout
-- to send, or null.
create or replace function wave_settle(
    p_client_reference uuid,
    p_session_id       text,
    p_succeeded        boolean,
    p_transaction_id   text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v     wave_payments%rowtype;
    v_org orgs%rowtype;
    v_start timestamptz;
    v_until date;
begin
    select * into v from wave_payments where id = p_client_reference for update;
    if not found then
        return null;
    end if;
    if v.session_id is not null and p_session_id is not null and v.session_id <> p_session_id then
        return null;
    end if;
    if v.status = 'succeeded' then
        return null;  -- delivered twice
    end if;
    if not p_succeeded then
        update wave_payments set status = 'failed' where id = v.id;
        return null;
    end if;

    update wave_payments
       set status = 'succeeded', paid_at = now(),
           transaction_id = p_transaction_id,
           session_id = coalesce(session_id, p_session_id)
     where id = v.id;
    select * into v_org from orgs where id = v.org_id;

    if v.kind = 'order' then
        update orders set paid_at = coalesce(paid_at, now()), payment_method = 'wave'
         where id = v.order_id;
        update wave_payments
           set payout_status = 'pending',
               payout_to = v_org.wave_payout_number,
               payout_amount = v.amount - v.commission
         where id = v.id;
        begin
            perform notify_org_admins(v.org_id, 'order_paid',
                'Commande payée par Wave : ' || to_char(v.amount, 'FM999G999G999')
                || ' F. L''argent part sur votre numéro Wave.');
            insert into notifications (recipient_id, org_id, kind, message)
            select o.customer_id, o.org_id, 'order_paid',
                   'Paiement reçu par ' || v_org.name || ' : merci !'
              from orders o where o.id = v.order_id;
        exception when others then null;
        end;
        return jsonb_build_object(
            'payment_id', v.id,
            'amount', v.amount - v.commission,
            'currency', v.currency,
            'mobile', v_org.wave_payout_number,
            'name', v_org.name);
    elsif v.kind = 'pro' then
        v_until := greatest(coalesce(case when v_org.plan = 'pro' then v_org.plan_until end,
                                     current_date), current_date)
                   + case when v.period = 'year' then interval '1 year' else interval '1 month' end;
        update orgs set plan = 'pro', plan_until = v_until,
                        plan_note = 'Wave ' || coalesce(p_transaction_id, '')
         where id = v.org_id;
        insert into plan_requests (org_id, user_id, amount, note, handled_at)
        values (v.org_id, v.payer_id, v.amount, 'Payé par Wave', now());
        begin
            perform notify_org_admins(v.org_id, 'pro_active',
                'Kaj Pro est actif jusqu''au ' || to_char(v_until, 'DD/MM/YYYY') || '.');
        exception when others then null;
        end;
    elsif v.kind = 'spot' then
        v_start := next_spot_start('article');
        update promotions
           set status = 'approved',
               starts_at = case when kind = 'shop' then now() else v_start end,
               ends_at = case when kind = 'shop' then now() else v_start end
                         + make_interval(days => days),
               decided_at = now(),
               note = 'Payé par Wave'
         where id = v.promotion_id and status in ('requested', 'paid_claimed');
        begin
            perform notify_org_admins(v.org_id, 'spot_approved',
                'Mise en avant payée par Wave : elle est programmée.');
        exception when others then null;
        end;
    end if;
    return null;
end;
$$;

create or replace function wave_payout_done(
    p_payment_id uuid,
    p_ok         boolean,
    p_payout_id  text default null,
    p_error      text default null
)
returns void
language sql
security definer
set search_path = public
as $$
    update wave_payments
       set payout_status = case when p_ok then 'sent' else 'failed' end,
           payout_id = coalesce(p_payout_id, payout_id),
           payout_error = case when p_ok then null else left(p_error, 300) end,
           paid_out_at = case when p_ok then now() end,
           payout_attempts = payout_attempts + 1
     where id = p_payment_id and payout_status in ('pending', 'failed');
$$;

-- Payouts still owed (the Worker's cron retries them), at most five tries.
create or replace function wave_payout_queue()
returns table (payment_id uuid, amount numeric, currency text, mobile text, name text)
language sql
stable
security definer
set search_path = public
as $$
    select p.id, p.payout_amount, p.currency, p.payout_to, o.name
    from wave_payments p join orgs o on o.id = p.org_id
    where p.payout_status in ('pending', 'failed')
      and p.payout_attempts < 5
      and p.payout_to is not null
    order by p.paid_at
    limit 20;
$$;

-- ------------------------------------------------------------
-- 5. The console's view
-- ------------------------------------------------------------
create or replace function platform_wave_payments(p_limit integer default 50)
returns table (
    id uuid, kind text, org_name text, amount numeric, commission numeric,
    method text, status text, payout_status text, payout_to text,
    payout_error text, created_at timestamptz, paid_at timestamptz
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select p.id, p.kind, o.name, p.amount, p.commission, p.method, p.status,
           p.payout_status, p.payout_to, p.payout_error, p.created_at, p.paid_at
    from wave_payments p join orgs o on o.id = p.org_id
    where exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
    order by (p.payout_status = 'failed') desc, p.created_at desc
    limit least(greatest(coalesce(p_limit, 50), 1), 200);
$$;

-- ------------------------------------------------------------
-- Grants
-- ------------------------------------------------------------
revoke execute on function set_wave_payout_number(uuid, text)          from public;
revoke execute on function set_wave_merchant_ref(uuid, text)           from public;
revoke execute on function wave_on()                                   from public;
revoke execute on function wave_begin(text, uuid, text, text)          from public;
revoke execute on function my_wave_payment(uuid)                       from public;
revoke execute on function wave_terms(uuid)                            from public;
revoke execute on function wave_attach(uuid, text, text)               from public;
revoke execute on function wave_settle(uuid, text, boolean, text)      from public;
revoke execute on function wave_payout_done(uuid, boolean, text, text) from public;
revoke execute on function wave_payout_queue()                         from public;
revoke execute on function platform_wave_payments(integer)             from public;

do $$
begin
    -- Supabase's default privileges grant every new function to
    -- authenticated directly (063 closed only anon and PUBLIC), so the
    -- Worker's four are taken back from it by name, as 060 does for push.
    -- Without this any signed-in person could settle their own order.
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function wave_attach(uuid, text, text)               from anon;
        revoke execute on function wave_settle(uuid, text, boolean, text)      from anon;
        revoke execute on function wave_payout_done(uuid, boolean, text, text) from anon;
        revoke execute on function wave_payout_queue()                         from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        revoke execute on function wave_attach(uuid, text, text)               from authenticated;
        revoke execute on function wave_settle(uuid, text, boolean, text)      from authenticated;
        revoke execute on function wave_payout_done(uuid, boolean, text, text) from authenticated;
        revoke execute on function wave_payout_queue()                         from authenticated;
        grant execute on function set_wave_payout_number(uuid, text) to authenticated;
        grant execute on function set_wave_merchant_ref(uuid, text)  to authenticated;
        grant execute on function wave_begin(text, uuid, text, text) to authenticated;
        grant execute on function my_wave_payment(uuid)              to authenticated;
        grant execute on function wave_terms(uuid)                   to authenticated;
        grant execute on function platform_wave_payments(integer)    to authenticated;
    end if;
    -- The kaj-pay Worker, and nothing else.
    if exists (select 1 from pg_roles where rolname = 'service_role') then
        grant execute on function wave_attach(uuid, text, text)               to service_role;
        grant execute on function wave_settle(uuid, text, boolean, text)      to service_role;
        grant execute on function wave_payout_done(uuid, boolean, text, text) to service_role;
        grant execute on function wave_payout_queue()                         to service_role;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 077_two_step.sql
-- ============================================================
-- ============================================================
-- 077_two_step.sql — a platform admin signs in with two steps.
--
-- The platform admin can suspend any business, read every business's
-- numbers, approve applications, set what Wave takes, and enter the
-- console's people pages. Until now all of that stood behind one password.
-- A password typed on a shared laptop, or guessed, was the whole platform.
--
-- Supabase Auth already knows a second step: an authenticator app (TOTP)
-- enrolled on the account. Passing it raises the token's `aal` claim from
-- aal1 to aal2. This migration makes the database insist on it:
--
--   1. two_step_gate() runs before every Data API request (PostgREST's
--      pre-request hook). A platform admin whose token is below aal2 is
--      refused — every table, every function, their own shops included —
--      except my_two_step(), which the app needs to know what to ask.
--      Fifty-three functions and three policies read is_platform_admin
--      inline; one gate in front of all of them cannot be forgotten by the
--      next one, which a check added to each would be.
--   2. my_two_step(): is this account held to it, has it a verified
--      factor, and has this token passed it.
--
-- Nobody else is touched: a shopkeeper, a courier or a shopper is waved
-- through on the first line. The worker's service-role calls carry no
-- user, and are waved through too.
--
-- Not covered by the hook (Supabase says so): Realtime and Storage. No
-- Realtime table and no Storage policy reads is_platform_admin, so there is
-- nothing behind them for an aal1 admin token to reach.
--
-- A lost phone: in the Supabase dashboard, Authentication › Users › the
-- account › delete its factor. The app then asks to enrol a new one.
-- ============================================================

create or replace function my_two_step()
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select jsonb_build_object(
        'required', coalesce((select is_platform_admin from profiles
                               where id = auth.uid()), false),
        'enrolled', exists (select 1 from auth.mfa_factors f
                             where f.user_id = auth.uid()
                               and f.status::text = 'verified'),
        'passed',   coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2'
    );
$$;

create or replace function two_step_gate()
returns void
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    -- The street, the worker, and anyone who has passed: through.
    if auth.uid() is null or coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2' then
        return;
    end if;
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        return;
    end if;
    -- The one door left open: what to ask. PostgREST names it with or
    -- without the leading slash depending on its version.
    if ltrim(coalesce(current_setting('request.path', true), ''), '/') = 'rpc/my_two_step' then
        return;
    end if;
    raise exception 'Validation en deux étapes requise'
        using errcode = '42501',
              hint = 'two_step_required';
end;
$$;

-- The account's history (075) learns the event.
create or replace function log_security_event(p_kind text, p_detail text default null)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null then
        raise exception 'log_security_event() needs a signed-in caller';
    end if;
    if p_kind not in ('password_changed', 'pin_changed', 'lock_changed',
                      'two_step_enabled') then
        raise exception 'Événement inconnu : %', p_kind;
    end if;
    perform security_log(auth.uid(), p_kind, left(p_detail, 120));
end;
$$;

revoke execute on function my_two_step()   from public;
revoke execute on function two_step_gate() from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function my_two_step()   to authenticated;
        grant execute on function two_step_gate() to authenticated;
    end if;
    -- PostgREST runs the hook as the request's role, the street's too. A
    -- hook anon cannot execute would refuse every vitrine.
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function two_step_gate() to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then
        grant execute on function two_step_gate() to service_role;
    end if;
    -- Only on Supabase, where PostgREST connects as authenticator.
    if exists (select 1 from pg_roles where rolname = 'authenticator') then
        alter role authenticator set pgrst.db_pre_request = 'public.two_step_gate';
    end if;
end $$;

notify pgrst, 'reload config';
notify pgrst, 'reload schema';


-- ============================================================
-- 078_two_step_optional.sql
-- ============================================================
-- ============================================================
-- 078_two_step_optional.sql — the second step becomes a choice.
--
-- 077 made the authenticator code compulsory for every platform admin.
-- The owner's call: not now. Sign-in is to stay the password once and the
-- device PIN after, for everybody, and Google sign-in is coming. The
-- second step stays built, but asleep until switched on in Compte ›
-- Sécurité (platform_settings.admin_two_step, off by default).
--
-- The hook stays registered: with the switch off it waves everybody
-- through, and switching it on needs no change to the authenticator role.
-- Switching it back off needs the code, which is right — otherwise the
-- switch would be the way round it — and is automatic: the gate refuses an
-- admin below aal2 every call, set_platform_setting included.
-- ============================================================

insert into platform_settings (key, value) values ('admin_two_step', 'false')
on conflict (key) do nothing;

-- Whether the platform has switched it on.
create or replace function two_step_on()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select coalesce((select (value #>> '{}')::boolean
                       from platform_settings where key = 'admin_two_step'), false);
$$;

create or replace function my_two_step()
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select jsonb_build_object(
        'required', two_step_on() and coalesce((select is_platform_admin from profiles
                                                 where id = auth.uid()), false),
        'enrolled', exists (select 1 from auth.mfa_factors f
                             where f.user_id = auth.uid()
                               and f.status::text = 'verified'),
        'passed',   coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2',
        'on',       two_step_on()
    );
$$;

create or replace function two_step_gate()
returns void
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null or coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2' then
        return;
    end if;
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        return;
    end if;
    if not two_step_on() then
        return;
    end if;
    if ltrim(coalesce(current_setting('request.path', true), ''), '/') = 'rpc/my_two_step' then
        return;
    end if;
    raise exception 'Validation en deux étapes requise'
        using errcode = '42501',
              hint = 'two_step_required';
end;
$$;

revoke execute on function two_step_on() from public;
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function two_step_on() from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function two_step_on() to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 079_product_photo_keys.sql
-- ============================================================
-- ============================================================
-- 079_product_photo_keys.sql — every article's picture, in one call.
--
-- The Articles page showed names and numbers only. The owner wants each
-- article's photograph on it, as a list or as cards. An article's picture
-- is its most recent photograph — the rule the vitrine and the search have
-- used since 059 — and asking product_photos() once per article would be a
-- request per row on a market connection. This answers for the whole shop.
--
-- SECURITY INVOKER: documents' own policies decide what the caller may
-- see, exactly as for product_photos(). PDFs (a delivery note filed against
-- the article) are left out: they are not a picture of it.
-- ============================================================

create or replace function product_photo_keys(p_org_id uuid)
returns table (product_id uuid, photo_key text)
language sql
stable
security invoker
set search_path = public
as $$
    select distinct on (d.product_id) d.product_id, d.r2_key
    from documents d
    where d.org_id = p_org_id
      and d.product_id is not null
      and coalesce(d.content_type, '') not ilike '%pdf%'
    order by d.product_id, coalesce(d.captured_at, d.created_at) desc;
$$;

revoke execute on function product_photo_keys(uuid) from public;
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function product_photo_keys(uuid) from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function product_photo_keys(uuid) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 080_org_logo.sql
-- ============================================================
-- ============================================================
-- 080_org_logo.sql — a shop's own logo.
--
-- The owner's words: enable logo adding to the stores. Every business,
-- Free or Pro — a logo is who the shop is, not a dressing — may hang one of
-- its own photographs as its logo. The vitrine shows it beside the name.
--
--   1. orgs.logo_key: the r2 key of one of the business's own documents.
--   2. set_org_logo(): an administrator sets it, or clears it with null.
--   3. storefront() carries it, inside the `style` it already returns —
--      added for every plan, so the signature (and every caller) stands.
--   4. storefront_photo_allowed(): the uploads Worker may now serve an
--      open vitrine's logo to the street, as it does its articles' photos.
-- ============================================================

alter table orgs add column if not exists logo_key text;

create or replace function set_org_logo(p_org_id uuid, p_key text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v_key text := nullif(btrim(coalesce(p_key, '')), '');
begin
    if auth.uid() is null then
        raise exception 'set_org_logo() needs a signed-in caller';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur choisit le logo de la boutique';
    end if;
    if v_key is not null and not exists (
        select 1 from documents d
         where d.org_id = p_org_id and d.r2_key = v_key
           and coalesce(d.content_type, '') not ilike '%pdf%') then
        raise exception 'Le logo doit être une photo de cette entreprise';
    end if;
    update orgs set logo_key = v_key where id = p_org_id;
end;
$$;

-- 068's window, with the logo in the style for every plan.
create or replace function storefront(p_slug text)
returns table (
    org_id        uuid,
    name          text,
    slug          text,
    profile       text,
    blurb         text,
    phone         text,
    address       text,
    theme         text,
    currency      text,
    lat           double precision,
    lng           double precision,
    wave_merchant text,
    style         jsonb
)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.name, o.slug, o.profile::text, o.storefront_blurb,
           o.phone, o.address, o.theme, o.default_currency, o.lat, o.lng,
           o.wave_merchant,
           (case when org_plan(o.id) = 'pro' then o.storefront_style
                 else '{}'::jsonb end)
           || case when o.logo_key is not null
                   then jsonb_build_object('logo_key', o.logo_key)
                   else '{}'::jsonb end
    from orgs o
    where o.id = storefront_open(p_slug);
$$;

-- The photos the Worker may serve to the street: the published articles'
-- (052), a Pro business's cover (068), and now any open vitrine's logo.
create or replace function storefront_photo_allowed(p_key text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists (
        select 1
        from documents d
        join products p on p.id = d.product_id
        join orgs     o on o.id = p.org_id
        where d.r2_key = p_key
          and p.is_active
          and p.is_published
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    ) or exists (
        select 1
        from orgs o
        where o.storefront_style ->> 'cover_key' = p_key
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
          and org_plan(o.id) = 'pro'
    ) or exists (
        select 1
        from orgs o
        where o.logo_key = p_key
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    );
$$;

revoke execute on function set_org_logo(uuid, text)       from public;
revoke execute on function storefront(text)               from public;
revoke execute on function storefront_photo_allowed(text) from public;

do $$
begin
    -- The street reads the window and its photos (063: a recreated street
    -- function says its grant again, by name).
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function storefront(text)               to anon;
        grant execute on function storefront_photo_allowed(text) to anon;
        revoke execute on function set_org_logo(uuid, text)      from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function storefront(text)               to authenticated;
        grant execute on function storefront_photo_allowed(text) to authenticated;
        grant execute on function set_org_logo(uuid, text)       to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 081_delivery_pro.sql
-- ============================================================
-- ============================================================
-- 081_delivery_pro.sql — delivery, and Kaj's online payment, are Kaj Pro;
-- a delivery may cost a minimum for the first kilometres.
--
-- The owner's split (Free runs a small shop, Pro grows it):
--
--   1. Delivery on the vitrine is Pro. delivery_fee() quotes nothing for a
--      shop that is not Pro, the window says so (style.delivers), and an
--      order for delivery is refused at the door of the orders table —
--      whichever path it comes by, an app built before this included.
--      Pickup stays free for everyone.
--   2. Paying online through Kaj's Wave checkout (076) is Pro: wave_terms()
--      says a Free shop is not ready, and a payment for its order is
--      refused at the door of wave_payments. A shop's own Wave link (057),
--      which costs Kaj nothing, stays free.
--   3. The fee may include kilometres: fee = base + per_km × max(0, km −
--      included_km), rounded to 25 F. Included 0 is the old « base + per
--      km » from the shop's door; included 3 makes the base the minimum for
--      any door within 3 km, each kilometre beyond adding per_km. A shop
--      sets its own (set_delivery_included_km), or keeps the platform's
--      (platform_settings.delivery_included_km, 0 to start).
--
-- The Pro list (066) gains 'delivery' and 'online_payment', so the badges
-- and the comparison page read the same line the database draws.
-- ============================================================

insert into platform_settings (key, value) values ('delivery_included_km', '0')
on conflict (key) do nothing;

update platform_settings
   set value = value || '["delivery"]'::jsonb
 where key = 'pro_features' and not (value ? 'delivery');
update platform_settings
   set value = value || '["online_payment"]'::jsonb
 where key = 'pro_features' and not (value ? 'online_payment');

alter table orgs add column if not exists delivery_included_km numeric(6, 2);
do $$ begin
    if not exists (select 1 from pg_constraint where conname = 'orgs_delivery_included_km_range') then
        alter table orgs add constraint orgs_delivery_included_km_range
            check (delivery_included_km is null
                   or (delivery_included_km >= 0 and delivery_included_km <= 50));
    end if;
end $$;

-- Whether this business may deliver: Pro, and pinned on the map.
create or replace function org_delivers(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists (
        select 1 from orgs o
         where o.id = p_org_id
           and o.lat is not null and o.lng is not null
           and org_plan(o.id) = 'pro');
$$;

create or replace function set_delivery_included_km(p_org_id uuid, p_km numeric)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null then
        raise exception 'set_delivery_included_km() needs a signed-in caller';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Only an administrator sets the delivery rates';
    end if;
    if p_km is not null and (p_km < 0 or p_km > 50) then
        raise exception 'Les kilomètres inclus vont de 0 à 50';
    end if;
    update orgs set delivery_included_km = p_km where id = p_org_id;
end;
$$;

-- 069's fee, with the included kilometres and the Pro gate.
create or replace function delivery_fee(
    p_org_id uuid,
    p_lat    double precision,
    p_lng    double precision
)
returns numeric
language plpgsql
stable
security definer
set search_path = public
as $$
declare
    v_org      orgs%rowtype;
    v_base     numeric;
    v_per_km   numeric;
    v_included numeric;
    v_currency text;
    v_fee      numeric;
    v_km       double precision;
begin
    if p_lat is null or p_lng is null then
        return null;
    end if;
    select * into v_org from orgs where id = p_org_id;
    if not found or v_org.lat is null or v_org.lng is null then
        return null;
    end if;
    if org_plan(p_org_id) <> 'pro' then
        return null; -- delivery is Kaj Pro (081)
    end if;
    v_km := distance_km(v_org.lat, v_org.lng, p_lat, p_lng);
    if v_km > delivery_reach_km(p_org_id) then
        return null; -- out of reach: there is no price for an impossible run
    end if;
    if v_org.delivery_base is not null then
        v_base   := v_org.delivery_base;
        v_per_km := v_org.delivery_per_km;
    else
        select (value #>> '{}')::text into v_currency
          from platform_settings where key = 'delivery_currency';
        if coalesce(v_org.default_currency, 'XOF') <> coalesce(v_currency, 'XOF') then
            return null; -- the platform's numbers are in another money
        end if;
        select (value #>> '{}')::numeric into v_base
          from platform_settings where key = 'delivery_base';
        select (value #>> '{}')::numeric into v_per_km
          from platform_settings where key = 'delivery_per_km';
        if v_base is null or v_per_km is null then
            return null;
        end if;
    end if;
    v_included := coalesce(
        v_org.delivery_included_km,
        (select (value #>> '{}')::numeric from platform_settings
          where key = 'delivery_included_km'),
        0);
    v_fee := v_base + v_per_km * greatest(0, v_km - v_included);
    return round(v_fee / 25) * 25;
end;
$$;

-- The door of the orders table: a delivery for a shop that is not Pro is
-- refused, whatever path the order came by.
create or replace function trg_order_delivery_pro()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if new.fulfilment = 'delivery' and org_plan(new.org_id) <> 'pro' then
        raise exception 'Kaj Pro : la livraison est réservée aux boutiques Kaj Pro. Choisissez le retrait en boutique.';
    end if;
    return new;
end;
$$;

create or replace trigger order_delivery_pro
    before insert on orders
    for each row execute function trg_order_delivery_pro();

-- The door of wave_payments: Kaj's checkout for an order is Pro.
create or replace function trg_wave_order_pro()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if new.kind = 'order' and org_plan(new.org_id) <> 'pro' then
        raise exception 'Kaj Pro : le paiement en ligne est réservé aux boutiques Kaj Pro';
    end if;
    return new;
end;
$$;

create or replace trigger wave_order_pro
    before insert on wave_payments
    for each row execute function trg_wave_order_pro();

-- 076's terms: a Free shop is not ready for Kaj's checkout.
create or replace function wave_terms(p_org_id uuid default null)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'on', wave_on(),
        'shop_ready', p_org_id is not null and exists (
            select 1 from orgs where id = p_org_id and wave_payout_number is not null
               and org_plan(id) = 'pro'),
        'card', coalesce((select (value #>> '{}')::boolean
                            from platform_settings where key = 'wave_card'), false),
        'commission_pct', coalesce((select (value #>> '{}')::numeric
                                      from platform_settings where key = 'wave_commission_pct'), 0)
    );
$$;

-- 080's window, saying whether the shop delivers.
create or replace function storefront(p_slug text)
returns table (
    org_id        uuid,
    name          text,
    slug          text,
    profile       text,
    blurb         text,
    phone         text,
    address       text,
    theme         text,
    currency      text,
    lat           double precision,
    lng           double precision,
    wave_merchant text,
    style         jsonb
)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.name, o.slug, o.profile::text, o.storefront_blurb,
           o.phone, o.address, o.theme, o.default_currency, o.lat, o.lng,
           o.wave_merchant,
           (case when org_plan(o.id) = 'pro' then o.storefront_style
                 else '{}'::jsonb end)
           || case when o.logo_key is not null
                   then jsonb_build_object('logo_key', o.logo_key)
                   else '{}'::jsonb end
           || jsonb_build_object('delivers', org_delivers(o.id))
    from orgs o
    where o.id = storefront_open(p_slug);
$$;

revoke execute on function org_delivers(uuid)                       from public;
revoke execute on function set_delivery_included_km(uuid, numeric)  from public;
revoke execute on function trg_order_delivery_pro()                 from public;
revoke execute on function trg_wave_order_pro()                     from public;
revoke execute on function storefront(text)                         from public;
revoke execute on function wave_terms(uuid)                         from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function storefront(text) to anon;
        revoke execute on function org_delivers(uuid) from anon;
        revoke execute on function set_delivery_included_km(uuid, numeric) from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function storefront(text)                        to authenticated;
        grant execute on function wave_terms(uuid)                        to authenticated;
        grant execute on function set_delivery_included_km(uuid, numeric) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 082_stripe_pro.sql
-- ============================================================
-- ============================================================
-- 082_stripe_pro.sql — Kaj Pro by card, as a subscription, through Stripe.
--
-- The owner: Stripe is for the subscription only (Wave stays the way to
-- pay an order); the platform chooses the prices, because the market moves.
--
--   1. One price, wherever it is paid: the month and year prices are 066's
--      pro_price_month / pro_price_year, which the platform already sets
--      from the Kaj Pro console, in pro_currency. Stripe charges what the
--      comparison page shows; a new price applies to the next subscription
--      (a running one renews at the price it was taken at, Stripe's rule).
--      stripe_on is the switch (off until the keys are in); plan_terms()
--      now says it, so the app shows the card button only when it works.
--   2. stripe_begin(): the Worker calls it with the owner's own token, so
--      under their identity. Only an administrator of the business; the
--      amount is the platform's, never the app's.
--   3. stripe_subscriptions: one row per business — Stripe's customer and
--      subscription, its status and the end of the paid period.
--   4. stripe_settle() (service role, the Worker alone): whatever Stripe
--      says about a subscription — first payment, renewal, cancellation —
--      is written down, and while it is active the business is Pro until
--      the end of the paid period (and one day of grace). A cancelled or
--      unpaid subscription is not cut short: Pro runs to what was paid.
--      Idempotent — Stripe delivers an event more than once.
--   5. my_stripe_subscription(): the owner reads where theirs stands.
-- ============================================================

insert into platform_settings (key, value) values ('stripe_on', 'false')
on conflict (key) do nothing;

create table if not exists stripe_subscriptions (
    org_id               uuid primary key references orgs(id) on delete cascade,
    customer_id          text,
    subscription_id      text unique,
    status               text,
    period               text check (period is null or period in ('month', 'year')),
    current_period_end   timestamptz,
    cancel_at_period_end boolean not null default false,
    updated_at           timestamptz not null default now()
);
alter table stripe_subscriptions enable row level security;
-- No policies: read through my_stripe_subscription(), written by the Worker.

create or replace function stripe_on()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select coalesce((select (value #>> '{}')::boolean
                       from platform_settings where key = 'stripe_on'), false);
$$;

-- 067's terms, saying whether the card is open.
create or replace function plan_terms()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'pro_features',            coalesce(plan_setting('pro_features'), '[]'::jsonb),
        'free_max_staff',          plan_limit('free_max_staff', 3),
        'free_max_invoices_month', plan_limit('free_max_invoices_month', 20),
        'free_max_photos',         plan_limit('free_max_photos', 50),
        'free_history_months',     plan_limit('free_history_months', 12),
        'pro_price_month',         plan_limit('pro_price_month', 2500),
        'pro_price_year',          plan_limit('pro_price_year', 25000),
        'pro_currency',            coalesce(plan_setting('pro_currency') #>> '{}', 'XOF'),
        'platform_wave',           coalesce(plan_setting('platform_wave') #>> '{}', ''),
        'platform_wave_name',      coalesce(plan_setting('platform_wave_name') #>> '{}', ''),
        'delivery_share_pct',      plan_limit('delivery_share_pct', 10),
        'stripe_on',               stripe_on()
    );
$$;

create or replace function stripe_begin(p_org_id uuid, p_period text)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_terms jsonb := plan_terms();
    v_org   orgs%rowtype;
    v_amount numeric;
begin
    if auth.uid() is null then
        raise exception 'stripe_begin() needs a signed-in caller';
    end if;
    if not stripe_on() then
        raise exception 'Le paiement par carte n''est pas encore ouvert';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur abonne l''entreprise à Kaj Pro';
    end if;
    if p_period not in ('month', 'year') then
        raise exception 'Période inconnue : %', p_period;
    end if;
    select * into v_org from orgs where id = p_org_id;
    v_amount := (v_terms ->> case when p_period = 'year' then 'pro_price_year'
                                  else 'pro_price_month' end)::numeric;
    if coalesce(v_amount, 0) <= 0 then
        raise exception 'Le prix de Kaj Pro n''est pas fixé';
    end if;
    return jsonb_build_object(
        'org_id',      v_org.id,
        'org_name',    v_org.name,
        'period',      p_period,
        'amount',      v_amount,
        'currency',    lower(v_terms ->> 'pro_currency'),
        'customer_id', (select customer_id from stripe_subscriptions where org_id = p_org_id),
        'email',       (select email from auth.users where id = auth.uid())
    );
end;
$$;

create or replace function stripe_settle(
    p_org_id          uuid,
    p_subscription_id text,
    p_customer_id     text,
    p_status          text,
    p_period          text,
    p_period_end      timestamptz,
    p_cancel_at_end   boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_was  text;
    v_org  orgs%rowtype;
    v_until date;
    v_active boolean := p_status in ('active', 'trialing');
begin
    select * into v_org from orgs where id = p_org_id;
    if not found then
        return jsonb_build_object('ok', false, 'reason', 'no such business');
    end if;
    select status into v_was from stripe_subscriptions where org_id = p_org_id;

    insert into stripe_subscriptions (org_id, customer_id, subscription_id, status,
                                      period, current_period_end, cancel_at_period_end,
                                      updated_at)
    values (p_org_id, p_customer_id, p_subscription_id, p_status,
            case when p_period in ('month', 'year') then p_period end,
            p_period_end, coalesce(p_cancel_at_end, false), now())
    on conflict (org_id) do update set
        customer_id          = coalesce(excluded.customer_id, stripe_subscriptions.customer_id),
        subscription_id      = coalesce(excluded.subscription_id, stripe_subscriptions.subscription_id),
        status               = excluded.status,
        period               = coalesce(excluded.period, stripe_subscriptions.period),
        current_period_end   = coalesce(excluded.current_period_end,
                                        stripe_subscriptions.current_period_end),
        cancel_at_period_end = excluded.cancel_at_period_end,
        updated_at           = now();

    if v_active and p_period_end is not null then
        v_until := (p_period_end at time zone 'Africa/Ouagadougou')::date + 1;
        -- Never shorter than what the business already has: a later date
        -- paid by Wave stays, and a Pro with no end (a gift) keeps none.
        update orgs
           set plan_until = case
                   when plan = 'pro' and plan_until is null then null
                   when plan = 'pro' then greatest(plan_until, v_until)
                   else v_until end,
               plan = 'pro',
               plan_note = 'Stripe ' || coalesce(p_subscription_id, '')
         where id = p_org_id;
        if v_was is distinct from p_status and v_was is distinct from 'active' then
            begin
                perform notify_org_admins(p_org_id, 'pro_active',
                    'Kaj Pro est actif, payé par carte, jusqu''au '
                    || to_char(v_until, 'DD/MM/YYYY') || '.');
            exception when others then null;
            end;
        end if;
    end if;
    return jsonb_build_object('ok', true, 'active', v_active, 'until', v_until);
end;
$$;

create or replace function my_stripe_subscription(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select jsonb_build_object(
        'status', s.status,
        'period', s.period,
        'current_period_end', s.current_period_end,
        'cancel_at_period_end', s.cancel_at_period_end,
        'has_customer', s.customer_id is not null)
    from stripe_subscriptions s
    where s.org_id = p_org_id and is_org_admin(p_org_id);
$$;

-- The customer id, for the Worker opening Stripe's own page where the owner
-- changes the card or cancels — under the owner's identity, admins only.
create or replace function stripe_customer_of(p_org_id uuid)
returns text
language sql
stable
security definer
set search_path = public, auth
as $$
    select s.customer_id from stripe_subscriptions s
     where s.org_id = p_org_id and is_org_admin(p_org_id);
$$;

revoke execute on function stripe_on()                                       from public;
revoke execute on function plan_terms()                                      from public;
revoke execute on function stripe_begin(uuid, text)                          from public;
revoke execute on function stripe_settle(uuid, text, text, text, text, timestamptz, boolean) from public;
revoke execute on function my_stripe_subscription(uuid)                      from public;
revoke execute on function stripe_customer_of(uuid)                          from public;

do $$
begin
    -- Supabase's default privileges give a new function to authenticated
    -- directly (063 closed only anon and PUBLIC): the Worker's own is taken
    -- back by name, as 076 learned.
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function stripe_settle(uuid, text, text, text, text, timestamptz, boolean) from anon;
        revoke execute on function stripe_begin(uuid, text)     from anon;
        revoke execute on function my_stripe_subscription(uuid) from anon;
        revoke execute on function stripe_customer_of(uuid)     from anon;
        revoke execute on function stripe_on()                  from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        revoke execute on function stripe_settle(uuid, text, text, text, text, timestamptz, boolean) from authenticated;
        grant execute on function plan_terms()                  to authenticated;
        grant execute on function stripe_begin(uuid, text)      to authenticated;
        grant execute on function my_stripe_subscription(uuid)  to authenticated;
        grant execute on function stripe_customer_of(uuid)      to authenticated;
    end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then
        grant execute on function stripe_settle(uuid, text, text, text, text, timestamptz, boolean) to service_role;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 083_farm_vitrine.sql
-- ============================================================
-- ============================================================
-- 083_farm_vitrine.sql — a farm has a vitrine too.
--
-- The owner: "farms do not have a vitrine, fix it." The window was never
-- closed to them in the database — storefront_open() asks only that it is
-- switched on — but a farm had nothing to put in it: the vitrine shows the
-- business's articles (products), and a farm keeps flocks, herds and
-- harvests. A farm now lists what it sells as articles like a shop does
-- (« À vendre »), so the order, the basket, delivery and payment are the
-- street's own, unchanged. Two things a farm needs that a shop rarely
-- does:
--
--   1. A unit. Eggs go by the tray, maize by the sack or the kg, a guinea
--      fowl by the head: products.unit, free words (20 characters), shown
--      after the price (« 2 500 F / plateau »). Null is « l'unité ».
--   2. A date. A batch of broilers ready on the 15th, a harvest next
--      month: products.available_from. Until that day the article is on
--      the vitrine as a pre-order (« Disponible à partir du 15/11 »), and
--      it can be ordered even with nothing in stock yet — that is what a
--      pre-order is. After it, the stock decides as for any article.
--
-- storefront_products() grows two columns, so it is dropped and recreated;
-- since 063 a new function is born closed, so the street's grant is said
-- again explicitly.
-- ============================================================

alter table products add column if not exists unit text;
alter table products drop constraint if exists products_unit_length;
alter table products add constraint products_unit_length
    check (unit is null or char_length(btrim(unit)) between 1 and 20);

alter table products add column if not exists available_from date;

drop function if exists storefront_products(text);
create function storefront_products(p_slug text)
returns table (
    id             uuid,
    name           text,
    sale_price     numeric,
    in_stock       boolean,
    photo_key      text,
    description    text,
    unit           text,
    available_from date
)
language sql
stable
security definer
set search_path = public
as $$
    select p.id, p.name, p.sale_price,
           -- A pre-order is orderable before there is anything to count.
           (p.quantity > 0
            or p.available_from > (now() at time zone 'Africa/Ouagadougou')::date),
           (select d.r2_key from documents d
             where d.product_id = p.id
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1),
           nullif(btrim(p.description), ''),
           nullif(btrim(p.unit), ''),
           case when p.available_from > (now() at time zone 'Africa/Ouagadougou')::date
                then p.available_from end
    from products p
    where p.org_id = storefront_open(p_slug)
      and p.is_active
      and p.is_published
    order by p.name;
$$;

revoke execute on function storefront_products(text) from public;
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function storefront_products(text) to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function storefront_products(text) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 084_cauris.sql
-- ============================================================
-- ============================================================
-- 084_cauris.sql — cauris: Mara's points, earned by doing well.
--
-- The owner's model: a business that does well earns « cauris » and spends
-- them on what Mara Pro gives (085); a weekly score ranks it in its league
-- (086). This file is the earning side only, as decided: run it with real
-- shops, tune the numbers from the console, then let cauris buy things.
--
--   1. cauris_rules: what each act earns, and its daily cap — the
--      platform's numbers, changed from the console (set_cauris_rule),
--      never a deploy. A few parameters sit in platform_settings: the
--      smallest order that counts, how many orders per customer per day,
--      the minutes for a quick acceptance, the days before an idle wallet
--      expires.
--   2. cauris_ledger: every gain and loss, written once, never edited.
--      (org, reason, ref) is unique, so an event delivered twice — a
--      status set again, a page reloaded — earns once. The balance is
--      the sum; there is no other place it is kept.
--   3. Earned by what is hard to fake, from the events themselves:
--      an order picked up or delivered (not from the business's own people,
--      not under the smallest amount, at most N per customer a day); a
--      customer who comes back within 30 days; a pending order accepted
--      within 15 minutes; a distinct visitor on the vitrine (capped, signed
--      members of the business never count); the till used 7 days running;
--      a farm's daily log; the vitrine complete; a business it brought in
--      that took off. Lost: an accepted order the business cancels.
--   4. Expiry: a wallet with no movement for 180 days (the parameter) is
--      emptied by an « expired » line, written when it is next read or
--      next earns — no scheduler needed.
--   5. Reading: my_cauris() for the business's admins (balance, this
--      week's score, the history, when it would expire); cauris_watch()
--      for the platform — the top earners of the week and how much of
--      their orders came from one customer, the shape of an abuse.
--
-- Every function here is born closed (063) and Supabase's default
-- privileges hand new functions to authenticated: the internal ones are
-- revoked from it by name, the readers granted by name.
-- ============================================================

-- ------------------------------------------------------------
-- 1. The rules and their parameters
-- ------------------------------------------------------------
create table if not exists cauris_rules (
    key       text primary key,
    points    integer not null,
    daily_cap integer check (daily_cap is null or daily_cap > 0),
    label     text not null,
    sort      integer not null default 0
);
alter table cauris_rules enable row level security;

insert into cauris_rules (key, points, daily_cap, label, sort) values
    ('order_done',         10, null, 'Commande terminée',                      10),
    ('returning_customer', 15, null, 'Un client revenu',                       20),
    ('quick_accept',        3, null, 'Commande acceptée en moins de 15 min',   30),
    ('visitor',             1,   30, 'Un visiteur sur la vitrine',             40),
    ('till_streak',        20, null, 'Caisse tenue 7 jours de suite',          50),
    ('farm_log',            5,    1, 'Cahier de la ferme tenu',                60),
    ('vitrine_complete',   50, null, 'Vitrine complète',                       70),
    ('referral',          200, null, 'Une entreprise parrainée a décollé',     80),
    ('lesson',             10, null, 'Leçon de l''Académie Mara',              90),
    ('shop_cancel',       -10, null, 'Commande acceptée puis annulée',        100)
on conflict (key) do nothing;

insert into platform_settings (key, value) values
    ('cauris_order_min',          '500'),
    ('cauris_orders_per_customer', '2'),
    ('cauris_quick_minutes',      '15'),
    ('cauris_expire_days',       '180')
on conflict (key) do nothing;

-- Who brought a business in (a referral), set once by its admin.
alter table orgs add column if not exists referred_by uuid references orgs(id) on delete set null;

-- ------------------------------------------------------------
-- 2. The ledger
-- ------------------------------------------------------------
create table if not exists cauris_ledger (
    id         bigserial primary key,
    org_id     uuid not null references orgs(id) on delete cascade,
    delta      integer not null check (delta <> 0),
    reason     text not null,
    ref        text not null,
    note       text,
    created_at timestamptz not null default now(),
    unique (org_id, reason, ref)
);
create index if not exists cauris_ledger_by_org on cauris_ledger (org_id, created_at desc);
alter table cauris_ledger enable row level security;
-- No policies: read through my_cauris(), written by the functions below.

-- Distinct visitors of a vitrine, a day (the device's own random id).
create table if not exists storefront_visitors (
    day     date not null,
    org_id  uuid not null references orgs(id) on delete cascade,
    visitor text not null,
    primary key (day, org_id, visitor)
);
alter table storefront_visitors enable row level security;

create or replace function cauris_param(p_key text, p_default int)
returns int
language sql
stable
security definer
set search_path = public
as $$
    select coalesce((select (value #>> '{}')::int
                       from platform_settings where key = p_key), p_default);
$$;

create or replace function cauris_today()
returns date
language sql
stable
as $$ select (now() at time zone 'Africa/Ouagadougou')::date $$;

create or replace function cauris_balance(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select coalesce(sum(delta), 0)::int from cauris_ledger where org_id = p_org_id;
$$;

-- An idle wallet empties itself: one « expired » line, the day it is seen.
create or replace function cauris_expire(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_last    timestamptz;
    v_balance int;
begin
    select max(created_at) into v_last from cauris_ledger where org_id = p_org_id;
    if v_last is null
       or v_last > now() - make_interval(days => cauris_param('cauris_expire_days', 180)) then
        return;
    end if;
    v_balance := cauris_balance(p_org_id);
    if v_balance > 0 then
        insert into cauris_ledger (org_id, delta, reason, ref, note)
        values (p_org_id, -v_balance, 'expired', cauris_today()::text,
                'Cauris non utilisés depuis ' || cauris_param('cauris_expire_days', 180) || ' jours')
        on conflict do nothing;
    end if;
end;
$$;

-- The one way cauris are earned or lost: by rule, capped, once per ref.
-- Returns what was written (0 when nothing was).
create or replace function cauris_award(
    p_org_id uuid,
    p_reason text,
    p_ref    text,
    p_note   text default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
    v_rule  cauris_rules%rowtype;
    v_today int;
    v_n     int;
begin
    select * into v_rule from cauris_rules where key = p_reason;
    if not found or v_rule.points = 0 or p_org_id is null then
        return 0;
    end if;
    -- An association does not compete (the owner's call): no cauris.
    if exists (select 1 from orgs where id = p_org_id
                and profile in ('church', 'association')) then
        return 0;
    end if;
    perform cauris_expire(p_org_id);
    if v_rule.daily_cap is not null then
        select count(*) into v_today from cauris_ledger
         where org_id = p_org_id and reason = p_reason
           and (created_at at time zone 'Africa/Ouagadougou')::date = cauris_today();
        if v_today >= v_rule.daily_cap then
            return 0;
        end if;
    end if;
    insert into cauris_ledger (org_id, delta, reason, ref, note)
    values (p_org_id, v_rule.points, p_reason, p_ref, p_note)
    on conflict (org_id, reason, ref) do nothing;
    get diagnostics v_n = row_count;
    return case when v_n > 0 then v_rule.points else 0 end;
end;
$$;

-- ------------------------------------------------------------
-- 3. Earned from the events themselves
-- ------------------------------------------------------------
create or replace function trg_cauris_order()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_inside boolean;
    v_today  int;
begin
    if new.status is not distinct from old.status then
        return new;
    end if;
    -- The business's own people ordering from it earn nothing.
    v_inside := exists (select 1 from memberships m
                         where m.org_id = new.org_id and m.user_id = new.customer_id);

    if new.status in ('picked_up', 'delivered') and not v_inside
       and coalesce(new.total, 0) >= cauris_param('cauris_order_min', 500) then
        select count(*) into v_today from cauris_ledger
         where org_id = new.org_id and reason = 'order_done'
           and note = new.customer_id::text
           and (created_at at time zone 'Africa/Ouagadougou')::date = cauris_today();
        if v_today < cauris_param('cauris_orders_per_customer', 2) then
            perform cauris_award(new.org_id, 'order_done', new.id::text, new.customer_id::text);
            -- Came back: another finished order from the same person in the
            -- 30 days before this one.
            if exists (select 1 from orders o
                        where o.org_id = new.org_id and o.customer_id = new.customer_id
                          and o.id <> new.id
                          and o.status in ('picked_up', 'delivered')
                          and o.created_at >= new.created_at - interval '30 days'
                          and o.created_at <  new.created_at) then
                perform cauris_award(new.org_id, 'returning_customer', new.id::text,
                                     new.customer_id::text);
            end if;
        end if;
    elsif old.status = 'pending' and new.status = 'accepted' and not v_inside
          and now() - new.created_at
              <= make_interval(mins => cauris_param('cauris_quick_minutes', 15)) then
        perform cauris_award(new.org_id, 'quick_accept', new.id::text);
    elsif new.status = 'cancelled' and old.status in ('accepted', 'ready')
          and auth.uid() is distinct from new.customer_id then
        -- Accepted, then dropped by the business (the customer's own
        -- cancellation costs it nothing).
        perform cauris_award(new.org_id, 'shop_cancel', new.id::text);
    end if;
    return new;
end;
$$;

-- Created once, never dropped: the live database applies only what
-- destroys nothing without the owner's say.
do $$ begin
    if not exists (select 1 from pg_trigger where tgname = 'cauris_order') then
        create trigger cauris_order
            after update of status on orders
            for each row execute function trg_cauris_order();
    end if;
end $$;

-- The till used every one of the last 7 days: once per 7 days.
create or replace function trg_cauris_sale()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_today date := cauris_today();
    v_days  int;
begin
    if exists (select 1 from cauris_ledger
                where org_id = new.org_id and reason = 'till_streak'
                  and (created_at at time zone 'Africa/Ouagadougou')::date > v_today - 7) then
        return new;
    end if;
    select count(distinct (s.occurred_at at time zone 'Africa/Ouagadougou')::date) into v_days
      from sales s
     where s.org_id = new.org_id
       and (s.occurred_at at time zone 'Africa/Ouagadougou')::date between v_today - 6 and v_today;
    if v_days >= 7 then
        perform cauris_award(new.org_id, 'till_streak', v_today::text);
    end if;
    return new;
end;
$$;

-- Created once, never dropped: the live database applies only what
-- destroys nothing without the owner's say.
do $$ begin
    if not exists (select 1 from pg_trigger where tgname = 'cauris_sale') then
        create trigger cauris_sale
            after insert on sales
            for each row execute function trg_cauris_sale();
    end if;
end $$;

-- A farm that keeps its log: once a day.
create or replace function trg_cauris_flock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    perform cauris_award((select f.org_id from flocks f where f.id = new.flock_id),
                         'farm_log', cauris_today()::text);
    return new;
end;
$$;

-- Created once, never dropped: the live database applies only what
-- destroys nothing without the owner's say.
do $$ begin
    if not exists (select 1 from pg_trigger where tgname = 'cauris_flock') then
        create trigger cauris_flock
            after insert on flock_events
            for each row execute function trg_cauris_flock();
    end if;
end $$;

-- A distinct visitor opening the vitrine. The device sends its own random
-- id; the business's signed-in members never count.
create or replace function record_visitor(p_slug text, p_visitor text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org uuid := storefront_open(p_slug);
    v_id  text := btrim(coalesce(p_visitor, ''));
    v_n   int;
begin
    if v_org is null or char_length(v_id) not between 8 and 64 then
        return;
    end if;
    if auth.uid() is not null and exists (
        select 1 from memberships where org_id = v_org and user_id = auth.uid()) then
        return;
    end if;
    insert into storefront_visitors (day, org_id, visitor)
    values (cauris_today(), v_org, v_id)
    on conflict do nothing;
    get diagnostics v_n = row_count;
    if v_n > 0 then
        perform cauris_award(v_org, 'visitor', cauris_today()::text || ':' || v_id);
    end if;
end;
$$;

-- The vitrine's own score, as the app counts it (070's six steps).
create or replace function vitrine_score(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select (100 * (
        (published > 0)::int
      + (with_photo >= 3 or (published > 0 and with_photo >= published))::int
      + blurb::int + phone::int + address::int + pin::int) / 6.0)::int
    from (
        select
            (select count(*) from products p
              where p.org_id = o.id and p.is_active and p.is_published) as published,
            (select count(*) from products p
              where p.org_id = o.id and p.is_active and p.is_published
                and exists (select 1 from documents d where d.product_id = p.id)) as with_photo,
            nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null as blurb,
            nullif(btrim(coalesce(o.phone, '')), '') is not null as phone,
            nullif(btrim(coalesce(o.address, '')), '') is not null as address,
            (o.lat is not null and o.lng is not null) as pin
        from orgs o where o.id = p_org_id
    ) x;
$$;

-- Milestones read on the business's own screens: the vitrine complete,
-- and — for whoever brought this business in — that it took off.
create or replace function cauris_milestones(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org orgs%rowtype;
begin
    if not is_org_member(p_org_id) then
        return;
    end if;
    select * into v_org from orgs where id = p_org_id;
    if v_org.storefront_enabled and vitrine_score(p_org_id) >= 100 then
        perform cauris_award(p_org_id, 'vitrine_complete', 'once');
    end if;
    if v_org.referred_by is not null
       and vitrine_score(p_org_id) >= 90
       and (select count(*) from orders o
             where o.org_id = p_org_id and o.status in ('picked_up', 'delivered')) >= 3 then
        perform cauris_award(v_org.referred_by, 'referral', p_org_id::text, v_org.name);
    end if;
end;
$$;

-- Who brought this business in: its admin says it once, in the first 30
-- days, by the other business's address (its slug). Never itself.
create or replace function set_referral(p_org_id uuid, p_code text)
returns text
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org orgs%rowtype;
    v_ref orgs%rowtype;
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur dit qui l''a parrainé';
    end if;
    select * into v_org from orgs where id = p_org_id;
    if v_org.referred_by is not null then
        raise exception 'Le parrain est déjà enregistré';
    end if;
    if v_org.created_at < now() - interval '30 days' then
        raise exception 'Le parrainage se dit dans les 30 premiers jours';
    end if;
    select * into v_ref from orgs
     where slug = lower(btrim(coalesce(p_code, ''))) and archived_at is null;
    if not found or v_ref.id = p_org_id then
        raise exception 'Code de parrainage inconnu';
    end if;
    -- The same people on both sides is not a referral.
    if exists (select 1 from memberships a join memberships b on a.user_id = b.user_id
                where a.org_id = p_org_id and b.org_id = v_ref.id) then
        raise exception 'Une entreprise ne se parraine pas elle-même';
    end if;
    update orgs set referred_by = v_ref.id where id = p_org_id;
    return v_ref.name;
end;
$$;

-- ------------------------------------------------------------
-- 4. Reading
-- ------------------------------------------------------------
-- The business's wallet, for its admins. Volatile: reading it may write the
-- expiry line.
create or replace function my_cauris(p_org_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_last timestamptz;
begin
    if not is_org_admin(p_org_id) then
        return null;
    end if;
    perform cauris_expire(p_org_id);
    select max(created_at) into v_last from cauris_ledger
     where org_id = p_org_id and reason <> 'expired';
    return jsonb_build_object(
        'balance', cauris_balance(p_org_id),
        'week', (select coalesce(sum(delta), 0) from cauris_ledger
                  where org_id = p_org_id and delta > 0 and reason <> 'expired'
                    and created_at >= date_trunc('week', now() at time zone 'Africa/Ouagadougou')
                                      at time zone 'Africa/Ouagadougou'),
        'expires_on', case when v_last is null then null
                           else ((v_last at time zone 'Africa/Ouagadougou')::date
                                 + cauris_param('cauris_expire_days', 180)) end,
        'referral_code', (select slug from orgs where id = p_org_id),
        'referred', (select referred_by is not null from orgs where id = p_org_id),
        'history', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'delta', l.delta,
                       'reason', l.reason,
                       'label', coalesce(r.label, case l.reason
                                    when 'expired' then 'Cauris expirés'
                                    when 'spent' then 'Dépensés'
                                    else l.reason end),
                       'note', case when l.reason in ('expired', 'spent', 'prize') then l.note end,
                       'at', l.created_at) order by l.created_at desc)
              from (select * from cauris_ledger where org_id = p_org_id
                     order by created_at desc limit 60) l
              left join cauris_rules r on r.key = l.reason), '[]'::jsonb),
        'rules', coalesce((
            select jsonb_agg(jsonb_build_object('key', key, 'points', points,
                       'daily_cap', daily_cap, 'label', label) order by sort)
              from cauris_rules where points > 0), '[]'::jsonb)
    );
end;
$$;

-- The rules, for the console.
create or replace function cauris_rules_list()
returns setof cauris_rules
language sql
stable
security definer
set search_path = public, auth
as $$
    select * from cauris_rules
     where exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
     order by sort;
$$;

create or replace function set_cauris_rule(p_key text, p_points int, p_daily_cap int default null)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Only the platform sets the cauris rules';
    end if;
    if p_points is null or abs(p_points) > 10000 then
        raise exception 'Points hors limites';
    end if;
    update cauris_rules
       set points = p_points,
           daily_cap = case when coalesce(p_daily_cap, 0) > 0 then p_daily_cap end
     where key = p_key;
    if not found then
        raise exception 'Règle inconnue : %', p_key;
    end if;
end;
$$;

-- The week's top earners, and the share of their orders from one customer.
create or replace function cauris_watch()
returns table (
    org_id        uuid,
    org_name      text,
    week          integer,
    balance       integer,
    orders        integer,
    top_customer_share numeric
)
language sql
stable
security definer
set search_path = public, auth
as $$
    with w as (
        select l.org_id, sum(l.delta)::int as week
          from cauris_ledger l
         where l.delta > 0 and l.created_at >= now() - interval '7 days'
         group by l.org_id
    ), c as (
        select l.org_id, l.note as customer, count(*) as n
          from cauris_ledger l
         where l.reason = 'order_done' and l.created_at >= now() - interval '7 days'
         group by l.org_id, l.note
    )
    select w.org_id, o.name, w.week, cauris_balance(w.org_id),
           coalesce((select sum(n) from c where c.org_id = w.org_id), 0)::int,
           coalesce(round((select max(n) from c where c.org_id = w.org_id)::numeric
                 / nullif((select sum(n) from c where c.org_id = w.org_id), 0), 2), 0)
      from w join orgs o on o.id = w.org_id
     where exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
     order by w.week desc
     limit 50;
$$;

