    ('Kaya',            13.0917, -1.0844),
    ('Tenkodogo',       11.7800, -0.3697),
    ('Fada N''Gourma',  12.0616,  0.3584),
    ('Dédougou',        12.4634, -3.4608),
    ('Dori',            14.0354, -0.0345),
    ('Gaoua',           10.3250, -3.1744),
    ('Ziniaré',         12.5822, -1.2983),
    ('Manga',           11.6636, -1.0731),
    ('Réo',             12.3197, -2.4719),
