-- Each week's results, kept: the badge, the prizes, and the history.
create table if not exists cauris_week_results (
    week_start date not null,
    org_id     uuid not null references orgs(id) on delete cascade,
    league     text not null,
    rank       integer not null,
    score      integer not null,
    primary key (week_start, org_id)
);
alter table cauris_week_results enable row level security;

-- ------------------------------------------------------------
-- 1. The league
-- ------------------------------------------------------------
create or replace function league_city(p_org_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select coalesce(
        nullif(btrim(o.city), ''),
        (select t.name from league_towns t
          where o.lat is not null and o.lng is not null
            and distance_km(o.lat, o.lng, t.lat, t.lng) <= 40
          order by distance_km(o.lat, o.lng, t.lat, t.lng)
          limit 1),
        'Autres villes')
    from orgs o where o.id = p_org_id;
$$;

create or replace function league_size(p_org_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
    with n as (
        select (select count(*) from orders x
                 where x.org_id = p_org_id and x.status in ('picked_up', 'delivered')
                   and x.created_at >= now() - interval '30 days')
             + (select count(*) from sales s
                 where s.org_id = p_org_id and s.kind = 'sale'
                   and s.occurred_at >= now() - interval '30 days') as c
    )
    select case
        when c < cauris_param('league_small_max', 30)   then 'petites'
        when c < cauris_param('league_medium_max', 150) then 'moyennes'
        else 'grandes' end
    from n;
$$;

create or replace function league_key(p_org_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select (case o.profile when 'farm' then 'farm' else 'retail' end)
           || '|' || league_city(o.id) || '|' || league_size(o.id)
    from orgs o where o.id = p_org_id;
$$;

-- « Boutiques · Ouagadougou · petites »
create or replace function league_label(p_key text)
returns text
language sql
immutable
as $$
    select (case split_part(p_key, '|', 1) when 'farm' then 'Fermes' else 'Boutiques' end)
        || ' · ' || split_part(p_key, '|', 2)
        || ' · ' || split_part(p_key, '|', 3);
$$;

create or replace function cauris_week_start(p_at timestamptz default now())
returns timestamptz
language sql
stable
as $$
    select date_trunc('week', p_at at time zone 'Africa/Ouagadougou')
           at time zone 'Africa/Ouagadougou';
$$;

-- Who races: shops and farms that earned at least once, not archived.
create or replace function league_scores(p_from timestamptz, p_to timestamptz)
returns table (org_id uuid, name text, hidden boolean, league text, score integer)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.name, o.board_hidden, league_key(o.id),
           coalesce((select sum(l.delta) from cauris_ledger l
                      where l.org_id = o.id and l.delta > 0
                        and l.reason not in ('prize', 'expired', 'spent')
                        and l.created_at >= p_from and l.created_at < p_to), 0)::int
      from orgs o
     where o.profile not in ('church', 'association')
       and o.archived_at is null and o.suspended_at is null
       and exists (select 1 from cauris_ledger l where l.org_id = o.id);
$$;

-- ------------------------------------------------------------
-- 2. The board
-- ------------------------------------------------------------
create or replace function league_board(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    with me_org as (
        select o.id, o.name, o.board_hidden, o.board_notify, league_key(o.id) as league
          from orgs o
         where o.id = p_org_id and is_org_member(p_org_id)
    ), board as (
        select s.org_id, s.name, s.hidden, s.score,
               (rank() over (order by s.score desc, s.name))::int as rank
          from league_scores(cauris_week_start(), now() + interval '1 second') s, me_org m
         where s.league = m.league
    ), me as (
        select coalesce((select b.score from board b where b.org_id = p_org_id), 0) as score
    ), mine as (
        select me.score,
               (select count(*) from board b where b.score > me.score)::int + 1 as rank,
               (select min(b.score) from board b where b.score > me.score) as above
          from me
    )
    select jsonb_build_object(
        'league', m.league,
        'label', league_label(m.league),
        'week_start', cauris_week_start(),
        'size', greatest((select count(*) from board), 1),
        'top', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'rank', t.rank,
                       'name', case when t.hidden and t.org_id <> p_org_id
                                    then 'Une ' || case when split_part(m.league, '|', 1) = 'farm'
                                                        then 'ferme' else 'boutique' end
                                         || ' de ' || split_part(m.league, '|', 2)
                                    else t.name end,
                       'score', t.score,
                       'me', t.org_id = p_org_id) order by t.rank, t.name)
              from (select * from board where score > 0 order by rank, name limit 3) t),
            '[]'::jsonb),
        'rank', x.rank,
        'score', x.score,
        'gap', case when x.above is null then null else x.above - x.score + 1 end,
        'hidden', m.board_hidden,
        'notify', m.board_notify,
        'last_week', (select jsonb_build_object('rank', r.rank, 'score', r.score)
                        from cauris_week_results r
                       where r.org_id = p_org_id
                         and r.week_start = (cauris_week_start() - interval '7 days')::date)
    )
    from me_org m, mine x;
$$;

create or replace function set_board_prefs(p_org_id uuid, p_hidden boolean, p_notify boolean)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur règle le classement';
    end if;
    update orgs set board_hidden = coalesce(p_hidden, board_hidden),
                    board_notify = coalesce(p_notify, board_notify)
     where id = p_org_id;
end;
$$;

-- ------------------------------------------------------------
-- 3. The four notifications, and the week's close
-- ------------------------------------------------------------
create or replace function cauris_board_notify()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
    v_from timestamptz := cauris_week_start();
    v_n    int := 0;
    r      record;
    v_top  text;
    v_me   record;
    v_gap  int;
begin
    create temporary table if not exists _all (
        org_id uuid, name text, hidden boolean, league text, score int, rank int) on commit drop;
    truncate _all;
    insert into _all
    select s.org_id, s.name, s.hidden, s.league, s.score,
           (rank() over (partition by s.league order by s.score desc, s.name))::int
      from league_scores(v_from, now()) s;

    for r in select a.* from _all a join orgs o on o.id = a.org_id where o.board_notify loop
        select string_agg(t.rank || '. ' ||
                   case when t.hidden then 'une ' ||
                        case when split_part(r.league, '|', 1) = 'farm' then 'ferme' else 'boutique' end
                        else t.name end
                   || ' ' || t.score, ' · ' order by t.rank, t.name)
          into v_top
          from (select * from _all where league = r.league and score > 0
                 order by rank, name limit 3) t;
        if v_top is null then
            continue;  -- nobody has earned yet in this league this week
        end if;
        select min(score) into v_gap from _all
         where league = r.league and score > r.score;
        perform notify_org_admins(r.org_id, 'cauris_board',
            '🏆 ' || league_label(r.league) || ' : ' || v_top || '. '
            || case
                 when r.rank = 1 and r.score > 0 then 'Vous êtes 1er, bravo ! Gardez la tête.'
                 when v_gap is not null then 'Vous êtes ' || r.rank || 'e : encore '
                      || (v_gap - r.score + 1) || ' cauris pour la place devant.'
                 else 'Vous êtes ' || r.rank || 'e.'
               end);
        v_n := v_n + 1;
    end loop;
    return v_n;
end;
$$;

create or replace function cauris_week_close(p_week_start date default null)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
    v_from timestamptz := coalesce(p_week_start::timestamp at time zone 'Africa/Ouagadougou',
                                   cauris_week_start() - interval '7 days');
    v_to   timestamptz := v_from + interval '7 days';
    v_week date := (v_from at time zone 'Africa/Ouagadougou')::date;
    v_n    int := 0;
    r      record;
    v_pts  int;
begin
    for r in
        select x.* from (
            select s.org_id, s.league, s.score,
                   (rank() over (partition by s.league order by s.score desc, s.name))::int as rank
              from league_scores(v_from, v_to) s
             where s.score > 0
        ) x where x.rank <= 3
    loop
        insert into cauris_week_results (week_start, org_id, league, rank, score)
        values (v_week, r.org_id, r.league, r.rank, r.score)
        on conflict (week_start, org_id) do nothing;
        if not found then
            continue;  -- already closed: once per week
        end if;
        v_pts := cauris_param('cauris_prize_' || r.rank, 0);
        if v_pts > 0 then
            insert into cauris_ledger (org_id, delta, reason, ref, note)
            values (r.org_id, v_pts, 'prize', v_week::text,
                    r.rank || 'e de la semaine · ' || league_label(r.league))
            on conflict do nothing;
        end if;
        if r.rank = 1 then
            insert into promotions (org_id, kind, days, price, currency, free, status,
                                    starts_at, ends_at, decided_at, note)
            values (r.org_id, 'shop', 7, 0, 'XOF', true, 'approved',
                    next_spot_start('shop'), next_spot_start('shop') + interval '7 days',
                    now(), 'Premier de la semaine (cauris)');
        end if;
        begin
            perform notify_org_admins(r.org_id, 'cauris_prize',
                '🏆 ' || r.rank || 'e de la semaine en ' || league_label(r.league)
                || ' ! +' || v_pts || ' cauris'
                || case when r.rank = 1 then ', et votre vitrine mise en avant 7 jours.' else '.' end);
        exception when others then null;
        end;
        v_n := v_n + 1;
    end loop;
    return v_n;
end;
$$;

-- ------------------------------------------------------------
-- 4. The vitrine's badge: last week's top 3
-- ------------------------------------------------------------
create or replace function storefront(p_slug text)
returns table (
    org_id        uuid,
    name          text,
    slug          text,
    profile       text,
    blurb         text,
    phone         text,
    address       text,
    theme         text,
    currency      text,
    lat           double precision,
    lng           double precision,
    wave_merchant text,
    style         jsonb
)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.name, o.slug, o.profile::text, o.storefront_blurb,
           o.phone, o.address, o.theme, o.default_currency, o.lat, o.lng,
           o.wave_merchant,
           (case when org_has(o.id, 'vitrine_plus') then o.storefront_style
                 else '{}'::jsonb end)
           || case when o.logo_key is not null
                   then jsonb_build_object('logo_key', o.logo_key)
                   else '{}'::jsonb end
           || jsonb_build_object('delivers', org_delivers(o.id))
           || coalesce((
                select jsonb_build_object('top_week', jsonb_build_object(
                           'rank', r.rank, 'league', league_label(r.league)))
                  from cauris_week_results r
                 where r.org_id = o.id
                   and r.week_start = (cauris_week_start() - interval '7 days')::date),
              '{}'::jsonb)
    from orgs o
    where o.id = storefront_open(p_slug);
$$;

-- ------------------------------------------------------------
-- 5. Grants, and the schedule
-- ------------------------------------------------------------
revoke execute on function league_city(uuid)                         from public;
revoke execute on function league_size(uuid)                         from public;
revoke execute on function league_key(uuid)                          from public;
revoke execute on function league_label(text)                        from public;
revoke execute on function cauris_week_start(timestamptz)            from public;
revoke execute on function league_scores(timestamptz, timestamptz)   from public;
revoke execute on function league_board(uuid)                        from public;
revoke execute on function set_board_prefs(uuid, boolean, boolean)   from public;
revoke execute on function cauris_board_notify()                     from public;
revoke execute on function cauris_week_close(date)                   from public;
revoke execute on function storefront(text)                          from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function storefront(text) to anon;
        revoke execute on function league_city(uuid)                       from anon;
        revoke execute on function league_size(uuid)                       from anon;
        revoke execute on function league_key(uuid)                        from anon;
        revoke execute on function league_scores(timestamptz, timestamptz) from anon;
        revoke execute on function league_board(uuid)                      from anon;
        revoke execute on function set_board_prefs(uuid, boolean, boolean) from anon;
        revoke execute on function cauris_board_notify()                   from anon;
        revoke execute on function cauris_week_close(date)                 from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function storefront(text)                         to authenticated;
        grant execute on function league_label(text)                       to authenticated;
        grant execute on function cauris_week_start(timestamptz)           to authenticated;
        grant execute on function league_board(uuid)                       to authenticated;
        grant execute on function set_board_prefs(uuid, boolean, boolean)  to authenticated;
        revoke execute on function league_city(uuid)                       from authenticated;
        revoke execute on function league_size(uuid)                       from authenticated;
        revoke execute on function league_key(uuid)                        from authenticated;
        revoke execute on function league_scores(timestamptz, timestamptz) from authenticated;
        revoke execute on function cauris_board_notify()                   from authenticated;
        revoke execute on function cauris_week_close(date)                 from authenticated;
    end if;
end $$;

do $$
begin
    if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
        begin
            create extension if not exists pg_cron;
            -- Ouagadougou is UTC all year: 19:00 there is 19:00 UTC.
            perform cron.schedule('cauris-board', '0 19 * * 0,1,3,5',
                                  'select public.cauris_board_notify()');
            perform cron.schedule('cauris-week-close', '10 0 * * 1',
                                  'select public.cauris_week_close()');
        exception when others then
            raise notice 'pg_cron not scheduled here: %', sqlerrm;
        end;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 087_academy.sql
-- ============================================================
-- ============================================================
-- 087_academy.sql — Académie Mara: learning by doing, paid in cauris.
--
-- The owner: an animated training that helps people understand the app.
-- Two kinds of lesson, one list:
--
--   * A guide — watched, step by step, in the app — is done when it has
--     been seen to the end.
--   * A mission — « Encaissez votre première vente » — is done when the
--     thing is done, and only then: complete_lesson() asks the business's
--     own data (a sale exists, three articles have their photo...), so a
--     mission cannot be ticked without being lived.
--
-- Each lesson earns its business the « lesson » rule's cauris (084), once
-- per lesson per business — not per person, or a shop with ten staff
-- would farm it. Each person climbs the levels on their own: Apprenti,
-- Commerçant once half the lessons are done, Maître with all of them.
-- An association follows the lessons of its kind and earns no cauris
-- (084's rule), but its people still climb.
-- ============================================================

create table if not exists academy_lessons (
    key      text primary key,
    title    text not null,
    kind     text not null check (kind in ('guide', 'mission')),
    profiles text[] not null default array['retail', 'farm'],
    minutes  integer not null default 1,
    sort     integer not null default 0
);
alter table academy_lessons enable row level security;

insert into academy_lessons (key, title, kind, profiles, minutes, sort) values
    ('welcome',      'Bienvenue sur Mara',                     'guide',   array['retail', 'farm', 'association', 'church'], 1, 10),
    ('first_article','Mettre un article en vente',             'mission', array['retail', 'farm'], 2, 20),
    ('vitrine_open', 'Ouvrir sa vitrine',                      'mission', array['retail', 'farm'], 2, 30),
    ('photos',       'Trois articles en photo',                'mission', array['retail', 'farm'], 3, 40),
    ('first_sale',   'Encaisser une vente',                    'mission', array['retail'],         2, 50),
    ('farm_log',     'Tenir le cahier de la ferme',            'mission', array['farm'],           2, 55),
    ('first_order',  'Accepter une commande de la vitrine',    'mission', array['retail', 'farm'], 2, 60),
    ('cauris',       'Gagner et dépenser des cauris',          'guide',   array['retail', 'farm'], 2, 70),
    ('league',       'Le classement de la semaine',            'guide',   array['retail', 'farm'], 1, 80)
on conflict (key) do nothing;

create table if not exists academy_done (
    org_id  uuid not null references orgs(id) on delete cascade,
    user_id uuid not null references profiles(id) on delete cascade,
    lesson  text not null references academy_lessons(key) on delete cascade,
    done_at timestamptz not null default now(),
    primary key (org_id, user_id, lesson)
);
alter table academy_done enable row level security;

-- Is a mission lived, by the business's own data?
create or replace function academy_mission_met(p_org_id uuid, p_lesson text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select case p_lesson
        when 'first_article' then exists (select 1 from products
                                           where org_id = p_org_id and is_active and is_published)
        when 'vitrine_open'  then exists (select 1 from orgs
                                           where id = p_org_id and storefront_enabled)
        when 'photos'        then (select count(*) from products p
                                    where p.org_id = p_org_id and p.is_active and p.is_published
                                      and exists (select 1 from documents d where d.product_id = p.id)) >= 3
        when 'first_sale'    then exists (select 1 from sales where org_id = p_org_id and kind = 'sale')
        when 'farm_log'      then exists (select 1 from flock_events e join flocks f on f.id = e.flock_id
                                           where f.org_id = p_org_id)
        when 'first_order'   then exists (select 1 from orders where org_id = p_org_id
                                           and status in ('accepted', 'ready', 'picked_up', 'delivered'))
        else true
    end;
$$;

-- A lesson finished: seen to the end, or — for a mission — lived.
create or replace function complete_lesson(p_org_id uuid, p_lesson text)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_lesson academy_lessons%rowtype;
    v_earned int := 0;
begin
    if auth.uid() is null or not is_org_member(p_org_id) then
        raise exception 'Leçon réservée aux membres de l''entreprise';
    end if;
    select * into v_lesson from academy_lessons where key = p_lesson;
    if not found then
        raise exception 'Leçon inconnue : %', p_lesson;
    end if;
    if v_lesson.kind = 'mission' and not academy_mission_met(p_org_id, p_lesson) then
        return jsonb_build_object('done', false, 'earned', 0);
    end if;
    insert into academy_done (org_id, user_id, lesson)
    values (p_org_id, auth.uid(), p_lesson)
    on conflict do nothing;
    v_earned := cauris_award(p_org_id, 'lesson', p_lesson);
    return jsonb_build_object('done', true, 'earned', v_earned);
end;
$$;

-- The person's academy for this business: every lesson of its kind, done
-- or not, the missions already lived (ready to collect), and the level.
create or replace function my_academy(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    with o as (select * from orgs where id = p_org_id and is_org_member(p_org_id)),
    l as (
        select a.*, exists (select 1 from academy_done d
                             where d.org_id = p_org_id and d.user_id = auth.uid()
                               and d.lesson = a.key) as done
          from academy_lessons a, o
         where o.profile = any (a.profiles)
    ),
    n as (select count(*) filter (where done) as done, count(*) as total from l)
    select jsonb_build_object(
        'lessons', coalesce((select jsonb_agg(jsonb_build_object(
                       'key', l.key, 'title', l.title, 'kind', l.kind,
                       'minutes', l.minutes, 'done', l.done,
                       'ready', l.kind = 'mission' and not l.done
                                and academy_mission_met(p_org_id, l.key))
                       order by l.sort) from l), '[]'::jsonb),
        'done', n.done,
        'total', n.total,
        'level', case when n.total > 0 and n.done >= n.total then 'Maître'
                      when n.done * 2 >= n.total and n.total > 0 then 'Commerçant'
                      else 'Apprenti' end,
        'cauris_each', coalesce((select points from cauris_rules where key = 'lesson'), 0)
    )
    from n, o;
$$;

revoke execute on function academy_mission_met(uuid, text) from public;
revoke execute on function complete_lesson(uuid, text)     from public;
revoke execute on function my_academy(uuid)                from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function academy_mission_met(uuid, text) from anon;
        revoke execute on function complete_lesson(uuid, text)     from anon;
        revoke execute on function my_academy(uuid)                from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        revoke execute on function academy_mission_met(uuid, text) from authenticated;
        grant execute on function complete_lesson(uuid, text)      to authenticated;
        grant execute on function my_academy(uuid)                 to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 088_association_trust.sql
-- ============================================================
-- ============================================================
-- 088_association_trust.sql — the trust level of an association.
--
-- An association does not race and earns no cauris (084): ranking churches
-- and associations by what they raise would press the givers and reward
-- the loudest, not the most honest. What it climbs instead is a trust
-- level, read off its own books — never declared, never bought:
--
--   verified    Mara checked who they are (a platform admin's tick).
--   regular     money recorded in at least 6 of the last 8 weeks.
--   justified   at least 80 % of the last 90 days' expenses carry their
--               receipt (a document filed against the entry); at least
--               3 expenses, so an empty book proves nothing.
--   clean       corrections (reversals) under 10 % of the last 90 days'
--               entries.
--   lasting     six months on Mara.
--
-- Five pillars, four levels: Nouvelle (0–1), Régulière (2–3), Fiable (4),
-- Exemplaire (all five — so never without Mara's verification).
--
-- This is the level and nothing it opens yet: the fundraising vitrine and
-- Wave collection it is meant to unlock wait on the platform's decisions.
-- ============================================================

alter table orgs add column if not exists verified_at timestamptz;
alter table orgs add column if not exists verified_by uuid references profiles(id) on delete set null;

-- Mara's tick, or its removal. A platform admin only; who ticked is kept.
create or replace function set_org_verified(p_org_id uuid, p_verified boolean)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Seul Mara peut vérifier une association';
    end if;
    if not exists (select 1 from orgs where id = p_org_id) then
        raise exception 'No such business';
    end if;
    update orgs
       set verified_at = case when p_verified then coalesce(verified_at, now()) end,
           verified_by = case when p_verified then coalesce(verified_by, auth.uid()) end
     where id = p_org_id;
end;
$$;

-- The five pillars and the level, for the association's own members (and
-- for Mara's admins). Null for anyone else and for a business: a shop's
-- standing is its cauris, not this.
create or replace function association_trust(p_org_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    o           orgs%rowtype;
    v_weeks     int;
    v_expenses  int;
    v_receipts  int;
    v_entries   int;
    v_reversals int;
    v_age_days  int;
    p_verified  boolean;
    p_regular   boolean;
    p_justified boolean;
    p_clean     boolean;
    p_lasting   boolean;
    v_met       int;
begin
    select * into o from orgs where id = p_org_id;
    if not found or o.profile not in ('church', 'association') then
        return null;
    end if;
    if not (is_org_member(p_org_id)
            or exists (select 1 from profiles where id = auth.uid() and is_platform_admin)) then
        return null;
    end if;

    select count(distinct date_trunc('week', je.created_at)) into v_weeks
      from journal_entries je
     where je.org_id = p_org_id and je.reverses_entry_id is null
       and je.created_at >= date_trunc('week', now()) - interval '7 weeks';

    select count(*), count(*) filter (where exists (
               select 1 from documents d where d.linked_journal_entry_id = je.id))
      into v_expenses, v_receipts
      from journal_entries je
     where je.org_id = p_org_id and je.reverses_entry_id is null
       and je.created_at >= now() - interval '90 days'
       and not exists (select 1 from journal_entries r where r.reverses_entry_id = je.id)
       and exists (select 1 from journal_lines jl join accounts a on a.id = jl.account_id
                    where jl.journal_entry_id = je.id and jl.debit > 0 and a.code like '5%');

    select count(*) filter (where je.reverses_entry_id is null),
           count(*) filter (where je.reverses_entry_id is not null)
      into v_entries, v_reversals
      from journal_entries je
     where je.org_id = p_org_id and je.created_at >= now() - interval '90 days';

    v_age_days := extract(day from now() - o.created_at)::int;

    p_verified  := o.verified_at is not null;
    p_regular   := v_weeks >= 6;
    p_justified := v_expenses >= 3 and v_receipts * 100 >= v_expenses * 80;
    p_clean     := v_entries >= 5 and v_reversals * 100 < v_entries * 10;
    p_lasting   := v_age_days >= 182;
    v_met := p_verified::int + p_regular::int + p_justified::int + p_clean::int + p_lasting::int;

    return jsonb_build_object(
        'level', case when v_met = 5 then 'Exemplaire'
                      when v_met = 4 then 'Fiable'
                      when v_met >= 2 then 'Régulière'
                      else 'Nouvelle' end,
        'met', v_met,
        'verified_at', o.verified_at,
        'pillars', jsonb_build_array(
            jsonb_build_object('key', 'verified', 'met', p_verified),
            jsonb_build_object('key', 'regular', 'met', p_regular,
                               'value', v_weeks, 'target', 6),
            jsonb_build_object('key', 'justified', 'met', p_justified,
                               'value', v_receipts, 'of', v_expenses),
            jsonb_build_object('key', 'clean', 'met', p_clean,
                               'value', v_reversals, 'of', v_entries),
            jsonb_build_object('key', 'lasting', 'met', p_lasting,
                               'value', v_age_days, 'target', 182)));
end;
$$;

revoke execute on function set_org_verified(uuid, boolean) from public;
revoke execute on function association_trust(uuid)        from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function set_org_verified(uuid, boolean) from anon;
        revoke execute on function association_trust(uuid)        from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_org_verified(uuid, boolean) to authenticated;
        grant execute on function association_trust(uuid)        to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 089_earned_locks.sql
-- ============================================================
-- ============================================================
-- 089_earned_locks.sql — tools are earned, for everyone, and the database
-- holds the door.
--
-- The owner: « I need users to earn their feature, so lock them till they
-- earn it » — no trial days, no business kept open because it was here
-- first. 085 drew the path in the app only, opened everything for seven
-- days, and left every business older than 085 ungated. Now, for shops
-- and farms alike:
--
--   invoices         the vitrine at 70 %
--   production       the vitrine at 90 %
--   credits          3 orders picked up or delivered
--   second_business  Mara Pro only
--
-- Locked means no new record: a business that already kept invoices,
-- production runs or debts still reads them all (the owner's choice:
-- « lock, keep reading »), and still collects what it is owed — paying
-- back a debt is never blocked. Pro opens the three tools at once (a
-- business paying for Pro is not asked to earn its free tools), and so
-- does « Mara Pro complet » bought with cauris, since org_plan() then
-- says pro. Associations and churches are not on this path.
--
-- The thresholds are platform settings. No destructive statement: the
-- triggers are created only where missing, functions replaced in place.
-- ============================================================

insert into platform_settings (key, value) values
    ('progress_invoices_pct',   '70'),
    ('progress_production_pct', '90'),
    ('progress_credit_orders',  '3')
on conflict (key) do nothing;

-- The one rule: is this step still ahead of the business?
create or replace function path_locked(p_org_id uuid, p_step text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select case
        when o.profile not in ('retail', 'farm') then false
        when p_step = 'second_business' then org_plan(o.id) <> 'pro'
        when org_plan(o.id) = 'pro' then false
        when p_step = 'invoices'
            then vitrine_score(o.id) < cauris_param('progress_invoices_pct', 70)
        when p_step = 'production'
            then vitrine_score(o.id) < cauris_param('progress_production_pct', 90)
        when p_step = 'credits'
            then (select count(*) from orders x
                   where x.org_id = o.id and x.status in ('picked_up', 'delivered'))
                 < cauris_param('progress_credit_orders', 3)
        else false
    end
    from orgs o where o.id = p_org_id;
$$;

-- What the refusal says, short.
create or replace function path_lock_message(p_step text)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select case p_step
        when 'invoices'   then 'Factures : vitrine à '
                               || cauris_param('progress_invoices_pct', 70) || ' % pour les débloquer.'
        when 'production' then 'Production : vitrine à '
                               || cauris_param('progress_production_pct', 90) || ' % pour la débloquer.'
        when 'credits'    then 'Carnet de crédit : '
                               || cauris_param('progress_credit_orders', 3)
                               || ' commandes terminées pour le débloquer.'
        when 'second_business' then 'Une deuxième entreprise : avec Mara Pro.'
        else 'Outil verrouillé.'
    end;
$$;

-- The door: a new invoice, production run or debt on a locked business is
-- refused. A server-side job (no signed-in caller) and Mara's own admins
-- pass — the rule is for the business, not for repairs.
create or replace function trg_path_lock()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is not null
       and not exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
       and path_locked(new.org_id, tg_argv[0]) then
        raise exception '%', path_lock_message(tg_argv[0]);
    end if;
    return new;
end;
$$;

-- A second business: asking for one needs Pro on a business already owned.
-- The first business is free, as ever.
create or replace function trg_second_business_lock()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if exists (select 1 from profiles where id = new.applicant_id and is_platform_admin) then
        return new;
    end if;
    if exists (select 1 from memberships m join orgs o on o.id = m.org_id
                where m.user_id = new.applicant_id and m.role = 'owner'
                  and o.profile in ('retail', 'farm'))
       and not exists (select 1 from memberships m
                        where m.user_id = new.applicant_id and m.role = 'owner'
                          and org_plan(m.org_id) = 'pro') then
        raise exception '%', path_lock_message('second_business');
    end if;
    return new;
end;
$$;

do $$
begin
    if not exists (select 1 from pg_trigger where tgname = 'path_lock_invoices') then
        create trigger path_lock_invoices before insert on invoices
            for each row execute function trg_path_lock('invoices');
    end if;
    if not exists (select 1 from pg_trigger where tgname = 'path_lock_production') then
        create trigger path_lock_production before insert on production_runs
            for each row execute function trg_path_lock('production');
    end if;
    if not exists (select 1 from pg_trigger where tgname = 'path_lock_debts') then
        create trigger path_lock_debts before insert on debts
            for each row execute function trg_path_lock('credits');
    end if;
    if not exists (select 1 from pg_trigger where tgname = 'path_lock_second_business') then
        create trigger path_lock_second_business before insert on org_applications
            for each row execute function trg_second_business_lock();
    end if;
end $$;

-- What the app draws: the same rule, step by step, and how far each is.
-- 085's keys stay (gated, in_trial, score, orders…) so an older app reads
-- it; in_trial is never true again.
create or replace function org_progress(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'gated',         o.profile in ('retail', 'farm'),
        'trial_until',   null,
        'in_trial',      false,
        'score',         vitrine_score(o.id),
        'orders',        (select count(*) from orders x
                           where x.org_id = o.id and x.status in ('picked_up', 'delivered')),
        'street_pct',    cauris_param('progress_street_pct', 60),
        'tools_pct',     cauris_param('progress_production_pct', 90),
        'invoices_pct',  cauris_param('progress_invoices_pct', 70),
        'production_pct', cauris_param('progress_production_pct', 90),
        'credit_orders', cauris_param('progress_credit_orders', 3),
        'orders_needed', cauris_param('progress_credit_orders', 3),
        'pro',           org_plan(o.id) = 'pro',
        'locks', jsonb_build_object(
            'invoices',        path_locked(o.id, 'invoices'),
            'production',      path_locked(o.id, 'production'),
            'credits',         path_locked(o.id, 'credits'),
            'second_business', path_locked(o.id, 'second_business')),
        'on_street',     o.progress_since is null
                         or vitrine_score(o.id) >= cauris_param('progress_street_pct', 60)
    )
    from orgs o where o.id = p_org_id;
$$;

revoke execute on function path_locked(uuid, text)       from public;
revoke execute on function path_lock_message(text)       from public;
revoke execute on function trg_path_lock()               from public;
revoke execute on function trg_second_business_lock()    from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function path_locked(uuid, text)    from anon;
        revoke execute on function path_lock_message(text)    from anon;
        revoke execute on function trg_path_lock()            from anon;
        revoke execute on function trg_second_business_lock() from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        -- The triggers call these as the writer; they read nothing private
        -- beyond a yes or no about the writer's own business.
        grant execute on function path_locked(uuid, text)    to authenticated;
        grant execute on function path_lock_message(text)    to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 090_cash_only.sql
-- ============================================================
-- ============================================================
-- 090_cash_only.sql — cash for now; Wave when Mara allows it.
--
-- The owner: « Remove Wave configuration for now. Every order will be cash
-- payment for now. Enable admin to authorise that later. » Wave stays in
-- the code (076) but every business is closed to it until a platform admin
-- ticks orgs.wave_allowed for it:
--
--   * a vitrine order paid by Wave is refused (an order trigger), and the
--     vitrine stops offering it — storefront() keeps wave_merchant back;
--   * Wave checkout for an order needs the tick as well as Pro (081/085);
--   * wave_terms() says the shop is not ready;
--   * feature_states() carries the tick, so the app hides the Wave
--     settings and the till's Wave button.
--
-- Mara Pro and the spots are paid to Mara, not to the shop: not touched
-- here. No destructive statement: a column added, functions replaced in
-- place with their own signatures, a trigger created where missing.
-- ============================================================

alter table orgs add column if not exists wave_allowed boolean not null default false;

create or replace function set_org_wave_allowed(p_org_id uuid, p_allowed boolean)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Seul Mara autorise Wave';
    end if;
    update orgs set wave_allowed = coalesce(p_allowed, false) where id = p_org_id;
    if not found then
        raise exception 'No such business';
    end if;
end;
$$;

-- A vitrine order paid by Wave, refused until Mara allows it.
create or replace function trg_order_cash_only()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if new.payment_method = 'wave'
       and not coalesce((select wave_allowed from orgs where id = new.org_id), false) then
        raise exception 'Paiement en espèces uniquement pour le moment.';
    end if;
    return new;
end;
$$;

do $$
begin
    if not exists (select 1 from pg_trigger where tgname = 'order_cash_only') then
        create trigger order_cash_only before insert on orders
            for each row execute function trg_order_cash_only();
    end if;
end $$;

-- 085's online-payment door, now also behind Mara's tick.
create or replace function trg_wave_order_pro()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if new.kind = 'order' and not coalesce((select wave_allowed from orgs where id = new.org_id), false) then
        raise exception 'Paiement en espèces uniquement pour le moment.';
    end if;
    if new.kind = 'order' and not org_has(new.org_id, 'online_payment') then
        raise exception 'Kaj Pro : le paiement en ligne est réservé aux boutiques Kaj Pro';
    end if;
    return new;
end;
$$;

create or replace function wave_terms(p_org_id uuid default null)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'on', wave_on(),
        'shop_ready', p_org_id is not null and exists (
            select 1 from orgs where id = p_org_id and wave_payout_number is not null
               and wave_allowed and org_has(id, 'online_payment')),
        'card', coalesce((select (value #>> '{}')::boolean
                            from platform_settings where key = 'wave_card'), false),
        'commission_pct', coalesce((select (value #>> '{}')::numeric
                                      from platform_settings where key = 'wave_commission_pct'), 0)
    );
$$;

-- 086's window, keeping the Wave number back until Mara allows it.
create or replace function storefront(p_slug text)
returns table (
    org_id        uuid,
    name          text,
    slug          text,
    profile       text,
    blurb         text,
    phone         text,
    address       text,
    theme         text,
    currency      text,
    lat           double precision,
    lng           double precision,
    wave_merchant text,
    style         jsonb
)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.name, o.slug, o.profile::text, o.storefront_blurb,
           o.phone, o.address, o.theme, o.default_currency, o.lat, o.lng,
           case when o.wave_allowed then o.wave_merchant end,
           (case when org_has(o.id, 'vitrine_plus') then o.storefront_style
                 else '{}'::jsonb end)
           || case when o.logo_key is not null
                   then jsonb_build_object('logo_key', o.logo_key)
                   else '{}'::jsonb end
           || jsonb_build_object('delivers', org_delivers(o.id))
           || coalesce((
                select jsonb_build_object('top_week', jsonb_build_object(
                           'rank', r.rank, 'league', league_label(r.league)))
                  from cauris_week_results r
                 where r.org_id = o.id
                   and r.week_start = (cauris_week_start() - interval '7 days')::date),
              '{}'::jsonb)
    from orgs o
    where o.id = storefront_open(p_slug);
$$;

-- 085's states, with the tick.
create or replace function feature_states(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select case when not is_org_member(p_org_id) then null else
    jsonb_build_object(
        'plan', org_plan(p_org_id),
        'balance', cauris_balance(p_org_id),
        'tools', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'feature', c.feature,
                       'cost', c.cost,
                       'until', u.until,
                       'waits_days', case
                           when c.min_days > 0
                            and o.created_at > now() - make_interval(days => c.min_days)
                           then c.min_days - extract(day from now() - o.created_at)::int end
                   ) order by c.sort)
              from cauris_costs c
              cross join orgs o
              left join cauris_unlocks u
                on u.org_id = p_org_id and u.feature = c.feature and u.until > now()
             where o.id = p_org_id), '[]'::jsonb),
        'progress', org_progress(p_org_id),
        'wave_allowed', coalesce((select wave_allowed from orgs where id = p_org_id), false)
    ) end;
$$;

revoke execute on function set_org_wave_allowed(uuid, boolean) from public;
revoke execute on function trg_order_cash_only()               from public;
revoke execute on function storefront(text)                     from public;
revoke execute on function wave_terms(uuid)                     from public;
revoke execute on function feature_states(uuid)                 from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function set_org_wave_allowed(uuid, boolean) from anon;
        revoke execute on function trg_order_cash_only()               from anon;
        revoke execute on function feature_states(uuid)                 from anon;
        grant execute on function storefront(text)                      to anon;
        revoke execute on function wave_terms(uuid)                     from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function set_org_wave_allowed(uuid, boolean) to authenticated;
        grant execute on function storefront(text)                     to authenticated;
        grant execute on function wave_terms(uuid)                     to authenticated;
        grant execute on function feature_states(uuid)                 to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 091_first_setup.sql
-- ============================================================
-- ============================================================
-- 091_first_setup.sql — a new business is walked through its first steps
-- before it opens.
--
-- The owner: « a new store owner be prompted for basic initial setup —
-- identity, add stock, vitrine and position — before they can access the
-- store interface ». orgs.setup_done_at records that the owner went
-- through it; until then the app shows the guided setup instead of the
-- home, to the business's admins (an employee is never stopped by it).
--
-- A business already selling is not sent back to the start: every shop or
-- farm with an article, or an open vitrine, is marked done here.
-- Associations, churches and generic businesses have no such setup.
--
-- feature_states() carries 'setup_done' to the app. No destructive
-- statement: a column, a backfill, functions replaced in place.
-- ============================================================

alter table orgs add column if not exists setup_done_at timestamptz;

update orgs o set setup_done_at = now()
 where setup_done_at is null
   and (o.profile not in ('retail', 'farm')
        or o.storefront_enabled
        or exists (select 1 from products p where p.org_id = o.id));

-- The owner (or an admin) says the first steps are done. The article is
-- the one step that cannot be skipped: a shop with nothing to sell is not
-- set up. The position may be left for later (and then earns no cauris
-- until it is set — the vitrine is only complete with it).
create or replace function finish_setup(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur termine la mise en route';
    end if;
    if not exists (select 1 from products where org_id = p_org_id and is_active) then
        raise exception 'Ajoutez d''abord un article.';
    end if;
    update orgs set setup_done_at = coalesce(setup_done_at, now()) where id = p_org_id;
end;
$$;

-- 090's states, with the first setup.
create or replace function feature_states(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select case when not is_org_member(p_org_id) then null else
    jsonb_build_object(
        'plan', org_plan(p_org_id),
        'balance', cauris_balance(p_org_id),
        'tools', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'feature', c.feature,
                       'cost', c.cost,
                       'until', u.until,
                       'waits_days', case
                           when c.min_days > 0
                            and o.created_at > now() - make_interval(days => c.min_days)
                           then c.min_days - extract(day from now() - o.created_at)::int end
                   ) order by c.sort)
              from cauris_costs c
              cross join orgs o
              left join cauris_unlocks u
                on u.org_id = p_org_id and u.feature = c.feature and u.until > now()
             where o.id = p_org_id), '[]'::jsonb),
        'progress', org_progress(p_org_id),
        'wave_allowed', coalesce((select wave_allowed from orgs where id = p_org_id), false),
        'setup_done', coalesce((select setup_done_at is not null from orgs where id = p_org_id), true)
    ) end;
$$;

revoke execute on function finish_setup(uuid)   from public;
revoke execute on function feature_states(uuid) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function finish_setup(uuid)   from anon;
        revoke execute on function feature_states(uuid) from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function finish_setup(uuid)   to authenticated;
        grant execute on function feature_states(uuid) to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 092_vitrine_minimum_and_referrals.sql
-- ============================================================
-- ============================================================
-- 092_vitrine_minimum_and_referrals.sql — a vitrine opens with 8 items;
-- sponsoring pays on its own and says how much.
--
-- 1. The owner: « Do not permit vitrine to a business if they do not have
--    more than 7 items for sale. » A vitrine is public — its page, the
--    street, the directory — only with 8 items on sale (active and
--    published). Below that the owner may switch it on and prepare it, and
--    still sees it themselves; the public does not. The vitrine's score
--    counts « 8 articles sur la vitrine » as its first step, so the tools
--    it opens (089) are not reached by a one-item window. The minimum is a
--    platform setting (vitrine_min_items).
--
-- 2. Sponsoring. The 200 cauris for a referred business that takes off
--    (vitrine complete, 3 finished orders) were checked only when that
--    business opened « Mes cauris », so a sponsor could wait forever. The
--    check now runs as each order is finished. my_cauris() also says what a
--    referral pays and lists the businesses sponsored, each with how far it
--    is from paying.
--
-- No destructive statement: functions replaced in place with their own
-- signatures, a trigger created where missing.
-- ============================================================

insert into platform_settings (key, value) values ('vitrine_min_items', '8')
on conflict (key) do nothing;

create or replace function vitrine_items(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select count(*)::int from products p
     where p.org_id = p_org_id and p.is_active and p.is_published;
$$;

-- 052's door, with the minimum. The business's own people still open it,
-- to see what they are preparing.
create or replace function storefront_open(p_slug text)
returns uuid
language sql
stable
security definer
set search_path = public, auth
as $$
    select o.id
    from orgs o
    where o.slug = lower(btrim(coalesce(p_slug, '')))
      and o.storefront_enabled
      and o.archived_at  is null
      and o.suspended_at is null
      and (vitrine_items(o.id) >= cauris_param('vitrine_min_items', 8)
           or exists (select 1 from memberships m
                       where m.org_id = o.id and m.user_id = auth.uid()));
$$;

-- 084's score: the first step is now the minimum, not a single item.
create or replace function vitrine_score(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select (100 * (
        (published >= greatest(cauris_param('vitrine_min_items', 8), 1))::int
      + (with_photo >= 3 or (published > 0 and with_photo >= published))::int
      + blurb::int + phone::int + address::int + pin::int) / 6.0)::int
    from (
        select
            (select count(*) from products p
              where p.org_id = o.id and p.is_active and p.is_published) as published,
            (select count(*) from products p
              where p.org_id = o.id and p.is_active and p.is_published
                and exists (select 1 from documents d where d.product_id = p.id)) as with_photo,
            nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null as blurb,
            nullif(btrim(coalesce(o.phone, '')), '') is not null as phone,
            nullif(btrim(coalesce(o.address, '')), '') is not null as address,
            (o.lat is not null and o.lng is not null) as pin
        from orgs o where o.id = p_org_id
    ) x;
$$;

-- 070's checklist, saying the minimum.
create or replace function vitrine_checklist(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select case when not is_org_member(p_org_id) then null else
    jsonb_build_object(
        'open',        o.storefront_enabled,
        'min_items',   cauris_param('vitrine_min_items', 8),
        'active',      (select count(*) from products p
                         where p.org_id = o.id and p.is_active and not p.is_ingredient),
        'published',   (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published),
        'unpublished', (select count(*) from products p
                         where p.org_id = o.id and p.is_active and not p.is_published
                           and not p.is_ingredient and coalesce(p.sale_price, 0) > 0),
        'with_photo',  (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published
                           and exists (select 1 from documents d where d.product_id = p.id)),
        'blurb',       nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null,
        'address',     nullif(btrim(coalesce(o.address, '')), '') is not null,
        'phone',       nullif(btrim(coalesce(o.phone, '')), '') is not null,
        'pin',         o.lat is not null and o.lng is not null
    ) end
    from orgs o where o.id = p_org_id;
$$;

-- 085's street, with the minimum.
create or replace function storefront_directory(
    p_lat double precision default null,
    p_lng double precision default null
)
returns table (
    org_id      uuid,
    name        text,
    slug        text,
    profile     text,
    blurb       text,
    address     text,
    lat         double precision,
    lng         double precision,
    distance_km double precision
)
language sql
stable
security definer
set search_path = public
as $$
    select d.org_id, d.name, d.slug, d.profile, d.blurb, d.address,
           d.lat, d.lng, d.distance_km
    from (
        select o.id as org_id, o.name, o.slug, o.profile::text,
               o.storefront_blurb as blurb, o.address, o.lat, o.lng,
               case
                   when p_lat is null or p_lng is null
                     or o.lat is null or o.lng is null then null
                   else 6371.0 * 2 * asin(sqrt(
                            power(sin(radians(o.lat - p_lat) / 2), 2)
                          + cos(radians(p_lat)) * cos(radians(o.lat))
                          * power(sin(radians(o.lng - p_lng) / 2), 2)))
               end as distance_km
        from orgs o
        where o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
          and vitrine_items(o.id) >= greatest(cauris_param('vitrine_min_items', 8), 1)
          and (o.progress_since is null
               or vitrine_score(o.id) >= cauris_param('progress_street_pct', 60))
    ) d
    order by (d.distance_km is null), d.distance_km, d.name;
$$;

-- The referral milestone, by itself: the sponsor is paid once the
-- business it brought in has a complete vitrine and 3 finished orders.
create or replace function referral_check(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org orgs%rowtype;
begin
    select * into v_org from orgs where id = p_org_id;
    if not found or v_org.referred_by is null then
        return;
    end if;
    if vitrine_score(p_org_id) >= 90
       and (select count(*) from orders o
             where o.org_id = p_org_id and o.status in ('picked_up', 'delivered')) >= 3 then
        perform cauris_award(v_org.referred_by, 'referral', p_org_id::text, v_org.name);
    end if;
end;
$$;

create or replace function trg_referral_check()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if new.status in ('picked_up', 'delivered')
       and old.status is distinct from new.status then
        perform referral_check(new.org_id);
    end if;
    return new;
end;
$$;

do $$
begin
    if not exists (select 1 from pg_trigger where tgname = 'orders_referral_check') then
        create trigger orders_referral_check after update of status on orders
            for each row execute function trg_referral_check();
    end if;
end $$;

-- 084's milestones, through the same check.
create or replace function cauris_milestones(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org orgs%rowtype;
begin
    if not is_org_member(p_org_id) then
        return;
    end if;
    select * into v_org from orgs where id = p_org_id;
    if v_org.storefront_enabled and vitrine_score(p_org_id) >= 100 then
        perform cauris_award(p_org_id, 'vitrine_complete', 'once');
    end if;
    perform referral_check(p_org_id);
end;
$$;

-- 084's wallet, saying what a referral pays and who was sponsored.
create or replace function my_cauris(p_org_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_last timestamptz;
begin
    if not is_org_admin(p_org_id) then
        return null;
    end if;
    perform cauris_expire(p_org_id);
    select max(created_at) into v_last from cauris_ledger
     where org_id = p_org_id and reason <> 'expired';
    return jsonb_build_object(
        'balance', cauris_balance(p_org_id),
        'week', (select coalesce(sum(delta), 0) from cauris_ledger
                  where org_id = p_org_id and delta > 0 and reason <> 'expired'
                    and created_at >= date_trunc('week', now() at time zone 'Africa/Ouagadougou')
                                      at time zone 'Africa/Ouagadougou'),
        'expires_on', case when v_last is null then null
                           else ((v_last at time zone 'Africa/Ouagadougou')::date
                                 + cauris_param('cauris_expire_days', 180)) end,
        'referral_code', (select slug from orgs where id = p_org_id),
        'referred', (select referred_by is not null from orgs where id = p_org_id),
        'referral_points', coalesce((select points from cauris_rules where key = 'referral'), 0),
        'referrals', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'name', r.name,
                       'score', vitrine_score(r.id),
                       'orders', (select count(*) from orders o
                                   where o.org_id = r.id and o.status in ('picked_up', 'delivered')),
                       'paid', exists (select 1 from cauris_ledger l
                                        where l.org_id = p_org_id and l.reason = 'referral'
                                          and l.ref = r.id::text)
                   ) order by r.created_at desc)
              from orgs r where r.referred_by = p_org_id), '[]'::jsonb),
        'history', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'delta', l.delta,
                       'reason', l.reason,
                       'label', coalesce(r.label, case l.reason
                                    when 'expired' then 'Cauris expirés'
                                    when 'spent' then 'Dépensés'
                                    else l.reason end),
                       'note', case when l.reason in ('expired', 'spent', 'prize', 'referral') then l.note end,
                       'at', l.created_at) order by l.created_at desc)
              from (select * from cauris_ledger where org_id = p_org_id
                     order by created_at desc limit 60) l
              left join cauris_rules r on r.key = l.reason), '[]'::jsonb),
        'rules', coalesce((
            select jsonb_agg(jsonb_build_object('key', key, 'points', points,
                       'daily_cap', daily_cap, 'label', label) order by sort)
              from cauris_rules where points > 0), '[]'::jsonb)
    );
end;
$$;

revoke execute on function vitrine_items(uuid)       from public;
revoke execute on function referral_check(uuid)      from public;
revoke execute on function trg_referral_check()      from public;
revoke execute on function storefront_open(text)     from public;
revoke execute on function vitrine_checklist(uuid)   from public;
revoke execute on function storefront_directory(double precision, double precision) from public;
revoke execute on function my_cauris(uuid)           from public;
revoke execute on function cauris_milestones(uuid)   from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function vitrine_items(uuid)     from anon;
        revoke execute on function referral_check(uuid)    from anon;
        revoke execute on function trg_referral_check()    from anon;
        revoke execute on function my_cauris(uuid)         from anon;
        revoke execute on function cauris_milestones(uuid) from anon;
        revoke execute on function vitrine_checklist(uuid) from anon;
        grant execute on function storefront_open(text)    to anon;
        grant execute on function storefront_directory(double precision, double precision) to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        revoke execute on function referral_check(uuid)    from authenticated;
        revoke execute on function trg_referral_check()    from authenticated;
        grant execute on function vitrine_items(uuid)      to authenticated;
        grant execute on function storefront_open(text)    to authenticated;
        grant execute on function vitrine_checklist(uuid)  to authenticated;
        grant execute on function storefront_directory(double precision, double precision) to authenticated;
        grant execute on function my_cauris(uuid)          to authenticated;
        grant execute on function cauris_milestones(uuid)  to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 093_vitrine_dressing.sql
-- ============================================================
-- ============================================================
-- 093_vitrine_dressing.sql — every vitrine dresses itself; Pro arranges it.
--
-- The owner asked for vitrine customisation for every user. Recommended
-- and agreed: chosen presets, not free design — a shopkeeper on a phone
-- picks well among good options, and the street stays legible.
--
-- 1. For every business (the basics): a cover photograph, the buttons'
--    colour among six that read on the street's paper, a tagline, and the
--    opening hours — now days and times (schedule), from which the line
--    « Lun–Sam 8h–19h » is written.
-- 2. With Mara Pro or its cauris unlock (vitrine_plus, 068): the shelf's
--    layout (grille, grandes photos, liste, menu), up to six articles « à
--    la une », hiding what is out of stock, any colour, and the live
--    « Ouvert maintenant / Fermé » banner the schedule drives.
--
-- A platform setting, vitrine_free_basics (1), opens the basics; at 0 the
-- 068 behaviour returns whole (everything behind Pro).
--
-- A business that stops being Pro keeps what it wrote — the Pro keys stay
-- stored and are carried over by every save it makes meanwhile — and the
-- street shows only the basics until it is Pro again.
--
-- No destructive statement: functions replaced with their own signatures.
-- ============================================================

insert into platform_settings (key, value) values ('vitrine_free_basics', '1')
on conflict (key) do nothing;

-- The six colours of the vitrine card (vitrine_plus_card.dart), the only
-- ones open to a business without vitrine_plus.
create or replace function vitrine_free_accents()
returns text[]
language sql
immutable
set search_path = public
as $$
    select array['#B1541A', '#2E7D5B', '#1F5FA8', '#8E3B6B', '#B8860B', '#444444'];
$$;

-- Open now, by the schedule, in Ouagadougou's time. Null without one.
-- A close earlier than the open is a night shop: open past midnight.
create or replace function vitrine_open_now(p_schedule jsonb)
returns boolean
language plpgsql
stable
set search_path = public
as $$
declare
    v_now   timestamp := now() at time zone 'Africa/Ouagadougou';
    v_day   int := extract(isodow from v_now)::int;
    v_prev  int := case when v_day = 1 then 7 else v_day - 1 end;
    v_t     time := v_now::time;
    v_open  time;
    v_close time;
begin
    if p_schedule is null or jsonb_typeof(p_schedule) <> 'object'
       or jsonb_typeof(p_schedule -> 'days') <> 'array' then
        return null;
    end if;
    v_open  := (p_schedule ->> 'open')::time;
    v_close := (p_schedule ->> 'close')::time;
    if v_close > v_open then
        return (p_schedule -> 'days') @> to_jsonb(v_day)
           and v_t >= v_open and v_t < v_close;
    end if;
    return ((p_schedule -> 'days') @> to_jsonb(v_day) and v_t >= v_open)
        or ((p_schedule -> 'days') @> to_jsonb(v_prev) and v_t < v_close);
exception when others then
    return null;
end;
$$;

-- 068's writer, split: the basics for everyone, the arrangement for Pro.
create or replace function set_storefront_style(p_org_id uuid, p_style jsonb)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_in       jsonb := coalesce(p_style, '{}'::jsonb);
    v_out      jsonb := '{}'::jsonb;
    v_old      jsonb;
    v_plus     boolean;
    v_text     text;
    v_pinned   jsonb;
    v_sched    jsonb;
    v_id       text;
    v_count    int;
begin
    if auth.uid() is null then
        raise exception 'set_storefront_style() needs a signed-in caller';
    end if;
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur peut habiller la vitrine';
    end if;
    v_plus := feature_access(p_org_id, 'vitrine_plus') = 'edit';
    if not v_plus and cauris_param('vitrine_free_basics', 1) = 0 then
        if pro_locked(p_org_id, 'vitrine_plus') then
            raise exception 'Kaj Pro : la vitrine personnalisée fait partie de Kaj Pro. Ouvrez Compte › Kaj Pro pour passer à la formule payante.';
        end if;
        raise exception 'La vitrine personnalisée vous est fermée. Voyez le propriétaire.';
    end if;
    if jsonb_typeof(v_in) <> 'object' then
        raise exception 'Le style de la vitrine doit être un objet';
    end if;
    select storefront_style into v_old from orgs where id = p_org_id;

    -- The basics.
    v_text := nullif(btrim(coalesce(v_in ->> 'tagline', '')), '');
    if v_text is not null then
        if char_length(v_text) > 80 then
            raise exception 'La phrase d''accroche fait 80 caractères au plus';
        end if;
        v_out := v_out || jsonb_build_object('tagline', v_text);
    end if;

    v_text := nullif(btrim(coalesce(v_in ->> 'hours', '')), '');
    if v_text is not null then
        if char_length(v_text) > 120 then
            raise exception 'Les horaires font 120 caractères au plus';
        end if;
        v_out := v_out || jsonb_build_object('hours', v_text);
    end if;

    v_sched := v_in -> 'schedule';
    if v_sched is not null and v_sched <> 'null'::jsonb then
        if jsonb_typeof(v_sched) <> 'object'
           or jsonb_typeof(v_sched -> 'days') <> 'array'
           or jsonb_array_length(v_sched -> 'days') = 0
           or coalesce(v_sched ->> 'open', '')  !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
           or coalesce(v_sched ->> 'close', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
           or v_sched ->> 'open' = v_sched ->> 'close'
           or exists (select 1 from jsonb_array_elements(v_sched -> 'days') d
                       where jsonb_typeof(d) <> 'number'
                          or d::text not in ('1','2','3','4','5','6','7'))
           or (select count(distinct d) from jsonb_array_elements(v_sched -> 'days') d)
              <> jsonb_array_length(v_sched -> 'days') then
            raise exception 'Les horaires : choisissez les jours, puis une heure d''ouverture et une de fermeture';
        end if;
        v_out := v_out || jsonb_build_object('schedule', jsonb_build_object(
            'days', (select jsonb_agg(d order by d::text::int)
                       from jsonb_array_elements(v_sched -> 'days') d),
            'open', v_sched ->> 'open',
            'close', v_sched ->> 'close'));
    end if;

    v_text := nullif(btrim(coalesce(v_in ->> 'accent', '')), '');
    if v_text is not null then
        if v_text !~ '^#[0-9A-Fa-f]{6}$' then
            raise exception 'La couleur doit s''écrire #RRGGBB';
        end if;
        if not v_plus and not upper(v_text) = any (vitrine_free_accents()) then
            raise exception 'Kaj Pro : les autres couleurs font partie de Kaj Pro. Choisissez l''une des six couleurs proposées.';
        end if;
        v_out := v_out || jsonb_build_object('accent', upper(v_text));
    end if;

    v_text := nullif(btrim(coalesce(v_in ->> 'cover_key', '')), '');
    if v_text is not null then
        if not exists (select 1 from documents d
                        where d.org_id = p_org_id and d.r2_key = v_text) then
            raise exception 'La photo de couverture doit être une photo de cette entreprise';
        end if;
        v_out := v_out || jsonb_build_object('cover_key', v_text);
    end if;

    -- The arrangement: written by vitrine_plus, carried over otherwise.
    if not v_plus then
        update orgs
           set storefront_style = v_out
               || jsonb_strip_nulls(jsonb_build_object(
                      'pinned', v_old -> 'pinned',
                      'hide_out_of_stock', v_old -> 'hide_out_of_stock',
                      'layout', v_old -> 'layout'))
         where id = p_org_id;
        return;
    end if;

    v_pinned := v_in -> 'pinned';
    if v_pinned is not null and jsonb_typeof(v_pinned) = 'array'
       and jsonb_array_length(v_pinned) > 0 then
        if jsonb_array_length(v_pinned) > 6 then
            raise exception 'Six articles épinglés au plus';
        end if;
        for v_id in select jsonb_array_elements_text(v_pinned) loop
            if v_id !~ '^[0-9a-fA-F-]{36}$' or not exists (
                select 1 from products p
                 where p.id = v_id::uuid and p.org_id = p_org_id) then
                raise exception 'Un article épinglé doit être un article de cette entreprise';
            end if;
        end loop;
        select count(distinct e) into v_count
          from jsonb_array_elements_text(v_pinned) e;
        if v_count <> jsonb_array_length(v_pinned) then
            raise exception 'Un article ne s''épingle qu''une fois';
        end if;
        v_out := v_out || jsonb_build_object('pinned', v_pinned);
    end if;

    if (v_in -> 'hide_out_of_stock') = 'true'::jsonb then
        v_out := v_out || '{"hide_out_of_stock": true}'::jsonb;
    end if;

    v_text := nullif(btrim(coalesce(v_in ->> 'layout', '')), '');
    if v_text is not null and v_text <> 'grid' then
        if v_text not in ('large', 'list', 'menu') then
            raise exception 'La présentation est grille, grandes photos, liste ou menu';
        end if;
        v_out := v_out || jsonb_build_object('layout', v_text);
    end if;

    update orgs set storefront_style = v_out where id = p_org_id;
end;
$$;

-- 090's window: the basics for every plan, the arrangement and the live
-- banner with vitrine_plus.
create or replace function storefront(p_slug text)
returns table (
    org_id        uuid,
    name          text,
    slug          text,
    profile       text,
    blurb         text,
    phone         text,
    address       text,
    theme         text,
    currency      text,
    lat           double precision,
    lng           double precision,
    wave_merchant text,
    style         jsonb
)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.name, o.slug, o.profile::text, o.storefront_blurb,
           o.phone, o.address, o.theme, o.default_currency, o.lat, o.lng,
           case when o.wave_allowed then o.wave_merchant end,
           (case when org_has(o.id, 'vitrine_plus') then
                     o.storefront_style
                     || case when o.storefront_style ? 'schedule'
                             then jsonb_strip_nulls(jsonb_build_object('open_now',
                                      vitrine_open_now(o.storefront_style -> 'schedule')))
                             else '{}'::jsonb end
                 when cauris_param('vitrine_free_basics', 1) = 1 then
                     o.storefront_style - 'pinned' - 'hide_out_of_stock' - 'layout'
                 else '{}'::jsonb end)
           || case when o.logo_key is not null
                   then jsonb_build_object('logo_key', o.logo_key)
                   else '{}'::jsonb end
           || jsonb_build_object('delivers', org_delivers(o.id))
           || coalesce((
                select jsonb_build_object('top_week', jsonb_build_object(
                           'rank', r.rank, 'league', league_label(r.league)))
                  from cauris_week_results r
                 where r.org_id = o.id
                   and r.week_start = (cauris_week_start() - interval '7 days')::date),
              '{}'::jsonb)
    from orgs o
    where o.id = storefront_open(p_slug);
$$;

-- 080's photo gate: a cover is servable for every plan while the basics
-- are open.
create or replace function storefront_photo_allowed(p_key text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists (
        select 1
        from documents d
        join products p on p.id = d.product_id
        join orgs     o on o.id = p.org_id
        where d.r2_key = p_key
          and p.is_active
          and p.is_published
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    ) or exists (
        select 1
        from orgs o
        where o.storefront_style ->> 'cover_key' = p_key
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
          and (org_has(o.id, 'vitrine_plus')
               or cauris_param('vitrine_free_basics', 1) = 1)
    ) or exists (
        select 1
        from orgs o
        where o.logo_key = p_key
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    );
$$;

revoke execute on function vitrine_free_accents()           from public;
revoke execute on function vitrine_open_now(jsonb)          from public;
revoke execute on function set_storefront_style(uuid, jsonb) from public;
revoke execute on function storefront(text)                  from public;
revoke execute on function storefront_photo_allowed(text)    from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function vitrine_free_accents()            from anon;
        revoke execute on function vitrine_open_now(jsonb)           from anon;
        revoke execute on function set_storefront_style(uuid, jsonb) from anon;
        grant execute on function storefront(text)                   to anon;
        grant execute on function storefront_photo_allowed(text)     to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        revoke execute on function vitrine_free_accents()            from authenticated;
        revoke execute on function vitrine_open_now(jsonb)           from authenticated;
        grant execute on function set_storefront_style(uuid, jsonb)  to authenticated;
        grant execute on function storefront(text)                   to authenticated;
        grant execute on function storefront_photo_allowed(text)     to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 094_showcase_vitrines.sql
-- ============================================================
-- ============================================================
-- 094_showcase_vitrines.sql — vitrines d'exemple on the street.
--
-- The owner: « Now we need to motivate users with store. Create fictive
-- stores in vitrine that I can manage from admin panel. » Seven businesses
-- the platform runs itself, each with 10 to 15 articles and their photos,
-- so a shopper sees what a full vitrine looks like and a shopkeeper sees
-- what theirs could become.
--
-- The rules:
--   * orgs.showcase marks them. They are Mara Pro (so they show the full
--     dressing of 093) and have no pin: they are never on the map, and the
--     page says « Pas à proximité ».
--   * Nobody can order from them: a BEFORE INSERT trigger on orders refuses
--     with the « Pas à proximité » sentence, whatever the path.
--   * They earn no cauris and so never stand in a league (086).
--   * The platform admins manage them as their owners, with the ordinary
--     business screens (articles, photos, prices, Habiller ma vitrine).
--     showcase_list() and showcase_join() serve the console's page;
--     set_showcase_visible() takes one off the street and puts it back.
--   * showcase_seed() creates the stores that do not exist yet — run once
--     here for the first platform admin, and again from the console after
--     one is deleted. It never touches a store that exists, so what the
--     admin edited stays edited.
--   * The photographs ship with the web app under /showcase/… (keys
--     « showcase/<store>/<file>.jpg »): the app reads them from the site, not
--     from the uploads Worker. A photo the admin takes later is an ordinary
--     upload and replaces it (the newest photo wins, 052).
--
-- No destructive statement.
-- ============================================================

alter table orgs add column if not exists showcase boolean not null default false;

comment on column orgs.showcase is
    'A vitrine d''exemple run by the platform (094): Pro, off the map, takes '
    'no orders, earns no cauris.';

-- The seven, and what they sell.
create or replace function showcase_seed()
returns integer
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_owner   uuid;
    v_store   record;
    v_org     uuid;
    v_made    int := 0;
    v_item    record;
    v_product uuid;
    v_cover   text;
begin
    if auth.uid() is not null then
        if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
            raise exception 'Réservé à l''administration de la plateforme';
        end if;
        v_owner := auth.uid();
    else
        select id into v_owner from profiles where is_platform_admin
         order by created_at limit 1;
    end if;
    if v_owner is null then
        return 0;
    end if;

    for v_store in
        select * from (values
            ('rowan-bike-shop', 'Rowan Bike Shop',
             'Vélos de route, gravel et BMX, révisés et prêts à rouler.',
             'Le vélo qu''il vous faut', '#1F5FA8', 'grid', 'route-carbone-rouge',
             '[1,2,3,4,5,6]', '09:00', '19:00'),
            ('tony-pizza', 'Tony Pizza',
             'Pizzas, burgers et fritures, du midi à minuit.',
             'La pizza du quartier', '#B1541A', 'large', 'pizza-pepperoni',
             '[1,2,3,4,5,6,7]', '11:00', '23:30'),
            ('chinese-fu-restaurant', 'Chinese Fu Restaurant',
             'Cuisine chinoise maison : soupes, sautés, vapeur et plaques chauffantes.',
             'Le goût de Canton', '#8E3B6B', 'list', 'plaque-chauffante-fruits-de-mer',
             '[2,3,4,5,6,7]', '11:30', '22:30'),
            ('jersey-bakery', 'Jersey Bakery',
             'Pâtisserie, viennoiserie et boissons chaudes, chaque matin.',
             'Tout juste sorti du four', '#B8860B', 'grid', 'brownies',
             '[1,2,3,4,5,6,7]', '06:30', '20:00'),
            ('bob-electronics', 'Bob Electronics',
             'Téléphones, accessoires et solaire, avec garantie.',
             'Branché sur votre quotidien', '#444444', 'list', null,
             '[1,2,3,4,5,6]', '08:30', '19:30'),
            ('ghana-restaurant', 'Ghana Restaurant',
             'Les plats d''Accra : jollof, waakye, banku, fufu et suya.',
             'Akwaaba !', '#2E7D5B', 'menu', 'brochettes',
             '[1,2,3,4,5,6,7]', '10:00', '22:00'),
            ('thomas-university-restaurant', 'Thomas University Restaurant',
             'Le restaurant du campus : plats chauds, salades et sandwichs à petit prix.',
             'Bien manger entre deux cours', '#2E7D5B', 'grid', 'combo-2-personnes',
             '[1,2,3,4,5]', '07:00', '21:00')
        ) s(slug, name, blurb, tagline, accent, layout, cover, days, open_at, close_at)
    loop
        if exists (select 1 from orgs where slug = v_store.slug) then
            continue;
        end if;
        insert into orgs (name, slug, profile, default_currency, showcase,
                          plan, plan_until, plan_note, storefront_enabled,
                          storefront_blurb, setup_done_at, progress_since)
        values (v_store.name, v_store.slug, 'retail', 'XOF', true,
                'pro', null, 'Vitrine d''exemple (094)', true,
                v_store.blurb, now(), null)
        returning id into v_org;
        insert into memberships (org_id, user_id, role, scope_kind, scope_id, visibility)
        values (v_org, v_owner, 'owner', 'org', v_org, 'full');
        perform seed_retail_accounts(v_org);

        v_cover := null;
        for v_item in
            select * from (values
                -- Rowan Bike Shop
                ('rowan-bike-shop', 'gravel-carbone-gris', 'Vélo gravel carbone gris', 1250000, 3, 'Cadre carbone, freins à disque, pneus de 40 mm.'),
                ('rowan-bike-shop', 'gravel-arc-en-ciel', 'Vélo gravel « Arc-en-ciel »', 980000, 2, 'Cadre aluminium dégradé, transmission 1×11.'),
                ('rowan-bike-shop', 'route-carbone-rouge', 'Vélo de route carbone rouge', 2400000, 1, 'Cadre aéro, groupe électronique, roues carbone.'),
                ('rowan-bike-shop', 'triathlon-noir', 'Vélo de triathlon', 2900000, 1, 'Position contre-la-montre, prolongateurs intégrés.'),
                ('rowan-bike-shop', 'fixie-noir-celeste', 'Fixie noir et céleste', 350000, 4, 'Pignon fixe, guidon piste, idéal en ville.'),
                ('rowan-bike-shop', 'randonneuse-rouge', 'Randonneuse acier rouge', 650000, 2, 'Porte-bagages avant et arrière, garde-boue.'),
                ('rowan-bike-shop', 'route-alu-argent', 'Vélo de route aluminium', 550000, 3, 'Cadre léger, 2×11 vitesses, freins à disque.'),
                ('rowan-bike-shop', 'route-carbone-noir', 'Vélo de route carbone noir', 1450000, 2, 'Cadre carbone, groupe 2×12.'),
                ('rowan-bike-shop', 'route-acier-classique', 'Vélo de route acier classique', 420000, 2, 'Cadre acier chromé, allure rétro.'),
                ('rowan-bike-shop', 'bmx-race-noir', 'BMX course 20 pouces noir', 260000, 3, 'Cadre aluminium, pédalier 3 pièces.'),
                ('rowan-bike-shop', 'bmx-race-bleu', 'BMX junior bleu', 180000, 4, 'Pour les 8 à 12 ans.'),
                ('rowan-bike-shop', 'bmx-race-rouge', 'BMX rouge', 150000, 5, 'Acier robuste, freins V-brake.'),
                ('rowan-bike-shop', 'bmx-dirt-jaune', 'BMX enfant jaune', 120000, 5, 'Roues de 16 pouces, pour débuter.'),
                ('rowan-bike-shop', 'bmx-street-rouge', 'BMX street rouge', 210000, 3, 'Pegs et rotor, pour les figures.'),
                ('rowan-bike-shop', 'bmx-freestyle-jaune', 'BMX freestyle jaune', 230000, 3, 'Cadre chromoly, frein U.'),
                -- Tony Pizza
                ('tony-pizza', 'pizza-pepperoni', 'Pizza pepperoni', 6500, 30, 'Sauce tomate, mozzarella, pepperoni.'),
                ('tony-pizza', 'pizza-fruits-de-mer', 'Pizza fruits de mer', 8500, 20, 'Crevettes, calamars, citron vert.'),
                ('tony-pizza', 'pizza-poulet-alfredo', 'Pizza poulet Alfredo', 7500, 25, 'Crème, poulet, champignons.'),
