                ('jersey-bakery', 'buche-rouge', 'Bûche fruits rouges', 15000, 5, 'Pour 8 personnes, sur commande la veille.'),
                ('jersey-bakery', 'crepe-jambon-fromage', 'Crêpe jambon-fromage', 3000, 20, 'Le salé du matin.'),
                ('jersey-bakery', 'oeuf-benedicte', 'Œufs Bénédicte', 4000, 15, 'Muffin, œuf poché, sauce hollandaise.'),
                -- Thomas University Restaurant
                ('thomas-university-restaurant', 'sandwich-roti-de-boeuf', 'Sandwich rôti de bœuf', 3000, 40, 'Baguette, bœuf, crudités.'),
                ('thomas-university-restaurant', 'sandwich-saumon', 'Sandwich saumon', 3500, 30, 'Saumon fumé, fromage frais.'),
                ('thomas-university-restaurant', 'salade-tortellini', 'Salade de tortellini', 3000, 25, 'Tortellini, olives, tomates.'),
                ('thomas-university-restaurant', 'feta-quinoa-betterave', 'Salade quinoa, feta et betterave', 3000, 25, 'Avocat, pois chiches.'),
                ('thomas-university-restaurant', 'stylish-bolognaise', 'Spaghetti bolognaise', 2500, 40, 'Sauce maison au bœuf.'),
                ('thomas-university-restaurant', 'poulet-milanais', 'Poulet milanais et pâtes', 3500, 30, 'Escalope panée, crème.'),
                ('thomas-university-restaurant', 'patate-douce-poulet-bbq', 'Patate douce et poulet BBQ', 3500, 25, 'Gratinée au fromage.'),
                ('thomas-university-restaurant', 'assiette-chawarma-poulet', 'Assiette chawarma poulet', 3500, 30, 'Frites, salade, sauce à l''ail.'),
                ('thomas-university-restaurant', 'chawarma-poulet', 'Chawarma poulet', 2000, 50, 'Le roulé du campus.'),
                ('thomas-university-restaurant', 'poulet-broasted', 'Poulet broasted', 3000, 30, 'Croustillant, avec pain.'),
                ('thomas-university-restaurant', 'ravioli-betterave', 'Raviolis à la betterave', 3500, 20, 'Sauce crème et parmesan.'),
                ('thomas-university-restaurant', 'sap-sap-salade', 'Salade sap-sap', 2500, 25, 'Pâtes, légumes croquants, œuf.'),
                ('thomas-university-restaurant', 'combo-2-personnes', 'Combo 2 personnes', 7000, 20, 'Poulet, croquettes, frites et sauces.'),
                ('thomas-university-restaurant', 'omelette-au-four', 'Omelette au four', 2000, 30, 'Le petit-déjeuner des révisions.'),
                ('thomas-university-restaurant', 'tortellini-fruits-de-mer', 'Tortellini aux fruits de mer', 4000, 20, 'Crevettes, sauce citronnée.'),
                -- Ghana Restaurant
                ('ghana-restaurant', 'brochettes', 'Suya (brochettes de bœuf épicées)', 2500, 40, 'Piment de suya, oignon, tomate.'),
                ('ghana-restaurant', null, 'Riz jollof au poulet', 3500, 40, 'Riz à la tomate, poulet grillé.'),
                ('ghana-restaurant', null, 'Waakye', 3000, 30, 'Riz et haricots, spaghetti, œuf, shito.'),
                ('ghana-restaurant', null, 'Banku et tilapia grillé', 5000, 20, 'Pâte de maïs fermentée, piment frais.'),
                ('ghana-restaurant', null, 'Fufu, soupe légère au poisson', 4000, 20, 'Igname et plantain pilés.'),
                ('ghana-restaurant', null, 'Kenkey et poisson frit', 3500, 20, 'Avec piment et oignon.'),
                ('ghana-restaurant', null, 'Kelewele', 1500, 40, 'Plantain frit épicé, gingembre.'),
                ('ghana-restaurant', null, 'Red red', 2500, 30, 'Haricots à l''huile rouge, plantain.'),
                ('ghana-restaurant', null, 'Soupe d''arachide au poulet', 4000, 20, 'Avec riz en boule (omo tuo).'),
                ('ghana-restaurant', null, 'Igname frite et shito', 2000, 30, 'Le goûter de la rue.'),
                ('ghana-restaurant', null, 'Sobolo', 1000, 50, 'Jus d''hibiscus au gingembre.'),
                ('ghana-restaurant', null, 'Shito maison (pot)', 2000, 20, 'Sauce pimentée au poisson séché.'),
                -- Bob Electronics
                ('bob-electronics', null, 'Smartphone Android 6,5 pouces', 95000, 10, '128 Go, double SIM.'),
                ('bob-electronics', null, 'Écouteurs Bluetooth', 12000, 25, 'Boîtier de charge, 20 h d''écoute.'),
                ('bob-electronics', null, 'Chargeur rapide 25 W', 6000, 40, 'Prise USB-C.'),
                ('bob-electronics', null, 'Batterie externe 20 000 mAh', 15000, 20, 'Deux ports, charge rapide.'),
                ('bob-electronics', null, 'Kit solaire 50 W', 85000, 5, 'Panneau, batterie, trois ampoules.'),
                ('bob-electronics', null, 'Ampoule LED rechargeable', 3500, 50, 'Six heures de lumière.'),
                ('bob-electronics', null, 'Téléviseur LED 32 pouces', 120000, 4, 'HD, deux ports HDMI.'),
                ('bob-electronics', null, 'Radio FM solaire', 9000, 15, 'Lampe torche intégrée.'),
                ('bob-electronics', null, 'Ventilateur rechargeable', 25000, 10, 'Batterie de huit heures.'),
                ('bob-electronics', null, 'Câble USB-C 1 m', 2000, 60, 'Tressé, charge rapide.'),
                ('bob-electronics', null, 'Clé USB 64 Go', 6500, 30, 'USB 3.0.'),
                ('bob-electronics', null, 'Montre connectée', 18000, 12, 'Pas, sommeil, notifications.'),
                ('bob-electronics', null, 'Enceinte Bluetooth', 20000, 12, 'Étanche, dix heures.')
            ) i(slug, photo, name, price, qty, description)
            where i.slug = v_store.slug
        loop
            insert into products (org_id, name, sale_price, quantity, is_active,
                                  is_published, description, created_by)
            values (v_org, v_item.name, v_item.price, v_item.qty, true,
                    true, v_item.description, v_owner)
            returning id into v_product;
            if v_item.photo is not null then
                insert into documents (org_id, r2_key, kind, product_id, uploaded_by)
                values (v_org, 'showcase/' || v_store.slug || '/' || v_item.photo || '.jpg',
                        'product_photo', v_product, v_owner);
            end if;
        end loop;

        if v_store.cover is not null then
            v_cover := 'showcase/' || v_store.slug || '/' || v_store.cover || '.jpg';
        end if;
        update orgs set storefront_style = jsonb_strip_nulls(jsonb_build_object(
                'tagline', v_store.tagline,
                'accent', v_store.accent,
                'layout', case when v_store.layout = 'grid' then null else v_store.layout end,
                'cover_key', v_cover,
                'schedule', jsonb_build_object('days', v_store.days::jsonb,
                                               'open', v_store.open_at,
                                               'close', v_store.close_at)))
         where id = v_org;
        v_made := v_made + 1;
    end loop;
    return v_made;
end;
$$;

-- The console's page: every vitrine d'exemple, how full it is, whether it
-- is on the street, and whether the caller already manages it.
create or replace function showcase_list()
returns table (
    org_id    uuid,
    name      text,
    slug      text,
    blurb     text,
    items     integer,
    photos    integer,
    visible   boolean,
    managing  boolean
)
language plpgsql
stable
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Réservé à l''administration de la plateforme';
    end if;
    return query
    select o.id, o.name, o.slug, o.storefront_blurb,
           (select count(*)::int from products p
             where p.org_id = o.id and p.is_active and p.is_published),
           (select count(distinct d.product_id)::int from documents d
              join products p on p.id = d.product_id
             where p.org_id = o.id and p.is_active and p.is_published),
           o.storefront_enabled and o.archived_at is null,
           exists (select 1 from memberships m
                    where m.org_id = o.id and m.user_id = auth.uid())
    from orgs o
    where o.showcase
    order by o.name;
end;
$$;

-- A platform admin takes the keys of one: owner, so every business screen
-- opens for them.
create or replace function showcase_join(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Réservé à l''administration de la plateforme';
    end if;
    if not exists (select 1 from orgs where id = p_org_id and showcase) then
        raise exception 'Ce n''est pas une vitrine d''exemple';
    end if;
    if not exists (select 1 from memberships
                    where org_id = p_org_id and user_id = auth.uid()) then
        insert into memberships (org_id, user_id, role, scope_kind, scope_id, visibility)
        values (p_org_id, auth.uid(), 'owner', 'org', p_org_id, 'full');
    end if;
end;
$$;

create or replace function set_showcase_visible(p_org_id uuid, p_visible boolean)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Réservé à l''administration de la plateforme';
    end if;
    update orgs set storefront_enabled = coalesce(p_visible, false)
     where id = p_org_id and showcase;
    if not found then
        raise exception 'Ce n''est pas une vitrine d''exemple';
    end if;
end;
$$;

-- What the street needs to say « Pas à proximité »: the open ones' slugs.
create or replace function showcase_slugs()
returns setof text
language sql
stable
security definer
set search_path = public
as $$
    select o.slug from orgs o
     where o.showcase and o.storefront_enabled
       and o.archived_at is null and o.suspended_at is null;
$$;

-- Nobody orders from a vitrine d'exemple, whatever the path.
create or replace function trg_order_showcase()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if exists (select 1 from orgs where id = new.org_id and showcase) then
        raise exception 'Pas à proximité : cette boutique ne prend pas de commandes près de chez vous. C''est une vitrine d''exemple de Mara.';
    end if;
    return new;
end;
$$;

do $$
begin
    if not exists (select 1 from pg_trigger where tgname = 'orders_showcase_closed') then
        create trigger orders_showcase_closed before insert on orders
            for each row execute function trg_order_showcase();
    end if;
end $$;

-- No cauris, so no league, no podium, no prize.
create or replace function trg_cauris_showcase()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if exists (select 1 from orgs where id = new.org_id and showcase) then
        return null;
    end if;
    return new;
end;
$$;

do $$
begin
    if not exists (select 1 from pg_trigger where tgname = 'cauris_ledger_showcase') then
        create trigger cauris_ledger_showcase before insert on cauris_ledger
            for each row execute function trg_cauris_showcase();
    end if;
end $$;

revoke execute on function showcase_seed()                   from public;
revoke execute on function showcase_list()                   from public;
revoke execute on function showcase_join(uuid)               from public;
revoke execute on function set_showcase_visible(uuid, boolean) from public;
revoke execute on function showcase_slugs()                  from public;
revoke execute on function trg_order_showcase()              from public;
revoke execute on function trg_cauris_showcase()             from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function showcase_seed()                     from anon;
        revoke execute on function showcase_list()                     from anon;
        revoke execute on function showcase_join(uuid)                 from anon;
        revoke execute on function set_showcase_visible(uuid, boolean) from anon;
        revoke execute on function trg_order_showcase()                from anon;
        revoke execute on function trg_cauris_showcase()               from anon;
        grant execute on function showcase_slugs()                     to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        revoke execute on function trg_order_showcase()                from authenticated;
        revoke execute on function trg_cauris_showcase()               from authenticated;
        grant execute on function showcase_seed()                      to authenticated;
        grant execute on function showcase_list()                      to authenticated;
        grant execute on function showcase_join(uuid)                  to authenticated;
        grant execute on function set_showcase_visible(uuid, boolean)  to authenticated;
        grant execute on function showcase_slugs()                     to authenticated;
    end if;
end $$;

-- The seven, for the first platform admin. None yet (a fresh database):
-- nothing; the console's button makes them later.
select showcase_seed();

notify pgrst, 'reload schema';


-- ============================================================
-- 095_showcase_order.sql
-- ============================================================
-- ============================================================
-- 095_showcase_order.sql — the vitrines d'exemple with the most photos
-- first.
--
-- The owner, looking at the street: « Please prioritize items you have
-- the pictures of. » showcase_slugs() (094) now names the vitrines
-- d'exemple in order of how many of their articles carry a photo, so the
-- street shows the full shelves first (Rowan Bike Shop, the university
-- restaurant, Tony Pizza…) and Bob Electronics, with none yet, last. The
-- app keeps that order; inside a vitrine d'exemple it puts the
-- photographed articles first.
--
-- No destructive statement: one function replaced with its own signature.
-- ============================================================

create or replace function showcase_slugs()
returns setof text
language sql
stable
security definer
set search_path = public
as $$
    select o.slug from orgs o
     where o.showcase and o.storefront_enabled
       and o.archived_at is null and o.suspended_at is null
     order by (select count(distinct d.product_id) from documents d
                 join products p on p.id = d.product_id
                where p.org_id = o.id and p.is_active and p.is_published) desc,
              o.name;
$$;

revoke execute on function showcase_slugs() from public;
do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        grant execute on function showcase_slugs() to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        grant execute on function showcase_slugs() to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 096_unlock_notices.sql
-- ============================================================
-- ============================================================
-- 096_unlock_notices.sql — « Factures débloquées ! »: the business hears
-- when a tool on its path opens.
--
-- The owner: « User should get a notification when a feature is
-- unlocked. » The path (089) opens invoices at a 70 % vitrine, production
-- at 90 %, the credit book after three finished orders — and until now
-- said nothing when it happened: the lock was simply gone the next time
-- somebody looked.
--
--   * org_unlocks keeps, per business, each step the path has opened and
--     when its admins saw the celebration. One row per step, ever: a step
--     that closes again (a photo taken off) and reopens is not news twice.
--   * check_unlocks(org) adds the steps that are open now and were not
--     before, and for each rings the admins' bell (notify_org_admins, so
--     the push of 060 follows). Only a Free shop or farm walks the path;
--     Mara Pro and every other profile have nothing to open.
--   * Triggers call it after what moves the path: an article published,
--     withdrawn or photographed, the vitrine's words, phone, address or
--     pin, an order finished. Each swallows its own failure — a bell must
--     never cost the write that rang it.
--   * unseen_unlocks(org) / mark_unlocks_seen(org): the home shows the
--     celebration once, to an admin, then forgets it.
--
-- What is open today is recorded as already seen: nobody is told on the
-- day this ships about a door that opened last month.
--
-- No destructive statement: one new table, new functions and triggers.
-- ============================================================

create table if not exists org_unlocks (
    org_id      uuid not null references orgs(id) on delete cascade,
    step        text not null check (step in ('invoices', 'production', 'credits')),
    unlocked_at timestamptz not null default now(),
    seen_at     timestamptz,
    primary key (org_id, step)
);

comment on table org_unlocks is
    'Each path step (089) a business has opened, once, and when its admins saw it (096).';

alter table org_unlocks enable row level security;

drop policy if exists org_unlocks_read on org_unlocks;
create policy org_unlocks_read on org_unlocks
    for select using (is_org_member(org_id));

-- What the bell says.
create or replace function unlock_message(p_step text)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select case p_step
        when 'invoices'   then 'Factures débloquées : votre vitrine a atteint '
                               || cauris_param('progress_invoices_pct', 70) || ' %.'
        when 'production' then 'Production débloquée : votre vitrine a atteint '
                               || cauris_param('progress_production_pct', 90) || ' %.'
        when 'credits'    then 'Carnet de crédit débloqué : '
                               || cauris_param('progress_credit_orders', 3)
                               || ' commandes terminées.'
        else 'Un outil est débloqué.'
    end;
$$;

-- The steps open now and not before: recorded, and the admins told.
create or replace function check_unlocks(p_org_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
    v_profile text;
    v_step    text;
    v_made    integer := 0;
begin
    select o.profile::text into v_profile from orgs o where o.id = p_org_id;
    if v_profile is null or v_profile not in ('retail', 'farm')
       or org_plan(p_org_id) = 'pro' then
        return 0;
    end if;
    -- All three already open: one index lookup, the common case.
    if (select count(*) from org_unlocks u where u.org_id = p_org_id) >= 3 then
        return 0;
    end if;
    foreach v_step in array array['invoices', 'production', 'credits'] loop
        if not exists (select 1 from org_unlocks u
                        where u.org_id = p_org_id and u.step = v_step)
           and not path_locked(p_org_id, v_step) then
            insert into org_unlocks (org_id, step) values (p_org_id, v_step)
                on conflict do nothing;
            if found then
                v_made := v_made + 1;
                perform notify_org_admins(p_org_id, 'unlock', unlock_message(v_step));
            end if;
        end if;
    end loop;
    return v_made;
end;
$$;

-- After what moves the path. The business is new.org_id on every table
-- but orgs, where it is the row itself.
create or replace function trg_check_unlocks()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org uuid;
begin
    if tg_table_name = 'orgs' then
        v_org := new.id;
    elsif tg_op = 'DELETE' then
        v_org := old.org_id;
    else
        v_org := new.org_id;
    end if;
    begin
        perform check_unlocks(v_org);
    exception when others then
        null;  -- a bell must never cost the write that rang it
    end;
    return null;
end;
$$;

drop trigger if exists products_check_unlocks on products;
create trigger products_check_unlocks
    after insert or delete or update of is_published, is_active on products
    for each row execute function trg_check_unlocks();

drop trigger if exists documents_check_unlocks on documents;
create trigger documents_check_unlocks
    after insert or delete or update of product_id on documents
    for each row execute function trg_check_unlocks();

drop trigger if exists orgs_check_unlocks on orgs;
create trigger orgs_check_unlocks
    after update of storefront_blurb, phone, address, lat, lng, plan on orgs
    for each row execute function trg_check_unlocks();

drop trigger if exists orders_check_unlocks on orders;
create trigger orders_check_unlocks
    after insert or update of status on orders
    for each row execute function trg_check_unlocks();

-- The celebration on the home: once, to an admin.
create or replace function unseen_unlocks(p_org_id uuid)
returns setof text
language sql
stable
security definer
set search_path = public
as $$
    select u.step from org_unlocks u
     where u.org_id = p_org_id and u.seen_at is null and is_org_admin(p_org_id)
     order by u.unlocked_at, u.step;
$$;

create or replace function mark_unlocks_seen(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Only an administrator sees the unlocks';
    end if;
    update org_unlocks set seen_at = now()
     where org_id = p_org_id and seen_at is null;
end;
$$;

-- What is open today was open before this shipped: recorded as seen,
-- nobody told.
insert into org_unlocks (org_id, step, unlocked_at, seen_at)
select o.id, s.step, now(), now()
  from orgs o
 cross join unnest(array['invoices', 'production', 'credits']) as s(step)
 where not path_locked(o.id, s.step)
on conflict do nothing;

revoke execute on function unlock_message(text)       from public;
revoke execute on function check_unlocks(uuid)        from public;
revoke execute on function trg_check_unlocks()        from public;
revoke execute on function unseen_unlocks(uuid)       from public;
revoke execute on function mark_unlocks_seen(uuid)    from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function unlock_message(text)    from anon;
        revoke execute on function check_unlocks(uuid)     from anon;
        revoke execute on function trg_check_unlocks()     from anon;
        revoke execute on function unseen_unlocks(uuid)    from anon;
        revoke execute on function mark_unlocks_seen(uuid) from anon;
        revoke all on table org_unlocks from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        revoke execute on function unlock_message(text)    from authenticated;
        revoke execute on function check_unlocks(uuid)     from authenticated;
        revoke execute on function trg_check_unlocks()     from authenticated;
        grant execute on function unseen_unlocks(uuid)     to authenticated;
        grant execute on function mark_unlocks_seen(uuid)  to authenticated;
        revoke insert, update, delete on table org_unlocks from authenticated;
        grant select on table org_unlocks to authenticated;
    end if;
end $$;


-- ============================================================
-- 097_le_chemin.sql
-- ============================================================
-- ============================================================
-- 097_le_chemin.sql — « Le Chemin »: one path, four stages, the server
-- holds every step.
--
-- The owner: « the training system combined with point earning … I see
-- many pages one after the other and it's confusing ». Seven surfaces told
-- the same progress: the first setup, the home path card, the vitrine
-- guide, the vitrine meter, the settings ticks, the Académie (087) and
-- Mes cauris. Now one spine, for shops and farms:
--
--   1 Ouvrir   first article, vitrine open, phone and address
--   2 Remplir  {min} articles, three photos, a sentence, the pin, a first
--              sale (a shop) or a first log line (a farm)
--   3 Vendre   a first accepted order, three finished, a customer back,
--              the till (or the log) kept 7 days
--   4 Grandir  a first tool bought with cauris, a business sponsored, the
--              week's top 3
--
--   * path_steps: the definitions (titles, why it matters, where to go,
--     what it pays, what it opens) — data, editable from SQL.
--   * org_path_done: a step reached stays reached, recorded once, and
--     paid once into cauris_ledger (reason 'path_step', ref = the step;
--     the ledger's unique (org, reason, ref) makes payment idempotent).
--   * path_state(org): what the app draws, for the business's members
--     (the wallet's balance and week for its admins only).
--   * The tool gates (089) become step-based and stay computed live from
--     the data: invoices with `articles` and `photos`, production with
--     stage 2 complete, the credit book with `three_orders`, a second
--     business with Pro. Pro and other profiles are never locked.
--   * 096's triggers record and pay the steps as the data moves, so a
--     business that never opens the app is still paid; new triggers on
--     sales, the farm log, cauris unlocks, sponsoring and the week's
--     podium. Each swallows its own failure.
--   * What every business already reached is recorded unpaid, once: the
--     lessons and the vitrine paid for it already.
--   * 096's seed, run under the percentages, is undone where the steps
--     still lock the tool, so the bell rings when they open it.
--   * The Académie (087) is removed: its functions and tables, its cauris
--     rule. Ledger lines of reason 'lesson' stay as history, labelled.
--
-- Re-runnable: tables if not exists, functions replaced, triggers dropped
-- and recreated, the seed guarded by a platform setting.
-- ============================================================

-- ------------------------------------------------------------
-- 0. Settings
-- ------------------------------------------------------------
insert into platform_settings (key, value) values
    -- Businesses racing in a league before the board says more than « Bientôt ».
    ('path_league_min', '3'),
    -- 1 opens every tool gate for everyone (the owner's switch; the test
    -- suites that are about something else use it for their fixtures).
    ('path_gates_open', '0')
on conflict (key) do nothing;

-- The vitrine percentages no longer gate anything (path_locked below).
delete from platform_settings where key in ('progress_invoices_pct', 'progress_production_pct');

-- ------------------------------------------------------------
-- 1. The steps
-- ------------------------------------------------------------
create table if not exists path_steps (
    key        text primary key,
    stage      integer not null check (stage between 1 and 4),
    sort       integer not null default 0,
    profiles   text[] not null default array['retail', 'farm'],
    title      text not null,
    title_farm text,
    line       text not null,
    line_farm  text,
    reward     integer not null default 0 check (reward >= 0),
    go         text not null default '',
    go_farm    text,
    opens      text check (opens is null or opens in ('invoices', 'production', 'credits'))
);

comment on table path_steps is
    'Le Chemin (097): each step of the path, its words, reward and what it opens.';

alter table path_steps enable row level security;
drop policy if exists path_steps_read on path_steps;
