-- ------------------------------------------------------------
-- 2. What each business reached
-- ------------------------------------------------------------
create table if not exists org_path_done (
    org_id  uuid not null references orgs(id) on delete cascade,
    step    text not null references path_steps(key) on delete cascade,
    done_at timestamptz not null default now(),
    paid    integer not null default 0,
    primary key (org_id, step)
);

comment on table org_path_done is
    'Each path step (097) a business reached, once, and the cauris it was paid for it.';

alter table org_path_done enable row level security;
drop policy if exists org_path_done_read on org_path_done;
create policy org_path_done_read on org_path_done
    for select using (is_org_member(org_id));

-- ------------------------------------------------------------
-- 3. How far a step is, live
-- ------------------------------------------------------------
create or replace function path_goal(p_org uuid, p_step text)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select case p_step
        when 'contact'      then 2
        when 'articles'     then greatest(cauris_param('vitrine_min_items', 8), 1)
        when 'photos'       then 3
        when 'three_orders' then greatest(cauris_param('progress_credit_orders', 3), 0)
        when 'till_week'    then 7
        when 'log_week'     then 7
        else 1
    end;
$$;

create or replace function path_progress(p_org uuid, p_step text)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select (case p_step
        when 'first_article' then
            (select count(*) from products p
              where p.org_id = p_org and p.is_active and p.is_published)
        when 'articles' then
            (select count(*) from products p
              where p.org_id = p_org and p.is_active and p.is_published)
        when 'vitrine_open' then
            (select count(*) from orgs o where o.id = p_org and o.storefront_enabled)
        when 'contact' then
            (select (nullif(btrim(coalesce(o.phone, '')), '') is not null)::int
                  + (nullif(btrim(coalesce(o.address, '')), '') is not null)::int
               from orgs o where o.id = p_org)
        when 'photos' then
            (select count(*) from products p
              where p.org_id = p_org and p.is_active and p.is_published
                and exists (select 1 from documents d where d.product_id = p.id))
        when 'blurb' then
            (select count(*) from orgs o
              where o.id = p_org and nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null)
        when 'pin' then
            (select count(*) from orgs o
              where o.id = p_org and o.lat is not null and o.lng is not null)
        when 'first_sale' then
            (select count(*) from (select 1 from sales s
                                    where s.org_id = p_org and s.kind = 'sale' limit 1) x)
        when 'farm_log' then
            (select count(*) from (select 1 from flock_events e join flocks f on f.id = e.flock_id
                                    where f.org_id = p_org limit 1) x)
        when 'first_order' then
            (select count(*) from (select 1 from orders x
                                    where x.org_id = p_org
                                      and x.status in ('accepted', 'ready', 'picked_up', 'delivered')
                                    limit 1) y)
        when 'three_orders' then
            (select count(*) from orders x
              where x.org_id = p_org and x.status in ('picked_up', 'delivered'))
        when 'returning' then
            (select count(*) from (select 1 from orders x
                                    where x.org_id = p_org and x.customer_id is not null
                                      and x.status in ('picked_up', 'delivered')
                                    group by x.customer_id having count(*) >= 2 limit 1) y)
        when 'till_week' then
            (select count(distinct (s.occurred_at at time zone 'Africa/Ouagadougou')::date)
               from sales s where s.org_id = p_org and s.kind = 'sale')
        when 'log_week' then
            (select count(distinct (e.occurred_at at time zone 'Africa/Ouagadougou')::date)
               from flock_events e join flocks f on f.id = e.flock_id
              where f.org_id = p_org)
        when 'first_unlock' then
            (select count(*) from (select 1 from cauris_unlocks u
                                    where u.org_id = p_org limit 1) x)
        when 'referral' then
            (select count(*) from (select 1 from orgs r
                                    where r.referred_by = p_org limit 1) x)
        -- A podium counts only in a week its league was a race: at least
        -- path_league_min businesses that earned that week. The week's
        -- results keep the podium alone (rank <= 3), so the racers are
        -- counted again from that week's ledger (league_scores over the
        -- week), in the league the result was written for. The league a
        -- business is in is worked out today (its town, its size), which
        -- for a past week may differ at the margin; the scores do not.
        when 'podium' then
            (select count(*) from (select 1 from cauris_week_results w
                                    where w.org_id = p_org and w.rank <= 3
                                      and (select count(*)
                                             from league_scores(
                                                    w.week_start::timestamp at time zone 'Africa/Ouagadougou',
                                                    (w.week_start + 7)::timestamp at time zone 'Africa/Ouagadougou') l
                                            where l.league = w.league and l.score > 0)
                                          >= cauris_param('path_league_min', 3)
                                    limit 1) x)
        else 0
    end)::int;
$$;

-- A step's words for this business: the farm's when it has its own, with
-- the vitrine minimum and what a sponsored business pays said.
create or replace function path_text(p_text text, p_farm_text text, p_profile text)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select replace(replace(case when p_profile = 'farm' and p_farm_text is not null
                                then p_farm_text else p_text end,
                           '{min}', path_goal(null, 'articles')::text),
                   '{referral}',
                   coalesce((select r.points from cauris_rules r where r.key = 'referral'), 0)::text);
$$;

-- ------------------------------------------------------------
-- 4. Recording and paying
-- ------------------------------------------------------------
-- The steps reached and not yet recorded: recorded, and each paid its
-- reward, once. Returns how many were recorded. A showcase vitrine (094)
-- records its steps but its ledger lines are dropped by 094's trigger, so
-- it is paid nothing.
create or replace function path_sync(p_org uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
    v_profile text;
    v_step    path_steps%rowtype;
    v_made    integer := 0;
    v_rows    integer;
begin
    select o.profile::text into v_profile from orgs o where o.id = p_org;
    if v_profile is null or v_profile not in ('retail', 'farm') then
        return 0;
    end if;
    for v_step in
        select s.* from path_steps s
         where v_profile = any (s.profiles)
           and not exists (select 1 from org_path_done d
                            where d.org_id = p_org and d.step = s.key)
         order by s.stage, s.sort
    loop
        if path_progress(p_org, v_step.key) >= path_goal(p_org, v_step.key) then
            insert into org_path_done (org_id, step) values (p_org, v_step.key)
                on conflict do nothing;
            if found then
                v_made := v_made + 1;
                if v_step.reward > 0 then
                    perform cauris_expire(p_org);
                    insert into cauris_ledger (org_id, delta, reason, ref, note)
                    values (p_org, v_step.reward, 'path_step', v_step.key,
                            path_text(v_step.title, v_step.title_farm, v_profile))
                    on conflict (org_id, reason, ref) do nothing;
                    get diagnostics v_rows = row_count;
                    if v_rows > 0 then
                        update org_path_done set paid = v_step.reward
                         where org_id = p_org and step = v_step.key;
                    end if;
                end if;
            end if;
        end if;
    end loop;
    return v_made;
end;
$$;

-- ------------------------------------------------------------
-- 5. The gates, by the steps (089's rule, rewritten)
-- ------------------------------------------------------------
create or replace function path_locked(p_org_id uuid, p_step text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select case
        when o.profile not in ('retail', 'farm') then false
        when p_step = 'second_business' then org_plan(o.id) <> 'pro'
        when org_plan(o.id) = 'pro' then false
        when cauris_param('path_gates_open', 0) = 1 then false
        when p_step = 'invoices'
            then path_progress(o.id, 'articles') < path_goal(o.id, 'articles')
              or path_progress(o.id, 'photos')   < path_goal(o.id, 'photos')
        when p_step = 'production'
            then exists (select 1 from path_steps s
                          where s.stage = 2 and o.profile = any (s.profiles)
                            and path_progress(o.id, s.key) < path_goal(o.id, s.key))
        when p_step = 'credits'
            then path_progress(o.id, 'three_orders') < path_goal(o.id, 'three_orders')
        else false
    end
    from orgs o where o.id = p_org_id;
$$;

create or replace function path_lock_message(p_step text)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select case p_step
        when 'invoices'   then 'Factures : ' || path_goal(null, 'articles')
                               || ' articles en vente et ' || path_goal(null, 'photos')
                               || ' en photo pour les débloquer.'
        when 'production' then 'Production : terminez l''étape Remplir pour la débloquer.'
        when 'credits'    then 'Carnet de crédit : '
                               || path_goal(null, 'three_orders')
                               || ' commandes terminées pour le débloquer.'
        when 'second_business' then 'Une deuxième entreprise : avec Mara Pro.'
        else 'Outil verrouillé.'
    end;
$$;

-- 096's bell, saying the steps.
create or replace function unlock_message(p_step text)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select case p_step
        when 'invoices'   then 'Factures débloquées : ' || path_goal(null, 'articles')
                               || ' articles en vente et ' || path_goal(null, 'photos')
                               || ' en photo.'
        when 'production' then 'Production débloquée : l''étape Remplir est terminée.'
        when 'credits'    then 'Carnet de crédit débloqué : '
                               || path_goal(null, 'three_orders')
                               || ' commandes terminées.'
        else 'Un outil est débloqué.'
    end;
$$;

-- 096's seed recorded as seen what was open under 089's percentages.
-- Where the steps still lock it, that row would keep the bell from ever
-- ringing when the steps do open it: dropped. Only rows that seed wrote in
-- this same transaction (the bundle is one), so a bell already earned
-- under the steps is never taken back. No live shop had invoices or
-- production open under the percentages when this shipped.
delete from org_unlocks
 where unlocked_at = now() and seen_at = now() and path_locked(org_id, step);

-- 089's progress, without the vitrine percentages that no longer gate
-- anything (an older app falls back to its own defaults for them).
create or replace function org_progress(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'gated',         o.profile in ('retail', 'farm'),
        'trial_until',   null,
        'in_trial',      false,
        'score',         vitrine_score(o.id),
        'orders',        (select count(*) from orders x
                           where x.org_id = o.id and x.status in ('picked_up', 'delivered')),
        'street_pct',    cauris_param('progress_street_pct', 60),
        'credit_orders', cauris_param('progress_credit_orders', 3),
        'orders_needed', cauris_param('progress_credit_orders', 3),
        'pro',           org_plan(o.id) = 'pro',
        'locks', jsonb_build_object(
            'invoices',        path_locked(o.id, 'invoices'),
            'production',      path_locked(o.id, 'production'),
            'credits',         path_locked(o.id, 'credits'),
            'second_business', path_locked(o.id, 'second_business')),
        'on_street',     o.progress_since is null
                         or vitrine_score(o.id) >= cauris_param('progress_street_pct', 60)
    )
    from orgs o where o.id = p_org_id;
$$;

-- ------------------------------------------------------------
-- 6. What the app draws
-- ------------------------------------------------------------
create or replace function path_state(p_org uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
    v_profile text;
    v_stage   integer;
    v_steps   jsonb;
    v_stages  jsonb;
    v_next    text;
    v_league  boolean := false;
    v_admin   boolean;
begin
    if p_org is null or not is_org_member(p_org) then
        return null;
    end if;
    v_admin := is_org_admin(p_org);
    select o.profile::text into v_profile from orgs o where o.id = p_org;
    if v_profile is null or v_profile not in ('retail', 'farm') then
        return null;
    end if;
    perform path_sync(p_org);
    perform cauris_expire(p_org);

    select coalesce(jsonb_agg(jsonb_build_object(
               'key', r.key, 'stage', r.stage, 'title', r.title, 'line', r.line,
               'go', r.go,
               -- A step reached stays reached: it shows its goal met, even
               -- if the data fell back since.
               'progress', case when r.done then r.goal else least(r.live, r.goal) end,
               -- What the data says right now, for the gates (live).
               'live', least(r.live, r.goal),
               'goal', r.goal, 'done', r.done, 'reward', r.reward, 'opens', r.opens)
               order by r.stage, r.sort), '[]'::jsonb)
      into v_steps
      from (select s.key, s.stage, s.sort, s.reward, s.opens,
                   path_text(s.title, s.title_farm, v_profile) as title,
                   path_text(s.line, s.line_farm, v_profile) as line,
                   case when v_profile = 'farm' and s.go_farm is not null
                        then s.go_farm else s.go end as go,
                   path_progress(p_org, s.key) as live,
                   path_goal(p_org, s.key) as goal,
                   exists (select 1 from org_path_done d
                            where d.org_id = p_org and d.step = s.key) as done
              from path_steps s
             where v_profile = any (s.profiles)) r;

    select coalesce(min((e ->> 'stage')::int), 5) into v_stage
      from jsonb_array_elements(v_steps) e where not (e ->> 'done')::boolean;
    select e ->> 'key' into v_next
      from jsonb_array_elements(v_steps) with ordinality x(e, i)
     where not (e ->> 'done')::boolean order by i limit 1;

    select jsonb_agg(jsonb_build_object(
               'n', n.n,
               'title', (array['Ouvrir', 'Remplir', 'Vendre', 'Grandir'])[n.n],
               'done', not exists (select 1 from jsonb_array_elements(v_steps) e
                                    where (e ->> 'stage')::int = n.n
                                      and not (e ->> 'done')::boolean))
               order by n.n)
      into v_stages from generate_series(1, 4) n(n);

    if v_stage >= 4 then
        -- A race is businesses earning this week: one that earned once,
        -- long ago, is on the board at 0 and does not make it one.
        v_league := (select count(*) from league_scores(cauris_week_start(),
                                                        now() + interval '1 second') l
                      where l.league = league_key(p_org) and l.score > 0)
                    >= cauris_param('path_league_min', 3);
    end if;

    return jsonb_build_object(
        'stage', v_stage,
        'stages', v_stages,
        'next', v_next,
        'steps', coalesce(v_steps, '[]'::jsonb),
        'tools', jsonb_build_object(
            'invoices',        not path_locked(p_org, 'invoices'),
            'production',      not path_locked(p_org, 'production'),
            'credits',         not path_locked(p_org, 'credits'),
            'second_business', not path_locked(p_org, 'second_business')),
        -- The wallet is the admins' (as my_cauris): null for the others.
        'balance', case when v_admin then cauris_balance(p_org) end,
        -- This week's score, as the league counts it (086).
        'week', case when v_admin then
                    (select coalesce(sum(l.delta), 0)::int from cauris_ledger l
                      where l.org_id = p_org and l.delta > 0
                        and l.reason not in ('prize', 'expired', 'spent')
                        and l.created_at >= cauris_week_start()) end,
        'league_open', v_league
    );
end;
$$;

-- ------------------------------------------------------------
-- 7. Recorded as the data moves: 096's triggers, and more
-- ------------------------------------------------------------
create or replace function trg_check_unlocks()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org uuid;
    v_ref uuid;
begin
    if tg_table_name = 'orgs' then
        v_org := new.id;
        -- Sponsoring is the sponsor's step.
        if tg_op = 'UPDATE' and new.referred_by is distinct from old.referred_by then
            v_ref := new.referred_by;
        end if;
    elsif tg_table_name = 'flock_events' then
        select f.org_id into v_org from flocks f where f.id = new.flock_id;
    elsif tg_op = 'DELETE' then
        v_org := old.org_id;
    else
        v_org := new.org_id;
    end if;
    begin
        perform path_sync(v_org);
    exception when others then
        null;  -- a step must never cost the write that reached it
    end;
    if v_ref is not null then
        begin
            perform path_sync(v_ref);
        exception when others then
            null;
        end;
    end if;
    begin
        perform check_unlocks(v_org);
    exception when others then
        null;  -- a bell must never cost the write that rang it
    end;
    return null;
end;
$$;

drop trigger if exists products_check_unlocks on products;
create trigger products_check_unlocks
    after insert or delete or update of is_published, is_active on products
    for each row execute function trg_check_unlocks();

drop trigger if exists documents_check_unlocks on documents;
create trigger documents_check_unlocks
    after insert or delete or update of product_id on documents
    for each row execute function trg_check_unlocks();

drop trigger if exists orgs_check_unlocks on orgs;
create trigger orgs_check_unlocks
    after update of storefront_enabled, storefront_blurb, phone, address, lat, lng, plan, referred_by
    on orgs
    for each row execute function trg_check_unlocks();

drop trigger if exists orders_check_unlocks on orders;
create trigger orders_check_unlocks
    after insert or update of status on orders
    for each row execute function trg_check_unlocks();

drop trigger if exists sales_check_unlocks on sales;
create trigger sales_check_unlocks
    after insert on sales
    for each row execute function trg_check_unlocks();

drop trigger if exists flock_events_check_unlocks on flock_events;
create trigger flock_events_check_unlocks
    after insert on flock_events
    for each row execute function trg_check_unlocks();

drop trigger if exists cauris_unlocks_check_unlocks on cauris_unlocks;
create trigger cauris_unlocks_check_unlocks
    after insert on cauris_unlocks
    for each row execute function trg_check_unlocks();

drop trigger if exists cauris_week_results_check_unlocks on cauris_week_results;
create trigger cauris_week_results_check_unlocks
    after insert on cauris_week_results
    for each row execute function trg_check_unlocks();

-- ------------------------------------------------------------
-- 8. What was reached before this shipped: recorded, not paid
-- ------------------------------------------------------------
-- Once: the lessons and the vitrine paid for it already. Guarded so the
-- bundle run again does not record, unpaid, what was reached since.
do $$
begin
    if not exists (select 1 from platform_settings where key = 'path_seeded') then
        insert into org_path_done (org_id, step, paid)
        select o.id, s.key, 0
          from orgs o
          join path_steps s on o.profile::text = any (s.profiles)
         where o.profile in ('retail', 'farm')
           and path_progress(o.id, s.key) >= path_goal(o.id, s.key)
        on conflict do nothing;
        insert into platform_settings (key, value) values ('path_seeded', to_jsonb(now()))
        on conflict (key) do nothing;
    end if;
end $$;

-- ------------------------------------------------------------
-- 9. The Académie goes
-- ------------------------------------------------------------
drop function if exists complete_lesson(uuid, text);
drop function if exists my_academy(uuid);
drop function if exists academy_mission_met(uuid, text);
drop table if exists academy_done;
drop table if exists academy_lessons;
-- No ledger line points at a rule (my_cauris labels by a left join), so
-- the rule can go; the 'lesson' lines stay, labelled below.
delete from cauris_rules where key = 'lesson';

-- 092's wallet, with the labels for what has no rule.
create or replace function my_cauris(p_org_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_last timestamptz;
begin
    if not is_org_admin(p_org_id) then
        return null;
    end if;
    perform cauris_expire(p_org_id);
    select max(created_at) into v_last from cauris_ledger
     where org_id = p_org_id and reason <> 'expired';
    return jsonb_build_object(
        'balance', cauris_balance(p_org_id),
        'week', (select coalesce(sum(delta), 0) from cauris_ledger
                  where org_id = p_org_id and delta > 0 and reason <> 'expired'
                    and created_at >= date_trunc('week', now() at time zone 'Africa/Ouagadougou')
                                      at time zone 'Africa/Ouagadougou'),
        'expires_on', case when v_last is null then null
                           else ((v_last at time zone 'Africa/Ouagadougou')::date
                                 + cauris_param('cauris_expire_days', 180)) end,
        'referral_code', (select slug from orgs where id = p_org_id),
        'referred', (select referred_by is not null from orgs where id = p_org_id),
        'referral_points', coalesce((select points from cauris_rules where key = 'referral'), 0),
        'referrals', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'name', r.name,
                       'score', vitrine_score(r.id),
                       'orders', (select count(*) from orders o
                                   where o.org_id = r.id and o.status in ('picked_up', 'delivered')),
                       'paid', exists (select 1 from cauris_ledger l
                                        where l.org_id = p_org_id and l.reason = 'referral'
                                          and l.ref = r.id::text)
                   ) order by r.created_at desc)
              from orgs r where r.referred_by = p_org_id), '[]'::jsonb),
        'history', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'delta', l.delta,
                       'reason', l.reason,
                       'label', coalesce(r.label, case l.reason
                                    when 'expired'   then 'Cauris expirés'
                                    when 'spent'     then 'Dépensés'
                                    when 'path_step' then 'Étape du chemin'
                                    when 'prize'     then 'Podium de la semaine'
                                    when 'lesson'    then 'Leçon de l''Académie Mara'
                                    else l.reason end),
                       'note', case when l.reason in ('expired', 'spent', 'prize', 'referral', 'path_step')
                                    then l.note end,
                       'at', l.created_at) order by l.created_at desc)
              from (select * from cauris_ledger where org_id = p_org_id
                     order by created_at desc limit 60) l
              left join cauris_rules r on r.key = l.reason), '[]'::jsonb),
        'rules', coalesce((
            select jsonb_agg(jsonb_build_object('key', key, 'points', points,
                       'daily_cap', daily_cap, 'label', label) order by sort)
              from cauris_rules where points > 0), '[]'::jsonb)
    );
end;
$$;

-- ------------------------------------------------------------
-- 10. Grants
-- ------------------------------------------------------------
revoke execute on function path_goal(uuid, text)          from public;
revoke execute on function path_progress(uuid, text)      from public;
revoke execute on function path_text(text, text, text)    from public;
revoke execute on function path_sync(uuid)                from public;
revoke execute on function path_state(uuid)               from public;
revoke execute on function path_locked(uuid, text)        from public;
revoke execute on function path_lock_message(text)        from public;
revoke execute on function unlock_message(text)           from public;
revoke execute on function org_progress(uuid)             from public;
revoke execute on function trg_check_unlocks()            from public;
revoke execute on function my_cauris(uuid)                from public;
revoke all on table path_steps    from public;
revoke all on table org_path_done from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function path_goal(uuid, text)       from anon;
        revoke execute on function path_progress(uuid, text)   from anon;
        revoke execute on function path_text(text, text, text) from anon;
        revoke execute on function path_sync(uuid)             from anon;
        revoke execute on function path_state(uuid)            from anon;
        revoke execute on function path_locked(uuid, text)     from anon;
        revoke execute on function path_lock_message(text)     from anon;
        revoke execute on function unlock_message(text)        from anon;
        revoke execute on function org_progress(uuid)          from anon;
        revoke execute on function trg_check_unlocks()         from anon;
        revoke execute on function my_cauris(uuid)             from anon;
        revoke all on table path_steps    from anon;
        revoke all on table org_path_done from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        -- The engine is the database's own: nobody calls it from an app.
        revoke execute on function path_goal(uuid, text)       from authenticated;
        revoke execute on function path_progress(uuid, text)   from authenticated;
        revoke execute on function path_text(text, text, text) from authenticated;
        revoke execute on function path_sync(uuid)             from authenticated;
        revoke execute on function unlock_message(text)        from authenticated;
        revoke execute on function trg_check_unlocks()         from authenticated;
        grant execute on function path_state(uuid)             to authenticated;
        -- As 089: the triggers call these as the writer.
        grant execute on function path_locked(uuid, text)      to authenticated;
        grant execute on function path_lock_message(text)      to authenticated;
        grant execute on function my_cauris(uuid)              to authenticated;
        revoke insert, update, delete on table path_steps    from authenticated;
        revoke insert, update, delete on table org_path_done from authenticated;
        grant select on table path_steps    to authenticated;
        grant select on table org_path_done to authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 098_services.sql
-- ============================================================
-- ============================================================
-- 098_services.sql — services in the vitrine, for shops, farms and
-- associations.
--
-- The owner: « Is it possible to post services with pricing in vitrine? …
-- Build all steps for all 3 types including associations. » Until now a
-- service could only be faked as an article with stock: at 0 it read
-- « Épuisé » and could not be ordered, and every till sale counted it down.
--
--   1. A service is a products row with is_service = true. price_from is
--      « à partir de » (the price is where it starts). The unit (083,
--      « heure », « séance », « personne ») serves services of every
--      profile. A name belongs to one kind: ensure_product takes
--      p_is_service, so adding a service never revives or converts an
--      article (retired or not) and adding an article never takes back a
--      service; a rename onto a name already held is refused in French;
--      an article with stock is never turned into a service.
--   2. A service has no stock, and that is held by the table itself, not
--      by each function that writes a count: a trigger keeps a service's
--      quantity at 0 and its low-stock threshold and expiry empty whatever
--      writes the row — record_sale() (029) and record_return() (032)
--      subtract and add as they always did and the count does not move, so
--      no « Stock bas » ever rings for it and it is in no stock value (the
--      reports read quantity > 0). A check constraint says the same, in
--      case the trigger is ever disabled. What has no sense for a service
--      is refused with a clear French word: a delivery received into stock
--      (receive_products, 016/032), being made by a production or being an
--      ingredient of one (026, 034). A service is never an ingredient.
--   3. The street: storefront_products() returns is_service and price_from
--      (the return type grows, so it is dropped and recreated and granted
--      again, as 083 did); a service is always « en stock » there, in the
--      search (059), in « À la une » (071) and on the directory cards (070).
--   4. The basket: place_order() (061) with one more rule — a basket of
--      services only is « sur rendez-vous »: fulfilment 'pickup' (no new
--      value), no delivery fee, and a note saying the date and time wanted.
--      A mixed basket is today's basket. Each order line remembers whether
--      it was a service (order_lines.is_service), and the shop's and the
--      customer's order lists (061) say so on each line. The customer's
--      notice (056's decide_order) says « Votre réservation … : terminée »
--      for such a booking, not « commande … récupérée ».
--   5. Associations get a vitrine. Nothing refused them one in the
--      database; the minimum did (092: 8 items). An association's vitrine
--      is public from 1 published item (platform setting
--      vitrine_min_items_association), the 092 minimum staying for shops
--      and farms: vitrine_min(org) says which, and storefront_open,
--      storefront_directory, vitrine_score and vitrine_checklist (092) read
--      it. For an association the photo step of the score is met without
--      a photo (its settings call one optional). Associations stay off Le
--      Chemin (097) and earn no cauris (084): untouched.
--   6. A finished order, service or not, does what it did: it moves the
--      order's status, and nothing in the books or the stock — the till
--      records the sale when the customer pays (055's comment on orders).
--      An association has no till; its treasurer records the money the way
--      its books already take it. Nothing is invented for it here.
--
-- Re-runnable (the bundle runs twice): columns if not exists, constraints
-- and triggers dropped and recreated, functions replaced, the one whose
-- return type changes dropped first.
-- ============================================================

-- ------------------------------------------------------------
-- 0. Settings
-- ------------------------------------------------------------
insert into platform_settings (key, value) values ('vitrine_min_items_association', '1')
on conflict (key) do nothing;

-- ------------------------------------------------------------
-- 1. Columns
-- ------------------------------------------------------------
alter table products add column if not exists is_service boolean not null default false;
alter table products add column if not exists price_from boolean not null default false;

comment on column products.is_service is
    'A service (098): no stock, never « Épuisé », booked « sur rendez-vous » when alone in a basket.';
comment on column products.price_from is
    '« à partir de » (098): the sale price is where the price starts.';

alter table order_lines add column if not exists is_service boolean not null default false;

-- ------------------------------------------------------------
-- 2. A service has no stock
-- ------------------------------------------------------------
create or replace function trg_service_no_stock()
returns trigger
language plpgsql
set search_path = public
as $$
begin
    if new.is_service then
        if new.is_ingredient then
            raise exception 'Un service ne peut pas être un ingrédient';
        end if;
        -- An article that still has goods on the shelf does not quietly
        -- become a service: its count would be zeroed with no trace.
        if tg_op = 'UPDATE' and not old.is_service and old.quantity <> 0 then
            raise exception 'Cet article a du stock : il ne peut pas devenir un service';
        end if;
        new.quantity     := 0;
        new.low_stock_at := null;
        new.expires_on   := null;
    end if;
    return new;
end;
$$;

drop trigger if exists service_no_stock on products;
create trigger service_no_stock
before insert or update on products
for each row execute function trg_service_no_stock();

alter table products drop constraint if exists products_service_no_stock;
alter table products add constraint products_service_no_stock
    check (not is_service or (quantity = 0 and not is_ingredient));

-- A delivery into stock, a batch made, an ingredient used: none is a service.
create or replace function trg_service_not_stocked()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if exists (select 1 from products p where p.id = new.product_id and p.is_service) then
        raise exception '%', case tg_table_name
            when 'stock_receipts'    then 'Un service n''a pas de stock : rien à réceptionner'
            when 'production_runs'   then 'Un service ne se fabrique pas'
            else 'Un service ne peut pas être un ingrédient' end;
    end if;
    return new;
end;
$$;

drop trigger if exists service_not_received on stock_receipts;
create trigger service_not_received
before insert on stock_receipts
for each row execute function trg_service_not_stocked();

drop trigger if exists service_not_made on production_runs;
create trigger service_not_made
before insert or update of product_id on production_runs
for each row execute function trg_service_not_stocked();

drop trigger if exists service_not_ingredient on production_inputs;
create trigger service_not_ingredient
before insert or update of product_id on production_inputs
for each row execute function trg_service_not_stocked();

-- ------------------------------------------------------------
-- 2b. One name, one kind
-- ------------------------------------------------------------
-- A name is claimed by one row of the business, retired or not (011's
-- products_by_name), and ensure_product (051) brings back whatever row
-- holds it. Without a word about the kind, adding the service « Lavage »
-- would revive a retired article « Lavage » and turn it into a service
-- (its count zeroed, its sales moved under the service), and a farm
-- adding « Lavage » for sale would get the service back. p_is_service says
-- which kind the caller is creating: true for « Mes services », false for
-- every article path; null (the till's and the production's lines typed
-- by name) keeps 051's behaviour, so a service can still be rung up by its
-- name. A retired row of the same kind comes back, as in 051; the other
-- kind, or an active service already there, is refused in French.
--
-- The signature grows, so the 051 one is dropped: two would make every
-- call with fewer arguments ambiguous.
drop function if exists ensure_product(uuid, text, numeric, numeric, text, date, uuid);
create or replace function ensure_product(
    p_org_id     uuid,
    p_name       text,
    p_sale_price numeric default null,
    p_cost_price numeric default null,
    p_barcode    text    default null,
    p_expires_on date    default null,
    p_actor      uuid    default null,
    p_is_service boolean default null
)
returns uuid
language plpgsql
set search_path = public
as $$
declare
    v_name    text := btrim(coalesce(p_name, ''));
    v_id      uuid;
    v_service boolean;
    v_active  boolean;
begin
    if v_name = '' then
        raise exception 'A product needs a name';
    end if;

    select id, is_service, is_active into v_id, v_service, v_active
      from products
     where org_id = p_org_id and lower(btrim(name)) = lower(v_name);

    if v_id is not null and p_is_service is not null then
        if p_is_service and not v_service then
            raise exception 'Un article porte déjà ce nom';
        end if;
        if not p_is_service and v_service then
            raise exception 'Un service porte déjà ce nom';
        end if;
        if p_is_service and v_active then
            raise exception 'Un service porte déjà ce nom';
        end if;
    end if;

    if v_id is null then
        -- p_actor rather than auth.uid(): this runs as the caller (051).
        insert into products (org_id, name, sale_price, cost_price, barcode,
                              expires_on, created_by, is_service)
        values (p_org_id, v_name,
                coalesce(p_sale_price, 0), coalesce(p_cost_price, 0),
                p_barcode, p_expires_on, p_actor,
                coalesce(p_is_service, false))
        returning id into v_id;
    else
        -- 051: re-adding a name brings the row back, filling only what was
        -- missing.
        update products set
            is_active  = true,
            sale_price = case when sale_price = 0 and p_sale_price is not null
                              then p_sale_price else sale_price end,
            cost_price = case when cost_price = 0 and p_cost_price is not null
                              then p_cost_price else cost_price end,
            barcode    = coalesce(barcode, p_barcode),
            expires_on = coalesce(expires_on, p_expires_on)
        where id = v_id;
    end if;

    return v_id;
end;
$$;

-- A rename onto a name another row holds: said in French, with the kind
-- that holds it, rather than as the raw unique violation of 011's index.
create or replace function trg_product_name_free()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_service boolean;
begin
    if lower(btrim(new.name)) is distinct from lower(btrim(old.name)) then
        select p.is_service into v_service
          from products p
         where p.org_id = new.org_id
           and p.id <> new.id
           and lower(btrim(p.name)) = lower(btrim(new.name));
        if found then
            raise exception '%', case when v_service
                then 'Un service porte déjà ce nom'
                else 'Un article porte déjà ce nom' end;
        end if;
    end if;
    return new;
end;
$$;

drop trigger if exists product_name_free on products;
create trigger product_name_free
before update of name on products
for each row execute function trg_product_name_free();

-- ------------------------------------------------------------
-- 3. The minimum, by profile
-- ------------------------------------------------------------
-- What opens a vitrine: 092's minimum for a shop or a farm, one item for
-- an association (and a legacy 'church').
create or replace function vitrine_min(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select case when o.profile in ('church', 'association')
                then greatest(cauris_param('vitrine_min_items_association', 1), 1)
                else cauris_param('vitrine_min_items', 8) end
      from orgs o where o.id = p_org_id;
$$;

-- 092's door, with the minimum by profile.
create or replace function storefront_open(p_slug text)
returns uuid
language sql
stable
security definer
set search_path = public, auth
as $$
    select o.id
    from orgs o
    where o.slug = lower(btrim(coalesce(p_slug, '')))
      and o.storefront_enabled
      and o.archived_at  is null
      and o.suspended_at is null
      and (vitrine_items(o.id) >= vitrine_min(o.id)
           or exists (select 1 from memberships m
                       where m.org_id = o.id and m.user_id = auth.uid()));
$$;

-- 092's score: the first step is the minimum of this business's profile.
-- An association's photo step is met without a photo: its settings say a
-- photo is optional (« Facultative : la salle, l'atelier… »), and a service
-- is read, not looked at — so one service, a blurb and a phone put it on
-- the street (4 of 6, over 085's 60 %), as the settings promise.
create or replace function vitrine_score(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select (100 * (
        (published >= greatest(vitrine_min(o_id), 1))::int
      + (association or with_photo >= 3
         or (published > 0 and with_photo >= published))::int
      + blurb::int + phone::int + address::int + pin::int) / 6.0)::int
    from (
        select
            o.id as o_id,
            o.profile in ('church', 'association') as association,
            (select count(*) from products p
              where p.org_id = o.id and p.is_active and p.is_published) as published,
            (select count(*) from products p
              where p.org_id = o.id and p.is_active and p.is_published
                and exists (select 1 from documents d where d.product_id = p.id)) as with_photo,
            nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null as blurb,
            nullif(btrim(coalesce(o.phone, '')), '') is not null as phone,
            nullif(btrim(coalesce(o.address, '')), '') is not null as address,
            (o.lat is not null and o.lng is not null) as pin
        from orgs o where o.id = p_org_id
    ) x;
$$;

-- 092's checklist: the minimum by profile, and how many services are on.
create or replace function vitrine_checklist(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select case when not is_org_member(p_org_id) then null else
    jsonb_build_object(
        'open',        o.storefront_enabled,
        'min_items',   vitrine_min(o.id),
        'active',      (select count(*) from products p
                         where p.org_id = o.id and p.is_active and not p.is_ingredient),
        'published',   (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published),
        'services',    (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published
                           and p.is_service),
        'unpublished', (select count(*) from products p
                         where p.org_id = o.id and p.is_active and not p.is_published
                           and not p.is_ingredient and coalesce(p.sale_price, 0) > 0),
        'with_photo',  (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published
                           and exists (select 1 from documents d where d.product_id = p.id)),
        'blurb',       nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null,
        'address',     nullif(btrim(coalesce(o.address, '')), '') is not null,
        'phone',       nullif(btrim(coalesce(o.phone, '')), '') is not null,
        'pin',         o.lat is not null and o.lng is not null
    ) end
    from orgs o where o.id = p_org_id;
$$;

-- 092's street, with the minimum by profile.
create or replace function storefront_directory(
    p_lat double precision default null,
    p_lng double precision default null
)
returns table (
    org_id      uuid,
    name        text,
    slug        text,
    profile     text,
    blurb       text,
    address     text,
    lat         double precision,
    lng         double precision,
    distance_km double precision
)
language sql
stable
security definer
set search_path = public
as $$
    select d.org_id, d.name, d.slug, d.profile, d.blurb, d.address,
           d.lat, d.lng, d.distance_km
    from (
        select o.id as org_id, o.name, o.slug, o.profile::text,
               o.storefront_blurb as blurb, o.address, o.lat, o.lng,
               case
                   when p_lat is null or p_lng is null
                     or o.lat is null or o.lng is null then null
                   else 6371.0 * 2 * asin(sqrt(
                            power(sin(radians(o.lat - p_lat) / 2), 2)
                          + cos(radians(p_lat)) * cos(radians(o.lat))
                          * power(sin(radians(o.lng - p_lng) / 2), 2)))
               end as distance_km
        from orgs o
        where o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
          and vitrine_items(o.id) >= greatest(vitrine_min(o.id), 1)
          and (o.progress_since is null
               or vitrine_score(o.id) >= cauris_param('progress_street_pct', 60))
    ) d
    order by (d.distance_km is null), d.distance_km, d.name;
$$;

-- ------------------------------------------------------------
-- 4. The street
-- ------------------------------------------------------------
-- 083's window, with is_service and price_from. A service is always
-- orderable; the articles come first, then the services.
drop function if exists storefront_products(text);
create function storefront_products(p_slug text)
returns table (
    id             uuid,
    name           text,
    sale_price     numeric,
    in_stock       boolean,
    photo_key      text,
    description    text,
    unit           text,
    available_from date,
    is_service     boolean,
    price_from     boolean
)
language sql
stable
security definer
set search_path = public
as $$
    select p.id, p.name, p.sale_price,
           -- A service has no count; a pre-order is orderable before there
           -- is anything to count.
           (p.is_service
            or p.quantity > 0
            or p.available_from > (now() at time zone 'Africa/Ouagadougou')::date),
           (select d.r2_key from documents d
             where d.product_id = p.id
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1),
           nullif(btrim(p.description), ''),
           nullif(btrim(p.unit), ''),
           case when p.available_from > (now() at time zone 'Africa/Ouagadougou')::date
                then p.available_from end,
           p.is_service,
           p.price_from
    from products p
    where p.org_id = storefront_open(p_slug)
      and p.is_active
      and p.is_published
    order by p.is_service, p.name;
$$;

-- 059's search: a service is never « épuisé ».
create or replace function search_products(
    p_query text,
    p_lat   double precision default null,
    p_lng   double precision default null
)
returns table (
    id          uuid,
    name        text,
    sale_price  numeric,
    in_stock    boolean,
    photo_key   text,
    shop_name   text,
    shop_slug   text,
    currency    text,
    shop_lat    double precision,
    shop_lng    double precision,
    distance_km double precision
)
language sql
stable
security definer
set search_path = public
as $$
    with q as (
        -- Escape the pattern characters so a shopper typing "%" or "_"
        -- searches for those characters instead of everything.
        select fold_search_text(btrim(coalesce(p_query, ''))) as folded
    ),
    hits as (
        select p.id, p.name, p.sale_price,
               (p.is_service or p.quantity > 0) as in_stock,
               (select d.r2_key from documents d
                 where d.product_id = p.id
                 order by coalesce(d.captured_at, d.created_at) desc
                 limit 1) as photo_key,
               o.name as shop_name, o.slug as shop_slug,
               o.default_currency as currency,
               o.lat as shop_lat, o.lng as shop_lng,
               case
                   when p_lat is null or p_lng is null
                     or o.lat is null or o.lng is null then null
                   else 6371.0 * 2 * asin(sqrt(
                            power(sin(radians(o.lat - p_lat) / 2), 2)
                          + cos(radians(p_lat)) * cos(radians(o.lat))
                          * power(sin(radians(o.lng - p_lng) / 2), 2)))
               end as distance_km,
               position((select folded from q) in fold_search_text(p.name))
                   as hit_at
        from products p
        join orgs o on o.id = p.org_id
        where length((select folded from q)) >= 2
          and fold_search_text(p.name) like
              '%' || replace(replace(replace((select folded from q),
                    '\', '\\'), '%', '\%'), '_', '\_') || '%'
          and p.is_active
          and p.is_published
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    )
    select h.id, h.name, h.sale_price, h.in_stock, h.photo_key,
           h.shop_name, h.shop_slug, h.currency,
           h.shop_lat, h.shop_lng, h.distance_km
    from hits h
    order by (h.hit_at = 1) desc, h.in_stock desc,
             (h.distance_km is null), h.distance_km, h.name, h.shop_name
    limit 50;
$$;

-- 071's « À la une »: a service is never « épuisé ».
create or replace function storefront_featured()
returns table (
    id         uuid,
    name       text,
    sale_price numeric,
    in_stock   boolean,
    photo_key  text,
    shop_name  text,
    shop_slug  text,
    currency   text
)
language sql
stable
security definer
set search_path = public
as $$
    select p.id, p.name, p.sale_price, (p.is_service or p.quantity > 0),
           (select d.r2_key from documents d
             where d.product_id = p.id
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1),
           o.name, o.slug, o.default_currency
    from products p
    join orgs o on o.id = p.org_id
    left join lateral (
        select min(pm.starts_at) as since from promotions pm
         where pm.product_id = p.id and pm.status = 'approved'
           and pm.starts_at <= now() and pm.ends_at > now()
    ) spot on true
    where (spot.since is not null or p.featured_until > now())
      and p.is_active
      and p.is_published
      and o.storefront_enabled
      and o.archived_at  is null
      and o.suspended_at is null
    order by (spot.since is null), spot.since, p.featured_until desc nulls last, p.name
    limit 12;
$$;

-- 070's cards: a service is not pushed back as if it were sold out.
create or replace function storefront_previews(p_slugs text[])
returns table (
    slug       text,
    product_id uuid,
    name       text,
    sale_price numeric,
    photo_key  text
)
language sql
stable
security definer
set search_path = public
as $$
    select x.slug, x.id, x.name, x.sale_price, x.photo_key
    from (
        select o.slug, p.id, p.name, p.sale_price, ph.r2_key as photo_key,
               row_number() over (
                   partition by o.id
                   order by (ph.r2_key is null),
                            (not p.is_service and p.quantity <= 0), p.name
               ) as n
        from orgs o
        join products p on p.org_id = o.id
        left join lateral (
            select d.r2_key from documents d
             where d.product_id = p.id
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1
        ) ph on true
        where o.slug = any (coalesce(p_slugs, '{}'))
          and o.id = storefront_open(o.slug)
          and p.is_active
          and p.is_published
    ) x
    where x.n <= 3
    order by x.slug, x.n;
$$;

-- ------------------------------------------------------------
-- 5. The basket
-- ------------------------------------------------------------
-- 061's order, plus: a basket of services only is « sur rendez-vous » —
-- picked up, never delivered, with the date and time wanted in the note.
-- Each line remembers whether it was a service.
create or replace function place_order(
    p_slug       text,
    p_lines      jsonb,
    p_fulfilment text default 'pickup',
    p_note       text default null,
    p_address    text default null,
    p_phone      text default null,
    p_payment    text default 'cash',
    p_drop_lat   double precision default null,
    p_drop_lng   double precision default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org      uuid;
    v_id       uuid;
    v_line     jsonb;
    v_product  products%rowtype;
    v_qty      numeric;
    v_total    numeric := 0;
    v_name     text;
    v_phone    text;
    v_currency text;
    v_wave     text;
    v_fee      numeric;
    v_address  text := nullif(btrim(coalesce(p_address, '')), '');
    v_note     text := nullif(btrim(coalesce(p_note, '')), '');
    v_services boolean;
begin
    if auth.uid() is null then
        raise exception 'Sign in to order';
    end if;
    v_org := storefront_open(p_slug);
    if v_org is null then
        raise exception 'This shop is not taking orders';
    end if;
    if p_fulfilment not in ('pickup', 'delivery') then
        raise exception 'Unknown fulfilment: %', p_fulfilment;
    end if;
    if p_lines is null or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'An order needs at least one article';
    end if;

    -- Services only: an appointment, not a parcel. Said before the
    -- delivery rules, so the customer hears the reason that applies.
    select coalesce(bool_and(coalesce(p.is_service, false)), false)
      into v_services
      from jsonb_array_elements(p_lines) l
      left join products p
        on p.id = nullif(l ->> 'product_id', '')::uuid and p.org_id = v_org;
    if v_services then
        if p_fulfilment <> 'pickup' then
            raise exception 'Un service se réserve sur rendez-vous : pas de livraison';
        end if;
        if v_note is null then
            raise exception 'Indiquez la date et l''heure souhaitées';
        end if;
    end if;

    if p_fulfilment = 'delivery' and v_address is null then
        raise exception 'A delivery needs an address';
    end if;
    if (p_drop_lat is null) <> (p_drop_lng is null) then
        raise exception 'A delivery pin needs both a latitude and a longitude';
    end if;
    if p_payment not in ('cash', 'wave') then
        raise exception 'Unknown payment method: %', p_payment;
    end if;
    select wave_merchant, default_currency into v_wave, v_currency
      from orgs where id = v_org;
    if p_payment = 'wave' and v_wave is null then
        raise exception 'This shop does not take Wave';
    end if;

    select coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''),
                    nullif(btrim(coalesce(full_name, '')), ''),
                    'Client'),
           phone
      into v_name, v_phone
      from profiles where id = auth.uid();

    -- The fee is fixed now, from the pin the customer gave: a rate
    -- changed tomorrow does not change what was agreed today.
    if p_fulfilment = 'delivery' then
        v_fee := delivery_fee(v_org, p_drop_lat, p_drop_lng);
    end if;

    insert into orders (org_id, customer_id, customer_name, phone,
                        fulfilment, note, address, currency, payment_method,
                        drop_lat, drop_lng, delivery_fee)
    values (v_org, auth.uid(), v_name,
            coalesce(nullif(btrim(coalesce(p_phone, '')), ''), v_phone),
            p_fulfilment,
            v_note,
            v_address,
            coalesce(v_currency, 'XOF'),
            p_payment,
            case when p_fulfilment = 'delivery' then p_drop_lat end,
            case when p_fulfilment = 'delivery' then p_drop_lng end,
            v_fee)
    returning id into v_id;

    for v_line in select * from jsonb_array_elements(p_lines) loop
        v_qty := (v_line->>'quantity')::numeric;
        if v_qty is null or v_qty <= 0 then
            raise exception 'A quantity must be positive';
        end if;
        select * into v_product
          from products
         where id = (v_line->>'product_id')::uuid
           and org_id = v_org
           and is_active
           and is_published;
        if not found then
            raise exception 'An article is not in this shop''s window';
        end if;
        insert into order_lines (order_id, product_id, name, unit_price, quantity, is_service)
        values (v_id, v_product.id, v_product.name,
                coalesce(v_product.sale_price, 0), v_qty, v_product.is_service);
        v_total := v_total + coalesce(v_product.sale_price, 0) * v_qty;
    end loop;

    update orders set total = v_total where id = v_id;

    begin
        perform notify_org_admins(
            v_org, 'new_order',
            case when v_services then 'Nouvelle demande de ' else 'Nouvelle commande de ' end
            || v_name || ' : '
            || to_char(v_total, 'FM999G999G999D00') || ' '
            || coalesce(v_currency, 'XOF')
            || case when p_payment = 'wave' then ' (Wave)' else '' end
            || case when v_fee is not null
                    then ' + livraison ' || to_char(v_fee, 'FM999G999G999') else '' end);
    exception when others then
        null;
    end;

    return v_id;
end;
$$;

-- 061's lists, each line saying whether it is a service. Same return
-- types (the lines are jsonb), so replaced in place.
create or replace function my_orders()
returns table (
    id             uuid,
    org_id         uuid,
    shop_name      text,
    shop_slug      text,
    status         text,
    fulfilment     text,
    note           text,
    address        text,
    phone          text,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    courier_name   text,
    payment_method text,
    paid_at        timestamptz,
    shop_wave      text,
    delivery_fee   numeric,
    lines          jsonb
)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.org_id, g.name, g.slug, o.status, o.fulfilment,
           o.note, o.address, o.phone, o.total, o.currency, o.created_at,
           (select coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                            nullif(btrim(coalesce(p.full_name, '')), ''))
              from profiles p where p.id = o.courier_id),
           o.payment_method, o.paid_at, g.wave_merchant, o.delivery_fee,
           (select coalesce(jsonb_agg(jsonb_build_object(
                       'name', l.name, 'unit_price', l.unit_price,
                       'quantity', l.quantity, 'is_service', l.is_service)
                       order by l.name), '[]'::jsonb)
              from order_lines l where l.order_id = o.id)
      from orders o
      join orgs g on g.id = o.org_id
     where o.customer_id = auth.uid()
     order by (o.status in ('pending', 'accepted', 'ready', 'in_transit')) desc,
              o.created_at desc;
$$;

create or replace function shop_orders(p_org_id uuid)
returns table (
    id             uuid,
    customer_name  text,
    phone          text,
    status         text,
    fulfilment     text,
    note           text,
    address        text,
    drop_lat       double precision,
    drop_lng       double precision,
    total          numeric,
    currency       text,
    created_at     timestamptz,
    courier_name   text,
    payment_method text,
    paid_at        timestamptz,
    delivery_fee   numeric,
    lines          jsonb
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
    if not is_org_member(p_org_id) then
        raise exception 'Only the shop sees its orders';
    end if;
    return query
    select o.id, o.customer_name, o.phone, o.status, o.fulfilment,
           o.note, o.address, o.drop_lat, o.drop_lng,
           o.total, o.currency, o.created_at,
           (select coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                            nullif(btrim(coalesce(p.full_name, '')), ''))
              from profiles p where p.id = o.courier_id),
           o.payment_method, o.paid_at, o.delivery_fee,
           (select coalesce(jsonb_agg(jsonb_build_object(
                       'name', l.name, 'unit_price', l.unit_price,
                       'quantity', l.quantity, 'is_service', l.is_service)
                       order by l.name), '[]'::jsonb)
              from order_lines l where l.order_id = o.id)
      from orders o
     where o.org_id = p_org_id
     order by (o.status in ('pending', 'accepted', 'ready', 'in_transit')) desc,
              o.created_at desc;
end;
$$;

-- 056's answer, in a booking's words: a basket of services only (picked
-- up, every line a service) is « Votre réservation », and its end is
-- « terminée » — nobody collects a haircut. Everything else as in 056.
create or replace function decide_order(p_order_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_order   orders%rowtype;
    v_ok      boolean;
    v_booking boolean;
begin
    select * into v_order from orders where id = p_order_id;
    if not found then
        raise exception 'No such order';
    end if;
    if not can_write_org(v_order.org_id) then
        raise exception 'Only the shop can answer its orders';
    end if;

    v_ok := case v_order.status
        when 'pending'    then p_status in ('accepted', 'refused')
        when 'accepted'   then p_status in ('ready', 'picked_up', 'delivered', 'cancelled')
        when 'ready'      then p_status in ('picked_up', 'delivered', 'cancelled')
        -- Once the parcel is on a motorbike the shop can only confirm the
        -- end of the journey, not rewrite it.
        when 'in_transit' then p_status = 'delivered'
        else false
    end;
    if not v_ok then
        raise exception 'An order cannot go from % to %', v_order.status, p_status;
    end if;
    if p_status = 'picked_up' and v_order.fulfilment = 'delivery' then
        raise exception 'A delivery is delivered, not picked up';
    end if;
    if p_status = 'delivered' and v_order.fulfilment = 'pickup' then
        raise exception 'A pickup is picked up, not delivered';
    end if;

    update orders
       set status     = p_status,
           updated_at = now(),
           decided_at = coalesce(decided_at, now())
     where id = p_order_id;

    v_booking := v_order.fulfilment = 'pickup'
        and exists (select 1 from order_lines l where l.order_id = p_order_id)
        and not exists (select 1 from order_lines l
                         where l.order_id = p_order_id and not l.is_service);

    begin
        insert into notifications (recipient_id, org_id, kind, message)
        select v_order.customer_id, v_order.org_id, 'order_' || p_status,
               case when v_booking then 'Votre réservation chez '
                    else 'Votre commande chez ' end
               || o.name || ' : '
               || case p_status
                    when 'accepted'  then 'acceptée'
                    when 'ready'     then 'prête'
                    when 'picked_up' then case when v_booking then 'terminée'
                                               else 'récupérée' end
                    when 'delivered' then 'livrée'
                    when 'refused'   then 'refusée'
                    else 'annulée' end
          from orgs o where o.id = v_order.org_id;
        -- A courier who already took the job hears about a cancellation.
        if p_status = 'cancelled' and v_order.courier_id is not null then
            insert into notifications (recipient_id, org_id, kind, message)
            values (v_order.courier_id, v_order.org_id, 'delivery_cancelled',
                    'La livraison pour ' || v_order.customer_name
                    || ' a été annulée par la boutique');
        end if;
    exception when others then
        null;
    end;
end;
$$;

-- ------------------------------------------------------------
-- 6. Grants (063: a new function is born closed to anon and PUBLIC)
-- ------------------------------------------------------------
-- vitrine_min is read only inside the SECURITY DEFINER functions above
-- (as their owner); no client calls it, so nobody else may.
revoke execute on function trg_service_no_stock()           from public;
revoke execute on function trg_service_not_stocked()        from public;
revoke execute on function trg_product_name_free()          from public;
revoke execute on function vitrine_min(uuid)                from public;
revoke execute on function storefront_products(text)        from public;
revoke execute on function ensure_product(uuid, text, numeric, numeric, text, date, uuid, boolean) from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function trg_service_no_stock()    from anon;
        revoke execute on function trg_service_not_stocked() from anon;
        revoke execute on function trg_product_name_free()   from anon;
        revoke execute on function vitrine_min(uuid)         from anon;
        revoke execute on function ensure_product(uuid, text, numeric, numeric, text, date, uuid, boolean) from anon;
        grant execute on function storefront_products(text)  to anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        revoke execute on function trg_service_no_stock()    from authenticated;
        revoke execute on function trg_service_not_stocked() from authenticated;
        revoke execute on function trg_product_name_free()   from authenticated;
        revoke execute on function vitrine_min(uuid)         from authenticated;
        grant execute on function ensure_product(uuid, text, numeric, numeric, text, date, uuid, boolean) to authenticated;
        grant execute on function storefront_products(text)  to authenticated;
    end if;
    if exists (select 1 from pg_roles where rolname = 'service_role') then
        grant execute on function ensure_product(uuid, text, numeric, numeric, text, date, uuid, boolean) to service_role;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 099_association_fixes.sql
-- ============================================================
-- ============================================================
-- 099_association_fixes.sql — an association's second business, and a
-- bell that says what it is about.
--
-- The owner, about associations: « Association will also have 2 business
-- locked, only accessible with pro », and « Make sure the notification
-- system covers the user needs. »
--
--   1. A second business needs Mara Pro, whatever the first one is.
--      089's door (trg_second_business_lock) counted owners of shops and
--      farms only, so the owner of a Free association could open a second
--      business freely. Now an owner of any business needs Pro on one they
--      own (Mara's own admins pass, as before). The rule is the person's,
--      so second_business_locked(user) says it once, for the door and for
--      path_locked(org, 'second_business') — which org_progress() hands to
--      the app's « 2e entreprise » row. It answers for the signed-in
--      caller: an employee who owns nothing is not shown a lock the door
--      would not hold (it was, under 089, for every member of a Free
--      shop), and an owner whose other business is Pro is not either.
--      With no caller (a server job) it answers for the business itself:
--      locked unless it is Pro, whatever its profile (nothing asks it so
--      today). Only that step changes for an association:
--      invoices, production and credits still answer false for it, so the
--      triggers of 089 (trg_path_lock), check_unlocks (096) and path_state
--      (097, which returns null for an association) are untouched.
--   2. The bell carries what it is about. notifications.params (jsonb)
--      holds the event's facts — which order, which customer, how much,
--      for whom (to: shop | customer | courier) — so the app opens the
--      right screen on a tap and writes the line in the phone's language.
--      message stays, in French, as before: the push Worker (060) sends it,
--      and it is what older rows and older apps read. Every function that
--      rings the bell is replaced from its latest definition with the same
--      words and its params beside them:
--        030 low stock, a member joined, a credit settled, a tontine ready;
--        098 place_order (a new order or demande), decide_order (each
--        status to the customer, a cancellation to the courier);
--        073 take_delivery, courier_deliver, courier_mark, courier_fail,
--        shop_deliver_self; 057 set_order_paid; 056 decide_courier;
--        071 decide_promotion; 075 register_device; 076 wave_settle;
--        082 stripe_settle; 086 cauris_board_notify, cauris_week_close;
--        096 check_unlocks.
--      The platform's own bells (a business application, a spot to
--      approve, a message the platform typed) stay French text: they are
--      written for Mara's admins, or typed by them.
--   3. A customer who cancels is heard. cancel_order (055) changed the
--      order and told nobody: the shop's or the association's admins now
--      hear « Awa a annulé sa commande » (or « sa demande », a booking).
--   4. Nobody may ring somebody else's bell. 063 granted EXECUTE on every
--      SECURITY DEFINER function to authenticated, notify_org_admins (030)
--      and notify_platform_spot (071) included: any signed-in person could
--      write any text to any business's admins, or to Mara's — and push
--      carries it to their phones. Both are internal: revoked from
--      authenticated (and anon and PUBLIC), like 060's push functions.
--
-- notify_org_admins gains a params argument as a new signature, the 4th
-- argument a jsonb: (org, kind, message, params, except). 030's
-- (org, kind, message, except) stays for any caller not yet passing
-- params, so a three-argument or named call is never ambiguous and the
-- bundle re-runs clean. A 4th POSITIONAL argument must be cast
-- (null::jsonb, '{}'::jsonb or null::uuid): uncast, it matches both.
--
-- Re-runnable (the bundle runs twice): a column if not exists, functions
-- replaced in place, no destructive statement.
-- ============================================================

-- ------------------------------------------------------------
-- 1. A second business: Pro on one already owned
-- ------------------------------------------------------------
-- The person's rule: a platform admin is never held; somebody who owns no
-- live business opens a first one freely (an archived one does not
-- count); an owner needs Pro on a live one they own.
create or replace function second_business_locked(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select not exists (select 1 from profiles
                        where id = p_user_id and is_platform_admin)
       and exists (select 1 from memberships m join orgs o on o.id = m.org_id
                    where m.user_id = p_user_id and m.role = 'owner'
                      and o.archived_at is null)
       and not exists (select 1 from memberships m join orgs o on o.id = m.org_id
                        where m.user_id = p_user_id and m.role = 'owner'
                          and o.archived_at is null
                          and org_plan(m.org_id) = 'pro');
$$;

-- 089's door, for every profile.
create or replace function trg_second_business_lock()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if second_business_locked(new.applicant_id) then
        raise exception '%', path_lock_message('second_business');
    end if;
    return new;
end;
$$;

-- 097's rule. Only the second_business branch moves: it is asked before
-- the profile, and for the caller. Every other step reads as in 097.
create or replace function path_locked(p_org_id uuid, p_step text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select case
        when p_step = 'second_business' then
            case when auth.uid() is null then org_plan(o.id) <> 'pro'
                 else second_business_locked(auth.uid()) end
        when o.profile not in ('retail', 'farm') then false
        when org_plan(o.id) = 'pro' then false
        when cauris_param('path_gates_open', 0) = 1 then false
        when p_step = 'invoices'
            then path_progress(o.id, 'articles') < path_goal(o.id, 'articles')
              or path_progress(o.id, 'photos')   < path_goal(o.id, 'photos')
        when p_step = 'production'
            then exists (select 1 from path_steps s
                          where s.stage = 2 and o.profile = any (s.profiles)
                            and path_progress(o.id, s.key) < path_goal(o.id, s.key))
        when p_step = 'credits'
            then path_progress(o.id, 'three_orders') < path_goal(o.id, 'three_orders')
        else false
    end
    from orgs o where o.id = p_org_id;
$$;

-- ------------------------------------------------------------
-- 2. The bell's facts
-- ------------------------------------------------------------
alter table notifications add column if not exists params jsonb;

comment on column notifications.params is
    'The event''s facts (099): ids, names, amounts and to (shop | customer | '
    'courier), for the app to open the right screen and say the line in the '
    'phone''s language. Null on rows written before 099 and on the '
    'platform''s own messages; message (French) is always there.';

-- The fan-out with the facts: the fourth argument is the params.
create or replace function notify_org_admins(
    p_org_id  uuid,
    p_kind    text,
    p_message text,
    p_params  jsonb,
    p_except  uuid default null
)
returns void
language sql
security definer
set search_path = public
as $$
    insert into notifications (recipient_id, org_id, kind, message, params)
    select distinct m.user_id, p_org_id, p_kind, p_message, p_params
      from memberships m
     where m.org_id = p_org_id
       and m.role in ('owner', 'super_admin', 'admin')
       and (p_except is null or m.user_id <> p_except);
$$;

-- 030: stock crossing below its threshold.
create or replace function trg_notify_low_stock()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
    if new.low_stock_at is not null
       and new.is_active
       and new.quantity <= new.low_stock_at
       and old.quantity > new.low_stock_at then
        perform notify_org_admins(new.org_id, 'low_stock',
            format('Stock bas : %s (%s restant)',
                   new.name, trim_scale(new.quantity)),
            jsonb_build_object('to', 'shop', 'product_id', new.id,
                               'name', new.name, 'quantity', trim_scale(new.quantity)));
    end if;
    return new;
exception when others then
    return new;
end;
$$;

-- 030: somebody joined the business.
create or replace function trg_notify_member_joined()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_who text;
    v_org text;
begin
    select coalesce(nullif(btrim(coalesce(full_name, '')), ''), 'Quelqu''un')
      into v_who from profiles where id = new.user_id;
    select name into v_org from orgs where id = new.org_id;
    perform notify_org_admins(new.org_id, 'member_joined',
        format('%s a rejoint %s', coalesce(v_who, 'Quelqu''un'),
               coalesce(v_org, 'votre activité')),
        jsonb_build_object('to', 'shop', 'who', v_who, 'org', v_org),
        p_except => new.user_id);
    return new;
exception when others then
    return new;
end;
$$;

-- 030: a credit fully repaid.
create or replace function trg_notify_debt_settled()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_debt debts%rowtype;
    v_paid numeric;
    v_customer text;
begin
    select * into v_debt from debts where id = new.debt_id;
    select coalesce(sum(amount), 0) into v_paid
      from debt_payments where debt_id = new.debt_id;
    if v_paid >= v_debt.amount then
        select name into v_customer from customers where id = v_debt.customer_id;
        perform notify_org_admins(v_debt.org_id, 'debt_settled',
            format('Crédit soldé : %s a fini de payer %s',
                   coalesce(v_customer, 'un client'),
                   trim_scale(v_debt.amount)),
            jsonb_build_object('to', 'shop', 'customer_id', v_debt.customer_id,
                               'customer', v_customer,
                               'amount', trim_scale(v_debt.amount),
                               'currency', (select default_currency from orgs
                                             where id = v_debt.org_id)));
    end if;
    return new;
exception when others then
    return new;
end;
$$;

-- 030: a tontine round where everyone has paid.
create or replace function trg_notify_tontine_ready()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
    v_t tontines%rowtype;
    v_members int;
    v_paid int;
begin
    select * into v_t from tontines where id = new.tontine_id;
    if new.round <> v_t.current_round then
        return new;
    end if;
    select count(*) into v_members
      from tontine_members where tontine_id = new.tontine_id;
    select count(*) into v_paid
      from tontine_contributions
     where tontine_id = new.tontine_id and round = v_t.current_round;
    if v_members > 0 and v_paid >= v_members then
        perform notify_org_admins(v_t.org_id, 'tontine_ready',
            format('Tontine %s : tour %s prêt à clore, tout le monde a payé',
                   v_t.name, v_t.current_round),
            jsonb_build_object('to', 'shop', 'tontine_id', v_t.id,
                               'name', v_t.name, 'round', v_t.current_round));
    end if;
    return new;
exception when others then
    return new;
end;
$$;

-- 098: an order (or, all services, a demande) placed from the vitrine.
create or replace function place_order(
    p_slug       text,
    p_lines      jsonb,
    p_fulfilment text default 'pickup',
    p_note       text default null,
    p_address    text default null,
    p_phone      text default null,
    p_payment    text default 'cash',
    p_drop_lat   double precision default null,
    p_drop_lng   double precision default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
    v_org      uuid;
    v_id       uuid;
    v_line     jsonb;
    v_product  products%rowtype;
    v_qty      numeric;
    v_total    numeric := 0;
    v_name     text;
    v_phone    text;
    v_currency text;
    v_wave     text;
    v_fee      numeric;
    v_address  text := nullif(btrim(coalesce(p_address, '')), '');
    v_note     text := nullif(btrim(coalesce(p_note, '')), '');
    v_services boolean;
begin
    if auth.uid() is null then
        raise exception 'Sign in to order';
    end if;
    v_org := storefront_open(p_slug);
    if v_org is null then
        raise exception 'This shop is not taking orders';
    end if;
    if p_fulfilment not in ('pickup', 'delivery') then
        raise exception 'Unknown fulfilment: %', p_fulfilment;
    end if;
    if p_lines is null or jsonb_typeof(p_lines) <> 'array'
       or jsonb_array_length(p_lines) = 0 then
        raise exception 'An order needs at least one article';
    end if;

    -- Services only: an appointment, not a parcel. Said before the
    -- delivery rules, so the customer hears the reason that applies.
    select coalesce(bool_and(coalesce(p.is_service, false)), false)
      into v_services
      from jsonb_array_elements(p_lines) l
      left join products p
        on p.id = nullif(l ->> 'product_id', '')::uuid and p.org_id = v_org;
    if v_services then
        if p_fulfilment <> 'pickup' then
            raise exception 'Un service se réserve sur rendez-vous : pas de livraison';
        end if;
        if v_note is null then
            raise exception 'Indiquez la date et l''heure souhaitées';
        end if;
    end if;

    if p_fulfilment = 'delivery' and v_address is null then
        raise exception 'A delivery needs an address';
    end if;
    if (p_drop_lat is null) <> (p_drop_lng is null) then
        raise exception 'A delivery pin needs both a latitude and a longitude';
    end if;
    if p_payment not in ('cash', 'wave') then
        raise exception 'Unknown payment method: %', p_payment;
    end if;
    select wave_merchant, default_currency into v_wave, v_currency
      from orgs where id = v_org;
    if p_payment = 'wave' and v_wave is null then
        raise exception 'This shop does not take Wave';
    end if;

    select coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''),
                    nullif(btrim(coalesce(full_name, '')), ''),
                    'Client'),
           phone
      into v_name, v_phone
      from profiles where id = auth.uid();

    -- The fee is fixed now, from the pin the customer gave: a rate
    -- changed tomorrow does not change what was agreed today.
    if p_fulfilment = 'delivery' then
        v_fee := delivery_fee(v_org, p_drop_lat, p_drop_lng);
    end if;

    insert into orders (org_id, customer_id, customer_name, phone,
                        fulfilment, note, address, currency, payment_method,
                        drop_lat, drop_lng, delivery_fee)
    values (v_org, auth.uid(), v_name,
            coalesce(nullif(btrim(coalesce(p_phone, '')), ''), v_phone),
            p_fulfilment,
            v_note,
            v_address,
            coalesce(v_currency, 'XOF'),
            p_payment,
            case when p_fulfilment = 'delivery' then p_drop_lat end,
            case when p_fulfilment = 'delivery' then p_drop_lng end,
            v_fee)
    returning id into v_id;

    for v_line in select * from jsonb_array_elements(p_lines) loop
        v_qty := (v_line->>'quantity')::numeric;
        if v_qty is null or v_qty <= 0 then
            raise exception 'A quantity must be positive';
        end if;
        select * into v_product
          from products
         where id = (v_line->>'product_id')::uuid
           and org_id = v_org
           and is_active
           and is_published;
        if not found then
            raise exception 'An article is not in this shop''s window';
        end if;
        insert into order_lines (order_id, product_id, name, unit_price, quantity, is_service)
        values (v_id, v_product.id, v_product.name,
                coalesce(v_product.sale_price, 0), v_qty, v_product.is_service);
        v_total := v_total + coalesce(v_product.sale_price, 0) * v_qty;
    end loop;

    update orders set total = v_total where id = v_id;

    begin
        perform notify_org_admins(
            v_org, 'new_order',
            case when v_services then 'Nouvelle demande de ' else 'Nouvelle commande de ' end
            || v_name || ' : '
            || to_char(v_total, 'FM999G999G999D00') || ' '
            || coalesce(v_currency, 'XOF')
            || case when p_payment = 'wave' then ' (Wave)' else '' end
            || case when v_fee is not null
                    then ' + livraison ' || to_char(v_fee, 'FM999G999G999') else '' end,
            jsonb_build_object('to', 'shop', 'order_id', v_id, 'booking', v_services,
                               'name', v_name, 'total', v_total,
                               'currency', coalesce(v_currency, 'XOF'),
                               'wave', p_payment = 'wave', 'fee', v_fee));
    exception when others then
        null;
    end;

    return v_id;
end;
$$;

-- 055: the customer changes their mind — and now the business hears it.
create or replace function cancel_order(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_order   orders%rowtype;
    v_booking boolean;
begin
    if auth.uid() is null then
        raise exception 'Sign in first';
    end if;
    update orders
       set status = 'cancelled', updated_at = now(), decided_at = now()
     where id = p_order_id
       and customer_id = auth.uid()
       and status = 'pending'
    returning * into v_order;
    if not found then
        raise exception 'This order can no longer be cancelled';
    end if;
    v_booking := v_order.fulfilment = 'pickup'
        and exists (select 1 from order_lines l where l.order_id = p_order_id)
        and not exists (select 1 from order_lines l
                         where l.order_id = p_order_id and not l.is_service);
    begin
        perform notify_org_admins(v_order.org_id, 'order_withdrawn',
            v_order.customer_name || ' a annulé sa '
            || case when v_booking then 'demande' else 'commande' end,
            jsonb_build_object('to', 'shop', 'order_id', v_order.id,
                               'booking', v_booking, 'name', v_order.customer_name));
    exception when others then
        null;
    end;
end;
$$;

-- 098: the shop answers; the customer hears each status.
create or replace function decide_order(p_order_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_order   orders%rowtype;
    v_ok      boolean;
    v_booking boolean;
begin
    select * into v_order from orders where id = p_order_id;
    if not found then
        raise exception 'No such order';
    end if;
    if not can_write_org(v_order.org_id) then
        raise exception 'Only the shop can answer its orders';
    end if;

    v_ok := case v_order.status
        when 'pending'    then p_status in ('accepted', 'refused')
        when 'accepted'   then p_status in ('ready', 'picked_up', 'delivered', 'cancelled')
        when 'ready'      then p_status in ('picked_up', 'delivered', 'cancelled')
        -- Once the parcel is on a motorbike the shop can only confirm the
        -- end of the journey, not rewrite it.
        when 'in_transit' then p_status = 'delivered'
        else false
    end;
    if not v_ok then
        raise exception 'An order cannot go from % to %', v_order.status, p_status;
    end if;
    if p_status = 'picked_up' and v_order.fulfilment = 'delivery' then
        raise exception 'A delivery is delivered, not picked up';
    end if;
    if p_status = 'delivered' and v_order.fulfilment = 'pickup' then
        raise exception 'A pickup is picked up, not delivered';
    end if;

    update orders
       set status     = p_status,
           updated_at = now(),
           decided_at = coalesce(decided_at, now())
     where id = p_order_id;

    v_booking := v_order.fulfilment = 'pickup'
        and exists (select 1 from order_lines l where l.order_id = p_order_id)
        and not exists (select 1 from order_lines l
                         where l.order_id = p_order_id and not l.is_service);

    begin
        insert into notifications (recipient_id, org_id, kind, message, params)
        select v_order.customer_id, v_order.org_id, 'order_' || p_status,
               case when v_booking then 'Votre réservation chez '
                    else 'Votre commande chez ' end
               || o.name || ' : '
               || case p_status
                    when 'accepted'  then 'acceptée'
                    when 'ready'     then 'prête'
                    when 'picked_up' then case when v_booking then 'terminée'
                                               else 'récupérée' end
                    when 'delivered' then 'livrée'
                    when 'refused'   then 'refusée'
                    else 'annulée' end,
               jsonb_build_object('to', 'customer', 'order_id', v_order.id,
                                  'booking', v_booking, 'shop', o.name,
                                  'status', p_status)
          from orgs o where o.id = v_order.org_id;
        -- A courier who already took the job hears about a cancellation.
        if p_status = 'cancelled' and v_order.courier_id is not null then
            insert into notifications (recipient_id, org_id, kind, message, params)
            values (v_order.courier_id, v_order.org_id, 'delivery_cancelled',
                    'La livraison pour ' || v_order.customer_name
                    || ' a été annulée par la boutique',
                    jsonb_build_object('to', 'courier', 'order_id', v_order.id,
                                       'name', v_order.customer_name));
        end if;
    exception when others then
        null;
    end;
end;
$$;

-- 056: the platform decides who carries; the courier hears it.
create or replace function decide_courier(p_user_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
    if not exists (select 1 from profiles
                    where id = auth.uid() and is_platform_admin) then
        raise exception 'Only the platform decides who carries';
    end if;
    if p_status not in ('approved', 'suspended', 'pending') then
        raise exception 'Unknown courier status: %', p_status;
    end if;
    update couriers
       set status = p_status, decided_at = now()
     where user_id = p_user_id;
    if not found then
        raise exception 'No such courier';
    end if;
    -- Their bell rings; a failed bell never fails the decision.
    begin
        insert into notifications (recipient_id, kind, message, params)
        values (p_user_id, 'courier_' || p_status,
                case p_status
                    when 'approved' then
                        'Vous êtes livreur Kaj : les livraisons vous attendent.'
                    when 'suspended' then
                        'Votre accès livreur est suspendu.'
                    else 'Votre inscription livreur est à l''étude.' end,
                jsonb_build_object('to', 'courier', 'status', p_status));
    exception when others then
        null;
    end;
end;
$$;

-- 073: a courier takes the job.
create or replace function take_delivery(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare v_order orders%rowtype; v_shop text;
begin
    perform assert_approved_courier();
    if not courier_may_take(p_order_id, auth.uid()) then
        raise exception 'Cette boutique a ses livreurs : la course s''ouvre à tous dans quelques minutes';
    end if;
    update orders
       set courier_id = auth.uid(), updated_at = now()
     where id = p_order_id
       and status = 'ready'
       and fulfilment = 'delivery'
       and courier_id is null
    returning * into v_order;
    if not found then
        raise exception 'This delivery is no longer available';
    end if;
    select name into v_shop from orgs where id = v_order.org_id;
    begin
        perform notify_org_admins(v_order.org_id, 'delivery_taken',
            'Un livreur prend la commande de ' || v_order.customer_name,
            jsonb_build_object('to', 'shop', 'order_id', v_order.id,
                               'name', v_order.customer_name));
        insert into notifications (recipient_id, org_id, kind, message, params)
        values (v_order.customer_id, v_order.org_id, 'order_courier',
                'Un livreur s''occupe de votre commande chez ' || v_shop,
                jsonb_build_object('to', 'customer', 'order_id', v_order.id,
                                   'shop', v_shop));
    exception when others then
        null;
    end;
end;
$$;

-- 073: the door, with the code.
create or replace function courier_deliver(p_order_id uuid, p_code text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v orders%rowtype; v_shop text;
begin
    select * into v from orders where id = p_order_id;
    if not found or v.courier_id is distinct from auth.uid() then
        raise exception 'Cette livraison n''est pas la vôtre';
    end if;
    if v.status <> 'in_transit' then
        raise exception 'Cette livraison n''est pas en route';
    end if;
    if v.handover_code is not null
       and btrim(coalesce(p_code, '')) <> v.handover_code then
        raise exception 'Code incorrect : demandez au client les 4 chiffres de sa commande';
    end if;
    update orders set status = 'delivered', updated_at = now() where id = p_order_id;
    select name into v_shop from orgs where id = v.org_id;
    begin
        insert into notifications (recipient_id, org_id, kind, message, params)
        values (v.customer_id, v.org_id, 'order_delivered',
                'Votre commande chez ' || v_shop || ' est livrée',
                jsonb_build_object('to', 'customer', 'order_id', v.id, 'shop', v_shop));
        perform notify_org_admins(v.org_id, 'order_delivered',
            'La commande de ' || v.customer_name || ' est livrée',
            jsonb_build_object('to', 'shop', 'order_id', v.id, 'name', v.customer_name));
    exception when others then null;
    end;
end;
$$;

-- 073: the road is one tap; the door needs the code (courier_deliver).
create or replace function courier_mark(p_order_id uuid, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare v_order orders%rowtype; v_shop text;
begin
    select * into v_order from orders where id = p_order_id;
    if not found or v_order.courier_id is distinct from auth.uid() then
        raise exception 'This delivery is not yours';
    end if;
    if p_status = 'delivered' then
        if v_order.status <> 'in_transit' then
            raise exception 'A delivery cannot go from % to %', v_order.status, p_status;
        end if;
        if v_order.handover_code is not null then
            raise exception 'Demandez au client le code de sa commande pour la clore';
        end if;
        perform courier_deliver(p_order_id, null);
        return;
    end if;
    if not (v_order.status = 'ready' and p_status = 'in_transit') then
        raise exception 'A delivery cannot go from % to %', v_order.status, p_status;
    end if;
    update orders set status = p_status, updated_at = now() where id = p_order_id;
    select name into v_shop from orgs where id = v_order.org_id;
    begin
        insert into notifications (recipient_id, org_id, kind, message, params)
        values (v_order.customer_id, v_order.org_id, 'order_in_transit',
                'Votre commande chez ' || v_shop || ' est en route',
                jsonb_build_object('to', 'customer', 'order_id', v_order.id,
                                   'shop', v_shop, 'self', false));
    exception when others then null;
    end;
end;
$$;

-- 073: when the door does not open.
create or replace function courier_fail(p_order_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v orders%rowtype; v_shop text; v_words text;
begin
    select * into v from orders where id = p_order_id;
    if not found or v.courier_id is distinct from auth.uid() then
        raise exception 'Cette livraison n''est pas la vôtre';
    end if;
    if v.status <> 'in_transit' then
        raise exception 'Seule une livraison en route peut échouer';
    end if;
    if p_reason not in ('absent', 'refused', 'unreachable', 'other') then
        raise exception 'Raison inconnue : %', p_reason;
    end if;
    v_words := case p_reason
        when 'absent'      then 'client absent'
        when 'refused'     then 'refusée par le client'
        when 'unreachable' then 'client injoignable'
        else 'autre raison' end;
    update orders set status = 'cancelled', outcome = p_reason, updated_at = now()
     where id = p_order_id;
    select name into v_shop from orgs where id = v.org_id;
    begin
        perform notify_org_admins(v.org_id, 'delivery_failed',
            'Livraison de ' || v.customer_name || ' échouée (' || v_words
            || ') : le livreur rapporte la commande.',
            jsonb_build_object('to', 'shop', 'order_id', v.id,
                               'name', v.customer_name, 'reason', p_reason));
        insert into notifications (recipient_id, org_id, kind, message, params)
        values (v.customer_id, v.org_id, 'delivery_failed',
                'La livraison de votre commande chez ' || v_shop
                || ' n''a pas pu se faire (' || v_words || ').',
                jsonb_build_object('to', 'customer', 'order_id', v.id,
                                   'shop', v_shop, 'reason', p_reason));
    exception when others then null;
    end;
end;
$$;

-- 073: « Je livre moi-même ».
create or replace function shop_deliver_self(p_order_id uuid)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare v orders%rowtype; v_shop text;
begin
    select * into v from orders where id = p_order_id;
    if not found or not can_write_org(v.org_id) then
        raise exception 'Seule la boutique livre ses commandes';
    end if;
    if v.fulfilment <> 'delivery' or v.status not in ('accepted', 'ready')
       or v.courier_id is not null then
        raise exception 'Cette commande a déjà un livreur, ou n''est pas à livrer';
    end if;
    update orders
       set status = 'in_transit', self_delivered = true, platform_fee = 0,
           updated_at = now()
     where id = p_order_id;
    select name into v_shop from orgs where id = v.org_id;
    begin
        insert into notifications (recipient_id, org_id, kind, message, params)
        values (v.customer_id, v.org_id, 'order_in_transit',
                v_shop || ' vous livre lui-même : votre commande est en route',
                jsonb_build_object('to', 'customer', 'order_id', v.id,
                                   'shop', v_shop, 'self', true));
    exception when others then null;
    end;
end;
$$;

-- 057: the shop says it was paid; the customer hears it.
create or replace function set_order_paid(p_order_id uuid, p_paid boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare v_order orders%rowtype;
begin
    select * into v_order from orders where id = p_order_id;
    if not found then
        raise exception 'No such order';
    end if;
    if not can_write_org(v_order.org_id) then
        raise exception 'Only the shop says what was paid';
    end if;
    update orders
       set paid_at = case when p_paid then coalesce(paid_at, now()) end,
           updated_at = now()
     where id = p_order_id;
    if p_paid and v_order.paid_at is null then
        begin
            insert into notifications (recipient_id, org_id, kind, message, params)
            select v_order.customer_id, v_order.org_id, 'order_paid',
                   'Votre paiement chez ' || o.name || ' est confirmé',
                   jsonb_build_object('to', 'customer', 'order_id', v_order.id,
                                      'shop', o.name, 'wave', false)
              from orgs o where o.id = v_order.org_id;
        exception when others then
            null;
        end;
    end if;
end;
$$;

-- 071: the platform answers a spot.
create or replace function decide_promotion(p_promotion_id uuid, p_approve boolean)
returns void
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v promotions%rowtype;
    v_start timestamptz;
begin
    if not exists (select 1 from profiles
                    where id = auth.uid() and is_platform_admin) then
        raise exception 'Seule la plateforme valide une mise en avant';
    end if;
    select * into v from promotions where id = p_promotion_id;
    if not found or v.status not in ('requested', 'paid_claimed') then
        raise exception 'Cette demande n''est plus en attente';
    end if;
    if p_approve then
        v_start := next_spot_start(v.kind);
        update promotions
           set status = 'approved', starts_at = v_start,
               ends_at = v_start + make_interval(days => v.days),
               decided_by = auth.uid(), decided_at = now()
         where id = p_promotion_id;
    else
        update promotions
           set status = 'refused', decided_by = auth.uid(), decided_at = now()
         where id = p_promotion_id;
    end if;
    begin
        perform notify_org_admins(v.org_id, 'spot_' || case when p_approve then 'approved' else 'refused' end,
            case when p_approve
                 then 'Votre mise en avant est validée : elle commence le '
                      || to_char(v_start at time zone 'Africa/Ouagadougou', 'DD/MM à HH24:MI') || '.'
                 else 'Votre demande de mise en avant n''a pas été retenue.' end,
            jsonb_build_object('to', 'shop', 'promotion_id', v.id,
                               'starts_at', v_start, 'wave', false));
    exception when others then null;
    end;
end;
$$;

-- 075: a new device on the account.
create or replace function register_device(p_device_id text, p_label text)
returns boolean
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_me    uuid := auth.uid();
    v_label text := left(coalesce(nullif(btrim(p_label), ''), 'Appareil'), 80);
    v_new   boolean;
    v_had   boolean;
begin
    if v_me is null then
        raise exception 'register_device() needs a signed-in caller';
    end if;
    select exists (select 1 from user_devices where user_id = v_me) into v_had;
    insert into user_devices (user_id, device_id, label)
    values (v_me, p_device_id, v_label)
    on conflict (user_id, device_id)
    do update set last_seen = now(), label = excluded.label
    returning (xmax = 0) into v_new;
    if v_new then
        perform security_log(v_me, 'new_device', v_label);
        if v_had then
            begin
                insert into notifications (recipient_id, org_id, kind, message, params)
                values (v_me, null, 'new_device',
                        'Nouvelle connexion à votre compte sur ' || v_label
                        || '. Ce n''était pas vous ? Ouvrez Compte › Sécurité '
                        || 'et fermez les autres appareils.',
                        jsonb_build_object('device', v_label));
            exception when others then null;
            end;
        end if;
    end if;
    return v_new;
end;
$$;

-- 076: Wave says a session ended.
create or replace function wave_settle(
    p_client_reference uuid,
    p_session_id       text,
    p_succeeded        boolean,
    p_transaction_id   text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v     wave_payments%rowtype;
    v_org orgs%rowtype;
    v_start timestamptz;
    v_until date;
begin
    select * into v from wave_payments where id = p_client_reference for update;
    if not found then
        return null;
    end if;
    if v.session_id is not null and p_session_id is not null and v.session_id <> p_session_id then
        return null;
    end if;
    if v.status = 'succeeded' then
        return null;  -- delivered twice
    end if;
    if not p_succeeded then
        update wave_payments set status = 'failed' where id = v.id;
        return null;
    end if;

    update wave_payments
       set status = 'succeeded', paid_at = now(),
           transaction_id = p_transaction_id,
           session_id = coalesce(session_id, p_session_id)
     where id = v.id;
    select * into v_org from orgs where id = v.org_id;

    if v.kind = 'order' then
        update orders set paid_at = coalesce(paid_at, now()), payment_method = 'wave'
         where id = v.order_id;
        update wave_payments
           set payout_status = 'pending',
               payout_to = v_org.wave_payout_number,
               payout_amount = v.amount - v.commission
         where id = v.id;
        begin
            perform notify_org_admins(v.org_id, 'order_paid',
                'Commande payée par Wave : ' || to_char(v.amount, 'FM999G999G999')
                || ' F. L''argent part sur votre numéro Wave.',
                jsonb_build_object('to', 'shop', 'order_id', v.order_id,
                                   'amount', v.amount, 'currency', v.currency,
                                   'wave', true));
            insert into notifications (recipient_id, org_id, kind, message, params)
            select o.customer_id, o.org_id, 'order_paid',
                   'Paiement reçu par ' || v_org.name || ' : merci !',
                   jsonb_build_object('to', 'customer', 'order_id', o.id,
                                      'shop', v_org.name, 'wave', true)
              from orders o where o.id = v.order_id;
        exception when others then null;
        end;
        return jsonb_build_object(
            'payment_id', v.id,
            'amount', v.amount - v.commission,
            'currency', v.currency,
            'mobile', v_org.wave_payout_number,
            'name', v_org.name);
    elsif v.kind = 'pro' then
        v_until := greatest(coalesce(case when v_org.plan = 'pro' then v_org.plan_until end,
                                     current_date), current_date)
                   + case when v.period = 'year' then interval '1 year' else interval '1 month' end;
        update orgs set plan = 'pro', plan_until = v_until,
                        plan_note = 'Wave ' || coalesce(p_transaction_id, '')
         where id = v.org_id;
        insert into plan_requests (org_id, user_id, amount, note, handled_at)
        values (v.org_id, v.payer_id, v.amount, 'Payé par Wave', now());
        begin
            perform notify_org_admins(v.org_id, 'pro_active',
                'Kaj Pro est actif jusqu''au ' || to_char(v_until, 'DD/MM/YYYY') || '.',
                jsonb_build_object('to', 'shop', 'until', v_until, 'card', false));
        exception when others then null;
        end;
    elsif v.kind = 'spot' then
        v_start := next_spot_start('article');
        update promotions
           set status = 'approved',
               starts_at = case when kind = 'shop' then now() else v_start end,
               ends_at = case when kind = 'shop' then now() else v_start end
                         + make_interval(days => days),
               decided_at = now(),
               note = 'Payé par Wave'
         where id = v.promotion_id and status in ('requested', 'paid_claimed');
        begin
            perform notify_org_admins(v.org_id, 'spot_approved',
                'Mise en avant payée par Wave : elle est programmée.',
                jsonb_build_object('to', 'shop', 'promotion_id', v.promotion_id,
                                   'wave', true));
        exception when others then null;
        end;
    end if;
    return null;
end;
$$;

-- 082: Stripe says a subscription moved.
create or replace function stripe_settle(
    p_org_id          uuid,
    p_subscription_id text,
    p_customer_id     text,
    p_status          text,
    p_period          text,
    p_period_end      timestamptz,
    p_cancel_at_end   boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_was  text;
    v_org  orgs%rowtype;
    v_until date;
    v_active boolean := p_status in ('active', 'trialing');
begin
    select * into v_org from orgs where id = p_org_id;
    if not found then
        return jsonb_build_object('ok', false, 'reason', 'no such business');
    end if;
    select status into v_was from stripe_subscriptions where org_id = p_org_id;

    insert into stripe_subscriptions (org_id, customer_id, subscription_id, status,
                                      period, current_period_end, cancel_at_period_end,
                                      updated_at)
    values (p_org_id, p_customer_id, p_subscription_id, p_status,
            case when p_period in ('month', 'year') then p_period end,
            p_period_end, coalesce(p_cancel_at_end, false), now())
    on conflict (org_id) do update set
        customer_id          = coalesce(excluded.customer_id, stripe_subscriptions.customer_id),
        subscription_id      = coalesce(excluded.subscription_id, stripe_subscriptions.subscription_id),
        status               = excluded.status,
        period               = coalesce(excluded.period, stripe_subscriptions.period),
        current_period_end   = coalesce(excluded.current_period_end,
                                        stripe_subscriptions.current_period_end),
        cancel_at_period_end = excluded.cancel_at_period_end,
        updated_at           = now();

    if v_active and p_period_end is not null then
        v_until := (p_period_end at time zone 'Africa/Ouagadougou')::date + 1;
        -- Never shorter than what the business already has: a later date
        -- paid by Wave stays, and a Pro with no end (a gift) keeps none.
        update orgs
           set plan_until = case
                   when plan = 'pro' and plan_until is null then null
                   when plan = 'pro' then greatest(plan_until, v_until)
                   else v_until end,
               plan = 'pro',
               plan_note = 'Stripe ' || coalesce(p_subscription_id, '')
         where id = p_org_id;
        if v_was is distinct from p_status and v_was is distinct from 'active' then
            begin
                perform notify_org_admins(p_org_id, 'pro_active',
                    'Kaj Pro est actif, payé par carte, jusqu''au '
                    || to_char(v_until, 'DD/MM/YYYY') || '.',
                    jsonb_build_object('to', 'shop', 'until', v_until, 'card', true));
            exception when others then null;
            end;
        end if;
    end if;
    return jsonb_build_object('ok', true, 'active', v_active, 'until', v_until);
end;
$$;

-- 086: the board, four times a week.
create or replace function cauris_board_notify()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
    v_from timestamptz := cauris_week_start();
    v_n    int := 0;
    r      record;
    v_top  text;
    v_top_j jsonb;
    v_me   record;
    v_gap  int;
begin
    create temporary table if not exists _all (
        org_id uuid, name text, hidden boolean, league text, score int, rank int) on commit drop;
    truncate _all;
    insert into _all
    select s.org_id, s.name, s.hidden, s.league, s.score,
           (rank() over (partition by s.league order by s.score desc, s.name))::int
      from league_scores(v_from, now()) s;

    for r in select a.* from _all a join orgs o on o.id = a.org_id where o.board_notify loop
        select string_agg(t.rank || '. ' ||
                   case when t.hidden then 'une ' ||
                        case when split_part(r.league, '|', 1) = 'farm' then 'ferme' else 'boutique' end
                        else t.name end
                   || ' ' || t.score, ' · ' order by t.rank, t.name),
               jsonb_agg(jsonb_build_object(
                   'rank', t.rank,
                   'name', case when t.hidden then null else t.name end,
                   'score', t.score) order by t.rank, t.name)
          into v_top, v_top_j
          from (select * from _all where league = r.league and score > 0
                 order by rank, name limit 3) t;
        if v_top is null then
            continue;  -- nobody has earned yet in this league this week
        end if;
        select min(score) into v_gap from _all
         where league = r.league and score > r.score;
        perform notify_org_admins(r.org_id, 'cauris_board',
            '🏆 ' || league_label(r.league) || ' : ' || v_top || '. '
            || case
                 when r.rank = 1 and r.score > 0 then 'Vous êtes 1er, bravo ! Gardez la tête.'
                 when v_gap is not null then 'Vous êtes ' || r.rank || 'e : encore '
                      || (v_gap - r.score + 1) || ' cauris pour la place devant.'
                 else 'Vous êtes ' || r.rank || 'e.'
               end,
            jsonb_build_object('to', 'shop', 'league', r.league, 'top', v_top_j,
                               'rank', r.rank, 'score', r.score,
                               'first', r.rank = 1 and r.score > 0,
                               'gap', case when v_gap is not null
                                           then v_gap - r.score + 1 end));
        v_n := v_n + 1;
    end loop;
    return v_n;
end;
$$;

-- 086: the week's close and its prizes.
create or replace function cauris_week_close(p_week_start date default null)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
    v_from timestamptz := coalesce(p_week_start::timestamp at time zone 'Africa/Ouagadougou',
                                   cauris_week_start() - interval '7 days');
    v_to   timestamptz := v_from + interval '7 days';
    v_week date := (v_from at time zone 'Africa/Ouagadougou')::date;
    v_n    int := 0;
    r      record;
    v_pts  int;
begin
    for r in
        select x.* from (
            select s.org_id, s.league, s.score,
                   (rank() over (partition by s.league order by s.score desc, s.name))::int as rank
              from league_scores(v_from, v_to) s
             where s.score > 0
        ) x where x.rank <= 3
    loop
        insert into cauris_week_results (week_start, org_id, league, rank, score)
        values (v_week, r.org_id, r.league, r.rank, r.score)
        on conflict (week_start, org_id) do nothing;
        if not found then
            continue;  -- already closed: once per week
        end if;
        v_pts := cauris_param('cauris_prize_' || r.rank, 0);
        if v_pts > 0 then
            insert into cauris_ledger (org_id, delta, reason, ref, note)
            values (r.org_id, v_pts, 'prize', v_week::text,
                    r.rank || 'e de la semaine · ' || league_label(r.league))
            on conflict do nothing;
        end if;
        if r.rank = 1 then
            insert into promotions (org_id, kind, days, price, currency, free, status,
                                    starts_at, ends_at, decided_at, note)
            values (r.org_id, 'shop', 7, 0, 'XOF', true, 'approved',
                    next_spot_start('shop'), next_spot_start('shop') + interval '7 days',
                    now(), 'Premier de la semaine (cauris)');
        end if;
        begin
            perform notify_org_admins(r.org_id, 'cauris_prize',
                '🏆 ' || r.rank || 'e de la semaine en ' || league_label(r.league)
                || ' ! +' || v_pts || ' cauris'
                || case when r.rank = 1 then ', et votre vitrine mise en avant 7 jours.' else '.' end,
                jsonb_build_object('to', 'shop', 'league', r.league, 'rank', r.rank,
                                   'points', v_pts, 'spot', r.rank = 1));
        exception when others then null;
        end;
        v_n := v_n + 1;
    end loop;
    return v_n;
end;
$$;

-- 096: the steps open now and not before, recorded and told.
create or replace function check_unlocks(p_org_id uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
    v_profile text;
    v_step    text;
    v_made    integer := 0;
begin
    select o.profile::text into v_profile from orgs o where o.id = p_org_id;
    if v_profile is null or v_profile not in ('retail', 'farm')
       or org_plan(p_org_id) = 'pro' then
        return 0;
    end if;
    -- All three already open: one index lookup, the common case.
    if (select count(*) from org_unlocks u where u.org_id = p_org_id) >= 3 then
        return 0;
    end if;
    foreach v_step in array array['invoices', 'production', 'credits'] loop
        if not exists (select 1 from org_unlocks u
                        where u.org_id = p_org_id and u.step = v_step)
           and not path_locked(p_org_id, v_step) then
            insert into org_unlocks (org_id, step) values (p_org_id, v_step)
                on conflict do nothing;
            if found then
                v_made := v_made + 1;
                perform notify_org_admins(p_org_id, 'unlock', unlock_message(v_step),
                    jsonb_build_object('to', 'shop', 'step', v_step,
                                       'articles', path_goal(null, 'articles'),
                                       'photos', path_goal(null, 'photos'),
                                       'orders', path_goal(null, 'three_orders')));
            end if;
        end if;
    end loop;
    return v_made;
end;
$$;

-- ------------------------------------------------------------
-- 3. Grants (063: a new function is born closed to anon and PUBLIC, and
--    open to authenticated — which these must not be)
-- ------------------------------------------------------------
revoke execute on function second_business_locked(uuid)                    from public;
revoke execute on function notify_org_admins(uuid, text, text, jsonb, uuid) from public;
revoke execute on function notify_org_admins(uuid, text, text, uuid)        from public;
revoke execute on function notify_platform_spot(text, text)                 from public;

do $$
begin
    if exists (select 1 from pg_roles where rolname = 'anon') then
        revoke execute on function second_business_locked(uuid)                    from anon;
        revoke execute on function notify_org_admins(uuid, text, text, jsonb, uuid) from anon;
        revoke execute on function notify_org_admins(uuid, text, text, uuid)        from anon;
        revoke execute on function notify_platform_spot(text, text)                 from anon;
    end if;
    if exists (select 1 from pg_roles where rolname = 'authenticated') then
        -- Read inside path_locked and the door, as their owner.
        revoke execute on function second_business_locked(uuid)                    from authenticated;
        -- Rung by the server's own functions only: nobody writes to another
        -- person's bell, or to their phone.
        revoke execute on function notify_org_admins(uuid, text, text, jsonb, uuid) from authenticated;
        revoke execute on function notify_org_admins(uuid, text, text, uuid)        from authenticated;
        revoke execute on function notify_platform_spot(text, text)                 from authenticated;
    end if;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- 100_team_photos_gifts.sql
-- ============================================================
-- ============================================================
-- 100_team_photos_gifts.sql — the team in one place, a worker earned,
-- photos counted, cauris an association can spend, the platform's gifts,
-- the owner's name on the picker, and the stock rules audited.
--
-- The owner's requests, and what each does here, for shops (retail),
-- farms and associations (association, and the legacy church):
--
--   1. « Équipe »: the owner sees their people and records each one's
--      salary (an amount and a period: par mois, par semaine, par jour;
--      optional). There was a place for it: employees (012), the payroll's
--      own row, which can already point at an account (user_id, 018). So
--      set_member_salary(org, user, amount, period) writes the salary on
--      that person's employees row — finding it by the account, or by the
--      name of an unlinked one, or adding it as a permanent's — and
--      employees.pay_period says per what. The payroll reads the period: a
--      permanent's salary is what one payment pays (a month's, a week's, a
--      day's) and « Paie et journées » says « / mois », « / semaine »,
--      « / jour ». A row's kind is never changed (somebody paid by the hour
--      keeps their rate, changed in the payroll), and clearing a salary
--      touches the amount only — an ended employment stays ended. Recording
--      is free; PAYING (shifts, staff_payments) keeps 066's Pro guard.
--      team_overview(org) is what the screen reads: the seats, the people
--      with their pay and their grants (to remove one), and the invitations
--      still out, each saying whether it can still come in. Same for all
--      three kinds.
--   2. Workers are earned. The owner plus ONE worker (any member who is
--      not an owner) is free once the first setup is done — 091's
--      setup_done_at; an association, a church or a generic business has
--      no walkthrough, so for them it is done. More needs Mara Pro or the
--      team unlocked with cauris ('team_access', 085: org_has()). 066's
--      cap on memberships (trg_cap_free_plan) is where every path that adds
--      a member passes — claim_invitation, claim_my_invitations, a direct
--      insert by an admin — so it is replaced, and it now runs on an update
--      too (a row turned from an owner's or a trainer's into a worker's, or
--      moved onto somebody else, is somebody new), one claim at a time per
--      business. The free count is the platform setting free_max_staff,
--      moved once from 066's 3 to 1 (a setting changed later by the platform
--      is never touched again), and it is 0 until the setup is done. A
--      trainer (038), Mara's own admins, an owner, and somebody already in
--      the business (a second grant adds nobody) never take the seat.
--      Nobody already there is removed: only adding is refused. An
--      invitation is refused at its writing too when the seat is already
--      taken (unless it is for somebody already in), so the owner hears it,
--      not the invitee; and the sign-in sweep skips an invitation the
--      business has no seat for instead of failing the whole sweep.
--      The back doors (security): 004 let a business's admins write any
--      membership, so an admin could add a trainer's grant (no seat, hidden
--      from the team), invite or insert an owner, or move or demote the
--      owner's row. Only the platform names a trainer or an owner now
--      (trg_membership_roles, 004's policies narrowed, owners' invitations
--      refused — invite_employee's included); the functions that open a
--      business write its first owner as before.
--   3. Photos on Basic: at most free_photo_items (10) photographed
--      articles or services — an active product with at least one
--      picture. The 11th needs Mara Pro or a photo slot bought with
--      cauris: cauris_costs 'photo_slot', 50, permanent (orgs.photo_slots;
--      the price the platform's, like every cost; refused to Pro and a
--      showcase, which have no limit). Held where a picture becomes an
--      article's — a document inserted on it, moved onto it, or re-filed
--      into a photo — and where an archived article comes back with one;
--      one at a time per business. Articles already photographed past the
--      limit keep their photos. Showcase vitrines (094) and Mara's admins
--      are exempt. No limit on the number of articles. Same for all three
--      kinds — an association's services are photographed like a shop's.
--      A picture is not paperwork (doc_is_photo): a delivery note filed on
--      the first article delivered (kind 'invoice') or a receipt takes no
--      photo place and stays under 066's general cap (free_max_photos).
--      Security: the vitrine took an article's newest DOCUMENT as its
--      picture, and the photo gate served any document of a published
--      article to the street — a supplier's delivery note could be the
--      public picture. storefront_products, search_products,
--      storefront_featured, storefront_previews and storefront_photo_allowed
--      now take pictures only (as do vitrine_score, vitrine_checklist,
--      path_progress and the Articles page's product_photo_keys).
--   4. Associations still earn nothing (084's cauris_award is untouched),
--      but they receive what the platform gives (5) and may now SPEND it:
--      spend_cauris no longer refuses them, and buy_photo_slot does not
--      either. my_cauris and feature_states never looked at the profile;
--      they now carry the promotional points too.
--   5. The platform's powers, for any business: platform_give_cauris
--      gives points (a 'gift' line) or, with a date, promotional points
--      ('promo') that must be spent before that day — spending takes them
--      first, soonest first (cauris_take), and what is left on the day is
--      removed by an 'expired' line written when the wallet is next read or
--      moves (cauris_expire), as 084's idle expiry is. platform_give_unlock
--      opens a Pro tool until a date, as a cauris_unlocks row noted
--      « Offert par Mara » with no cauris spent — or lengthens a tool the
--      business bought, which stays its own. Each is rung to the business's
--      admins with its params (099). A gift is not earned: it is kept out
--      of the week's score and the leagues (league_scores, my_cauris' week,
--      path_state's week, cauris_watch), and an unlock given is not the
--      business's « premier outil » on Le Chemin (path_progress). A
--      showcase vitrine is refused (its ledger drops every line, 094).
--   6. my_orgs() carries owner_name — the owner's name, for the picker.
--  10. The stock audit. Two corrections did not follow the stock:
--      update_production_run (034) changed a batch's output count and left
--      the shelf with the old one — « 20 » corrected to « 40 » kept 20
--      cakes in stock; now the shelf moves by the difference, and the
--      article's cost price (026: the latest batch's unit cost) follows
--      while it is still this batch's. And update_flock_event (033) let a
--      correction take more birds out of a flock than are left (« 3 »
--      typed as « 300 »), the very thing record_flock_event (009) refuses;
--      now it refuses it too.
--
-- Functions replaced, each from its latest definition: trg_cap_free_plan
-- (066), claim_my_invitations (017), plan_terms (082), cauris_expire
-- (084), spend_cauris (085), feature_states (091), my_cauris (097),
-- path_progress and path_state (097), league_scores (086), cauris_watch
-- (084), my_orgs (065, dropped and recreated: its columns grow),
-- update_production_run (034), update_flock_event (033),
-- storefront_photo_allowed (093), storefront_products, search_products,
-- storefront_featured, storefront_previews, vitrine_score and
-- vitrine_checklist (098), product_photo_keys (079); 004's insert, update
-- and delete policies on memberships.
--
-- Re-runnable (the bundle runs twice): columns and tables if not exists,
-- settings on conflict do nothing (the one move of free_max_staff guarded
-- by a marker), functions replaced, triggers dropped and recreated.
-- ============================================================

-- ------------------------------------------------------------
-- 0. Settings, columns, tables
-- ------------------------------------------------------------
insert into platform_settings (key, value) values
    ('free_photo_items', '10')
on conflict (key) do nothing;

-- 066 offered 3 accounts; the owner now offers one. Once: what the platform
-- sets afterwards stays.
do $$
begin
    if not exists (select 1 from platform_settings where key = 'team_seats_seeded') then
        update platform_settings set value = '1'
         where key = 'free_max_staff' and value #>> '{}' = '3';
        insert into platform_settings (key, value) values ('team_seats_seeded', to_jsonb(now()))
        on conflict (key) do nothing;
    end if;
end $$;

insert into cauris_costs (feature, cost, min_days, sort) values
    ('photo_slot', 50, 0, 100)
on conflict (feature) do nothing;

alter table orgs add column if not exists photo_slots integer not null default 0;
alter table orgs drop constraint if exists orgs_photo_slots_positive;
alter table orgs add constraint orgs_photo_slots_positive check (photo_slots >= 0);
comment on column orgs.photo_slots is
    'Photo slots bought with cauris (100): each lets one more article be photographed on Basic, for good.';

alter table employees add column if not exists pay_period text;
alter table employees drop constraint if exists employees_pay_period_kind;
alter table employees add constraint employees_pay_period_kind
    check (pay_period is null or pay_period in ('month', 'week', 'day'));
comment on column employees.pay_period is
    'What the salary is per (100): month, week or day. Null reads as month (012''s salary).';

alter table cauris_unlocks add column if not exists note text;
alter table cauris_unlocks add column if not exists gifted_by uuid references profiles(id) on delete set null;
comment on column cauris_unlocks.gifted_by is
    'Set when the platform opened the tool as a gift (100): no cauris were spent.';

create table if not exists cauris_promos (
    id          uuid primary key default gen_random_uuid(),
    org_id      uuid not null references orgs(id) on delete cascade,
    points      integer not null check (points > 0),
    left_points integer not null check (left_points >= 0),
    expires_on  date not null,
    note        text,
    given_by    uuid references profiles(id) on delete set null,
    created_at  timestamptz not null default now(),
    closed_at   timestamptz
);
create index if not exists cauris_promos_open
    on cauris_promos (org_id, expires_on) where left_points > 0;
alter table cauris_promos enable row level security;
-- No policies: read through my_cauris() and feature_states().
comment on table cauris_promos is
    'Promotional cauris the platform gave (100), to be spent before expires_on. '
    'left_points is what spending has not taken yet; the ledger holds the points.';

comment on column employees.salary is
    'A permanent''s salary for one pay_period (100; null period = a month, as 012 had it). '
    'Ignored for casuals, who are paid hourly_rate for their shifts.';

-- A picture of an article, as against the paperwork filed on it. The app
-- writes 'photo' (record_document's default, « Autre » in the gallery),
-- 'product_photo' (the article's sheet, À vendre, a service), 'receipt' and
-- 'invoice' (a receipt; a delivery note, which confirm_products_screen files
-- on the first article delivered), and 'logo' (080, never an article's);
-- null reads as a photo. A PDF is never a picture (079). The photo count,
-- the vitrine and the photo gate (storefront_photo_allowed, read by anon)
-- take only pictures: a supplier's delivery note filed on an article is not
-- its public picture.
create or replace function doc_is_photo(p_kind text, p_content_type text default null)
returns boolean
language sql
immutable
set search_path = public
as $$
    select coalesce(p_kind, 'photo') not in ('invoice', 'receipt', 'logo')
       and coalesce(p_content_type, '') not ilike '%pdf%';
$$;

-- ------------------------------------------------------------
-- 1–2. The team
-- ------------------------------------------------------------
-- The first setup is behind the business: 091's mark, or a profile that has
-- no walkthrough (an association, a church, a generic business).
create or replace function org_setup_done(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select coalesce((select o.setup_done_at is not null
                            or o.profile::text not in ('retail', 'farm')
                       from orgs o where o.id = p_org_id), false);
$$;

-- The workers: everyone in the business who is not one of its owners — a
-- trainer (038) and Mara's own admins aside.
create or replace function org_workers(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select count(distinct m.user_id)::int
      from memberships m
     where m.org_id = p_org_id
       and not m.is_trainer
       and not exists (select 1 from memberships o
                        where o.org_id = m.org_id and o.user_id = m.user_id
                          and o.role = 'owner')
       and not exists (select 1 from profiles p
                        where p.id = m.user_id and p.is_platform_admin);
$$;

-- How many workers come free: none before the setup, then the platform's
-- number (one).
create or replace function org_free_workers(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select case when org_setup_done(p_org_id)
                then greatest(plan_limit('free_max_staff', 1), 0) else 0 end;
$$;

-- Where the business stands: what the app draws (« 1 personne offerte »,
-- or the lock with Pro and the cauris price).
create or replace function team_seats(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'free',       org_free_workers(p_org_id),
        'used',       org_workers(p_org_id),
        'unlimited',  org_has(p_org_id, 'team_access'),
        'setup_done', org_setup_done(p_org_id),
        'open',       org_has(p_org_id, 'team_access')
                      or org_workers(p_org_id) < org_free_workers(p_org_id),
        'cost',       (select c.cost from cauris_costs c where c.feature = 'team_access'),
        'until',      (select u.until from cauris_unlocks u
                        where u.org_id = p_org_id and u.feature = 'team_access'
                          and u.until > now()),
        -- Opened by Mara (platform_give_unlock), not bought: « Offert par Mara ».
        'gift',       coalesce((select u.gifted_by is not null from cauris_unlocks u
                                 where u.org_id = p_org_id and u.feature = 'team_access'
                                   and u.until > now()), false)
    );
$$;

-- What the refusal says, to the owner or to the person invited. Fixed
-- words, so the app can say them in English.
create or replace function team_full_message(p_org_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select case when org_setup_done(p_org_id)
        then 'Kaj Pro : cette entreprise a déjà sa personne offerte en plus du propriétaire. '
             || 'Pour ajouter quelqu''un : Mara Pro, ou l''équipe débloquée avec des cauris.'
        else 'Kaj Pro : la personne offerte s''ouvre une fois la mise en route de l''entreprise terminée. '
             || 'Avant : Mara Pro, ou l''équipe débloquée avec des cauris.'
    end;
$$;

-- Would one more worker be refused right now?
create or replace function team_full(p_org_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select org_plan(p_org_id) = 'free'
       and not org_has(p_org_id, 'team_access')
       and org_workers(p_org_id) >= org_free_workers(p_org_id);
$$;

-- 066's caps, with the team counted as the owner asked and the articles'
-- photos left to their own rule (3).
create or replace function trg_cap_free_plan()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_cap   int;
    v_count int;
begin
    if auth.uid() is null
       or exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
       or org_plan(new.org_id) <> 'free' then
        return new;
    end if;

    if tg_table_name = 'memberships' then
        -- What the row makes of its person. An owner, a trainer (only the
        -- platform names one: trg_membership_roles) or Mara's own admin is
        -- no worker.
        if new.role = 'owner' or coalesce(new.is_trainer, false)
           or exists (select 1 from profiles where id = new.user_id and is_platform_admin) then
            return new;
        end if;
        -- A worker's row that stays a worker's — another role between
        -- workers, the same person, the same business — adds nobody. A row
        -- that stops being an owner's or a trainer's, or that changes hands
        -- or business, is somebody new: it takes the seat like an insert.
        if tg_op = 'UPDATE'
           and old.user_id = new.user_id and old.org_id = new.org_id
           and old.role <> 'owner' and not coalesce(old.is_trainer, false) then
            return new;
        end if;
        -- Somebody already there by another grant — a worker, or still its
        -- owner — adds nobody either. A trainer's grant does not count: a
        -- trainer given a second role becomes a worker.
        if exists (select 1 from memberships m
                    where m.org_id = new.org_id and m.user_id = new.user_id
                      and m.id <> new.id and not m.is_trainer) then
            return new;
        end if;
        -- One at a time per business: two codes claimed at once cannot both
        -- take the last seat.
        perform pg_advisory_xact_lock(hashtext('team:' || new.org_id::text));
        if team_full(new.org_id) then
            raise exception '%', team_full_message(new.org_id);
        end if;

    elsif tg_table_name = 'invoices' then
        v_cap := plan_limit('free_max_invoices_month', 20);
        select count(*) into v_count from invoices
         where org_id = new.org_id
           and issued_on >= date_trunc('month', coalesce(new.issued_on, current_date))::date
           and issued_on <  (date_trunc('month', coalesce(new.issued_on, current_date)) + interval '1 month')::date;
        if v_count >= v_cap then
            raise exception 'Kaj Pro : la formule gratuite permet % factures par mois. Ouvrez Compte › Kaj Pro pour continuer ce mois-ci.', v_cap;
        end if;

    elsif tg_table_name = 'documents' then
        -- An article's picture is counted by article (trg_photo_items); the
        -- paperwork filed on an article (a delivery note, a receipt) is
        -- counted here, with every capture that is about no article.
        if new.product_id is not null and doc_is_photo(new.kind, new.content_type) then
            return new;
        end if;
        v_cap := plan_limit('free_max_photos', 50);
        select count(*) into v_count from documents
         where org_id = new.org_id
           and (product_id is null or not doc_is_photo(kind, content_type));
        if v_count >= v_cap then
            raise exception 'Kaj Pro : la formule gratuite garde % photos. Ouvrez Compte › Kaj Pro pour en ajouter.', v_cap;
        end if;
    end if;

    return new;
end;
$$;

-- 066's cap ran on an insert only: a row edited by an admin (004 lets them)
-- from an owner's or a trainer's into a worker's, or onto somebody else,
-- walked past it. Now on an update too.
drop trigger if exists cap_free_staff on memberships;
create trigger cap_free_staff
before insert or update on memberships
for each row execute function trg_cap_free_plan();

-- Who may make an owner or a trainer. 004 lets a business's admins write
-- memberships directly, so an admin could insert a trainer's grant (038: a
-- trainer takes no seat and is hidden from the team), or an owner's, or
-- move the owner's own row onto themselves. The platform names trainers
-- (assign_trainer) and owners. The functions that open a business
-- (create_org, approve_org_application, 094's showcases) write its first
-- owner: an owner's grant is taken only while the business has none, and a
-- written-straight-from-the-app one never (004's policies, below). No
-- transfer of ownership exists yet (044 says it comes first); when it does,
-- it is the platform's act or a definer function of its own.
create or replace function trg_membership_roles()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null
       or exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        return new;
    end if;
    if (tg_op = 'INSERT' and coalesce(new.is_trainer, false))
       or (tg_op = 'UPDATE' and new.is_trainer is distinct from old.is_trainer) then
        raise exception 'Seule la plateforme nomme une formatrice ou un formateur'
            using errcode = 'insufficient_privilege';
    end if;
    -- 044 refuses it in set_membership_role; any other write too.
    if tg_op = 'UPDATE' and old.role = 'owner'
       and (new.role is distinct from old.role
            or new.user_id is distinct from old.user_id
            or new.org_id is distinct from old.org_id) then
        raise exception 'Le propriétaire ne se change pas ici'
            using errcode = 'insufficient_privilege';
    end if;
    if new.role = 'owner' and (tg_op = 'INSERT' or old.role is distinct from 'owner')
       and exists (select 1 from memberships m
                    where m.org_id = new.org_id and m.role = 'owner' and m.id <> new.id) then
        raise exception 'Seule la plateforme nomme un propriétaire'
            using errcode = 'insufficient_privilege';
    end if;
    return new;
end;
$$;

drop trigger if exists membership_roles on memberships;
create trigger membership_roles
before insert or update on memberships
for each row execute function trg_membership_roles();

-- 004's door for an admin's own writes, narrowed: no owner's grant and no
-- trainer's is written, changed or (for the owner's) removed straight from
-- the app, except by Mara's admins — the owner leaving their own business
-- aside. The definer functions above do not pass through a policy; the
-- trigger holds them. Everything else an admin did, they still do.
drop policy if exists "memberships granted by org admins" on memberships;
create policy "memberships granted by org admins"
on memberships for insert
with check (
    is_org_admin(org_id)
    and ((role <> 'owner' and not is_trainer)
         or exists (select 1 from profiles where id = auth.uid() and is_platform_admin))
);

drop policy if exists "memberships amended by org admins" on memberships;
create policy "memberships amended by org admins"
on memberships for update
using (
    is_org_admin(org_id)
    and ((role <> 'owner' and not is_trainer)
         or exists (select 1 from profiles where id = auth.uid() and is_platform_admin))
)
with check (
    is_org_admin(org_id)
    and ((role <> 'owner' and not is_trainer)
         or exists (select 1 from profiles where id = auth.uid() and is_platform_admin))
);

drop policy if exists "memberships revoked by org admins" on memberships;
create policy "memberships revoked by org admins"
on memberships for delete
using (
    is_org_admin(org_id)
    and (role <> 'owner' or user_id = auth.uid()
         or exists (select 1 from profiles where id = auth.uid() and is_platform_admin))
);

-- An invitation: never for an owner (the platform's to name — an invitation
-- claimed becomes a membership through a definer function, so it is held
-- here, at its writing, invite_employee's included); and, when the seat is
-- already taken, said to the owner now rather than to the invitee later —
-- unless it is for somebody already in the business (by their number), who
-- takes no new seat.
create or replace function trg_invitation_seat()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if auth.uid() is null
       or exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        return new;
    end if;
    if new.role = 'owner' then
        raise exception 'Seule la plateforme nomme un propriétaire'
            using errcode = 'insufficient_privilege';
    end if;
    if tg_op = 'UPDATE' then
        return new;
    end if;
    if team_full(new.org_id)
       and not (new.phone is not null and exists (
                select 1 from memberships m
                  join profiles p on p.id = m.user_id
                  left join auth.users u on u.id = m.user_id
                 where m.org_id = new.org_id
                   and (p.phone = new.phone or u.phone = new.phone))) then
        raise exception '%', team_full_message(new.org_id);
    end if;
    return new;
end;
$$;

drop trigger if exists invitation_seat on pending_invitations;
create trigger invitation_seat
before insert or update of role on pending_invitations
for each row execute function trg_invitation_seat();

-- 017's sweep: an invitation the business has no seat for stays waiting
-- (it is claimed once a seat opens), and the others still go through.
create or replace function claim_my_invitations()
returns int
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
    v_uid   uuid := auth.uid();
    v_phone text;
    v_email text;
    v_alt   text;
    v_count int := 0;
    v_inv   pending_invitations%rowtype;
begin
    if v_uid is null then
        return 0;
    end if;

    if not exists (select 1 from profiles where id = v_uid) then
        return 0;
    end if;

    select u.phone, u.email into v_phone, v_email from auth.users u where u.id = v_uid;
    select p.phone into v_alt from profiles p where p.id = v_uid;

    for v_inv in
        select * from pending_invitations i
        where i.claimed_at is null
          and i.expires_at > now()
          and (
              (v_phone is not null and i.phone = v_phone)
              or (v_alt is not null and i.phone = v_alt)
              or (v_email is not null and lower(i.email) = lower(v_email))
          )
        for update
    loop
        begin
            insert into memberships (org_id, user_id, role, scope_kind, scope_id, visibility)
            values (v_inv.org_id, v_uid, v_inv.role, v_inv.scope_kind,
                    v_inv.scope_id, v_inv.visibility)
            on conflict (user_id, scope_kind, scope_id, role) do nothing;
        exception when raise_exception or insufficient_privilege then
            continue;  -- no seat, or a grant only the platform makes (100):
                       -- left for later, the rest go on
        end;

        update pending_invitations
        set claimed_at = now(), claimed_by = v_uid
        where id = v_inv.id and claimed_at is null;

        v_count := v_count + 1;
    end loop;

    return v_count;
end;
$$;

-- A person's name as the screens say it.
create or replace function person_name(p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
    select coalesce(nullif(btrim(concat_ws(' ', p.first_name, p.last_name)), ''),
                    nullif(btrim(coalesce(p.full_name, '')), ''),
                    p.phone)
      from profiles p where p.id = p_user_id;
$$;

-- The Équipe screen, in one read: the seats, the people (owners first) with
-- their salary, the invitations still out. The business's admins only:
-- what a colleague earns is theirs to see (012).
--
-- A member's pay is their payroll row's: a permanent's salary for its
-- period, or — for somebody paid by the hour in « Paie et journées » — the
-- hourly rate, which is changed there. Each member carries their grants
-- (to remove them from the team), and each invitation says whether it can
-- still come in: not when the seat is taken, unless it is for somebody
-- already in the business.
create or replace function team_overview(p_org_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, auth
as $$
declare
    v_full boolean;
begin
    if auth.uid() is null or not is_org_admin(p_org_id) then
        return null;
    end if;
    v_full := team_full(p_org_id);
    return jsonb_build_object(
        'seats', team_seats(p_org_id),
        'members', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'user_id', u.user_id,
                       'name', person_name(u.user_id),
                       'phone', p.phone,
                       'roles', to_jsonb(u.roles),
                       'owner', 'owner' = any (u.roles),
                       'me', u.user_id = auth.uid(),
                       'since', u.since,
                       'memberships', to_jsonb(u.ids),
                       'salary', case when e.kind = 'permanent' and e.salary > 0 then e.salary end,
                       'period', case when e.kind = 'permanent' and e.salary > 0
                                      then coalesce(e.pay_period, 'month') end,
                       'hourly', case when e.kind = 'casual' and e.hourly_rate > 0
                                      then e.hourly_rate end,
                       'employee_id', e.id)
                   order by ('owner' = any (u.roles)) desc, lower(person_name(u.user_id)))
              from (select m.user_id,
                           array_agg(distinct m.role::text order by m.role::text) as roles,
                           array_agg(m.id order by m.created_at) as ids,
                           min(m.created_at) as since
                      from memberships m
                     where m.org_id = p_org_id and not m.is_trainer
                     group by m.user_id) u
              join profiles p on p.id = u.user_id
              left join lateral (
                  select x.id, x.kind, x.salary, x.hourly_rate, x.pay_period from employees x
                   where x.org_id = p_org_id and x.user_id = u.user_id and x.is_active
                   order by x.created_at limit 1) e on true), '[]'::jsonb),
        'invitations', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'id', i.id, 'code', i.code, 'phone', i.phone,
                       'name', i.full_name, 'role', i.role,
                       'expires_at', i.expires_at,
                       'blocked', v_full and not (i.phone is not null and exists (
                           select 1 from memberships m
                             join profiles q on q.id = m.user_id
                             left join auth.users a on a.id = m.user_id
                            where m.org_id = p_org_id
                              and (q.phone = i.phone or a.phone = i.phone))))
                   order by i.created_at desc)
              from pending_invitations i
             where i.org_id = p_org_id and i.claimed_at is null
               and i.expires_at > now()), '[]'::jsonb),
        'org_name', (select name from orgs where id = p_org_id)
    );
end;
$$;

-- A member's salary, on their payroll row (012), for a period: par mois,
-- par semaine, par jour. Null or 0 clears it. Free: the payroll's Pro guard
-- is on paying (shifts, staff_payments), not here.
--
-- The payroll reads the period (100): a permanent's salary is what one
-- pay_employee() pays — a month's, a week's or a day's — and « Paie et
-- journées » writes « / mois », « / semaine », « / jour » beside it. A row's
-- kind is never changed here: somebody paid by the hour (a casual, whose
-- shifts are the record) keeps their rate, changed in « Paie et journées »;
-- a new row is a permanent's. Clearing touches the amount only — an ended
-- employment stays ended; recording a salary for a member whose row had
-- ended brings it back, as re-adding them in the payroll does (012).
create or replace function set_member_salary(
    p_org_id  uuid,
    p_user_id uuid,
    p_amount  numeric,
    p_period  text default 'month'
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_row    employees%rowtype;
    v_id     uuid;
    v_name   text;
    v_phone  text;
    v_amount numeric := coalesce(p_amount, 0);
    v_period text := coalesce(nullif(btrim(coalesce(p_period, '')), ''), 'month');
begin
    if auth.uid() is null or not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur note le salaire de l''équipe';
    end if;
    if not exists (select 1 from memberships
                    where org_id = p_org_id and user_id = p_user_id) then
        raise exception 'Cette personne n''est pas dans l''équipe';
    end if;
    if v_amount < 0 or v_amount > 1000000000 then
        raise exception 'Le salaire doit être un montant positif';
    end if;
    if v_period not in ('month', 'week', 'day') then
        raise exception 'Période inconnue : %', v_period;
    end if;

    select person_name(p_user_id), phone into v_name, v_phone
      from profiles where id = p_user_id;
    v_name := coalesce(v_name, 'Membre');

    -- Their row: by the account, else an unlinked one of the same name
    -- (somebody already on the payroll before they had the app).
    select * into v_row from employees
     where org_id = p_org_id and user_id = p_user_id
     order by is_active desc, created_at limit 1;
    if v_row.id is null then
        select * into v_row from employees
         where org_id = p_org_id and user_id is null
           and lower(btrim(full_name)) = lower(btrim(v_name))
         order by is_active desc, created_at limit 1;
    end if;

    if v_row.id is null then
        if v_amount = 0 then
            return null;  -- nothing to clear
        end if;
        -- The name is unique in the business (012): another person's row
        -- of the same name keeps it, this one takes the phone beside it.
        if exists (select 1 from employees
                    where org_id = p_org_id
                      and lower(btrim(full_name)) = lower(btrim(v_name))) then
            v_name := v_name || ' (' || coalesce(v_phone, left(p_user_id::text, 8)) || ')';
        end if;
        insert into employees (org_id, full_name, phone, kind, salary, pay_period,
                               user_id, created_by)
        values (p_org_id, v_name, v_phone, 'permanent', v_amount, v_period,
                p_user_id, auth.uid())
        returning id into v_id;
        return v_id;
    end if;

    if v_amount = 0 then
        -- The amount only: nothing comes back to life, no kind changes, and
        -- a row of the same name not linked to this account is somebody
        -- else's, left alone (the screen reads only a linked row).
        if v_row.user_id is null then
            return null;
        end if;
        update employees
           set salary     = case when kind = 'permanent' then 0 else salary end,
               pay_period = case when kind = 'permanent' then null else pay_period end
         where id = v_row.id;
        return v_row.id;
    end if;

    if v_row.kind <> 'permanent' then
        raise exception 'Cette personne est payée à l''heure dans « Paie et journées » : son taux se change là-bas.';
    end if;

    update employees
       set user_id    = p_user_id,
           is_active  = true,
           ended_on   = null,
           end_reason = null,
           salary     = v_amount,
           pay_period = v_period
     where id = v_row.id;
    return v_row.id;
end;
$$;

-- ------------------------------------------------------------
-- 3. Photos on Basic
-- ------------------------------------------------------------
-- The articles (and services) photographed: active, with a picture — the
-- paperwork filed on an article (doc_is_photo) is not one.
create or replace function org_photo_items(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select count(*)::int from products p
     where p.org_id = p_org_id and p.is_active
       and exists (select 1 from documents d
                    where d.product_id = p.id and doc_is_photo(d.kind, d.content_type));
$$;

-- How many may be: null when there is no limit (Mara Pro, a showcase).
create or replace function org_photo_limit(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select case
        when org_plan(o.id) = 'pro' or o.showcase then null
        else greatest(plan_limit('free_photo_items', 10), 0) + o.photo_slots
    end
    from orgs o where o.id = p_org_id;
$$;

create or replace function photo_state(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'used',      org_photo_items(p_org_id),
        'limit',     org_photo_limit(p_org_id),
        'slots',     (select photo_slots from orgs where id = p_org_id),
        'slot_cost', (select cost from cauris_costs where feature = 'photo_slot')
    );
$$;

-- Where a picture becomes an article's: a document inserted on it, or one
-- moved onto it, or one on it re-filed from paperwork into a photo. One at
-- a time per business (an advisory lock), so two photos at once cannot both
-- take the last place. Refused at a filing, the capture stays in Documents,
-- with no article: the message says so (the app sends the bytes first and
-- files them after, so a photo taken offline is never lost).
create or replace function trg_photo_items()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_limit int;
begin
    if new.product_id is null or not doc_is_photo(new.kind, new.content_type) then
        return new;  -- no article, or paperwork: 066's general cap
    end if;
    if tg_op = 'UPDATE' and old.product_id is not distinct from new.product_id
       and doc_is_photo(old.kind, old.content_type) then
        return new;  -- already this article's picture
    end if;
    if auth.uid() is null
       or exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        return new;
    end if;
    v_limit := org_photo_limit(new.org_id);
    if v_limit is null then
        return new;
    end if;
    perform pg_advisory_xact_lock(hashtext('photos:' || new.org_id::text));
    -- Another picture of an article already photographed takes no new
    -- place; an article out of the shop is counted when it comes back
    -- (trg_photo_revive).
    if exists (select 1 from documents d
                where d.product_id = new.product_id and d.id <> new.id
                  and doc_is_photo(d.kind, d.content_type))
       or not exists (select 1 from products p
                       where p.id = new.product_id and p.is_active) then
        return new;
    end if;
    if org_photo_items(new.org_id) >= v_limit then
        if tg_op = 'UPDATE' then
            raise exception 'Kaj Pro : toutes vos places photo sont prises. '
                'La photo reste dans vos documents, sans article. Pour la mettre sur l''article : '
                'Mara Pro, ou une place photo achetée avec des cauris.';
        end if;
        raise exception 'Kaj Pro : toutes vos places photo sont prises. '
            'Pour photographier un article de plus : Mara Pro, ou une place photo achetée avec des cauris.';
    end if;
    return new;
end;
$$;

drop trigger if exists photo_items_limit on documents;
create trigger photo_items_limit
before insert or update of product_id, kind, content_type on documents
for each row execute function trg_photo_items();

-- An article out of the shop (027's archive) gives its place back; brought
-- back with its picture — archive_product(…, false), or 051's re-add by its
-- name — it takes one again, and is refused when none is left.
create or replace function trg_photo_revive()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_limit int;
begin
    if old.is_active or not new.is_active
       or auth.uid() is null
       or exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
       or not exists (select 1 from documents d
                       where d.product_id = new.id and doc_is_photo(d.kind, d.content_type)) then
        return new;
    end if;
    v_limit := org_photo_limit(new.org_id);
    if v_limit is null then
        return new;
    end if;
    perform pg_advisory_xact_lock(hashtext('photos:' || new.org_id::text));
    if org_photo_items(new.org_id) >= v_limit then
        raise exception 'Kaj Pro : cet article a une photo et toutes vos places photo sont prises. '
            'Pour le remettre : Mara Pro, une place photo achetée avec des cauris, '
            'ou un autre article photographié retiré.';
    end if;
    return new;
end;
$$;

drop trigger if exists photo_revive_limit on products;
create trigger photo_revive_limit
before update of is_active on products
for each row execute function trg_photo_revive();

-- 093's photo gate, read by the uploads Worker for anon: an article's
-- picture only — a delivery note or a receipt filed on a published article
-- is not served to the street. The cover and the logo as 093.
create or replace function storefront_photo_allowed(p_key text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
    select exists (
        select 1
        from documents d
        join products p on p.id = d.product_id
        join orgs     o on o.id = p.org_id
        where d.r2_key = p_key
          and doc_is_photo(d.kind, d.content_type)
          and p.is_active
          and p.is_published
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    ) or exists (
        select 1
        from orgs o
        where o.storefront_style ->> 'cover_key' = p_key
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
          and (org_has(o.id, 'vitrine_plus')
               or cauris_param('vitrine_free_basics', 1) = 1)
    ) or exists (
        select 1
        from orgs o
        where o.logo_key = p_key
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    );
$$;

-- 098's window, its picture the article's newest photo (not the newest
-- document: a delivery note filed on it is not its picture).
create or replace function storefront_products(p_slug text)
returns table (
    id             uuid,
    name           text,
    sale_price     numeric,
    in_stock       boolean,
    photo_key      text,
    description    text,
    unit           text,
    available_from date,
    is_service     boolean,
    price_from     boolean
)
language sql
stable
security definer
set search_path = public
as $$
    select p.id, p.name, p.sale_price,
           (p.is_service
            or p.quantity > 0
            or p.available_from > (now() at time zone 'Africa/Ouagadougou')::date),
           (select d.r2_key from documents d
             where d.product_id = p.id and doc_is_photo(d.kind, d.content_type)
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1),
           nullif(btrim(p.description), ''),
           nullif(btrim(p.unit), ''),
           case when p.available_from > (now() at time zone 'Africa/Ouagadougou')::date
                then p.available_from end,
           p.is_service,
           p.price_from
    from products p
    where p.org_id = storefront_open(p_slug)
      and p.is_active
      and p.is_published
    order by p.is_service, p.name;
$$;

-- 098's search, the same picture.
create or replace function search_products(
    p_query text,
    p_lat   double precision default null,
    p_lng   double precision default null
)
returns table (
    id          uuid,
    name        text,
    sale_price  numeric,
    in_stock    boolean,
    photo_key   text,
    shop_name   text,
    shop_slug   text,
    currency    text,
    shop_lat    double precision,
    shop_lng    double precision,
    distance_km double precision
)
language sql
stable
security definer
set search_path = public
as $$
    with q as (
        select fold_search_text(btrim(coalesce(p_query, ''))) as folded
    ),
    hits as (
        select p.id, p.name, p.sale_price,
               (p.is_service or p.quantity > 0) as in_stock,
               (select d.r2_key from documents d
                 where d.product_id = p.id and doc_is_photo(d.kind, d.content_type)
                 order by coalesce(d.captured_at, d.created_at) desc
                 limit 1) as photo_key,
               o.name as shop_name, o.slug as shop_slug,
               o.default_currency as currency,
               o.lat as shop_lat, o.lng as shop_lng,
               case
                   when p_lat is null or p_lng is null
                     or o.lat is null or o.lng is null then null
                   else 6371.0 * 2 * asin(sqrt(
                            power(sin(radians(o.lat - p_lat) / 2), 2)
                          + cos(radians(p_lat)) * cos(radians(o.lat))
                          * power(sin(radians(o.lng - p_lng) / 2), 2)))
               end as distance_km,
               position((select folded from q) in fold_search_text(p.name))
                   as hit_at
        from products p
        join orgs o on o.id = p.org_id
        where length((select folded from q)) >= 2
          and fold_search_text(p.name) like
              '%' || replace(replace(replace((select folded from q),
                    '\', '\\'), '%', '\%'), '_', '\_') || '%'
          and p.is_active
          and p.is_published
          and o.storefront_enabled
          and o.archived_at  is null
          and o.suspended_at is null
    )
    select h.id, h.name, h.sale_price, h.in_stock, h.photo_key,
           h.shop_name, h.shop_slug, h.currency,
           h.shop_lat, h.shop_lng, h.distance_km
    from hits h
    order by (h.hit_at = 1) desc, h.in_stock desc,
             (h.distance_km is null), h.distance_km, h.name, h.shop_name
    limit 50;
$$;

-- 098's « À la une », the same picture.
create or replace function storefront_featured()
returns table (
    id         uuid,
    name       text,
    sale_price numeric,
    in_stock   boolean,
    photo_key  text,
    shop_name  text,
    shop_slug  text,
    currency   text
)
language sql
stable
security definer
set search_path = public
as $$
    select p.id, p.name, p.sale_price, (p.is_service or p.quantity > 0),
           (select d.r2_key from documents d
             where d.product_id = p.id and doc_is_photo(d.kind, d.content_type)
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1),
           o.name, o.slug, o.default_currency
    from products p
    join orgs o on o.id = p.org_id
    left join lateral (
        select min(pm.starts_at) as since from promotions pm
         where pm.product_id = p.id and pm.status = 'approved'
           and pm.starts_at <= now() and pm.ends_at > now()
    ) spot on true
    where (spot.since is not null or p.featured_until > now())
      and p.is_active
      and p.is_published
      and o.storefront_enabled
      and o.archived_at  is null
      and o.suspended_at is null
    order by (spot.since is null), spot.since, p.featured_until desc nulls last, p.name
    limit 12;
$$;

-- 098's street cards, the same picture.
create or replace function storefront_previews(p_slugs text[])
returns table (
    slug       text,
    product_id uuid,
    name       text,
    sale_price numeric,
    photo_key  text
)
language sql
stable
security definer
set search_path = public
as $$
    select x.slug, x.id, x.name, x.sale_price, x.photo_key
    from (
        select o.slug, p.id, p.name, p.sale_price, ph.r2_key as photo_key,
               row_number() over (
                   partition by o.id
                   order by (ph.r2_key is null),
                            (not p.is_service and p.quantity <= 0), p.name
               ) as n
        from orgs o
        join products p on p.org_id = o.id
        left join lateral (
            select d.r2_key from documents d
             where d.product_id = p.id and doc_is_photo(d.kind, d.content_type)
             order by coalesce(d.captured_at, d.created_at) desc
             limit 1
        ) ph on true
        where o.slug = any (coalesce(p_slugs, '{}'))
          and o.id = storefront_open(o.slug)
          and p.is_active
          and p.is_published
    ) x
    where x.n <= 3
    order by x.slug, x.n;
$$;

-- 098's score and checklist: « en photo » counts pictures, not paperwork.
create or replace function vitrine_score(p_org_id uuid)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select (100 * (
        (published >= greatest(vitrine_min(o_id), 1))::int
      + (association or with_photo >= 3
         or (published > 0 and with_photo >= published))::int
      + blurb::int + phone::int + address::int + pin::int) / 6.0)::int
    from (
        select
            o.id as o_id,
            o.profile in ('church', 'association') as association,
            (select count(*) from products p
              where p.org_id = o.id and p.is_active and p.is_published) as published,
            (select count(*) from products p
              where p.org_id = o.id and p.is_active and p.is_published
                and exists (select 1 from documents d
                             where d.product_id = p.id
                               and doc_is_photo(d.kind, d.content_type))) as with_photo,
            nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null as blurb,
            nullif(btrim(coalesce(o.phone, '')), '') is not null as phone,
            nullif(btrim(coalesce(o.address, '')), '') is not null as address,
            (o.lat is not null and o.lng is not null) as pin
        from orgs o where o.id = p_org_id
    ) x;
$$;

create or replace function vitrine_checklist(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
    select case when not is_org_member(p_org_id) then null else
    jsonb_build_object(
        'open',        o.storefront_enabled,
        'min_items',   vitrine_min(o.id),
        'active',      (select count(*) from products p
                         where p.org_id = o.id and p.is_active and not p.is_ingredient),
        'published',   (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published),
        'services',    (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published
                           and p.is_service),
        'unpublished', (select count(*) from products p
                         where p.org_id = o.id and p.is_active and not p.is_published
                           and not p.is_ingredient and coalesce(p.sale_price, 0) > 0),
        'with_photo',  (select count(*) from products p
                         where p.org_id = o.id and p.is_active and p.is_published
                           and exists (select 1 from documents d
                                        where d.product_id = p.id
                                          and doc_is_photo(d.kind, d.content_type))),
        'blurb',       nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null,
        'address',     nullif(btrim(coalesce(o.address, '')), '') is not null,
        'phone',       nullif(btrim(coalesce(o.phone, '')), '') is not null,
        'pin',         o.lat is not null and o.lng is not null
    ) end
    from orgs o where o.id = p_org_id;
$$;

-- 079's thumbnails on the Articles page: the same picture as the vitrine.
create or replace function product_photo_keys(p_org_id uuid)
returns table (product_id uuid, photo_key text)
language sql
stable
security invoker
set search_path = public
as $$
    select distinct on (d.product_id) d.product_id, d.r2_key
    from documents d
    where d.org_id = p_org_id
      and d.product_id is not null
      and doc_is_photo(d.kind, d.content_type)
    order by d.product_id, coalesce(d.captured_at, d.created_at) desc;
$$;

-- ------------------------------------------------------------
-- 4–5. Cauris: promotional points, spending, gifts
-- ------------------------------------------------------------
-- 084's expiry, with the promotional points: an idle wallet still empties
-- itself (and its promotional points with it); otherwise what is left of a
-- promotion on its day is taken out, never below zero. A promotion's own
-- expiry line is not « a movement » that keeps a wallet alive.
create or replace function cauris_expire(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
    v_last    timestamptz;
    v_balance int;
    v_take    int;
    r         record;
begin
    select max(created_at) into v_last from cauris_ledger
     where org_id = p_org_id
       and not (reason = 'expired' and ref like 'promo:%');
    if v_last is not null
       and v_last <= now() - make_interval(days => cauris_param('cauris_expire_days', 180)) then
        v_balance := cauris_balance(p_org_id);
        if v_balance > 0 then
            insert into cauris_ledger (org_id, delta, reason, ref, note)
            values (p_org_id, -v_balance, 'expired', cauris_today()::text,
                    'Cauris non utilisés depuis ' || cauris_param('cauris_expire_days', 180) || ' jours')
            on conflict do nothing;
        end if;
        update cauris_promos set left_points = 0, closed_at = now()
         where org_id = p_org_id and left_points > 0;
        return;
    end if;

    for r in select * from cauris_promos
              where org_id = p_org_id and left_points > 0
                and expires_on <= cauris_today()
              order by expires_on, created_at
              for update
    loop
        v_take := least(r.left_points, greatest(cauris_balance(p_org_id), 0));
        if v_take > 0 then
            insert into cauris_ledger (org_id, delta, reason, ref, note)
            values (p_org_id, -v_take, 'expired', 'promo:' || r.id,
                    'Cauris offerts à utiliser avant le ' || to_char(r.expires_on, 'DD/MM/YYYY'))
            on conflict do nothing;
        end if;
        update cauris_promos set left_points = 0, closed_at = now() where id = r.id;
    end loop;
end;
$$;

-- What is left of the promotions, soonest first, never more than the
-- wallet holds (a lost cauri — an order cancelled — comes out of them too).
create or replace function cauris_promo_left(p_org_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select coalesce(jsonb_agg(jsonb_build_object('points', x.pts, 'until', x.expires_on)
                              order by x.expires_on, x.created_at), '[]'::jsonb)
      from (
        select c.expires_on, c.created_at,
               least(c.left_points,
                     greatest(cauris_balance(p_org_id)
                              - coalesce(sum(c.left_points) over (
                                    order by c.expires_on, c.created_at
                                    rows between unbounded preceding and 1 preceding), 0), 0))::int as pts
          from cauris_promos c
         where c.org_id = p_org_id and c.left_points > 0
           and c.expires_on > cauris_today()
      ) x
     where x.pts > 0;
$$;

-- The one way cauris are spent: one spender at a time, the price in one
-- 'spent' line, the promotional points used first, soonest first.
-- Returns the balance after.
create or replace function cauris_take(p_org_id uuid, p_cost int, p_ref text, p_note text)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
    v_balance int;
    v_left    int := p_cost;
    v_take    int;
    r         record;
begin
    perform pg_advisory_xact_lock(hashtext('cauris:' || p_org_id::text));
    perform cauris_expire(p_org_id);
    v_balance := cauris_balance(p_org_id);
    if v_balance < p_cost then
        raise exception 'Il vous manque % cauris', p_cost - v_balance;
    end if;
    insert into cauris_ledger (org_id, delta, reason, ref, note)
    values (p_org_id, -p_cost, 'spent', p_ref, p_note);
    for r in select id, left_points from cauris_promos
              where org_id = p_org_id and left_points > 0
                and expires_on > cauris_today()
              order by expires_on, created_at
              for update
    loop
        exit when v_left <= 0;
        v_take := least(r.left_points, v_left);
        update cauris_promos
           set left_points = left_points - v_take,
               closed_at = case when left_points - v_take = 0 then now() end
         where id = r.id;
        v_left := v_left - v_take;
    end loop;
    return v_balance - p_cost;
end;
$$;

-- 085's spending: for an association too now (it earns nothing, but what
-- the platform gives it, it may spend); through cauris_take; a tool bought
-- after it was given is the business's own again.
create or replace function spend_cauris(p_org_id uuid, p_feature text)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_cost   cauris_costs%rowtype;
    v_org    orgs%rowtype;
    v_until  timestamptz;
    v_days   int := cauris_param('cauris_unlock_days', 30);
    v_after  int;
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur dépense les cauris de l''entreprise';
    end if;
    select * into v_cost from cauris_costs where feature = p_feature;
    if not found or p_feature = 'photo_slot' then
        raise exception 'Cet outil ne s''ouvre pas avec des cauris';
    end if;
    select * into v_org from orgs where id = p_org_id;
    if v_cost.min_days > 0 and v_org.created_at > now() - make_interval(days => v_cost.min_days) then
        raise exception 'Cet outil s''ouvre avec des cauris après % jours sur Mara', v_cost.min_days;
    end if;

    v_after := cauris_take(p_org_id, v_cost.cost,
                           p_feature || ':' || gen_random_uuid()::text, p_feature);

    select greatest(coalesce(u.until, now()), now()) + make_interval(days => v_days)
      into v_until
      from (select 1) x left join cauris_unlocks u
        on u.org_id = p_org_id and u.feature = p_feature;

    insert into cauris_unlocks (org_id, feature, until)
    values (p_org_id, p_feature, v_until)
    on conflict (org_id, feature) do update
        set until = excluded.until, updated_at = now(), note = null, gifted_by = null;

    return jsonb_build_object('feature', p_feature, 'until', v_until,
                              'balance', v_after);
end;
$$;

-- A photo slot: 50 cauris (the platform's price), for good.
create or replace function buy_photo_slot(p_org_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_cost  int;
    v_after int;
    v_slots int;
begin
    if not is_org_admin(p_org_id) then
        raise exception 'Seul un administrateur dépense les cauris de l''entreprise';
    end if;
    select cost into v_cost from cauris_costs where feature = 'photo_slot';
    if v_cost is null then
        raise exception 'Les places photo ne s''achètent pas avec des cauris';
    end if;
    -- Mara Pro and a showcase have no limit: a slot would buy nothing.
    if org_photo_limit(p_org_id) is null then
        raise exception 'Cette entreprise a déjà ses photos sans limite';
    end if;
    v_after := cauris_take(p_org_id, v_cost, 'photo_slot:' || gen_random_uuid()::text,
                           'photo_slot');
    update orgs set photo_slots = photo_slots + 1 where id = p_org_id
    returning photo_slots into v_slots;
    return jsonb_build_object('slots', v_slots, 'balance', v_after,
                              'photos', photo_state(p_org_id));
end;
$$;

-- A Pro tool, in the words of the bell.
create or replace function cauris_feature_label(p_feature text)
returns text
language sql
immutable
set search_path = public
as $$
    select case p_feature
        when 'pro_all'        then 'Mara Pro complet'
        when 'analytics'      then 'les analyses'
        when 'delivery'       then 'la livraison'
        when 'online_payment' then 'le paiement en ligne'
        when 'vitrine_plus'   then 'la vitrine personnalisée'
        when 'accounting'     then 'la comptabilité'
        when 'team_access'    then 'l''équipe'
        when 'payroll'        then 'la paie'
        when 'currencies'     then 'les devises'
        when 'tontines'       then 'les tontines'
        else p_feature
    end;
$$;

-- The platform gives points: a gift, or — with a date — promotional points
-- to be spent before that day.
create or replace function platform_give_cauris(
    p_org_id     uuid,
    p_points     integer,
    p_note       text default null,
    p_expires_on date default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org   orgs%rowtype;
    v_note  text := nullif(btrim(coalesce(p_note, '')), '');
    v_ref   text := gen_random_uuid()::text;
    v_promo uuid;
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Seule la plateforme offre des cauris';
    end if;
    select * into v_org from orgs where id = p_org_id;
    if not found then
        raise exception 'Entreprise inconnue';
    end if;
    if v_org.showcase then
        raise exception 'Une vitrine d''exemple ne reçoit pas de cauris';
    end if;
    if p_points is null or p_points <= 0 or p_points > 100000 then
        raise exception 'Le nombre de cauris doit être entre 1 et 100 000';
    end if;
    if p_expires_on is not null and p_expires_on <= cauris_today() then
        raise exception 'La date doit être après aujourd''hui';
    end if;

    perform pg_advisory_xact_lock(hashtext('cauris:' || p_org_id::text));
    perform cauris_expire(p_org_id);
    if p_expires_on is null then
        insert into cauris_ledger (org_id, delta, reason, ref, note)
        values (p_org_id, p_points, 'gift', v_ref, coalesce(v_note, 'Offert par Mara'));
    else
        insert into cauris_promos (org_id, points, left_points, expires_on, note, given_by)
        values (p_org_id, p_points, p_points, p_expires_on, v_note, auth.uid())
        returning id into v_promo;
        insert into cauris_ledger (org_id, delta, reason, ref, note)
        values (p_org_id, p_points, 'promo', v_promo::text,
                coalesce(v_note, 'Offert par Mara') || ' · avant le '
                || to_char(p_expires_on, 'DD/MM/YYYY'));
    end if;

    begin
        perform notify_org_admins(p_org_id,
            case when p_expires_on is null then 'cauris_gift' else 'cauris_promo' end,
            'Mara vous offre ' || p_points || ' cauris'
            || case when p_expires_on is not null
                    then ', à utiliser avant le ' || to_char(p_expires_on, 'DD/MM/YYYY') else '' end
            || case when v_note is not null then ' : ' || v_note else '' end || '.',
            jsonb_build_object('to', 'shop', 'points', p_points, 'note', v_note,
                               'until', p_expires_on));
    exception when others then
        null;  -- a bell never costs the gift
    end;

    return jsonb_build_object('balance', cauris_balance(p_org_id),
                              'promo', cauris_promo_left(p_org_id));
end;
$$;

-- The platform opens a Pro tool until a date (that day included). No
-- cauris move; the row says who gave it.
create or replace function platform_give_unlock(
    p_org_id  uuid,
    p_feature text,
    p_until   date,
    p_note    text default null
)
returns timestamptz
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org   orgs%rowtype;
    v_until timestamptz;
    v_note  text := coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Offert par Mara');
begin
    if not exists (select 1 from profiles where id = auth.uid() and is_platform_admin) then
        raise exception 'Seule la plateforme offre un outil';
    end if;
    select * into v_org from orgs where id = p_org_id;
    if not found then
        raise exception 'Entreprise inconnue';
    end if;
    if p_feature is null or p_feature = 'photo_slot'
       or not (coalesce(plan_setting('pro_features'), '[]'::jsonb) ? p_feature
               or exists (select 1 from cauris_costs where feature = p_feature)) then
        raise exception 'Outil inconnu : %', coalesce(p_feature, '');
    end if;
    if p_until is null or p_until < cauris_today() then
        raise exception 'La date doit être aujourd''hui ou plus tard';
    end if;
    v_until := (p_until + 1)::timestamp at time zone 'Africa/Ouagadougou';

    -- A tool the business bought and still has open stays its own: the gift
    -- only lengthens it, and never relabels it « Offert par Mara » (nor takes
    -- it off Le Chemin's « premier outil »).
    insert into cauris_unlocks (org_id, feature, until, note, gifted_by)
    values (p_org_id, p_feature, v_until, v_note, auth.uid())
    on conflict (org_id, feature) do update
        set until = greatest(cauris_unlocks.until, excluded.until),
            note = case when cauris_unlocks.gifted_by is null and cauris_unlocks.until > now()
                        then cauris_unlocks.note else excluded.note end,
            gifted_by = case when cauris_unlocks.gifted_by is null and cauris_unlocks.until > now()
                             then null else excluded.gifted_by end,
            updated_at = now()
    returning until into v_until;

    begin
        perform notify_org_admins(p_org_id, 'feature_gift',
            'Mara vous offre ' || cauris_feature_label(p_feature) || ' jusqu''au '
            || to_char(p_until, 'DD/MM/YYYY') || '.',
            jsonb_build_object('to', 'shop', 'feature', p_feature, 'until', p_until,
                               'note', v_note));
    exception when others then
        null;
    end;
    return v_until;
end;
$$;

-- 091's states, with the promotions, the photos and the team. Reading may
-- write a promotion's expiry line, so it is volatile now (as my_cauris is).
-- A photo slot is not a tool opened for 30 days: it is left out of 'tools'.
create or replace function feature_states(p_org_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
begin
    if not is_org_member(p_org_id) then
        return null;
    end if;
    perform cauris_expire(p_org_id);
    return jsonb_build_object(
        'plan', org_plan(p_org_id),
        'balance', cauris_balance(p_org_id),
        'tools', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'feature', c.feature,
                       'cost', c.cost,
                       'until', u.until,
                       'gift', u.gifted_by is not null,
                       'waits_days', case
                           when c.min_days > 0
                            and o.created_at > now() - make_interval(days => c.min_days)
                           then c.min_days - extract(day from now() - o.created_at)::int end
                   ) order by c.sort)
              from cauris_costs c
              cross join orgs o
              left join cauris_unlocks u
                on u.org_id = p_org_id and u.feature = c.feature and u.until > now()
             where o.id = p_org_id and c.feature <> 'photo_slot'), '[]'::jsonb),
        'progress', org_progress(p_org_id),
        'wave_allowed', coalesce((select wave_allowed from orgs where id = p_org_id), false),
        'setup_done', coalesce((select setup_done_at is not null from orgs where id = p_org_id), true),
        'promo', cauris_promo_left(p_org_id),
        'photos', photo_state(p_org_id),
        'team', team_seats(p_org_id)
    );
end;
$$;

-- 097's wallet, with the promotions, and gifts kept out of the week's score.
create or replace function my_cauris(p_org_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_last timestamptz;
begin
    if not is_org_admin(p_org_id) then
        return null;
    end if;
    perform cauris_expire(p_org_id);
    select max(created_at) into v_last from cauris_ledger
     where org_id = p_org_id and reason <> 'expired';
    return jsonb_build_object(
        'balance', cauris_balance(p_org_id),
        'week', (select coalesce(sum(delta), 0) from cauris_ledger
                  where org_id = p_org_id and delta > 0
                    and reason not in ('expired', 'gift', 'promo')
                    and created_at >= date_trunc('week', now() at time zone 'Africa/Ouagadougou')
                                      at time zone 'Africa/Ouagadougou'),
        'expires_on', case when v_last is null then null
                           else ((v_last at time zone 'Africa/Ouagadougou')::date
                                 + cauris_param('cauris_expire_days', 180)) end,
        'promo', cauris_promo_left(p_org_id),
        'referral_code', (select slug from orgs where id = p_org_id),
        'referred', (select referred_by is not null from orgs where id = p_org_id),
        'referral_points', coalesce((select points from cauris_rules where key = 'referral'), 0),
        'referrals', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'name', r.name,
                       'score', vitrine_score(r.id),
                       'orders', (select count(*) from orders o
                                   where o.org_id = r.id and o.status in ('picked_up', 'delivered')),
                       'paid', exists (select 1 from cauris_ledger l
                                        where l.org_id = p_org_id and l.reason = 'referral'
                                          and l.ref = r.id::text)
                   ) order by r.created_at desc)
              from orgs r where r.referred_by = p_org_id), '[]'::jsonb),
        'history', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'delta', l.delta,
                       'reason', l.reason,
                       'label', coalesce(r.label, case l.reason
                                    when 'expired'   then 'Cauris expirés'
                                    when 'spent'     then 'Dépensés'
                                    when 'path_step' then 'Étape du chemin'
                                    when 'prize'     then 'Podium de la semaine'
                                    when 'lesson'    then 'Leçon de l''Académie Mara'
                                    when 'gift'      then 'Cadeau de Mara'
                                    when 'promo'     then 'Cauris offerts par Mara'
                                    else l.reason end),
                       'note', case when l.reason in ('expired', 'spent', 'prize', 'referral',
                                                      'path_step', 'gift', 'promo')
                                    then l.note end,
                       'at', l.created_at) order by l.created_at desc)
              from (select * from cauris_ledger where org_id = p_org_id
                     order by created_at desc limit 60) l
              left join cauris_rules r on r.key = l.reason), '[]'::jsonb),
        'rules', coalesce((
            select jsonb_agg(jsonb_build_object('key', key, 'points', points,
                       'daily_cap', daily_cap, 'label', label) order by sort)
              from cauris_rules where points > 0), '[]'::jsonb)
    );
end;
$$;

-- 086's scores: a gift is not earned.
create or replace function league_scores(p_from timestamptz, p_to timestamptz)
returns table (org_id uuid, name text, hidden boolean, league text, score integer)
language sql
stable
security definer
set search_path = public
as $$
    select o.id, o.name, o.board_hidden, league_key(o.id),
           coalesce((select sum(l.delta) from cauris_ledger l
                      where l.org_id = o.id and l.delta > 0
                        and l.reason not in ('prize', 'expired', 'spent', 'gift', 'promo')
                        and l.created_at >= p_from and l.created_at < p_to), 0)::int
      from orgs o
     where o.profile not in ('church', 'association')
       and o.archived_at is null and o.suspended_at is null
       and exists (select 1 from cauris_ledger l where l.org_id = o.id);
$$;

-- 084's watch: the week's earners, not the platform's own gifts.
create or replace function cauris_watch()
returns table (
    org_id        uuid,
    org_name      text,
    week          integer,
    balance       integer,
    orders        integer,
    top_customer_share numeric
)
language sql
stable
security definer
set search_path = public, auth
as $$
    with w as (
        select l.org_id, sum(l.delta)::int as week
          from cauris_ledger l
         where l.delta > 0 and l.created_at >= now() - interval '7 days'
           and l.reason not in ('gift', 'promo')
         group by l.org_id
    ), c as (
        select l.org_id, l.note as customer, count(*) as n
          from cauris_ledger l
         where l.reason = 'order_done' and l.created_at >= now() - interval '7 days'
         group by l.org_id, l.note
    )
    select w.org_id, o.name, w.week, cauris_balance(w.org_id),
           coalesce((select sum(n) from c where c.org_id = w.org_id), 0)::int,
           coalesce(round((select max(n) from c where c.org_id = w.org_id)::numeric
                 / nullif((select sum(n) from c where c.org_id = w.org_id), 0), 2), 0)
      from w join orgs o on o.id = w.org_id
     where exists (select 1 from profiles where id = auth.uid() and is_platform_admin)
     order by w.week desc
     limit 50;
$$;

-- 097's steps, verbatim but two: « Mon premier outil avec mes cauris » is
-- a tool the business opened itself, not one Mara gave it; and « en photo »
-- counts pictures, not a delivery note filed on an article.
create or replace function path_progress(p_org uuid, p_step text)
returns integer
language sql
stable
security definer
set search_path = public
as $$
    select (case p_step
        when 'first_article' then
            (select count(*) from products p
              where p.org_id = p_org and p.is_active and p.is_published)
        when 'articles' then
            (select count(*) from products p
              where p.org_id = p_org and p.is_active and p.is_published)
        when 'vitrine_open' then
            (select count(*) from orgs o where o.id = p_org and o.storefront_enabled)
        when 'contact' then
            (select (nullif(btrim(coalesce(o.phone, '')), '') is not null)::int
                  + (nullif(btrim(coalesce(o.address, '')), '') is not null)::int
               from orgs o where o.id = p_org)
        when 'photos' then
            (select count(*) from products p
              where p.org_id = p_org and p.is_active and p.is_published
                and exists (select 1 from documents d
                             where d.product_id = p.id
                               and doc_is_photo(d.kind, d.content_type)))
        when 'blurb' then
            (select count(*) from orgs o
              where o.id = p_org and nullif(btrim(coalesce(o.storefront_blurb, '')), '') is not null)
        when 'pin' then
            (select count(*) from orgs o
              where o.id = p_org and o.lat is not null and o.lng is not null)
        when 'first_sale' then
            (select count(*) from (select 1 from sales s
                                    where s.org_id = p_org and s.kind = 'sale' limit 1) x)
        when 'farm_log' then
            (select count(*) from (select 1 from flock_events e join flocks f on f.id = e.flock_id
                                    where f.org_id = p_org limit 1) x)
        when 'first_order' then
            (select count(*) from (select 1 from orders x
                                    where x.org_id = p_org
                                      and x.status in ('accepted', 'ready', 'picked_up', 'delivered')
                                    limit 1) y)
        when 'three_orders' then
            (select count(*) from orders x
              where x.org_id = p_org and x.status in ('picked_up', 'delivered'))
        when 'returning' then
            (select count(*) from (select 1 from orders x
                                    where x.org_id = p_org and x.customer_id is not null
                                      and x.status in ('picked_up', 'delivered')
                                    group by x.customer_id having count(*) >= 2 limit 1) y)
        when 'till_week' then
            (select count(distinct (s.occurred_at at time zone 'Africa/Ouagadougou')::date)
               from sales s where s.org_id = p_org and s.kind = 'sale')
        when 'log_week' then
            (select count(distinct (e.occurred_at at time zone 'Africa/Ouagadougou')::date)
               from flock_events e join flocks f on f.id = e.flock_id
              where f.org_id = p_org)
        when 'first_unlock' then
            (select count(*) from (select 1 from cauris_unlocks u
                                    where u.org_id = p_org and u.gifted_by is null
                                    limit 1) x)
        when 'referral' then
            (select count(*) from (select 1 from orgs r
                                    where r.referred_by = p_org limit 1) x)
        when 'podium' then
            (select count(*) from (select 1 from cauris_week_results w
                                    where w.org_id = p_org and w.rank <= 3
                                      and (select count(*)
                                             from league_scores(
                                                    w.week_start::timestamp at time zone 'Africa/Ouagadougou',
                                                    (w.week_start + 7)::timestamp at time zone 'Africa/Ouagadougou') l
                                            where l.league = w.league and l.score > 0)
                                          >= cauris_param('path_league_min', 3)
                                    limit 1) x)
        else 0
    end)::int;
$$;

-- 097's path, its « cette semaine » as the leagues count it now: a gift
-- or promotional points from Mara are not earned (as my_cauris, league_scores).
create or replace function path_state(p_org uuid)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public, auth
as $$
declare
    v_profile text;
    v_stage   integer;
    v_steps   jsonb;
    v_stages  jsonb;
    v_next    text;
    v_league  boolean := false;
    v_admin   boolean;
begin
    if p_org is null or not is_org_member(p_org) then
        return null;
    end if;
    v_admin := is_org_admin(p_org);
    select o.profile::text into v_profile from orgs o where o.id = p_org;
    if v_profile is null or v_profile not in ('retail', 'farm') then
        return null;
    end if;
    perform path_sync(p_org);
    perform cauris_expire(p_org);

    select coalesce(jsonb_agg(jsonb_build_object(
               'key', r.key, 'stage', r.stage, 'title', r.title, 'line', r.line,
               'go', r.go,
               -- A step reached stays reached: it shows its goal met, even
               -- if the data fell back since.
               'progress', case when r.done then r.goal else least(r.live, r.goal) end,
               -- What the data says right now, for the gates (live).
               'live', least(r.live, r.goal),
               'goal', r.goal, 'done', r.done, 'reward', r.reward, 'opens', r.opens)
               order by r.stage, r.sort), '[]'::jsonb)
      into v_steps
      from (select s.key, s.stage, s.sort, s.reward, s.opens,
                   path_text(s.title, s.title_farm, v_profile) as title,
                   path_text(s.line, s.line_farm, v_profile) as line,
                   case when v_profile = 'farm' and s.go_farm is not null
                        then s.go_farm else s.go end as go,
                   path_progress(p_org, s.key) as live,
                   path_goal(p_org, s.key) as goal,
                   exists (select 1 from org_path_done d
                            where d.org_id = p_org and d.step = s.key) as done
              from path_steps s
             where v_profile = any (s.profiles)) r;

    select coalesce(min((e ->> 'stage')::int), 5) into v_stage
      from jsonb_array_elements(v_steps) e where not (e ->> 'done')::boolean;
    select e ->> 'key' into v_next
      from jsonb_array_elements(v_steps) with ordinality x(e, i)
     where not (e ->> 'done')::boolean order by i limit 1;

    select jsonb_agg(jsonb_build_object(
               'n', n.n,
               'title', (array['Ouvrir', 'Remplir', 'Vendre', 'Grandir'])[n.n],
               'done', not exists (select 1 from jsonb_array_elements(v_steps) e
                                    where (e ->> 'stage')::int = n.n
                                      and not (e ->> 'done')::boolean))
               order by n.n)
      into v_stages from generate_series(1, 4) n(n);

    if v_stage >= 4 then
        -- A race is businesses earning this week: one that earned once,
        -- long ago, is on the board at 0 and does not make it one.
        v_league := (select count(*) from league_scores(cauris_week_start(),
                                                        now() + interval '1 second') l
                      where l.league = league_key(p_org) and l.score > 0)
                    >= cauris_param('path_league_min', 3);
    end if;

    return jsonb_build_object(
        'stage', v_stage,
        'stages', v_stages,
        'next', v_next,
        'steps', coalesce(v_steps, '[]'::jsonb),
        'tools', jsonb_build_object(
            'invoices',        not path_locked(p_org, 'invoices'),
            'production',      not path_locked(p_org, 'production'),
            'credits',         not path_locked(p_org, 'credits'),
            'second_business', not path_locked(p_org, 'second_business')),
        -- The wallet is the admins' (as my_cauris): null for the others.
        'balance', case when v_admin then cauris_balance(p_org) end,
        -- This week's score, as the league counts it (086): Mara's gifts
        -- and promotional points (100) are not earned.
        'week', case when v_admin then
                    (select coalesce(sum(l.delta), 0)::int from cauris_ledger l
                      where l.org_id = p_org and l.delta > 0
                        and l.reason not in ('prize', 'expired', 'spent', 'gift', 'promo')
                        and l.created_at >= cauris_week_start()) end,
        'league_open', v_league
    );
end;
$$;

-- 082's terms, with the photographed articles a Basic business keeps.
create or replace function plan_terms()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
    select jsonb_build_object(
        'pro_features',            coalesce(plan_setting('pro_features'), '[]'::jsonb),
        'free_max_staff',          plan_limit('free_max_staff', 1),
        'free_max_invoices_month', plan_limit('free_max_invoices_month', 20),
        'free_max_photos',         plan_limit('free_max_photos', 50),
        'free_photo_items',        plan_limit('free_photo_items', 10),
        'free_history_months',     plan_limit('free_history_months', 12),
        'pro_price_month',         plan_limit('pro_price_month', 2500),
        'pro_price_year',          plan_limit('pro_price_year', 25000),
        'pro_currency',            coalesce(plan_setting('pro_currency') #>> '{}', 'XOF'),
        'platform_wave',           coalesce(plan_setting('platform_wave') #>> '{}', ''),
        'platform_wave_name',      coalesce(plan_setting('platform_wave_name') #>> '{}', ''),
        'delivery_share_pct',      plan_limit('delivery_share_pct', 10),
        'stripe_on',               stripe_on()
    );
$$;

-- ------------------------------------------------------------
-- 6. The owner's name on the picker
-- ------------------------------------------------------------
-- 065's my_orgs, plus owner_name: who owns each business (the first owner
-- by date), so a platform admin choosing among hundreds knows which is
-- whose. The columns grow, so it is dropped and recreated.
drop function if exists my_orgs();

create function my_orgs()
returns table (
    org_id           uuid,
    name             text,
    slug             text,
    profile          text,
    default_currency text,
    roles            text[],
    visibility       text,
    theme            text,
    suspended        boolean,
    plan             text,
    owner_name       text
)
language sql
stable
security definer
set search_path = public, auth
as $$
    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array['platform_admin'::text],
        'full'::text,
        o.theme,
        (o.suspended_at is not null),
        org_plan(o.id),
        (select person_name(m.user_id) from memberships m
          where m.org_id = o.id and m.role = 'owner'
          order by m.created_at limit 1)
    from orgs o
    where exists(select 1 from profiles where id = auth.uid() and is_platform_admin)

    union all

    select
        o.id, o.name, o.slug, o.profile, o.default_currency,
        array_agg(distinct m.role::text order by m.role::text),
        case when bool_or(m.visibility = 'full') then 'full' else 'summary' end,
        o.theme,
        (o.suspended_at is not null),
        org_plan(o.id),
        (select person_name(w.user_id) from memberships w
          where w.org_id = o.id and w.role = 'owner'
          order by w.created_at limit 1)
    from memberships m
    join orgs o on o.id = m.org_id
    where m.user_id = auth.uid()
      and o.archived_at is null
      and not exists(select 1 from profiles where id = auth.uid() and is_platform_admin)
    group by o.id, o.name, o.slug, o.profile, o.default_currency, o.theme,
             o.suspended_at

    order by name;
$$;

-- ------------------------------------------------------------
-- 10. The stock follows its corrections
-- ------------------------------------------------------------
-- 034's correction of a batch, and now the shelf with it: the output
-- product moves by what the count changed (« 20 » corrected to « 40 » puts
-- 20 more cakes on the shelf). The ingredients stay as consumed (034).
create or replace function update_production_run(
    p_run_id       uuid,
    p_quantity     numeric     default null,
    p_product_name text        default null,
    p_note         text        default null,
    p_occurred_at  timestamptz default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_run production_runs%rowtype;
begin
    if auth.uid() is null then
        raise exception 'update_production_run() needs a signed-in caller';
    end if;

    select * into v_run from production_runs where id = p_run_id for update;

    if v_run.id is null then
        raise exception 'No such production run';
    end if;
    if not can_write_org(v_run.org_id) then
        raise exception 'You cannot correct entries for this business';
    end if;
    if p_quantity is not null and p_quantity <= 0 then
        raise exception 'A production needs the quantity that was made (got %)',
            p_quantity;
    end if;

    update production_runs set
        quantity     = coalesce(p_quantity, quantity),
        product_name = coalesce(nullif(btrim(coalesce(p_product_name, '')), ''),
                                product_name),
        note         = coalesce(p_note, note),
        occurred_at  = coalesce(p_occurred_at, occurred_at),
        unit_cost    = case
                         when p_quantity is not null and p_quantity > 0
                         then round(total_cost / p_quantity, 4)
                         else unit_cost
                       end
    where id = p_run_id;

    if p_quantity is not null and p_quantity <> v_run.quantity
       and v_run.product_id is not null then
        -- 026 set the article's cost price to this batch's unit cost (the
        -- latest batch's, as receive_products does for a delivery). While
        -- it still is this batch's — no later batch, no delivery since at
        -- another cost — it follows the corrected count.
        update products
           set quantity   = quantity + (p_quantity - v_run.quantity),
               cost_price = case
                   when v_run.total_cost > 0
                    and cost_price = round(v_run.unit_cost, 2)
                    and not exists (select 1 from production_runs r
                                     where r.product_id = v_run.product_id
                                       and r.id <> v_run.id
                                       and r.created_at > v_run.created_at)
                   then round(v_run.total_cost / p_quantity, 2)
                   else cost_price end
         where id = v_run.product_id;
    end if;

    return p_run_id;
end;
$$;

-- 033's correction of a flock event, held to 009's rule: no more birds out
-- than the flock has.
create or replace function update_flock_event(
    p_event_id    uuid,
    p_quantity    numeric     default null,
    p_kind        text        default null,
    p_note        text        default null,
    p_occurred_at timestamptz default null
)
returns uuid
language plpgsql
security definer
set search_path = public, auth
as $$
declare
    v_org   uuid;
    v_flock uuid;
    v_ev    flock_events%rowtype;
    v_kind  text;
    v_qty   numeric;
    v_alive numeric;
begin
    if auth.uid() is null then
        raise exception 'update_flock_event() needs a signed-in caller';
    end if;

    select e.* into v_ev from flock_events e where e.id = p_event_id;
    select f.org_id, f.id into v_org, v_flock from flocks f where f.id = v_ev.flock_id;

    if v_org is null then
        raise exception 'No such flock event';
    end if;
    if not can_write_org(v_org) then
        raise exception 'You cannot correct entries for this business';
    end if;
    if p_quantity is not null and p_quantity < 0 then
        raise exception 'A count cannot be negative (got %)', p_quantity;
    end if;

    v_kind := coalesce(nullif(btrim(coalesce(p_kind, '')), ''), v_ev.kind);
    v_qty  := coalesce(p_quantity, v_ev.quantity);
    if v_kind in ('mortality', 'sold') then
        select f.bird_count - coalesce(sum(e.quantity) filter (
                   where e.kind in ('mortality', 'sold') and e.id <> p_event_id), 0)
          into v_alive
          from flocks f
          left join flock_events e on e.flock_id = f.id
         where f.id = v_flock
         group by f.bird_count;
        if v_qty > v_alive then
            raise exception
                'Only % birds left in this flock, cannot record % as %',
                v_alive, v_qty, v_kind;
        end if;
    end if;

    update flock_events set
        quantity    = v_qty,
        kind        = v_kind,
        note        = coalesce(p_note, note),
        occurred_at = coalesce(p_occurred_at, occurred_at)
    where id = p_event_id;

    return p_event_id;
end;
$$;

